-- ==============================================================================================
-- بخش دوم: تابع به‌روزرسانی شده MiladiToShamsi7
-- ==============================================================================================

IF OBJECT_ID(N'[dbo].[MiladiToShamsi7]') IS NOT NULL
    DROP FUNCTION [dbo].[MiladiToShamsi7];
GO

CREATE FUNCTION dbo.MiladiToShamsi7 ( @MD AS DATETIME )
RETURNS VARCHAR(20)
AS
BEGIN
    IF @MD IS NULL
        RETURN '';
    ELSE
    BEGIN
        DECLARE @Y INT, @M INT, @D INT, @fDay INT, @fMonth INT, @aDay INT, @eDay INT, @i INT, @sw INT, @Date CHAR(10),
                @A0 INT, @A1 INT, @A2 INT, @A3 INT, @A4 INT, @A5 INT, @A6 INT, @A7 INT, @A8 INT, @A9 INT, @A10 INT, @A11 INT;
        SET @Y = YEAR(@MD);
        SET @M = MONTH(@MD);
        SET @D = DAY(@MD);
        SET @A0 = 31; SET @A1 = 28; SET @A2 = 31; SET @A3 = 30; SET @A4 = 31; SET @A5 = 30;
        SET @A6 = 31; SET @A7 = 31; SET @A8 = 30; SET @A9 = 31; SET @A10 = 30; SET @A11 = 31;
        SET @sw = 0;
        IF ABS(@Y - 200) % 4 = 1
        BEGIN
            SET @fDay = 11;
            SET @sw = 1;
        END
        ELSE
            SET @fDay = 10;
        IF ABS(@Y - 200) % 4 = 0
            SET @A1 = 29;
        SET @fMonth = 10;
        SET @aDay = @D;
        SET @i = 1;
        WHILE @i <= @M - 1
        BEGIN
            SET @aDay = @aDay + (SELECT CASE @i - 1
                WHEN 0 THEN @A0 WHEN 1 THEN @A1 WHEN 2 THEN @A2 WHEN 3 THEN @A3 WHEN 4 THEN @A4 WHEN 5 THEN @A5
                WHEN 6 THEN @A6 WHEN 7 THEN @A7 WHEN 8 THEN @A8 WHEN 9 THEN @A9 WHEN 10 THEN @A10 WHEN 11 THEN @A11
            END);
            SET @i = @i + 1;
        END;
        SET @eDay = 89 - @fDay + @sw;
        IF @aDay <= @eDay
        BEGIN
            SET @Y = @Y - 622;
            SET @aDay = @aDay + @fDay;
            SET @M = @fMonth;
            WHILE @aDay > 30
            BEGIN
                SET @aDay = @aDay - 30;
                SET @M = @M + 1;
            END;
            SET @D = @aDay;
        END
        ELSE
        BEGIN
            SET @Y = @Y - 621;
            SET @aDay = @aDay - @eDay;
            IF @aDay < 187
            BEGIN
                SET @M = 1;
                WHILE @aDay > 31
                BEGIN
                    SET @aDay = @aDay - 31;
                    SET @M = @M + 1;
                END;
                SET @D = @aDay;
            END
            ELSE
            BEGIN
                SET @aDay = @aDay - 186;
                SET @M = 7;
                WHILE @aDay > 30
                BEGIN
                    SET @aDay = @aDay - 30;
                    SET @M = @M + 1;
                END;
                SET @D = @aDay;
            END;
        END;
        SET @Date = SUBSTRING(LTRIM(STR(@Y)), 0, 5) + '/';
        IF @M < 10
            SET @Date = RTRIM(@Date) + '0' + LTRIM(STR(@M)) + '/';
        ELSE
            SET @Date = RTRIM(@Date) + LTRIM(STR(@M)) + '/';
        IF @D < 10
            SET @Date = RTRIM(@Date) + '0' + LTRIM(STR(@D)) + '/';
        ELSE
            SET @Date = RTRIM(@Date) + LTRIM(STR(@D)) + '/';
    END;
    SET @Date = RTRIM(@Date);
    IF @MD = '1992/3/20'
        SET @Date = '1370/12/30';
    RETURN (@Date)+' '+CONVERT(NVARCHAR(8), @MD, 108);
END;

GO
PRINT N'تابع MiladiToShamsi7 به‌روزرسانی شد.';
GO

-- ==============================================================================================
-- بخش سوم: ایجاد و به‌روزرسانی استورد پروسیجرها (شامل ۳۷ پروسیجر مفقود و ۶۱ پروسیجر اصلاح‌شده)
-- ==============================================================================================

-- Procedure: [dbo].[RawDatabase]
IF OBJECT_ID(N'[dbo].[RawDatabase]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RawDatabase] AS SELECT 1;');
GO
ALTER PROCEDURE dbo.RawDatabase
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        PRINT N'شروع خام‌سازی...';

        --------------------------------------------------
        -- غیرفعال کردن تمام Triggerها
        --------------------------------------------------
        EXEC sp_MSforeachtable
            'DISABLE TRIGGER ALL ON ?';

        PRINT N'Trigger ها غیرفعال شدند.';


        --------------------------------------------------
        -- خام کردن جداول مشخص‌شده
        --------------------------------------------------

        IF OBJECT_ID(N'dbo.TblKala', N'U') IS NOT NULL
        BEGIN
            DELETE FROM dbo.TblKala;
            PRINT N'TblKala پاک شد.';
        END


        IF OBJECT_ID(N'dbo.TblPerson', N'U') IS NOT NULL
        BEGIN
            DELETE FROM dbo.TblPerson;
            PRINT N'TblPerson پاک شد.';
        END


        IF OBJECT_ID(N'dbo.TR', N'U') IS NOT NULL
        BEGIN
            DELETE FROM dbo.TR;
            PRINT N'TR پاک شد.';
        END


        --------------------------------------------------
        -- فعال کردن تمام Triggerها
        --------------------------------------------------
        EXEC sp_MSforeachtable
            'ENABLE TRIGGER ALL ON ?';

        PRINT N'تمام Trigger ها ENABLE شدند.';

        PRINT N'--------------------------------';
        PRINT N'خام‌سازی با موفقیت انجام شد.';
        PRINT N'--------------------------------';

    END TRY

    BEGIN CATCH

        PRINT N'خطا: ' + ERROR_MESSAGE();

        -- در هر حالت Triggerها فعال شوند
        BEGIN TRY
            EXEC sp_MSforeachtable
                'ENABLE TRIGGER ALL ON ?';
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;

    END CATCH
END

GO

-- Procedure: [dbo].[Report_KalaForooshMande]
IF OBJECT_ID(N'[dbo].[Report_KalaForooshMande]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[Report_KalaForooshMande] AS SELECT 1;');
GO
ALTER PROCEDURE dbo.Report_KalaForooshMande
    @IdKala1 INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        TR.CShobe AS [کد شعبه],

        ISNULL(
            (
                SELECT TOP 1 A.Name
                FROM dbo.TblAnbar A
                WHERE A.Cshobe = TR.CShobe
                ORDER BY A.ID
            ), N''
        ) AS [نام شعبه],

        TR.DateR AS [تاریخ فروش],
        TR.Factor AS [شماره فاکتور],
        TR.IdAnbr AS [کد انبار],

        TR.IdKala AS [کد کالا],
        ISNULL(K.Name, N'') AS [نام کالا],

        dbo.ShowTed(TR.TED) AS [مقدار فروش],

        CAST(TR.Nerkh AS BIGINT) AS [قیمت واحد],
        CAST(TR.Bes AS BIGINT) AS [مبلغ فروش],

        dbo.ShowTed(ISNULL(M.Mande, 0)) AS [مانده بعد فروش],

        dbo.ShowTed(
            ISNULL(M.Mande, 0) + TR.TED
        ) AS [مانده قبل فروش]

    FROM dbo.TR TR

    LEFT JOIN
    (
        SELECT
            IDKala,
            MAX(Name) AS Name
        FROM dbo.TblKala
        GROUP BY IDKala
    ) K
        ON K.IDKala = TR.IdKala

    OUTER APPLY
    (
        SELECT
            SUM(
                ISNULL(V.Td_in, 0)
                -
                ISNULL(V.Td_out, 0)
            ) AS Mande

        FROM dbo.ViewKadexKol2 V

        WHERE
            V.IDKala = @IdKala1

            AND
            (
                V.IDAnbar IN
                (
                    SELECT A.ID
                    FROM dbo.TblAnbar A
                    WHERE A.Cshobe = TR.CShobe
                )
                OR V.CShobe = TR.CShobe
                OR V.CShobe = 0
            )

            AND
            (
                V.DateR < TR.DateR
                OR
                (
                    V.DateR = TR.DateR
                    AND V.ID <= TR.Sodor
                )
            )

    ) M

    WHERE
        TR.IdKala = @IdKala1
        AND TR.CShobe > 0
        AND TR.IdAnbr > 0
        AND TR.Type IN (203, 211)

    ORDER BY
        TR.CShobe,
        TR.DateR,
        TR.Sodor;

END
GO

-- Procedure: [dbo].[RptForushAndBarghashForush]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForush]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForush] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForush]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL ,
	@Type VARCHAR(10) = '203,104'
AS
BEGIN
	IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL   
            DROP TABLE  #RptForushAndAvamelKala_Base;        
        CREATE TABLE #RptForushAndAvamelKala_Base   
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  DateR NVARCHAR(100),
			  [Rank] INT ,   
              IdAnbar INT ,   
              IdKala INT ,   
			  Mab BIGINT ,   
              Takh BIGINT ,   
              Ted DECIMAL(18, 5),
			  EzafMashmol BIGINT,
			  KasrMashmol BIGINT,
			  Ezaf BIGINT,
			  Kasr BIGINT,
			  Maliat BIGINT,
			  Mashmol TINYINT,
			  DarsadMashmol NUMERIC(18,3),
			  Cshobe INT,
			  WeightKala NUMERIC(18,3)
            );     
        INSERT  INTO #RptForushAndAvamelKala_Base   
                ( Factor ,   
                  [Type] , 
				  DateR,
				  [Rank] ,   
                  IdAnbar ,   
                  IdKala ,   
                  Mab ,   
                  Takh ,   
                  Ted,
				  EzafMashmol,
				  KasrMashmol,
				  Ezaf,
				  Kasr,
				  Maliat,
				  Mashmol,
				  DarsadMashmol,
				  Cshobe,
				  WeightKala
                )   
                SELECT  Factor , 
						[Type] , 
						DateR,
						RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,dbo.TR.Sodor	) ,    
                        IdAnbr ,    
                        TR.Idkala ,    
                        Bes+Bed, 
                        Takh ,    
                        TED,
						  0,
						  0,
						  0,
						  0,
						  0,
						dbo.TR.Mashmol,
						dbo.TR.DarsadMashmol,
						CShobe,
						dbo.TblKala.WeightKala*tr.TED
                FROM    dbo.TR 
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                                   AND TR.Idkala = dbo.TblKala.IDKala 
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
						AND TR.Idkala > 0    
                        AND DateR BETWEEN @Date1 AND @Date2
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
						ORDER BY Mashmol DESC,DarsadMashmol DESC,dbo.TR.Sodor	
						
						
						
						
		IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
			DROP TABLE  #RptForushAndAvamelKala_MabFactor;   
		CREATE TABLE #RptForushAndAvamelKala_MabFactor		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptForushAndAvamelKala_MabFactor 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptForushAndAvamelKala_Base AS tbl   
                GROUP BY tbl.Factor, tbl.[Type];   


			UPDATE #RptForushAndAvamelKala_MabFactor SET Mab = 1 WHERE Mab = 0
				
				 
   
		IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
			DROP TABLE  #RptForushAndAvamelKala_MabAgent; 
		CREATE TABLE #RptForushAndAvamelKala_MabAgent 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptForushAndAvamelKala_MabAgent   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
						CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
                FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 0 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				

				

			IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptForushAndAvamelKala_MabFactorMashmol;   
		CREATE TABLE #RptForushAndAvamelKala_MabFactorMashmol		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptForushAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				
				
				IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptForushAndAvamelKala_MabAgentMashmol; 
		CREATE TABLE #RptForushAndAvamelKala_MabAgentMashmol 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptForushAndAvamelKala_MabAgentMashmol   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
						CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
                FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				
				
				UPDATE tblKF SET 
				tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
				tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
				FROM #RptForushAndAvamelKala_Base AS tblKF
				INNER JOIN #RptForushAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptForushAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


				


				UPDATE tblKF SET 
				tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
				tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
				FROM #RptForushAndAvamelKala_Base AS tblKF
				INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptForushAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0






				IF ( OBJECT_ID('#RptForushAndAvamelKala_Difference', 'U') ) IS NOT NULL 
					DROP TABLE  #RptForushAndAvamelKala_Difference;   
				CREATE TABLE #RptForushAndAvamelKala_Difference 
				(   
				 Factor INT ,   
				[Type] TINYINT , 
				Ezaf BIGINT ,
				Kasr BIGINT
				);    

				INSERT INTO #RptForushAndAvamelKala_Difference
				SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptForushAndAvamelKala_Base
				GROUP BY Factor,Type


				
			
		

				UPDATE tblD SET 
				tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblAm.Kasr - tblD.Kasr
				 FROM #RptForushAndAvamelKala_MabAgentMashmol AS tblAm
				INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type





				DELETE FROM #RptForushAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0


				UPDATE tblKF SET 
				tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
				tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
				FROM #RptForushAndAvamelKala_Base AS tblKF
				INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
				DELETE FROM #RptForushAndAvamelKala_Difference


				




				INSERT INTO #RptForushAndAvamelKala_Difference
				SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptForushAndAvamelKala_Base
				GROUP BY Factor,Type

				
				UPDATE tblD SET 
				tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblA.Kasr - tblD.Kasr
				 FROM #RptForushAndAvamelKala_MabAgent AS tblA
				INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


				DELETE FROM #RptForushAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0

				

				UPDATE tblKF SET 
				tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
				tblKF.Kasr = tblKF.Kasr+tblD.Kasr
				FROM #RptForushAndAvamelKala_Base AS tblKF
				INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


			



			DELETE #RptForushAndAvamelKala_MabFactorMashmol
			
        INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
                FROM    #RptForushAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
		IF ( OBJECT_ID('#RptForushAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
			DROP TABLE  #RptForushAndAvamelKala_MabMaliat; 
		CREATE TABLE #RptForushAndAvamelKala_MabMaliat 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Mab BIGINT 
            );     
        INSERT  INTO #RptForushAndAvamelKala_MabMaliat   
                ( Factor ,   
                  [Type] , 
				  Mab
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes-dbo.TR.Bed) ELSE SUM(dbo.TR.Bed-dbo.TR.Bes) END
                FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	




				UPDATE tblKF SET 
				tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
				FROM #RptForushAndAvamelKala_Base AS tblKF
				INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
				INNER JOIN #RptForushAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


				IF ( OBJECT_ID('#RptForushAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
					DROP TABLE  #RptForushAndAvamelKala_DifferenceMaliat;   
				CREATE TABLE #RptForushAndAvamelKala_DifferenceMaliat 
				(   
				 Factor INT ,   
				 [Type] TINYINT , 
				 Mab BIGINT 
				);    

				INSERT INTO #RptForushAndAvamelKala_DifferenceMaliat
				SELECT Factor,Type,SUM(Maliat) FROM #RptForushAndAvamelKala_Base
				GROUP BY Factor,Type

				UPDATE tblD SET 
				tblD.Mab = tblM.Mab - tblD.Mab
				 FROM #RptForushAndAvamelKala_MabMaliat AS tblM
				INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


				DELETE FROM #RptForushAndAvamelKala_DifferenceMaliat
				WHERE Mab = 0


				UPDATE tblKF SET 
				tblKF.Maliat = tblKF.Maliat+tblD.Mab
				FROM #RptForushAndAvamelKala_Base AS tblKF
				INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


				IF ( OBJECT_ID('#RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
			DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;   
		CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		 
            (   
			  Shfactor INT ,   
              [Type] TINYINT , 
			  Code VARCHAR(100) 
            );     
        INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp 
                SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
                FROM    #RptForushAndAvamelKala_Base AS tbl 
				LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
		IF (ISNULL(@Tasviye, '') <> '') 
		BEGIN 
			DELETE #RptForushAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
		END 
 

			  SELECT 
			   tr.Type ,
               ISNULL(TblTypeTR.Name,'') TypeName ,
               ISNULL(CustumCod,0) CustumCod ,
               ISNULL(dbo.TblPerson.Name + ' '+dbo.TblPerson.Famil,'') Moshtari ,
               Factor ,
               DateR ,
               tr.IdAnbar ,
               ISNULL(dbo.TblAnbar.Name,'') AnbarName ,
               tr.IdKala ,
               ISNULL(dbo.TblKala.Name,'') KalaName ,
               Ted ,
               ISNULL(dbo.TblUnit.Name,'') Unit ,
               CAST(ROUND(( TR.Mab + TR.Takh ) / TR.TED, 0) AS BIGINT)  Fi ,
               TR.Mab + TR.Takh MabKol ,
               Takh ,
               KasrMashmol ,
               EzafMashmol ,
               TR.Mab+tr.EzafMashmol-tr.KasrMashmol MabMashmol ,
               Maliat ,
               Kasr ,
               Ezaf ,
               TR.Mab+tr.EzafMashmol-tr.KasrMashmol + Maliat-Kasr+Ezaf MabKhales ,
               tr.Cshobe ,
               ISNULL(dbo.TblCompanyShobe.Name,'') ShobeName ,
               CASE WHEN Mashmol = 1 THEN 'مشمول' ELSE 'معاف' END AS  Mashmol ,
               DarsadMashmol,
			   tr.WeightKala FROM #RptForushAndAvamelKala_Base AS tr
			   LEFT OUTER JOIN dbo.TblAnbar ON TR.IdAnbar = dbo.TblAnbar.ID
               LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
               LEFT OUTER JOIN dbo.TblUnit ON dbo.TblKala.Unit1 = dbo.TblUnit.ID
               LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
               LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
			   LEFT OUTER JOIN dbo.TblTypeTR ON TR.Type = dbo.TblTypeTR.ID
               LEFT OUTER JOIN dbo.TblCompanyShobe ON TR.CShobe = dbo.TblCompanyShobe.Id
			   WHERE  ( @IdKala IS NULL
                                          OR tr.IDKala IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdKala) )
                                        )
                                    AND ( @IdAnbar IS NULL
                                          OR TR.IdAnbar IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdAnbar) )
                                        )
                                    AND ( @Moshtari IS NULL
                                          OR dbo.TblFactorOnvan.CustumCod IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@Moshtari) )
                                        )
									AND ( @Vizitor IS NULL
                                          OR ISNULL(dbo.TblFactorOnvan.VizitorID,0) IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@Vizitor) )
                                        )
									AND ( @Driver IS NULL
                                          OR ISNULL(dbo.TblFactorOnvan.Driver,0) IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@Driver) )
                                        )
									AND ( @GroupCode IS NULL
                                          OR ISNULL(dbo.TblKala.GroupCode,'') IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTableStr(@GroupCode) )
                                        )
									AND	( @Tasviye IS NULL 
						  OR EXISTS (SELECT * FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type]))
		ORDER BY 
		 CustumCod ,
            tr.Type DESC ,
            DateR ,
            tr.Factor;


										  
END

GO

-- Procedure: [dbo].[RptForushAndBarghashForushAnbar]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushAnbar]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushAnbar] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushAnbar]
	@Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL,
	@Toggle BIT = 0  ,
	@Type VARCHAR(10) = '203,104'  
AS
BEGIN
	IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL   
        DROP TABLE  #RptForushAndAvamelKala_Base;        
    CREATE TABLE #RptForushAndAvamelKala_Base   
        (   
            Factor INT ,   
            [Type] TINYINT , 
			DateR NVARCHAR(100),
			[Rank] INT ,   
            IdAnbar INT ,   
            IdKala INT ,   
			Mab BIGINT ,   
            Takh BIGINT ,   
            Ted DECIMAL(18, 5),
			EzafMashmol BIGINT,
			KasrMashmol BIGINT,
			Ezaf BIGINT,
			Kasr BIGINT,
			Maliat BIGINT,
			Mashmol TINYINT,
			DarsadMashmol NUMERIC(18,3),
			Cshobe INT,
			WeightKala NUMERIC(18,3)
        );     
    INSERT  INTO #RptForushAndAvamelKala_Base   
    ( Factor ,   
        [Type] , 
		[Rank] ,   
        IdAnbar ,   
        IdKala ,   
        Mab ,   
        Takh ,   
        Ted,
		EzafMashmol,
		KasrMashmol,
		Ezaf,
		Kasr,
		Maliat,
		Mashmol,
		DarsadMashmol,
		WeightKala
    )   
    SELECT  Factor , 
			[Type] , 
			RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
            IdAnbr ,    
            TR.Idkala ,    
            SUM(Bes+Bed), 
            SUM(Takh) ,    
            SUM(TED),
				0,
				0,
				0,
				0,
				0,
			dbo.TR.Mashmol,
			dbo.TR.DarsadMashmol,
			SUM(TED*WeightKala) AS WeightKala
    FROM    dbo.TR 
        LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                        AND TR.Idkala = dbo.TblKala.IDKala 
    WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
			AND TR.Idkala > 0    
            AND DateR BETWEEN @Date1 AND @Date2 
			AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
			GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
			ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)

			
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactor;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactor		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactor 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
    GROUP BY tbl.Factor, tbl.[Type];   

	UPDATE #RptForushAndAvamelKala_MabFactor SET Mab = 1 WHERE Mab = 0
				
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgent; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgent 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgent   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 0 )
    GROUP BY tbl.Factor , tbl.[Type]  	
		

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactorMashmol;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactorMashmol		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
				
		
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgentMashmol; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgentMashmol 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgentMashmol   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	
				
				
	UPDATE tblKF SET 
	tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
	tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


	UPDATE tblKF SET 
	tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
	tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_Difference', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_Difference;   
	CREATE TABLE #RptForushAndAvamelKala_Difference 
	(   
		Factor INT ,   
	[Type] TINYINT , 
	Ezaf BIGINT ,
	Kasr BIGINT
	);    

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type


	UPDATE tblD SET 
	tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblAm.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgentMashmol AS tblAm
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0


	UPDATE tblKF SET 
	tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
	tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1
			
	DELETE FROM #RptForushAndAvamelKala_Difference

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

				
	UPDATE tblD SET 
	tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblA.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgent AS tblA
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

	UPDATE tblKF SET 
	tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
	tblKF.Kasr = tblKF.Kasr+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

	DELETE #RptForushAndAvamelKala_MabFactorMashmol
			
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
			 
   
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabMaliat; 
	CREATE TABLE #RptForushAndAvamelKala_MabMaliat 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Mab BIGINT 
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabMaliat   
    ( Factor ,   
        [Type] , 
		Mab
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes-dbo.TR.Bed) ELSE SUM(dbo.TR.Bed-dbo.TR.Bes) END
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	

	UPDATE tblKF SET 
	tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
	INNER JOIN #RptForushAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_DifferenceMaliat;   
	CREATE TABLE #RptForushAndAvamelKala_DifferenceMaliat 
	(   
		Factor INT ,   
		[Type] TINYINT , 
		Mab BIGINT 
	);    

	INSERT INTO #RptForushAndAvamelKala_DifferenceMaliat
	SELECT Factor,Type,SUM(Maliat) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Mab = tblM.Mab - tblD.Mab
		FROM #RptForushAndAvamelKala_MabMaliat AS tblM
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_DifferenceMaliat
	WHERE Mab = 0


	UPDATE tblKF SET 
	tblKF.Maliat = tblKF.Maliat+tblD.Mab
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	IF ( OBJECT_ID('#RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;   
	CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		 
        (   
			Shfactor INT ,   
            [Type] TINYINT , 
			Code VARCHAR(100) 
        );     
    INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp 
    SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
    FROM    #RptForushAndAvamelKala_Base AS tbl 
	LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
	WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
	IF (ISNULL(@Tasviye, '') <> '') 
	BEGIN 
		DELETE #RptForushAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
	END 


	IF ( OBJECT_ID('#RptForushAndBargashtForushAggregation_Final', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndBargashtForushAggregation_Final;   
	CREATE TABLE #RptForushAndBargashtForushAggregation_Final 
		( 
			IdAnbar INT , 
			AnbarName NVARCHAR(200) , 
			TedForush DECIMAL(18, 5) , 
			MabForush BIGINT , 
			TedBargasht DECIMAL(18, 5) , 
			MabBargasht BIGINT ,
			MabMaliatForush BIGINT,
			MabMaliatBargasht BIGINT,
			WeightKala NUMERIC(18,3)
		); 
	INSERT INTO #RptForushAndBargashtForushAggregation_Final 
	( IdAnbar , 
	    AnbarName , 
		TedForush , 
	    MabForush , 
	    TedBargasht , 
	    MabBargasht ,
		MabMaliatForush,
		MabMaliatBargasht,
		WeightKala
	) 
	SELECT 
    tr.IdAnbar ,
    ISNULL(ta.Name,'') AnbarName ,
	CASE tr.Type WHEN 203 THEN tr.Ted ELSE 0 END AS TedForush ,
	CASE tr.Type WHEN 203 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabForush,
	CASE tr.Type WHEN 104 THEN tr.Ted ELSE 0 END AS TedBargasht ,
	CASE tr.Type WHEN 104 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabBargasht,
	CASE tr.Type WHEN 203 THEN Maliat ELSE 0 END AS MabMaliatForush,
	CASE tr.Type WHEN 104 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
	CASE tr.Type WHEN 104 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
	FROM #RptForushAndAvamelKala_Base AS tr
	LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
    LEFT OUTER JOIN dbo.TblAnbar AS ta ON tr.IdAnbar = ta.ID 
    LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
    LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
	WHERE  ( @IdKala IS NULL
            OR 
			(@Toggle = 0 AND tr.IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala)))
			OR 
            (@Toggle = 1 AND tr.IdAnbar NOT IN
										(SELECT IDAnbar FROM dbo.TblKala 
										WHERE IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala))))
        )
		AND ( @Vizitor IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.VizitorID,0) IN (SELECT * FROM dbo.CSVToTable(@Vizitor)))
			OR 
            (@Toggle = 1 AND tr.IdAnbar NOT IN
											(SELECT t.IdAnbr FROM dbo.TR AS t
											INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
											WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.VizitorID IN (SELECT * FROM dbo.CSVToTable(@Vizitor))))
        )
		AND ( @Driver IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.Driver,0) IN (SELECT * FROM dbo.CSVToTable(@Driver)))
			OR 
			(@Toggle = 1 AND tr.IdAnbar NOT IN
											(SELECT t.IdAnbr FROM dbo.TR AS t
											INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
											WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.Driver IN (SELECT * FROM dbo.CSVToTable(@Driver))))
        )
		AND ( @GroupCode IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblKala.GroupCode,'') IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode)))
			OR 
			(@Toggle = 1 AND tr.IdAnbar NOT IN
											(SELECT IdAnbar FROM dbo.TblKala 
											WHERE GroupCode IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode))))
        )
		AND	( @Tasviye IS NULL 
			OR 
			EXISTS (SELECT * FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type])
		)
		AND ( @Moshtari IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.CustumCod,0) IN (SELECT * FROM  dbo.CSVToTable(@Moshtari)))
			OR 
			(@Toggle = 1 AND tr.IdAnbar NOT IN
											(SELECT t.IdAnbr FROM dbo.TR AS t
											INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
											WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.CustumCod IN (SELECT * FROM dbo.CSVToTable(@Moshtari))))
        )
	
	SELECT  CAST(ISNULL(tblA.id, 0) AS BIT) AS Tik , 
            tbl.IdAnbar , 
            tbl.AnbarName , 
             CAST(SUM(tbl.TedForush) AS FLOAT) AS TedForush ,
            SUM(tbl.MabForush) AS MabForush ,
			SUM(tbl.MabMaliatForush) AS MabMaliatForush ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedForush) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabForush) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatForush) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabForush+MabMaliatForush) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptForushAndBargashtForushAggregation_Final AS tbl 
			LEFT OUTER JOIN dbo.CSVToTable(@IdAnbar) AS tblA ON tblA.id = tbl.IdAnbar 
    GROUP BY CAST(ISNULL(tblA.id, 0) AS BIT) , 
            tbl.IdAnbar , 
			tbl.AnbarName 
    ORDER BY tbl.IdAnbar;	 
										  
END

GO

-- Procedure: [dbo].[RptForushAndBarghashForushDriver]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushDriver]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushDriver] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushDriver]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL,
	@Toggle BIT = 0 ,
	@Type VARCHAR(10) = '203,104'
AS
BEGIN
	IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL   
        DROP TABLE  #RptForushAndAvamelKala_Base;        
    CREATE TABLE #RptForushAndAvamelKala_Base   
        (   
            Factor INT ,   
            [Type] TINYINT , 
			DateR NVARCHAR(100),
			[Rank] INT ,   
            IdAnbar INT ,   
            IdKala INT ,   
			Mab BIGINT ,   
            Takh BIGINT ,   
            Ted DECIMAL(18, 5),
			EzafMashmol BIGINT,
			KasrMashmol BIGINT,
			Ezaf BIGINT,
			Kasr BIGINT,
			Maliat BIGINT,
			Mashmol TINYINT,
			DarsadMashmol NUMERIC(18,3),
			Cshobe INT,
			WeightKala NUMERIC(18,3)
        );     
    INSERT  INTO #RptForushAndAvamelKala_Base   
    ( Factor ,   
        [Type] , 
		[Rank] ,   
        IdAnbar ,   
        IdKala ,   
        Mab ,   
        Takh ,   
        Ted,
		EzafMashmol,
		KasrMashmol,
		Ezaf,
		Kasr,
		Maliat,
		Mashmol,
		DarsadMashmol,
		WeightKala
    )   
    SELECT  Factor , 
			[Type] , 
			RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
            IdAnbr ,    
            TR.Idkala ,    
            SUM(Bes+Bed), 
            SUM(Takh) ,    
            SUM(TED),
				0,
				0,
				0,
				0,
				0,
			dbo.TR.Mashmol,
			dbo.TR.DarsadMashmol,
			SUM(TED*WeightKala) AS WeightKala
    FROM    dbo.TR 
        LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                 AND TR.Idkala = dbo.TblKala.IDKala 
    WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
			AND TR.Idkala > 0    
            AND DateR BETWEEN @Date1 AND @Date2 
			AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
			GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
			ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)

				
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactor;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactor		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactor 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
    GROUP BY tbl.Factor, tbl.[Type];   


	UPDATE #RptForushAndAvamelKala_MabFactor SET Mab = 1 WHERE Mab = 0

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgent; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgent 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgent   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 0 )
    GROUP BY tbl.Factor , tbl.[Type]  	
					

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactorMashmol;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactorMashmol		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
				

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgentMashmol; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgentMashmol 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgentMashmol   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	
				
				
	UPDATE tblKF SET 
	tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
	tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


	UPDATE tblKF SET 
	tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
	tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_Difference', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_Difference;   
	CREATE TABLE #RptForushAndAvamelKala_Difference 
	(   
		Factor INT ,   
	[Type] TINYINT , 
	Ezaf BIGINT ,
	Kasr BIGINT
	);    

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblAm.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgentMashmol AS tblAm
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type

	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

	UPDATE tblKF SET 
	tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
	tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
	DELETE FROM #RptForushAndAvamelKala_Difference

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

				
	UPDATE tblD SET 
	tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblA.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgent AS tblA
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type

	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

	UPDATE tblKF SET 
	tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
	tblKF.Kasr = tblKF.Kasr+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	DELETE #RptForushAndAvamelKala_MabFactorMashmol
			
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabMaliat; 
	CREATE TABLE #RptForushAndAvamelKala_MabMaliat 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Mab BIGINT 
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabMaliat   
    ( Factor ,   
        [Type] , 
		Mab
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes-dbo.TR.Bed) ELSE SUM(dbo.TR.Bed-dbo.TR.Bes) END
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	


	UPDATE tblKF SET 
	tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
	INNER JOIN #RptForushAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_DifferenceMaliat;   
	CREATE TABLE #RptForushAndAvamelKala_DifferenceMaliat 
	(   
		Factor INT ,   
		[Type] TINYINT , 
		Mab BIGINT 
	);    

	INSERT INTO #RptForushAndAvamelKala_DifferenceMaliat
	SELECT Factor,Type,SUM(Maliat) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Mab = tblM.Mab - tblD.Mab
		FROM #RptForushAndAvamelKala_MabMaliat AS tblM
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_DifferenceMaliat
	WHERE Mab = 0


	UPDATE tblKF SET 
	tblKF.Maliat = tblKF.Maliat+tblD.Mab
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	IF ( OBJECT_ID('#RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;   
	CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		 
        (   
			Shfactor INT ,   
            [Type] TINYINT , 
			Code VARCHAR(100) 
        );     
    INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp 
    SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
    FROM    #RptForushAndAvamelKala_Base AS tbl 
	LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
	WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
	IF (ISNULL(@Tasviye, '') <> '') 
	BEGIN 
		DELETE #RptForushAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
	END 

	IF ( OBJECT_ID('#RptForushAndBargashtForushAggregation_Final', 'U') ) IS NOT NULL
		DROP TABLE  #RptForushAndBargashtForushAggregation_Final;  
	CREATE TABLE #RptForushAndBargashtForushAggregation_Final
		(
			DriverID INT ,
			DriverName NVARCHAR(200) ,
			TedForush DECIMAL(18, 5) ,
			MabForush BIGINT ,
			TedBargasht DECIMAL(18, 5) ,
			MabBargasht BIGINT,
			MabMaliatForush BIGINT,
			MabMaliatBargasht BIGINT,
			WeightKala NUMERIC(18,3)
		);
	INSERT INTO #RptForushAndBargashtForushAggregation_Final
	( 
		DriverID ,
		DriverName ,
		TedForush ,
		MabForush ,
		TedBargasht ,
		MabBargasht,
		MabMaliatForush,
		MabMaliatBargasht,
		WeightKala
	)
	SELECT 
    TblFactorOnvan.Driver ,
    LTRIM(RTRIM(TblPerson.Name+' '+ TblPerson.Famil)) COLLATE DATABASE_DEFAULT DriverName ,
	CASE tr.Type WHEN 203 THEN tr.Ted ELSE 0 END AS TedForush ,
	CASE tr.Type WHEN 203 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabForush,
	CASE tr.Type WHEN 104 THEN tr.Ted ELSE 0 END AS TedBargasht ,
	CASE tr.Type WHEN 104 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabBargasht,
	CASE tr.Type WHEN 203 THEN Maliat ELSE 0 END AS MabMaliatForush,
	CASE tr.Type WHEN 104 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
	CASE tr.Type WHEN 104 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
	FROM #RptForushAndAvamelKala_Base AS tr
    LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
    LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
    LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.Driver = dbo.TblPerson.Sh_ozviat
	WHERE  ( @IdKala IS NULL
            OR 
			(@Toggle = 0 AND tr.IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.Driver,0) NOT IN
															(SELECT f.Driver FROM dbo.TR AS t
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND t.IdKala IN (SELECT * FROM dbo.CSVToTable(@IdKala))))
        )
		AND ( @IdAnbar IS NULL
            OR 
			(@Toggle = 0 AND tr.IdAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.Driver,0) NOT IN
															(SELECT f.Driver FROM dbo.TR AS t
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND t.IdAnbr IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))))
        )
		AND ( @Vizitor IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.VizitorID,0) IN (SELECT * FROM dbo.CSVToTable(@Vizitor)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.Driver,0) NOT IN
															(SELECT Driver FROM dbo.TblFactorOnvan WHERE Type IN(203,104) AND  VizitorID IN (SELECT * FROM dbo.CSVToTable(@Vizitor))))
        )
		AND ( @GroupCode IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblKala.GroupCode,'') IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode)))
			OR 
			(@Toggle = 1 AND ISNULL(TblFactorOnvan.Driver,0) NOT IN
															(SELECT f.Driver FROM dbo.TR AS t
															INNER JOIN dbo.TblKala AS k ON t.Idkala = k.IDKala AND t.IdAnbr = k.IDAnbar
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND k.GroupCode IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode))))
        )
		AND	( @Tasviye IS NULL 
			OR 
			EXISTS (SELECT * FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type])
		)
		AND ( @Moshtari IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.CustumCod,0) IN (SELECT * FROM  dbo.CSVToTable(@Moshtari)))
			OR 
			(@Toggle = 1 AND ISNULL(TblFactorOnvan.Driver,0) NOT IN
															(SELECT Driver FROM dbo.TblFactorOnvan WHERE Type IN(SELECT * FROM dbo.CSVToTable(@Type)) AND CustumCod IN (SELECT * FROM dbo.CSVToTable(@Driver))))
        )
	
	SELECT  CAST(ISNULL(tblM.id, 0) AS BIT) AS Tik ,
            tbl.DriverID ,
            tbl.DriverName ,
             CAST(SUM(tbl.TedForush) AS FLOAT) AS TedForush ,
            SUM(tbl.MabForush) AS MabForush ,
			SUM(tbl.MabMaliatForush) AS MabMaliatForush ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedForush) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabForush) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatForush) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabForush+MabMaliatForush) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptForushAndBargashtForushAggregation_Final AS tbl
			LEFT OUTER JOIN dbo.CSVToTable(@Driver) AS tblM ON tblM.id = tbl.DriverID
    GROUP BY CAST(ISNULL(tblM.id, 0) AS BIT) ,
            tbl.DriverID ,
			tbl.DriverName
    ORDER BY tbl.DriverID;	
										  
END

GO

-- Procedure: [dbo].[RptForushAndBarghashForushFactor]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushFactor]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushFactor] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushFactor] 
	@Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL  ,
	@Type VARCHAR(10) = '203,104'
AS
BEGIN

	DECLARE @dtfactor1 TABLE(factor INT,type INT)
	INSERT INTO @dtfactor1
	(
	    factor,
	    type
	)
	SELECT DISTINCT t.Factor,t.Type FROM tr AS t 
	INNER JOIN (SELECT IDAnbar,IDKala FROM dbo.TblKala 
				WHERE (@GroupCode IS NULL OR ISNULL(GroupCode,'') IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode)))
				AND (@IdAnbar IS NULL OR IDAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar)))
				AND (@IdKala IS NULL OR IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala)))) AS k ON k.idanbar=t.IdAnbr AND k.idkala=t.Idkala
	WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type))

	IF @Tasviye IS NOT NULL
	BEGIN
	    DELETE f FROM @dtfactor1 AS f WHERE NOT EXISTS(
		SELECT * FROM (
		SELECT Factor, Type, CAST(Srfsl AS VARCHAR) + '-' + CAST(Moin AS VARCHAR) + '-' + CAST(HSB AS VARCHAR) AS code FROM TR 
		WHERE Tp1=0 AND Idkala=0 AND Factor>0 AND Type IN (SELECT * FROM dbo.CSVToTable(@Type))) AS tt 
		WHERE tt.Type=f.Type AND tt.Factor=f.factor AND tt.Code COLLATE DATABASE_DEFAULT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)))
	END
	

	DECLARE @dtfactor2 TABLE(factor INT,type INT,Weightfactor DECIMAL(18,3),ted NUMERIC(25,7),mab BIGINT,takh BIGINT, mabmashmol BIGINT, mabmaliat BIGINT,mabkosorat BIGINT,mabezafat BIGINT,mabmashmolkosorat BIGINT, mabmashmolezafat BIGINT,mabkol BIGINT)
	INSERT INTO @dtfactor2
	(
	    factor,
	    type,
		Weightfactor,
		ted,
		mab,
		takh,
		mabmashmol,
		mabmaliat,
		mabkosorat,
		mabezafat,
		mabmashmolkosorat,
		mabmashmolezafat,
		mabkol
	)
	SELECT t.Factor,t.Type,SUM(t.TED*ISNULL(k.WeightKala,0)) AS Weightfactor,
		SUM(t.TED) AS Ted,
		SUM(CASE WHEN t.Idkala>0 then t.bed+t.bes+t.Takh-t.Maliat ELSE 0 END) AS mab,
		SUM(t.Takh) AS takh,
		SUM(CASE WHEN t.Mashmol=1 THEN t.bed+t.bes ELSE 0 END) AS mabmashmol,
		CASE WHEN SUM(t.Maliat)>0 THEN SUM(t.Maliat) ELSE SUM(CASE WHEN avamel.Maliat=1 THEN t.bed+t.bes ELSE 0 END) END AS mabmaliat,
		SUM(CASE WHEN avamel.State=1 THEN t.bed+t.bes ELSE 0 END) AS mabkosorat,
		SUM(CASE WHEN avamel.State=0 AND avamel.Maliat=0 THEN t.bed+t.bes ELSE 0 END) AS mabezafat,
		SUM(CASE WHEN avamel.State=1 AND avamel.Mashmol=1 THEN t.bed+t.bes ELSE 0 END) AS mabmashmolkosorat,
		SUM(CASE WHEN avamel.State=0 AND avamel.Maliat=0 AND avamel.Mashmol=1 THEN t.bed+t.bes ELSE 0 END) AS mabmashmolezafat ,
		SUM(CASE WHEN t.Idkala>0 then t.bed+t.bes 
				 WHEN t.Tp1>0 THEN CASE WHEN t.type=203 then t.bes-t.Bed ELSE t.bed-t.Bes END
				 ELSE 0 END) AS mabkol
	FROM dbo.TR AS t
	INNER JOIN @dtfactor1 AS f ON f.factor=t.factor AND f.type = t.Type
	LEFT JOIN dbo.TblKala AS k ON  k.IDAnbar =t.IdAnbr AND k.IDKala = t.Idkala
	LEFT JOIN dbo.TblFactorAvamel AS avamel ON t.IdAmel=avamel.Id AND t.Tp1>0
	GROUP BY t.Factor,t.Type



	
	SELECT f.ShFactor,f.Type,tt.Name AS typename,f.CustumCod,ISNULL(p.Name,'') + ' ' +ISNULL(p.Famil,'') AS custumname ,f.DateFactor,
	f2.mab,f2.takh,f2.mabkosorat,f2.mabmashmolkosorat,f2.mabezafat,f2.mabmashmolezafat,f2.mabmashmol,f2.mabmaliat,f2.mabkol,
	f.CShobe,ISNULL(cs.Name , '') AS shobename,f2.Weightfactor,f2.ted
	FROM dbo.TblFactorOnvan AS f
	INNER JOIN @dtfactor2 AS f2 ON f2.factor=f.ShFactor AND f2.type = f.Type
	INNER JOIN dbo.TblTypeTR AS tt ON tt.ID = f.Type
	LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat=f.CustumCod
	LEFT JOIN dbo.TblCompanyShobe AS cs ON cs.Id = f.CShobe
	WHERE f.DateFactor BETWEEN @Date1 AND @Date2
	AND (@CShobe = 0 OR f.CShobe = @CShobe)
	AND (@Moshtari IS NULL OR f.CustumCod IN (SELECT * FROM dbo.CSVToTable(@Moshtari)))
	AND (@Vizitor IS NULL OR f.VizitorID IN (SELECT * FROM dbo.CSVToTable(@Vizitor)))
	AND (@Driver IS NULL OR f.Driver IN (SELECT * FROM dbo.CSVToTable(@Driver)))
	ORDER BY f.Type,f.ShFactor

END

GO

-- Procedure: [dbo].[RptForushAndBarghashForushGroupKala]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushGroupKala]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushGroupKala] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushGroupKala]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL,
	@Toggle BIT = 0 ,
	@Type VARCHAR(10) = '203,104'
AS
BEGIN
	IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL   
        DROP TABLE  #RptForushAndAvamelKala_Base;        
    CREATE TABLE #RptForushAndAvamelKala_Base   
        (   
            Factor INT ,   
            [Type] TINYINT , 
			DateR NVARCHAR(100),
			[Rank] INT ,   
            IdAnbar INT ,   
            IdKala INT ,   
			Mab BIGINT ,   
            Takh BIGINT ,   
            Ted DECIMAL(18, 5),
			EzafMashmol BIGINT,
			KasrMashmol BIGINT,
			Ezaf BIGINT,
			Kasr BIGINT,
			Maliat BIGINT,
			Mashmol TINYINT,
			DarsadMashmol NUMERIC(18,3),
			Cshobe INT,
			WeightKala NUMERIC(18,3)
        );     
    INSERT  INTO #RptForushAndAvamelKala_Base   
    ( Factor ,   
        [Type] , 
		[Rank] ,   
        IdAnbar ,   
        IdKala ,   
        Mab ,   
        Takh ,   
        Ted,
		EzafMashmol,
		KasrMashmol,
		Ezaf,
		Kasr,
		Maliat,
		Mashmol,
		DarsadMashmol,
		WeightKala
    )   
    SELECT  Factor , 
			[Type] , 
			RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
            IdAnbr ,    
            TR.Idkala ,    
            SUM(Bes+Bed), 
            SUM(Takh) ,    
            SUM(TED),
				0,
				0,
				0,
				0,
				0,
			dbo.TR.Mashmol,
			dbo.TR.DarsadMashmol,
			SUM(TED*WeightKala) AS WeightKala
    FROM    dbo.TR 
        LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                        AND TR.Idkala = dbo.TblKala.IDKala 
    WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
			AND TR.Idkala > 0    
            AND DateR BETWEEN @Date1 AND @Date2 
			AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
			GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
			ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
						
	
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactor;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactor		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactor 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
    GROUP BY tbl.Factor, tbl.[Type];   


	UPDATE #RptForushAndAvamelKala_MabFactor SET Mab = 1 WHERE Mab = 0

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgent; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgent 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgent   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 0 )
    GROUP BY tbl.Factor , tbl.[Type]  		

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactorMashmol;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactorMashmol		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
	
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgentMashmol; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgentMashmol 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgentMashmol   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	
				
				
	UPDATE tblKF SET 
	tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
	tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type

	UPDATE tblKF SET 
	tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
	tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0

	IF ( OBJECT_ID('#RptForushAndAvamelKala_Difference', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_Difference;   
	CREATE TABLE #RptForushAndAvamelKala_Difference 
	(   
		Factor INT ,   
	[Type] TINYINT , 
	Ezaf BIGINT ,
	Kasr BIGINT
	);    

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblAm.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgentMashmol AS tblAm
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type

	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

	UPDATE tblKF SET 
	tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
	tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1
		
	DELETE FROM #RptForushAndAvamelKala_Difference

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type
	
	UPDATE tblD SET 
	tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblA.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgent AS tblA
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

				

	UPDATE tblKF SET 
	tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
	tblKF.Kasr = tblKF.Kasr+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

	DELETE #RptForushAndAvamelKala_MabFactorMashmol
			
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabMaliat; 
	CREATE TABLE #RptForushAndAvamelKala_MabMaliat 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Mab BIGINT 
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabMaliat   
    ( Factor ,   
        [Type] , 
		Mab
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes-dbo.TR.Bed) ELSE SUM(dbo.TR.Bed-dbo.TR.Bes) END
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	

	UPDATE tblKF SET 
	tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
	INNER JOIN #RptForushAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_DifferenceMaliat;   
	CREATE TABLE #RptForushAndAvamelKala_DifferenceMaliat 
	(   
		Factor INT ,   
		[Type] TINYINT , 
		Mab BIGINT 
	);    

	INSERT INTO #RptForushAndAvamelKala_DifferenceMaliat
	SELECT Factor,Type,SUM(Maliat) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Mab = tblM.Mab - tblD.Mab
		FROM #RptForushAndAvamelKala_MabMaliat AS tblM
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_DifferenceMaliat
	WHERE Mab = 0


	UPDATE tblKF SET 
	tblKF.Maliat = tblKF.Maliat+tblD.Mab
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	IF ( OBJECT_ID('#RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;   
	CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		 
        (   
			Shfactor INT ,   
            [Type] TINYINT , 
			Code VARCHAR(100) 
        );     
    INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp 
    SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
    FROM    #RptForushAndAvamelKala_Base AS tbl 
	LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
	WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
	IF (ISNULL(@Tasviye, '') <> '') 
	BEGIN 
		DELETE #RptForushAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
	END 

	IF ( OBJECT_ID('#RptForushAndBargashtForushAggregation_Final', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndBargashtForushAggregation_Final;   
	CREATE TABLE #RptForushAndBargashtForushAggregation_Final 
		( 
			GroupCode NVARCHAR(200) , 
			GroupName NVARCHAR(200) , 
			TedForush DECIMAL(18, 5) , 
			MabForush BIGINT , 
			TedBargasht DECIMAL(18, 5) , 
			MabBargasht BIGINT,
			MabMaliatForush BIGINT,
			MabMaliatBargasht BIGINT ,
			WeightKala NUMERIC(18,3)
		); 
	INSERT INTO #RptForushAndBargashtForushAggregation_Final 
	( GroupCode , 
	    GroupName , 
		TedForush , 
	    MabForush , 
	    TedBargasht , 
	    MabBargasht,
		MabMaliatForush,
		MabMaliatBargasht,
		WeightKala
	) 
	SELECT 
    ISNULL(dbo.TblKala.GroupCode,'') AS  GroupCode,
    ISNULL(dbo.TblGroupKala.Name,'') GroupName ,
	CASE tr.Type WHEN 203 THEN tr.Ted ELSE 0 END AS TedForush ,
	CASE tr.Type WHEN 203 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabForush,
	CASE tr.Type WHEN 104 THEN tr.Ted ELSE 0 END AS TedBargasht ,
	CASE tr.Type WHEN 104 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabBargasht,
	CASE tr.Type WHEN 203 THEN Maliat ELSE 0 END AS MabMaliatForush,
	CASE tr.Type WHEN 104 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
	CASE tr.Type WHEN 104 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
	FROM #RptForushAndAvamelKala_Base AS tr
    LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
	LEFT OUTER JOIN dbo.TblGroupKala ON dbo.TblGroupKala.Code COLLATE SQL_Latin1_General_CP1_CI_AS = dbo.TblKala.GroupCode
    LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
    LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
	WHERE  ( @IdKala IS NULL
            OR 
			(@Toggle = 0 AND tr.IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala)))
			OR 
            (@Toggle = 1 AND ISNULL(TblKala.GroupCode,'') NOT IN
										(SELECT GroupCode FROM dbo.TblKala 
										WHERE IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala))))
        )
		AND ( @IdAnbar IS NULL
            OR 
			(@Toggle = 0 AND tr.IdAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar)))
			OR 
            (@Toggle = 1 AND ISNULL(TblKala.GroupCode,'') NOT IN
										(SELECT GroupCode FROM dbo.TblKala 
										WHERE IdAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))))
        )
		AND ( @Vizitor IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.VizitorID,0) IN (SELECT * FROM dbo.CSVToTable(@Vizitor)))
			OR 
            (@Toggle = 1 AND ISNULL(TblKala.GroupCode,'') NOT IN
										(SELECT k.GroupCode FROM dbo.TR AS t
										INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
										INNER JOIN dbo.TblKala AS k ON k.IDAnbar=t.IdAnbr AND k.IDKala=t.Idkala
										WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.VizitorID IN (SELECT * FROM dbo.CSVToTable(@Vizitor))))
        )
		AND ( @Driver IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.Driver,0) IN (SELECT * FROM dbo.CSVToTable(@Driver)))
			OR 
			(@Toggle = 1 AND ISNULL(TblKala.GroupCode,'') NOT IN
										(SELECT k.GroupCode FROM dbo.TR AS t
										INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
										INNER JOIN dbo.TblKala AS k ON k.IDAnbar=t.IdAnbr AND k.IDKala=t.Idkala
										WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.Driver IN (SELECT * FROM dbo.CSVToTable(@Driver))))
        )
		AND	( @Tasviye IS NULL 
			OR 
			EXISTS (SELECT * FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type])
		)
		AND ( @Moshtari IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.CustumCod,0) IN (SELECT * FROM  dbo.CSVToTable(@Moshtari)))
			OR 
			(@Toggle = 1 AND ISNULL(TblKala.GroupCode,'') NOT IN
										(SELECT k.GroupCode FROM dbo.TR AS t
										INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
										INNER JOIN dbo.TblKala AS k ON k.IDAnbar=t.IdAnbr AND k.IDKala=t.Idkala
										WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.CustumCod IN (SELECT * FROM dbo.CSVToTable(@Moshtari))))
        )
	
	SELECT   CAST((CASE WHEN tblK.id IS NULL THEN 0 ELSE 1 END) AS bit) AS Tik , 
            tbl.GroupCode , 
            tbl.GroupName , 
            CAST(SUM(tbl.TedForush) AS FLOAT) AS TedForush ,
            SUM(tbl.MabForush) AS MabForush ,
			SUM(tbl.MabMaliatForush) AS MabMaliatForush ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedForush) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabForush) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatForush) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabForush+MabMaliatForush) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptForushAndBargashtForushAggregation_Final AS tbl 
			LEFT OUTER JOIN dbo.CSVToTableStr(@GroupCode) AS tblK ON tblK.id COLLATE SQL_Latin1_General_CP1_CI_AS = tbl.GroupCode 
    GROUP BY tblk.id , 
            tbl.GroupCode , 
			tbl.GroupName
    ORDER BY tbl.GroupCode;	 
										  
END

GO

-- Procedure: [dbo].[RptForushAndBarghashForushKala]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushKala]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushKala] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushKala]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL,
	@Toggle BIT = 0 ,
	@Type VARCHAR(10) = '203,104'
AS
BEGIN
	IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL   
        DROP TABLE  #RptForushAndAvamelKala_Base;        
    CREATE TABLE #RptForushAndAvamelKala_Base   
        (   
            Factor INT ,   
            [Type] TINYINT , 
			DateR NVARCHAR(100),
			[Rank] INT ,   
            IdAnbar INT ,   
            IdKala INT ,   
			Mab BIGINT ,   
            Takh BIGINT ,   
            Ted DECIMAL(18, 5),
			EzafMashmol BIGINT,
			KasrMashmol BIGINT,
			Ezaf BIGINT,
			Kasr BIGINT,
			Maliat BIGINT,
			Mashmol TINYINT,
			DarsadMashmol NUMERIC(18,3),
			Cshobe INT,
			WeightKala NUMERIC(18,3)
        );     
    INSERT  INTO #RptForushAndAvamelKala_Base   
    ( Factor ,   
        [Type] , 
		[Rank] ,   
        IdAnbar ,   
        IdKala ,   
        Mab ,   
        Takh ,   
        Ted,
		EzafMashmol,
		KasrMashmol,
		Ezaf,
		Kasr,
		Maliat,
		Mashmol,
		DarsadMashmol,
		WeightKala
    )   
    SELECT  Factor , 
			[Type] , 
			RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
            IdAnbr ,    
            TR.Idkala ,    
            SUM(Bes+Bed), 
            SUM(Takh) ,    
            SUM(TED),
				0,
				0,
				0,
				0,
				0,
			dbo.TR.Mashmol,
			dbo.TR.DarsadMashmol,
			SUM(TED*WeightKala) AS WeightKala
    FROM    dbo.TR 
        LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                        AND TR.Idkala = dbo.TblKala.IDKala 
    WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
			AND TR.Idkala > 0    
            AND DateR BETWEEN @Date1 AND @Date2 
			AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
			GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
			ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
			
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactor;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactor		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactor 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
    GROUP BY tbl.Factor, tbl.[Type];   

	UPDATE #RptForushAndAvamelKala_MabFactor SET Mab = 1 WHERE Mab = 0

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgent; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgent 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgent   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 0 )
    GROUP BY tbl.Factor , tbl.[Type]  	
		

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactorMashmol;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactorMashmol		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
						
				
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgentMashmol; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgentMashmol 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgentMashmol   
    ( Factor ,   
        [Type] , 
		Ezaf ,   
        Kasr    
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	

	UPDATE tblKF SET 
	tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
	tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type

	UPDATE tblKF SET 
	tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
	tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_Difference', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_Difference;   
	CREATE TABLE #RptForushAndAvamelKala_Difference 
	(   
		Factor INT ,   
	[Type] TINYINT , 
	Ezaf BIGINT ,
	Kasr BIGINT
	);    

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type


	UPDATE tblD SET 
	tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblAm.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgentMashmol AS tblAm
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type

	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

	UPDATE tblKF SET 
	tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
	tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
	DELETE FROM #RptForushAndAvamelKala_Difference


	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

				
	UPDATE tblD SET 
	tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblA.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgent AS tblA
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0


	UPDATE tblKF SET 
	tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
	tblKF.Kasr = tblKF.Kasr+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	DELETE #RptForushAndAvamelKala_MabFactorMashmol
			
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabMaliat; 
	CREATE TABLE #RptForushAndAvamelKala_MabMaliat 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Mab BIGINT 
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabMaliat   
    ( Factor ,   
        [Type] , 
		Mab
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes-dbo.TR.Bed) ELSE SUM(dbo.TR.Bed-dbo.TR.Bes) END
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	


	UPDATE tblKF SET 
	tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
	INNER JOIN #RptForushAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_DifferenceMaliat;   
	CREATE TABLE #RptForushAndAvamelKala_DifferenceMaliat 
	(   
		Factor INT ,   
		[Type] TINYINT , 
		Mab BIGINT 
	);    

	INSERT INTO #RptForushAndAvamelKala_DifferenceMaliat
	SELECT Factor,Type,SUM(Maliat) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Mab = tblM.Mab - tblD.Mab
		FROM #RptForushAndAvamelKala_MabMaliat AS tblM
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_DifferenceMaliat
	WHERE Mab = 0


	UPDATE tblKF SET 
	tblKF.Maliat = tblKF.Maliat+tblD.Mab
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	IF ( OBJECT_ID('#RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;   
	CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		 
        (   
			Shfactor INT ,   
            [Type] TINYINT , 
			Code VARCHAR(100) 
        );     
    INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp 
    SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
    FROM    #RptForushAndAvamelKala_Base AS tbl 
	LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
	WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
	IF (ISNULL(@Tasviye, '') <> '') 
	BEGIN 
		DELETE #RptForushAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
	END 
			

	IF ( OBJECT_ID('#RptForushAndBargashtForushAggregation_Final', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndBargashtForushAggregation_Final;   
	CREATE TABLE #RptForushAndBargashtForushAggregation_Final 
		( 
			IdKala INT , 
			KalaName NVARCHAR(200) , 
			TedForush DECIMAL(18, 5) , 
			MabForush BIGINT , 
			TedBargasht DECIMAL(18, 5) , 
			MabBargasht BIGINT ,
			MabMaliatForush BIGINT,
			MabMaliatBargasht BIGINT,
			WeightKala NUMERIC(18,3)
		); 
	INSERT INTO #RptForushAndBargashtForushAggregation_Final 
	( IdKala , 
		KalaName , 
		TedForush , 
		MabForush , 
		TedBargasht , 
		MabBargasht ,
		MabMaliatForush,
		MabMaliatBargasht,
		WeightKala
	) 
	SELECT 
    tr.IdKala ,
    ISNULL(dbo.TblKala.Name,'') KalaName ,
	CASE tr.Type WHEN 203 THEN tr.Ted ELSE 0 END AS TedForush ,
	CASE tr.Type WHEN 203 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabForush,
	CASE tr.Type WHEN 104 THEN tr.Ted ELSE 0 END AS TedBargasht ,
	CASE tr.Type WHEN 104 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabBargasht,
	CASE tr.Type WHEN 203 THEN Maliat ELSE 0 END AS MabMaliatForush,
	CASE tr.Type WHEN 104 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
	CASE tr.Type WHEN 104 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
	FROM #RptForushAndAvamelKala_Base AS tr
    LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
    LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
    LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
	WHERE( @IdAnbar IS NULL
            OR 
			(@Toggle = 0 AND tr.IdAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar)))
			OR 
            (@Toggle = 1 AND tr.IdKala NOT IN
										(SELECT Idkala FROM dbo.TblKala 
										WHERE IDAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))))
        )
		AND ( @Vizitor IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.VizitorID,0) IN (SELECT * FROM dbo.CSVToTable(@Vizitor)))
			OR 
            (@Toggle = 1 AND tr.IdKala NOT IN
											(SELECT t.IdKala FROM dbo.TR AS t
											INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
											WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.VizitorID IN (SELECT * FROM dbo.CSVToTable(@Vizitor))))
        )
		AND ( @Driver IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.Driver,0) IN (SELECT * FROM dbo.CSVToTable(@Driver)))
			OR 
			(@Toggle = 1 AND tr.IdKala NOT IN
											(SELECT t.IdKala FROM dbo.TR AS t
											INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
											WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.Driver IN (SELECT * FROM dbo.CSVToTable(@Driver))))
        )
		AND ( @GroupCode IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblKala.GroupCode,'') IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode)))
			OR 
			(@Toggle = 1 AND tr.IdKala NOT IN
											(SELECT IdKala FROM dbo.TblKala 
											WHERE GroupCode IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode))))
        )
		AND	( @Tasviye IS NULL 
			OR 
			EXISTS (SELECT * FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type])
		)
		AND ( @Moshtari IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.CustumCod,0) IN (SELECT * FROM  dbo.CSVToTable(@Moshtari)))
			OR 
			(@Toggle = 1 AND tr.IdKala NOT IN
											(SELECT t.IdKala FROM dbo.TR AS t
											INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
											WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND f.CustumCod IN (SELECT * FROM dbo.CSVToTable(@Moshtari))))
        )
	
	SELECT  CAST(ISNULL(tblK.id, 0) AS BIT) AS Tik , 
            tbl.IdKala , 
            tbl.KalaName , 
			CAST(SUM(tbl.TedForush) AS FLOAT) AS TedForush ,
            SUM(tbl.MabForush) AS MabForush ,
			SUM(tbl.MabMaliatForush) AS MabMaliatForush ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedForush) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabForush) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatForush) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabForush+MabMaliatForush) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptForushAndBargashtForushAggregation_Final AS tbl 
			LEFT OUTER JOIN dbo.CSVToTable(@IdKala) AS tblK ON tblK.id = tbl.IdKala 
    GROUP BY CAST(ISNULL(tblK.id, 0) AS BIT) , 
            tbl.IdKala , 
			tbl.KalaName 
    ORDER BY tbl.IdKala;	 
										  
END

GO

-- Procedure: [dbo].[RptForushAndBarghashForushMoshtari]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushMoshtari]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushMoshtari] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushMoshtari]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL,
	@Toggle BIT = 0,
	@Type VARCHAR(10) = '203,104'
AS
BEGIN
	IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL   
        DROP TABLE  #RptForushAndAvamelKala_Base;        
    CREATE TABLE #RptForushAndAvamelKala_Base   
        (   
            Factor INT ,   
            [Type] TINYINT , 
			DateR NVARCHAR(100),
			[Rank] INT ,   
            IdAnbar INT ,   
            IdKala INT ,   
			Mab BIGINT ,   
            Takh BIGINT ,   
            Ted DECIMAL(18, 5),
			EzafMashmol BIGINT,
			KasrMashmol BIGINT,
			Ezaf BIGINT,
			Kasr BIGINT,
			Maliat BIGINT,
			Mashmol TINYINT,
			DarsadMashmol NUMERIC(18,3),
			Cshobe INT,
			WeightKala NUMERIC(18,3)
        );     
    INSERT  INTO #RptForushAndAvamelKala_Base   
            ( Factor ,   
                [Type] , 
				[Rank] ,   
                IdAnbar ,   
                IdKala ,   
                Mab ,   
                Takh ,   
                Ted,
				EzafMashmol,
				KasrMashmol,
				Ezaf,
				Kasr,
				Maliat,
				Mashmol,
				DarsadMashmol,
				WeightKala
            )   
    SELECT  Factor , 
			[Type] , 
			RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
            IdAnbr ,    
            TR.Idkala ,    
            SUM(Bes+Bed), 
            SUM(Takh) ,    
            SUM(TED),
				0,
				0,
				0,
				0,
				0,
			dbo.TR.Mashmol,
			dbo.TR.DarsadMashmol,
			SUM(TED*WeightKala) AS WeightKala
    FROM    dbo.TR 
        LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                        AND TR.Idkala = dbo.TblKala.IDKala 
    WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
			AND TR.Idkala > 0    
            AND DateR BETWEEN @Date1 AND @Date2 
			AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
			GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
			ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
		
						
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactor;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactor		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactor 
            SELECT  tbl.Factor, tbl.[Type], 
                    SUM(tbl.Mab)   
            FROM    #RptForushAndAvamelKala_Base AS tbl   
            GROUP BY tbl.Factor, tbl.[Type];   

	UPDATE #RptForushAndAvamelKala_MabFactor SET Mab = 1 WHERE Mab = 0

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgent; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgent 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgent   
            ( Factor ,   
                [Type] , 
				Ezaf ,   
                Kasr    
            )   
            SELECT  tbl.Factor , 
					tbl.[Type] , 
                    CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
					CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
            FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
                    INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
					LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
            WHERE    
                    Idkala = 0   
                    AND Tp1 > 0  
					AND ( ISNULL(fa.Maliat, 0) = 0 )
					AND ( ISNULL(fa.Mashmol, 0) = 0 )
            GROUP BY tbl.Factor , tbl.[Type]  	

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactorMashmol;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactorMashmol		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
            SELECT  tbl.Factor, tbl.[Type], 
                    SUM(tbl.Mab)   
            FROM    #RptForushAndAvamelKala_Base AS tbl   
			WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
            GROUP BY tbl.Factor, tbl.[Type];   
				
				
				
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgentMashmol; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgentMashmol 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgentMashmol   
            ( Factor ,   
                [Type] , 
				Ezaf ,   
                Kasr    
            )   
	SELECT  tbl.Factor , 
			tbl.[Type] , 
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
	FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
			INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
	WHERE    
			Idkala = 0   
			AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 1 )
	GROUP BY tbl.Factor , tbl.[Type]  	
				
				
	UPDATE tblKF SET 
	tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
	tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


	UPDATE tblKF SET 
	tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
	tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_Difference', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_Difference;   
	CREATE TABLE #RptForushAndAvamelKala_Difference 
	(   
		Factor INT ,   
	[Type] TINYINT , 
	Ezaf BIGINT ,
	Kasr BIGINT
	);    

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type


	UPDATE tblD SET 
	tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblAm.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgentMashmol AS tblAm
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type

	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0


	UPDATE tblKF SET 
	tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
	tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
	DELETE FROM #RptForushAndAvamelKala_Difference

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type
				
	UPDATE tblD SET 
	tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblA.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgent AS tblA
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type

	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

	UPDATE tblKF SET 
	tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
	tblKF.Kasr = tblKF.Kasr+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

	DELETE #RptForushAndAvamelKala_MabFactorMashmol
			
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabMaliat; 
	CREATE TABLE #RptForushAndAvamelKala_MabMaliat 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Mab BIGINT 
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabMaliat   
            ( Factor ,   
                [Type] , 
				Mab
            )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes-dbo.TR.Bed) ELSE SUM(dbo.TR.Bed-dbo.TR.Bes) END
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	

	UPDATE tblKF SET 
	tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
	INNER JOIN #RptForushAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_DifferenceMaliat;   
	CREATE TABLE #RptForushAndAvamelKala_DifferenceMaliat 
	(   
		Factor INT ,   
		[Type] TINYINT , 
		Mab BIGINT 
	);    

	INSERT INTO #RptForushAndAvamelKala_DifferenceMaliat
	SELECT Factor,Type,SUM(Maliat) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Mab = tblM.Mab - tblD.Mab
		FROM #RptForushAndAvamelKala_MabMaliat AS tblM
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_DifferenceMaliat
	WHERE Mab = 0


	UPDATE tblKF SET 
	tblKF.Maliat = tblKF.Maliat+tblD.Mab
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	IF ( OBJECT_ID('#RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;   
	CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		 
        (   
			Shfactor INT ,   
            [Type] TINYINT , 
			Code VARCHAR(100) 
        );     
    INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp 
            SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
            FROM    #RptForushAndAvamelKala_Base AS tbl 
			LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
			WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
	IF (ISNULL(@Tasviye, '') <> '') 
	BEGIN 
		DELETE #RptForushAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
	END 
			
			

	IF ( OBJECT_ID('#RptForushAndBargashtForushAggregation_Final', 'U') ) IS NOT NULL
		DROP TABLE  #RptForushAndBargashtForushAggregation_Final;  
	CREATE TABLE #RptForushAndBargashtForushAggregation_Final
    (
		CustomerId INT ,
		CustomerName NVARCHAR(200) ,
        TedForush DECIMAL(18, 5) ,
        MabForush BIGINT ,
        TedBargasht DECIMAL(18, 5) ,
        MabBargasht BIGINT,
		MabMaliatForush BIGINT,
		MabMaliatBargasht BIGINT,
	    WeightKala NUMERIC(18,3)
    );
	INSERT INTO #RptForushAndBargashtForushAggregation_Final
	    ( 
			CustomerId ,
	        CustomerName ,
			TedForush ,
	        MabForush ,
	        TedBargasht ,
	        MabBargasht,
			MabMaliatForush,
			MabMaliatBargasht,
			WeightKala
	    )


	SELECT 
    ISNULL(TblFactorOnvan.CustumCod,0) as CustomerId ,
    ISNULL(LTRIM(RTRIM(TblPerson.Name+' '+ TblPerson.Famil)),'') COLLATE DATABASE_DEFAULT CustomerName ,
	CASE tr.Type WHEN 203 THEN tr.Ted ELSE 0 END AS TedForush ,
	CASE tr.Type WHEN 203 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabForush,
	CASE tr.Type WHEN 104 THEN tr.Ted ELSE 0 END AS TedBargasht ,
	CASE tr.Type WHEN 104 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabBargasht,
	CASE tr.Type WHEN 203 THEN Maliat ELSE 0 END AS MabMaliatForush,
	CASE tr.Type WHEN 104 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
	CASE tr.Type WHEN 104 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
	FROM #RptForushAndAvamelKala_Base AS tr
    LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
    LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
    LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
	WHERE  ( @IdKala IS NULL
            OR 
			(@Toggle = 0 AND tr.IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.CustumCod,0) NOT IN
															(SELECT f.CustumCod FROM dbo.TR AS t
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND t.IdKala IN (SELECT * FROM dbo.CSVToTable(@IdKala))))
        )
		AND ( @IdAnbar IS NULL
            OR 
			(@Toggle = 0 AND tr.IdAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.CustumCod,0) NOT IN
															(SELECT f.CustumCod FROM dbo.TR AS t
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND t.IdAnbr IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))))
        )
		AND ( @Vizitor IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.VizitorID,0) IN (SELECT * FROM dbo.CSVToTable(@Vizitor)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.CustumCod,0) NOT IN
															(SELECT CustumCod FROM dbo.TblFactorOnvan WHERE Type IN(SELECT * FROM dbo.CSVToTable(@Type)) AND  VizitorID IN (SELECT * FROM dbo.CSVToTable(@Vizitor))))
        )
		AND ( @Driver IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.Driver,0) IN (SELECT * FROM dbo.CSVToTable(@Driver)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.CustumCod,0) NOT IN
															(SELECT CustumCod FROM dbo.TblFactorOnvan WHERE Type IN(SELECT * FROM dbo.CSVToTable(@Type)) AND Driver IN (SELECT * FROM dbo.CSVToTable(@Driver))))
        )
		AND ( @GroupCode IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblKala.GroupCode,'') IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode)))
			OR 
			(@Toggle = 1 AND ISNULL(TblFactorOnvan.CustumCod,0) NOT IN
															(SELECT f.CustumCod FROM dbo.TR AS t
															INNER JOIN dbo.TblKala AS k ON t.Idkala = k.IDKala AND t.IdAnbr = k.IDAnbar
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND k.GroupCode IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode))))
        )
		AND	( @Tasviye IS NULL 
			OR 
			EXISTS (SELECT * FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type]))

	
	SELECT  CAST(ISNULL(tblM.id, 0) AS BIT) AS Tik ,
			tbl.CustomerId ,
			tbl.CustomerName ,
			CAST(SUM(tbl.TedForush) AS FLOAT) AS TedForush ,
			SUM(tbl.MabForush) AS MabForush ,
			SUM(tbl.MabMaliatForush) AS MabMaliatForush ,
			CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
			SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedForush) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabForush) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatForush) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabForush+MabMaliatForush) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
			FROM    #RptForushAndBargashtForushAggregation_Final AS tbl
			LEFT OUTER JOIN dbo.CSVToTable(@Moshtari) AS tblM ON tblM.id = tbl.CustomerId
	GROUP BY CAST(ISNULL(tblM.id, 0) AS BIT) ,
			tbl.CustomerId ,
			tbl.CustomerName
	ORDER BY tbl.CustomerId;	
										  
END

GO

-- Procedure: [dbo].[RptForushAndBarghashForushTasviye]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushTasviye]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushTasviye] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushTasviye]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL,
	@Type VARCHAR(10) = '203,104'
	  
AS  
    BEGIN    
        IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL  
            DROP TABLE  #RptForushAndAvamelKala_Base;       
        CREATE TABLE #RptForushAndAvamelKala_Base  
            (  
              Shfactor INT ,  
              [Type] TINYINT ,
			  CustomerId INT ,
			  [Rank] INT ,  
              IdAnbar INT ,  
              IdKala INT , 
              Mab BIGINT ,  
              Takh BIGINT ,  
              Ted INT,
			  VizitorId INT,
			  DriverId INT,
			  GroupCode NVARCHAR(100)
            );    
        INSERT  INTO #RptForushAndAvamelKala_Base  
                ( Shfactor ,  
                  [Type] ,
				  CustomerId ,
				  [Rank] ,  
                  IdAnbar ,  
                  IdKala ,  
                  Mab ,  
                  Takh ,  
                  Ted,
				  VizitorId,
				  DriverId,
				  GroupCode
                )  
                SELECT  Factor ,
						dbo.TR.[Type] ,
						ISNULL(tfo.CustumCod,0) ,
						RANK() OVER ( PARTITION BY TR.Factor,tr.Type ORDER BY MIN(Sodor) ) ,   
                        IdAnbr ,   
                        TR.Idkala , 
                        SUM(Bed + Bes) ,
                        SUM(Takh) ,   
                        SUM(TED),
						ISNULL(tfo.VizitorID,0),
						ISNULL(tfo.Driver,0),
						ISNULL(TblKala.GroupCode,'')
                FROM    dbo.TR
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar
                                                   AND TR.Idkala = dbo.TblKala.IDKala
												   LEFT OUTER JOIN dbo.TblFactorOnvan AS tfo ON dbo.TR.Factor = tfo.ShFactor AND dbo.TR.[Type] = tfo.[Type]
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))  
						AND TR.Idkala > 0   
                        AND DateR BETWEEN @Date1 AND @Date2
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 )							  
				GROUP BY Factor, dbo.TR.[Type], tfo.CustumCod, IdAnbr, TR.Idkala,tfo.VizitorID,tfo.Driver,dbo.TblKala.GroupCode

		IF (ISNULL(@IdKala, '') <> '')
		BEGIN
			DELETE #RptForushAndAvamelKala_Base WHERE IdKala NOT IN (SELECT * FROM dbo.CSVToTableStr(@IdKala))
		END	

		IF (ISNULL(@IdAnbar, '') <> '')
		BEGIN
			DELETE #RptForushAndAvamelKala_Base WHERE IdAnbar NOT IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))
		END

		IF (ISNULL(@Moshtari, '') <> '')
		BEGIN
			DELETE #RptForushAndAvamelKala_Base WHERE CustomerId NOT IN (SELECT * FROM dbo.CSVToTable(@Moshtari))
		END

		IF (ISNULL(@Vizitor, '') <> '')
		BEGIN
			DELETE #RptForushAndAvamelKala_Base WHERE VizitorId NOT IN (SELECT * FROM dbo.CSVToTable(@Vizitor))
		END


		IF (ISNULL(@Driver, '') <> '')
		BEGIN
			DELETE #RptForushAndAvamelKala_Base WHERE DriverId NOT IN (SELECT * FROM dbo.CSVToTable(@Driver))
		END

		IF (ISNULL(@GroupCode, '') <> '')
		BEGIN
			DELETE #RptForushAndAvamelKala_Base WHERE GroupCode NOT IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode))
		END

		IF ( OBJECT_ID('##RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL
			DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;  
		CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		
            (  
			  Shfactor INT ,  
              [Type] TINYINT ,
			  MabForush BIGINT ,
			  MabBargasht BIGINT ,
			  Srfsl INT ,
			  Moin INT ,
			  HSB BIGINT 
            );    
        INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp
                SELECT  ttr.Factor, ttr.[Type], SUM(ttr.Bed - ttr.Bes), 0, ttr.Srfsl, ttr.Moin, ttr.HSB
                FROM    dbo.TR AS ttr 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 AND EXISTS (SELECT * FROM #RptForushAndAvamelKala_Base AS tbl WHERE ttr.Factor = tbl.Shfactor AND ttr.[Type] = tbl.[Type])
		GROUP BY ttr.Factor, ttr.[Type], ttr.Srfsl, ttr.Moin, ttr.HSB	

		DELETE #RptForushAndAvamelKala_TasviyeFactorTmp
		WHERE NOT EXISTS (SELECT * FROM #RptForushAndAvamelKala_Base AS tblBase WHERE tblBase.Shfactor = Shfactor AND tblBase.[Type] = [Type])
		
	UPDATE tbl
	SET tbl.MabBargasht = MabForush * -1, tbl.MabForush = 0
	FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tbl WHERE [Type] = 104
	
	SELECT  CAST( CASE ISNULL(tblT.id, '') WHEN '' THEN 0 ELSE 1 END AS BIT) AS Tik ,
            tbl.Srfsl ,
            tbl.Moin ,
			tbl.HSB ,
			dbo.GetSahebHesab(tbl.Srfsl, tbl.Moin, tbl.HSB) AS HesabName ,
            SUM(tbl.MabForush) AS MabForush ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabForush) - SUM(tbl.MabBargasht) AS MabKol
            FROM    #RptForushAndAvamelKala_TasviyeFactorTmp AS tbl
			LEFT OUTER JOIN dbo.CSVToTableStr(@Tasviye) AS tblT ON tblT.id = CAST(tbl.Srfsl AS VARCHAR) + '-' + CAST(tbl.Moin AS VARCHAR) + '-' + CAST(tbl.HSB AS VARCHAR)  COLLATE DATABASE_DEFAULT
    GROUP BY CAST( CASE ISNULL(tblT.id, '') WHEN '' THEN 0 ELSE 1 END AS BIT) ,
            tbl.Srfsl ,
            tbl.Moin ,
			tbl.HSB ,
			dbo.GetSahebHesab(tbl.Srfsl, tbl.Moin, tbl.HSB) 
    ORDER BY tbl.Srfsl, tbl.Moin, tbl.HSB
   
    END;

GO

-- Procedure: [dbo].[RptForushAndBarghashForushVizitor]
IF OBJECT_ID(N'[dbo].[RptForushAndBarghashForushVizitor]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptForushAndBarghashForushVizitor] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptForushAndBarghashForushVizitor]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL,
	@Toggle BIT = 0,
	@Type VARCHAR(10) = '203,104'
AS
BEGIN
	IF ( OBJECT_ID('#RptForushAndAvamelKala_Base', 'U') ) IS NOT NULL   
        DROP TABLE  #RptForushAndAvamelKala_Base;        
    CREATE TABLE #RptForushAndAvamelKala_Base   
        (   
            Factor INT ,   
            [Type] TINYINT , 
			DateR NVARCHAR(100),
			[Rank] INT ,   
            IdAnbar INT ,   
            IdKala INT ,   
			Mab BIGINT ,   
            Takh BIGINT ,   
            Ted DECIMAL(18, 5),
			EzafMashmol BIGINT,
			KasrMashmol BIGINT,
			Ezaf BIGINT,
			Kasr BIGINT,
			Maliat BIGINT,
			Mashmol TINYINT,
			DarsadMashmol NUMERIC(18,3),
			Cshobe INT,
			WeightKala NUMERIC(18,3)
        );     
    INSERT  INTO #RptForushAndAvamelKala_Base   
    ( Factor ,   
        [Type] , 
		[Rank] ,   
        IdAnbar ,   
        IdKala ,   
        Mab ,   
        Takh ,   
        Ted,
		EzafMashmol,
		KasrMashmol,
		Ezaf,
		Kasr,
		Maliat,
		Mashmol,
		DarsadMashmol,
		WeightKala
    )   
    SELECT  Factor , 
			[Type] , 
			RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
            IdAnbr ,    
            TR.Idkala ,    
            SUM(Bes+Bed), 
            SUM(Takh) ,    
            SUM(TED),
				0,
				0,
				0,
				0,
				0,
			dbo.TR.Mashmol,
			dbo.TR.DarsadMashmol,
			SUM(TED*WeightKala) AS WeightKala
    FROM    dbo.TR 
        LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                        AND TR.Idkala = dbo.TblKala.IDKala 
    WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
			AND TR.Idkala > 0    
            AND DateR BETWEEN @Date1 AND @Date2 
			AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
			GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
			ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
			
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactor;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactor		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactor 
            SELECT  tbl.Factor, tbl.[Type], 
                    SUM(tbl.Mab)   
            FROM    #RptForushAndAvamelKala_Base AS tbl   
            GROUP BY tbl.Factor, tbl.[Type];   


	UPDATE #RptForushAndAvamelKala_MabFactor SET Mab = 1 WHERE Mab = 0

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgent; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgent 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgent   
            ( Factor ,   
                [Type] , 
				Ezaf ,   
                Kasr    
            )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 0 )
    GROUP BY tbl.Factor , tbl.[Type]  	
					

	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabFactorMashmol;   
	CREATE TABLE #RptForushAndAvamelKala_MabFactorMashmol		 
        (   
            Factor INT ,   
            [Type] TINYINT , 
			Mab BIGINT   
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM(tbl.Mab)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
	
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabAgentMashmol; 
	CREATE TABLE #RptForushAndAvamelKala_MabAgentMashmol 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Ezaf BIGINT ,
			Kasr BIGINT
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabAgentMashmol   
            ( Factor ,   
                [Type] , 
				Ezaf ,   
                Kasr    
            )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END,
			CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END 
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
			AND ( ISNULL(fa.Maliat, 0) = 0 )
			AND ( ISNULL(fa.Mashmol, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	
				
				
	UPDATE tblKF SET 
	tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
	tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type

	UPDATE tblKF SET 
	tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
	tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
	INNER JOIN #RptForushAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_Difference', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_Difference;   
	CREATE TABLE #RptForushAndAvamelKala_Difference 
	(   
		Factor INT ,   
	[Type] TINYINT , 
	Ezaf BIGINT ,
	Kasr BIGINT
	);    

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type


	UPDATE tblD SET 
	tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblAm.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgentMashmol AS tblAm
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type

	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0


	UPDATE tblKF SET 
	tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
	tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
	DELETE FROM #RptForushAndAvamelKala_Difference

	INSERT INTO #RptForushAndAvamelKala_Difference
	SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

				
	UPDATE tblD SET 
	tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
	tblD.Kasr = tblA.Kasr - tblD.Kasr
		FROM #RptForushAndAvamelKala_MabAgent AS tblA
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_Difference
	WHERE Ezaf = 0 AND Kasr = 0

				

	UPDATE tblKF SET 
	tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
	tblKF.Kasr = tblKF.Kasr+tblD.Kasr
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	DELETE #RptForushAndAvamelKala_MabFactorMashmol
			
    INSERT  INTO #RptForushAndAvamelKala_MabFactorMashmol 
    SELECT  tbl.Factor, tbl.[Type], 
            SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
    FROM    #RptForushAndAvamelKala_Base AS tbl   
	WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
    GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
	IF ( OBJECT_ID('#RptForushAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_MabMaliat; 
	CREATE TABLE #RptForushAndAvamelKala_MabMaliat 
        (   
            Factor INT ,   
            [Type] TINYINT , 
            Mab BIGINT 
        );     
    INSERT  INTO #RptForushAndAvamelKala_MabMaliat   
    ( Factor ,   
        [Type] , 
		Mab
    )   
    SELECT  tbl.Factor , 
			tbl.[Type] , 
            CASE tbl.[Type] WHEN 203 THEN SUM(dbo.TR.Bes-dbo.TR.Bed) ELSE SUM(dbo.TR.Bed-dbo.TR.Bes) END
    FROM    #RptForushAndAvamelKala_MabFactor AS tbl   
            INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
			LEFT JOIN dbo.TblFactorAvamel AS fa ON fa.Id = dbo.TR.IdAmel
    WHERE    
            Idkala = 0   
            AND Tp1 > 0  
			AND ( ISNULL(fa.Maliat, 0) = 1 )
    GROUP BY tbl.Factor , tbl.[Type]  	

	UPDATE tblKF SET 
	tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
	INNER JOIN #RptForushAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
	WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


	IF ( OBJECT_ID('#RptForushAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_DifferenceMaliat;   
	CREATE TABLE #RptForushAndAvamelKala_DifferenceMaliat 
	(   
		Factor INT ,   
		[Type] TINYINT , 
		Mab BIGINT 
	);    

	INSERT INTO #RptForushAndAvamelKala_DifferenceMaliat
	SELECT Factor,Type,SUM(Maliat) FROM #RptForushAndAvamelKala_Base
	GROUP BY Factor,Type

	UPDATE tblD SET 
	tblD.Mab = tblM.Mab - tblD.Mab
		FROM #RptForushAndAvamelKala_MabMaliat AS tblM
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


	DELETE FROM #RptForushAndAvamelKala_DifferenceMaliat
	WHERE Mab = 0


	UPDATE tblKF SET 
	tblKF.Maliat = tblKF.Maliat+tblD.Mab
	FROM #RptForushAndAvamelKala_Base AS tblKF
	INNER JOIN #RptForushAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


	IF ( OBJECT_ID('#RptForushAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
		DROP TABLE  #RptForushAndAvamelKala_TasviyeFactorTmp;   
	CREATE TABLE #RptForushAndAvamelKala_TasviyeFactorTmp		 
        (   
			Shfactor INT ,   
            [Type] TINYINT , 
			Code VARCHAR(100) 
        );     
    INSERT  INTO #RptForushAndAvamelKala_TasviyeFactorTmp 
    SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
    FROM    #RptForushAndAvamelKala_Base AS tbl 
	LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
	WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
	IF (ISNULL(@Tasviye, '') <> '') 
	BEGIN 
		DELETE #RptForushAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
	END 


	IF ( OBJECT_ID('#RptForushAndBargashtForushAggregation_Final', 'U') ) IS NOT NULL
		DROP TABLE  #RptForushAndBargashtForushAggregation_Final;  
	CREATE TABLE #RptForushAndBargashtForushAggregation_Final
		(
			VizitorID INT ,
			VizitorName NVARCHAR(200) ,
			TedForush DECIMAL(18, 5) ,
			MabForush BIGINT ,
			TedBargasht DECIMAL(18, 5) ,
			MabBargasht BIGINT,
			MabMaliatForush BIGINT,
			MabMaliatBargasht BIGINT,
			WeightKala NUMERIC(18,3)
		);
	INSERT INTO #RptForushAndBargashtForushAggregation_Final
	( 
		VizitorID ,
	    VizitorName ,
		TedForush ,
	    MabForush ,
	    TedBargasht ,
	    MabBargasht,
		MabMaliatForush,
		MabMaliatBargasht,
		WeightKala
	)
	SELECT 
    TblFactorOnvan.VizitorID ,
    LTRIM(RTRIM(TblPerson.Name+' '+ TblPerson.Famil)) COLLATE DATABASE_DEFAULT VizitorName ,
	CASE tr.Type WHEN 203 THEN tr.Ted ELSE 0 END AS TedForush ,
	CASE tr.Type WHEN 203 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabForush,
	CASE tr.Type WHEN 104 THEN tr.Ted ELSE 0 END AS TedBargasht ,
	CASE tr.Type WHEN 104 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabBargasht,
	CASE tr.Type WHEN 203 THEN Maliat ELSE 0 END AS MabMaliatForush,
	CASE tr.Type WHEN 104 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
	CASE tr.Type WHEN 104 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
	FROM #RptForushAndAvamelKala_Base AS tr
    LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
    LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
    LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.VizitorID = dbo.TblPerson.Sh_ozviat
	WHERE  ( @IdKala IS NULL
            OR 
			(@Toggle = 0 AND tr.IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.VizitorID,0) NOT IN
															(SELECT f.VizitorID FROM dbo.TR AS t
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND t.IdKala IN (SELECT * FROM dbo.CSVToTable(@IdKala))))
        )
		AND ( @IdAnbar IS NULL
            OR 
			(@Toggle = 0 AND tr.IdAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar)))
			OR 
            (@Toggle = 1 AND ISNULL(TblFactorOnvan.VizitorID,0) NOT IN
															(SELECT f.VizitorID FROM dbo.TR AS t
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND t.IdAnbr IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))))
        )
		AND ( @Driver IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.Driver,0) IN (SELECT * FROM dbo.CSVToTable(@Driver)))
			OR 
			(@Toggle = 1 AND ISNULL(TblFactorOnvan.VizitorID,0) NOT IN
															(SELECT VizitorID FROM dbo.TblFactorOnvan WHERE Type IN(SELECT * FROM dbo.CSVToTable(@Type)) AND Driver IN (SELECT * FROM dbo.CSVToTable(@Driver))))
        )
		AND ( @GroupCode IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblKala.GroupCode,'') IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode)))
			OR 
			(@Toggle = 1 AND ISNULL(TblFactorOnvan.VizitorID,0) NOT IN
															(SELECT f.VizitorID FROM dbo.TR AS t
															INNER JOIN dbo.TblKala AS k ON t.Idkala = k.IDKala AND t.IdAnbr = k.IDAnbar
															INNER JOIN dbo.TblFactorOnvan AS f ON f.Type=t.Type AND f.ShFactor=t.Factor
															WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type)) AND k.GroupCode IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode))))
        )
		AND	( @Tasviye IS NULL 
			OR 
			EXISTS (SELECT * FROM #RptForushAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type])
		)
		AND ( @Moshtari IS NULL
            OR 
			(@Toggle = 0 AND ISNULL(dbo.TblFactorOnvan.CustumCod,0) IN (SELECT * FROM  dbo.CSVToTable(@Moshtari)))
			OR 
			(@Toggle = 1 AND ISNULL(TblFactorOnvan.VizitorID,0) NOT IN
															(SELECT VizitorID FROM dbo.TblFactorOnvan WHERE Type IN(SELECT * FROM dbo.CSVToTable(@Type)) AND CustumCod IN (SELECT * FROM dbo.CSVToTable(@Driver))))
        )
				
	SELECT  CAST(ISNULL(tblM.id, 0) AS BIT) AS Tik ,
            tbl.VizitorID ,
            tbl.VizitorName ,
            CAST(SUM(tbl.TedForush) AS FLOAT) AS TedForush ,
            SUM(tbl.MabForush) AS MabForush ,
			SUM(tbl.MabMaliatForush) AS MabMaliatForush ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedForush) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabForush) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatForush) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabForush+MabMaliatForush) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptForushAndBargashtForushAggregation_Final AS tbl
			LEFT OUTER JOIN dbo.CSVToTable(@Vizitor) AS tblM ON tblM.id = tbl.VizitorID
    GROUP BY CAST(ISNULL(tblM.id, 0) AS BIT) ,
            tbl.VizitorID ,
			tbl.VizitorName
    ORDER BY tbl.VizitorID;	
										  
END

GO

-- Procedure: [dbo].[RptKharidAndBarghashKharid]
IF OBJECT_ID(N'[dbo].[RptKharidAndBarghashKharid]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBarghashKharid] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBarghashKharid]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@GroupCode VARCHAR(MAX) = NULL ,
	@Type VARCHAR(10) = '204,103'    
AS
BEGIN
	IF ( OBJECT_ID('#RptKharidAndAvamelKala_Base', 'U') ) IS NOT NULL   
            DROP TABLE  #RptKharidAndAvamelKala_Base;        
        CREATE TABLE #RptKharidAndAvamelKala_Base   
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  DateR NVARCHAR(100),
			  [Rank] INT ,   
              IdAnbar INT ,   
              IdKala INT ,   
			  Mab BIGINT ,   
              Takh BIGINT ,   
              Ted DECIMAL(18, 5),
			  EzafMashmol BIGINT,
			  KasrMashmol BIGINT,
			  Ezaf BIGINT,
			  Kasr BIGINT,
			  Maliat BIGINT,
			  Mashmol TINYINT,
			  DarsadMashmol NUMERIC(18,3),
			  Cshobe INT,
			  WeightKala NUMERIC(18,3)
            );     
        INSERT  INTO #RptKharidAndAvamelKala_Base   
                ( Factor ,   
                  [Type] , 
				  DateR,
				  [Rank] ,   
                  IdAnbar ,   
                  IdKala ,   
                  Mab ,   
                  Takh ,   
                  Ted,
				  EzafMashmol,
				  KasrMashmol,
				  Ezaf,
				  Kasr,
				  Maliat,
				  Mashmol,
				  DarsadMashmol,
				  Cshobe,
				  WeightKala
                )   
                SELECT  Factor , 
						[Type] , 
						DateR,
						RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,dbo.TR.Sodor	) ,    
                        IdAnbr ,    
                        TR.Idkala ,    
                        Bed+Bes, 
                        Takh ,    
                        TED,
						  0,
						  0,
						  0,
						  0,
						  0,
						dbo.TR.Mashmol,
						dbo.TR.DarsadMashmol,
						CShobe,
						dbo.TblKala.WeightKala*tr.TED
                FROM    dbo.TR 
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                                   AND TR.Idkala = dbo.TblKala.IDKala 
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
						AND TR.Idkala > 0    
                        AND DateR BETWEEN @Date1 AND @Date2
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
						ORDER BY Mashmol DESC,DarsadMashmol DESC,dbo.TR.Sodor	
						
						
						
						
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactor;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactor		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactor 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
                GROUP BY tbl.Factor, tbl.[Type];   



				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgent; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgent 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgent   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 0 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				

				

			IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactorMashmol;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactorMashmol		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				
				
				IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgentMashmol; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgentMashmol 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgentMashmol   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				
				
				UPDATE tblKF SET 
				tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
				tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


				


				UPDATE tblKF SET 
				tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
				tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0






				IF ( OBJECT_ID('#RptKharidAndAvamelKala_Difference', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_Difference;   
				CREATE TABLE #RptKharidAndAvamelKala_Difference 
				(   
				 Factor INT ,   
				[Type] TINYINT , 
				Ezaf BIGINT ,
				Kasr BIGINT
				);    

				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type


				
			
		

				UPDATE tblD SET 
				tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblAm.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type





				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0


				UPDATE tblKF SET 
				tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
				tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
				DELETE FROM #RptKharidAndAvamelKala_Difference


				




				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				
				UPDATE tblD SET 
				tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblA.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgent AS tblA
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0

				

				UPDATE tblKF SET 
				tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
				tblKF.Kasr = tblKF.Kasr+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


			



			DELETE #RptKharidAndAvamelKala_MabFactorMashmol
			
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabMaliat; 
		CREATE TABLE #RptKharidAndAvamelKala_MabMaliat 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Mab BIGINT 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabMaliat   
                ( Factor ,   
                  [Type] , 
				  Mab
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed-dbo.TR.Bes) ELSE SUM(dbo.TR.Bes-dbo.TR.Bed) END
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	




				UPDATE tblKF SET 
				tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
				INNER JOIN #RptKharidAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_DifferenceMaliat;   
				CREATE TABLE #RptKharidAndAvamelKala_DifferenceMaliat 
				(   
				 Factor INT ,   
				 [Type] TINYINT , 
				 Mab BIGINT 
				);    

				INSERT INTO #RptKharidAndAvamelKala_DifferenceMaliat
				SELECT Factor,Type,SUM(Maliat) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				UPDATE tblD SET 
				tblD.Mab = tblM.Mab - tblD.Mab
				 FROM #RptKharidAndAvamelKala_MabMaliat AS tblM
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_DifferenceMaliat
				WHERE Mab = 0


				UPDATE tblKF SET 
				tblKF.Maliat = tblKF.Maliat+tblD.Mab
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_TasviyeFactorTmp;   
		CREATE TABLE #RptKharidAndAvamelKala_TasviyeFactorTmp		 
            (   
			  Shfactor INT ,   
              [Type] TINYINT , 
			  Code VARCHAR(100) 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_TasviyeFactorTmp 
                SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
                FROM    #RptKharidAndAvamelKala_Base AS tbl 
				LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
		IF (ISNULL(@Tasviye, '') <> '') 
		BEGIN 
			DELETE #RptKharidAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
		END 
 

			  SELECT 
			   tr.Type ,
               ISNULL(TblTypeTR.Name,'') TypeName ,
               ISNULL(CustumCod,0) CustumCod ,
               ISNULL(dbo.TblPerson.Name + ' '+dbo.TblPerson.Famil,'') Moshtari ,
               Factor ,
               DateR ,
               tr.IdAnbar ,
               ISNULL(dbo.TblAnbar.Name,'') AnbarName ,
               tr.IdKala ,
               ISNULL(dbo.TblKala.Name,'') KalaName ,
               Ted ,
               ISNULL(dbo.TblUnit.Name,'') Unit ,
               CAST(ROUND(( TR.Mab + TR.Takh ) / TR.TED, 0) AS BIGINT)  Fi ,
               TR.Mab + TR.Takh MabKol ,
               Takh ,
               KasrMashmol ,
               EzafMashmol ,
               TR.Mab+tr.EzafMashmol-tr.KasrMashmol MabMashmol ,
               Maliat ,
               Kasr ,
               Ezaf ,
               TR.Mab+tr.EzafMashmol-tr.KasrMashmol + Maliat-Kasr+Ezaf MabKhales ,
               tr.Cshobe ,
               ISNULL(dbo.TblCompanyShobe.Name,'') ShobeName ,
               CASE WHEN Mashmol = 1 THEN 'مشمول' ELSE 'معاف' END AS  Mashmol ,
               DarsadMashmol,
			   tr.WeightKala FROM #RptKharidAndAvamelKala_Base AS tr
			   LEFT OUTER JOIN dbo.TblAnbar ON TR.IdAnbar = dbo.TblAnbar.ID
               LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
               LEFT OUTER JOIN dbo.TblUnit ON dbo.TblKala.Unit1 = dbo.TblUnit.ID
               LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
               LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
			   LEFT OUTER JOIN dbo.TblTypeTR ON TR.Type = dbo.TblTypeTR.ID
               LEFT OUTER JOIN dbo.TblCompanyShobe ON TR.CShobe = dbo.TblCompanyShobe.Id
			   WHERE  ( @IdKala IS NULL
                                          OR tr.IDKala IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdKala) )
                                        )
                                    AND ( @IdAnbar IS NULL
                                          OR TR.IdAnbar IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdAnbar) )
                                        )
                                    AND ( @Moshtari IS NULL
                                          OR dbo.TblFactorOnvan.CustumCod IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@Moshtari) )
                                        )
									AND ( @GroupCode IS NULL
                                          OR ISNULL(dbo.TblKala.GroupCode,'') IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTableStr(@GroupCode) )
                                        )
									AND	( @Tasviye IS NULL 
						  OR EXISTS (SELECT * FROM #RptKharidAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type]))
		ORDER BY 
		 CustumCod ,
            tr.Type DESC ,
            DateR ,
            tr.Factor;


										  
END

GO

-- Procedure: [dbo].[RptKharidAndBarghashKharidAnbar]
IF OBJECT_ID(N'[dbo].[RptKharidAndBarghashKharidAnbar]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBarghashKharidAnbar] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBarghashKharidAnbar]
	@Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@GroupCode VARCHAR(MAX) = NULL  ,
	@Type VARCHAR(10) = '204,103'   
AS
BEGIN
	IF ( OBJECT_ID('#RptKharidAndAvamelKala_Base', 'U') ) IS NOT NULL   
            DROP TABLE  #RptKharidAndAvamelKala_Base;        
        CREATE TABLE #RptKharidAndAvamelKala_Base   
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  DateR NVARCHAR(100),
			  [Rank] INT ,   
              IdAnbar INT ,   
              IdKala INT ,   
			  Mab BIGINT ,   
              Takh BIGINT ,   
              Ted DECIMAL(18, 5),
			  EzafMashmol BIGINT,
			  KasrMashmol BIGINT,
			  Ezaf BIGINT,
			  Kasr BIGINT,
			  Maliat BIGINT,
			  Mashmol TINYINT,
			  DarsadMashmol NUMERIC(18,3),
			  Cshobe INT,
			  WeightKala NUMERIC(18,3)
            );     
        INSERT  INTO #RptKharidAndAvamelKala_Base   
                ( Factor ,   
                  [Type] , 
				  [Rank] ,   
                  IdAnbar ,   
                  IdKala ,   
                  Mab ,   
                  Takh ,   
                  Ted,
				  EzafMashmol,
				  KasrMashmol,
				  Ezaf,
				  Kasr,
				  Maliat,
				  Mashmol,
				  DarsadMashmol,
				  WeightKala
                )   
                SELECT  Factor , 
						[Type] , 
						RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
                        IdAnbr ,    
                        TR.Idkala ,    
                        SUM(Bed+Bes), 
                        SUM(Takh) ,    
                        SUM(TED),
						  0,
						  0,
						  0,
						  0,
						  0,
						dbo.TR.Mashmol,
						dbo.TR.DarsadMashmol,
						SUM(TED*WeightKala) AS WeightKala
                FROM    dbo.TR 
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                                   AND TR.Idkala = dbo.TblKala.IDKala 
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
						AND TR.Idkala > 0    
                        AND DateR BETWEEN @Date1 AND @Date2 
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
						GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
						ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
						
						
						
						
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactor;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactor		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactor 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
                GROUP BY tbl.Factor, tbl.[Type];   



				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgent; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgent 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgent   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 0 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				

				

			IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactorMashmol;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactorMashmol		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				
				
				IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgentMashmol; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgentMashmol 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgentMashmol   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				
				
				UPDATE tblKF SET 
				tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
				tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


				


				UPDATE tblKF SET 
				tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
				tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0






				IF ( OBJECT_ID('#RptKharidAndAvamelKala_Difference', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_Difference;   
				CREATE TABLE #RptKharidAndAvamelKala_Difference 
				(   
				 Factor INT ,   
				[Type] TINYINT , 
				Ezaf BIGINT ,
				Kasr BIGINT
				);    

				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type


				
			
		

				UPDATE tblD SET 
				tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblAm.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type





				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0


				UPDATE tblKF SET 
				tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
				tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
				DELETE FROM #RptKharidAndAvamelKala_Difference


				




				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				
				UPDATE tblD SET 
				tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblA.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgent AS tblA
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0

				

				UPDATE tblKF SET 
				tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
				tblKF.Kasr = tblKF.Kasr+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


			



			DELETE #RptKharidAndAvamelKala_MabFactorMashmol
			
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabMaliat; 
		CREATE TABLE #RptKharidAndAvamelKala_MabMaliat 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Mab BIGINT 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabMaliat   
                ( Factor ,   
                  [Type] , 
				  Mab
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed-dbo.TR.Bes) ELSE SUM(dbo.TR.Bes-dbo.TR.Bed) END
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	




				UPDATE tblKF SET 
				tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
				INNER JOIN #RptKharidAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_DifferenceMaliat;   
				CREATE TABLE #RptKharidAndAvamelKala_DifferenceMaliat 
				(   
				 Factor INT ,   
				 [Type] TINYINT , 
				 Mab BIGINT 
				);    

				INSERT INTO #RptKharidAndAvamelKala_DifferenceMaliat
				SELECT Factor,Type,SUM(Maliat) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				UPDATE tblD SET 
				tblD.Mab = tblM.Mab - tblD.Mab
				 FROM #RptKharidAndAvamelKala_MabMaliat AS tblM
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_DifferenceMaliat
				WHERE Mab = 0


				UPDATE tblKF SET 
				tblKF.Maliat = tblKF.Maliat+tblD.Mab
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_TasviyeFactorTmp;   
		CREATE TABLE #RptKharidAndAvamelKala_TasviyeFactorTmp		 
            (   
			  Shfactor INT ,   
              [Type] TINYINT , 
			  Code VARCHAR(100) 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_TasviyeFactorTmp 
                SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
                FROM    #RptKharidAndAvamelKala_Base AS tbl 
				LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
		IF (ISNULL(@Tasviye, '') <> '') 
		BEGIN 
			DELETE #RptKharidAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
		END 
			


			IF ( OBJECT_ID('#RptKharidAndBargashtKharidAggregation_Final', 'U') ) IS NOT NULL 
        DROP TABLE  #RptKharidAndBargashtKharidAggregation_Final;   
    CREATE TABLE #RptKharidAndBargashtKharidAggregation_Final 
        ( 
          IdAnbar INT , 
		  AnbarName NVARCHAR(200) , 
          TedKharid DECIMAL(18, 5) , 
          MabKharid BIGINT , 
          TedBargasht DECIMAL(18, 5) , 
          MabBargasht BIGINT ,
		  MabMaliatKharid BIGINT,
		  MabMaliatBargasht BIGINT,
	      WeightKala NUMERIC(18,3)
        ); 
	INSERT INTO #RptKharidAndBargashtKharidAggregation_Final 
	        ( IdAnbar , 
	          AnbarName , 
			  TedKharid , 
	          MabKharid , 
	          TedBargasht , 
	          MabBargasht ,
			  MabMaliatKharid,
			  MabMaliatBargasht,
			  WeightKala
	        ) 

			  SELECT 
               tr.IdAnbar ,
               ISNULL(ta.Name,'') AnbarName ,
			   CASE tr.Type WHEN 103 THEN tr.Ted ELSE 0 END AS TedKharid ,
			   CASE tr.Type WHEN 103 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabKharid,
			   CASE tr.Type WHEN 204 THEN tr.Ted ELSE 0 END AS TedBargasht ,
			   CASE tr.Type WHEN 204 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabBargasht,
			   CASE tr.Type WHEN 103 THEN Maliat ELSE 0 END AS MabMaliatKharid,
			   CASE tr.Type WHEN 204 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
			   CASE tr.Type WHEN 204 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
			   FROM #RptKharidAndAvamelKala_Base AS tr
			   LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
               LEFT OUTER JOIN dbo.TblAnbar AS ta ON tr.IdAnbar = ta.ID 
               LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
               LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
			   WHERE  ( @IdKala IS NULL
                                          OR tr.IDKala IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdKala) )
                                        )
                                    AND ( @Moshtari IS NULL
                                          OR dbo.TblFactorOnvan.CustumCod IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@Moshtari) )
                                        )
									AND ( @GroupCode IS NULL
                                          OR ISNULL(dbo.TblKala.GroupCode,'') IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTableStr(@GroupCode) )
                                        )
									AND	( @Tasviye IS NULL 
						  OR EXISTS (SELECT * FROM #RptKharidAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type]))
	
	SELECT  CAST(ISNULL(tblA.id, 0) AS BIT) AS Tik , 
            tbl.IdAnbar , 
            tbl.AnbarName , 
             CAST(SUM(tbl.TedKharid) AS FLOAT) AS TedKharid ,
            SUM(tbl.MabKharid) AS MabKharid ,
			SUM(tbl.MabMaliatKharid) AS MabMaliatKharid ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedKharid) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabKharid) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatKharid) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabKharid+MabMaliatKharid) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptKharidAndBargashtKharidAggregation_Final AS tbl 
			LEFT OUTER JOIN dbo.CSVToTable(@IdAnbar) AS tblA ON tblA.id = tbl.IdAnbar 
    GROUP BY CAST(ISNULL(tblA.id, 0) AS BIT) , 
            tbl.IdAnbar , 
			tbl.AnbarName 
    ORDER BY tbl.IdAnbar;	 
										  
END

GO

-- Procedure: [dbo].[RptKharidAndBarghashKharidFactor]
IF OBJECT_ID(N'[dbo].[RptKharidAndBarghashKharidFactor]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBarghashKharidFactor] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBarghashKharidFactor]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@GroupCode VARCHAR(MAX) = NULL  ,
	@Type VARCHAR(10) = '204,103'   
AS
BEGIN

	DECLARE @dtfactor1 TABLE(factor INT,type INT)
	INSERT INTO @dtfactor1
	(
	    factor,
	    type
	)
	SELECT DISTINCT t.Factor,t.Type FROM tr AS t 
	INNER JOIN (SELECT IDAnbar,IDKala FROM dbo.TblKala 
				WHERE (@GroupCode IS NULL OR ISNULL(GroupCode,'') IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode)))
				AND (@IdAnbar IS NULL OR IDAnbar IN (SELECT * FROM dbo.CSVToTable(@IdAnbar)))
				AND (@IdKala IS NULL OR IDKala IN (SELECT * FROM dbo.CSVToTable(@IdKala)))) AS k ON k.idanbar=t.IdAnbr AND k.idkala=t.Idkala
	WHERE t.Type IN (SELECT * FROM dbo.CSVToTable(@Type))

	IF @Tasviye IS NOT NULL
	BEGIN
	    DELETE f FROM @dtfactor1 AS f WHERE NOT EXISTS(
		SELECT * FROM (
		SELECT Factor, Type, CAST(Srfsl AS VARCHAR) + '-' + CAST(Moin AS VARCHAR) + '-' + CAST(HSB AS VARCHAR) AS code FROM TR 
		WHERE Tp1=0 AND Idkala=0 AND Factor>0 AND Type IN (SELECT * FROM dbo.CSVToTable(@Type))) AS tt 
		WHERE tt.Type=f.Type AND tt.Factor=f.factor AND tt.Code COLLATE DATABASE_DEFAULT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)))
	END
	

	DECLARE @dtfactor2 TABLE(factor INT,type INT,Weightfactor DECIMAL(18,3),ted NUMERIC(25,7),mab BIGINT,takh BIGINT, mabmashmol BIGINT, mabmaliat BIGINT,mabkosorat BIGINT,mabezafat BIGINT,mabmashmolkosorat BIGINT, mabmashmolezafat BIGINT,mabkol BIGINT)
	INSERT INTO @dtfactor2
	(
	    factor,
	    type,
		Weightfactor,
		ted,
		mab,
		takh,
		mabmashmol,
		mabmaliat,
		mabkosorat,
		mabezafat,
		mabmashmolkosorat,
		mabmashmolezafat,
		mabkol
	)
	SELECT t.Factor,t.Type,SUM(t.TED*ISNULL(k.WeightKala,0)) AS Weightfactor,
		SUM(t.TED) AS Ted,
		SUM(CASE WHEN t.Idkala>0 then t.bed+t.bes+t.Takh-t.Maliat ELSE 0 END) AS mab,
		SUM(t.Takh) AS takh,
		SUM(CASE WHEN t.Mashmol=1 THEN t.bed+t.bes ELSE 0 END) AS mabmashmol,
		CASE WHEN SUM(t.Maliat)>0 THEN SUM(t.Maliat) ELSE SUM(CASE WHEN avamel.Maliat=1 THEN t.bed+t.bes ELSE 0 END) END AS mabmaliat,
		SUM(CASE WHEN avamel.State=1 THEN t.bed+t.bes ELSE 0 END) AS mabkosorat,
		SUM(CASE WHEN avamel.State=0 AND avamel.Maliat=0 THEN t.bed+t.bes ELSE 0 END) AS mabezafat,
		SUM(CASE WHEN avamel.State=1 AND avamel.Mashmol=1 THEN t.bed+t.bes ELSE 0 END) AS mabmashmolkosorat,
		SUM(CASE WHEN avamel.State=0 AND avamel.Maliat=0 AND avamel.Mashmol=1 THEN t.bed+t.bes ELSE 0 END) AS mabmashmolezafat ,
		SUM(CASE WHEN t.Idkala>0 then t.bed+t.bes 
				 WHEN t.Tp1>0 THEN CASE WHEN t.type=103 then t.bed-t.Bes ELSE t.bes-t.Bed END
				 ELSE 0 END) AS mabkol
	FROM dbo.TR AS t
	INNER JOIN @dtfactor1 AS f ON f.factor=t.factor AND f.type = t.Type
	LEFT JOIN dbo.TblKala AS k ON  k.IDAnbar =t.IdAnbr AND k.IDKala = t.Idkala
	LEFT JOIN dbo.TblFactorAvamel AS avamel ON t.IdAmel=avamel.Id AND t.Tp1>0
	GROUP BY t.Factor,t.Type



	
	SELECT f.ShFactor,f.Type,tt.Name AS typename,f.CustumCod,ISNULL(p.Name,'') + ' ' +ISNULL(p.Famil,'') AS custumname ,f.DateFactor,
	f2.mab,f2.takh,f2.mabkosorat,f2.mabmashmolkosorat,f2.mabezafat,f2.mabmashmolezafat,f2.mabmashmol,f2.mabmaliat,f2.mabkol,
	f.CShobe,ISNULL(cs.Name , '') AS shobename,f2.Weightfactor,f2.ted
	FROM dbo.TblFactorOnvan AS f
	INNER JOIN @dtfactor2 AS f2 ON f2.factor=f.ShFactor AND f2.type = f.Type
	INNER JOIN dbo.TblTypeTR AS tt ON tt.ID = f.Type
	LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat=f.CustumCod
	LEFT JOIN dbo.TblCompanyShobe AS cs ON cs.Id = f.CShobe
	WHERE f.DateFactor BETWEEN @Date1 AND @Date2
	AND (@CShobe = 0 OR f.CShobe = @CShobe)
	AND (@Moshtari IS NULL OR f.CustumCod IN (SELECT * FROM dbo.CSVToTable(@Moshtari)))
	ORDER BY f.Type,f.ShFactor

END

GO

-- Procedure: [dbo].[RptKharidAndBarghashKharidGroupKala]
IF OBJECT_ID(N'[dbo].[RptKharidAndBarghashKharidGroupKala]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBarghashKharidGroupKala] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBarghashKharidGroupKala]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@GroupCode VARCHAR(MAX) = NULL  ,
	@Type VARCHAR(10) = '204,103'   
AS
BEGIN
	IF ( OBJECT_ID('#RptKharidAndAvamelKala_Base', 'U') ) IS NOT NULL   
            DROP TABLE  #RptKharidAndAvamelKala_Base;        
        CREATE TABLE #RptKharidAndAvamelKala_Base   
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  DateR NVARCHAR(100),
			  [Rank] INT ,   
              IdAnbar INT ,   
              IdKala INT ,   
			  Mab BIGINT ,   
              Takh BIGINT ,   
              Ted DECIMAL(18, 5),
			  EzafMashmol BIGINT,
			  KasrMashmol BIGINT,
			  Ezaf BIGINT,
			  Kasr BIGINT,
			  Maliat BIGINT,
			  Mashmol TINYINT,
			  DarsadMashmol NUMERIC(18,3),
			  Cshobe INT,
			  WeightKala NUMERIC(18,3)
            );     
        INSERT  INTO #RptKharidAndAvamelKala_Base   
                ( Factor ,   
                  [Type] , 
				  [Rank] ,   
                  IdAnbar ,   
                  IdKala ,   
                  Mab ,   
                  Takh ,   
                  Ted,
				  EzafMashmol,
				  KasrMashmol,
				  Ezaf,
				  Kasr,
				  Maliat,
				  Mashmol,
				  DarsadMashmol,
				  WeightKala
                )   
                SELECT  Factor , 
						[Type] , 
						RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
                        IdAnbr ,    
                        TR.Idkala ,    
                        SUM(Bed+Bes), 
                        SUM(Takh) ,    
                        SUM(TED),
						  0,
						  0,
						  0,
						  0,
						  0,
						dbo.TR.Mashmol,
						dbo.TR.DarsadMashmol,
						SUM(TED*WeightKala) AS WeightKala
                FROM    dbo.TR 
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                                   AND TR.Idkala = dbo.TblKala.IDKala 
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
						AND TR.Idkala > 0    
                        AND DateR BETWEEN @Date1 AND @Date2 
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
						GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
						ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
						
						
						
						
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactor;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactor		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactor 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
                GROUP BY tbl.Factor, tbl.[Type];   



				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgent; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgent 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgent   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 0 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				

				

			IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactorMashmol;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactorMashmol		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				
				
				IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgentMashmol; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgentMashmol 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgentMashmol   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				
				
				UPDATE tblKF SET 
				tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
				tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


				


				UPDATE tblKF SET 
				tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
				tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0






				IF ( OBJECT_ID('#RptKharidAndAvamelKala_Difference', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_Difference;   
				CREATE TABLE #RptKharidAndAvamelKala_Difference 
				(   
				 Factor INT ,   
				[Type] TINYINT , 
				Ezaf BIGINT ,
				Kasr BIGINT
				);    

				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type


				
			
		

				UPDATE tblD SET 
				tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblAm.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type





				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0


				UPDATE tblKF SET 
				tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
				tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
				DELETE FROM #RptKharidAndAvamelKala_Difference


				




				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				
				UPDATE tblD SET 
				tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblA.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgent AS tblA
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0

				

				UPDATE tblKF SET 
				tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
				tblKF.Kasr = tblKF.Kasr+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


			



			DELETE #RptKharidAndAvamelKala_MabFactorMashmol
			
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabMaliat; 
		CREATE TABLE #RptKharidAndAvamelKala_MabMaliat 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Mab BIGINT 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabMaliat   
                ( Factor ,   
                  [Type] , 
				  Mab
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed-dbo.TR.Bes) ELSE SUM(dbo.TR.Bes-dbo.TR.Bed) END
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	




				UPDATE tblKF SET 
				tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
				INNER JOIN #RptKharidAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_DifferenceMaliat;   
				CREATE TABLE #RptKharidAndAvamelKala_DifferenceMaliat 
				(   
				 Factor INT ,   
				 [Type] TINYINT , 
				 Mab BIGINT 
				);    

				INSERT INTO #RptKharidAndAvamelKala_DifferenceMaliat
				SELECT Factor,Type,SUM(Maliat) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				UPDATE tblD SET 
				tblD.Mab = tblM.Mab - tblD.Mab
				 FROM #RptKharidAndAvamelKala_MabMaliat AS tblM
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_DifferenceMaliat
				WHERE Mab = 0


				UPDATE tblKF SET 
				tblKF.Maliat = tblKF.Maliat+tblD.Mab
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_TasviyeFactorTmp;   
		CREATE TABLE #RptKharidAndAvamelKala_TasviyeFactorTmp		 
            (   
			  Shfactor INT ,   
              [Type] TINYINT , 
			  Code VARCHAR(100) 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_TasviyeFactorTmp 
                SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
                FROM    #RptKharidAndAvamelKala_Base AS tbl 
				LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
		IF (ISNULL(@Tasviye, '') <> '') 
		BEGIN 
			DELETE #RptKharidAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
		END 
			


			IF ( OBJECT_ID('#RptKharidAndBargashtKharidAggregation_Final', 'U') ) IS NOT NULL 
        DROP TABLE  #RptKharidAndBargashtKharidAggregation_Final;   
    CREATE TABLE #RptKharidAndBargashtKharidAggregation_Final 
        ( 
          GroupCode NVARCHAR(200) , 
		  GroupName NVARCHAR(200) , 
          TedKharid DECIMAL(18, 5) , 
          MabKharid BIGINT , 
          TedBargasht DECIMAL(18, 5) , 
          MabBargasht BIGINT,
		  MabMaliatKharid BIGINT,
		  MabMaliatBargasht BIGINT ,
	      WeightKala NUMERIC(18,3)
        ); 
	INSERT INTO #RptKharidAndBargashtKharidAggregation_Final 
	        ( GroupCode , 
	          GroupName , 
			  TedKharid , 
	          MabKharid , 
	          TedBargasht , 
	          MabBargasht,
			  MabMaliatKharid,
			  MabMaliatBargasht,
			  WeightKala
	        ) 


			  SELECT 
               ISNULL(dbo.TblKala.GroupCode,'') AS  GroupCode,
               ISNULL(dbo.TblGroupKala.Name,'') GroupName ,
			   CASE tr.Type WHEN 103 THEN tr.Ted ELSE 0 END AS TedKharid ,
			   CASE tr.Type WHEN 103 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabKharid,
			   CASE tr.Type WHEN 204 THEN tr.Ted ELSE 0 END AS TedBargasht ,
			   CASE tr.Type WHEN 204 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabBargasht,
			   CASE tr.Type WHEN 103 THEN Maliat ELSE 0 END AS MabMaliatKharid,
			   CASE tr.Type WHEN 204 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
			   CASE tr.Type WHEN 204 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
			   FROM #RptKharidAndAvamelKala_Base AS tr
               LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
			   LEFT OUTER JOIN dbo.TblGroupKala ON dbo.TblGroupKala.Code COLLATE SQL_Latin1_General_CP1_CI_AS = dbo.TblKala.GroupCode
               LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
               LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
			   WHERE  ( @IdKala IS NULL
                                          OR tr.IDKala IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdKala) )
                                        )
                                    AND ( @IdAnbar IS NULL
                                          OR TR.IdAnbar IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdAnbar) )
                                        )
                                    AND ( @Moshtari IS NULL
                                          OR dbo.TblFactorOnvan.CustumCod IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@Moshtari) )
                                        )
									AND	( @Tasviye IS NULL 
						  OR EXISTS (SELECT * FROM #RptKharidAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type]))
	
	SELECT   CAST((CASE WHEN tblK.id IS NULL THEN 0 ELSE 1 END) AS bit) AS Tik , 
            tbl.GroupCode , 
            tbl.GroupName , 
            CAST(SUM(tbl.TedKharid) AS FLOAT) AS TedKharid ,
            SUM(tbl.MabKharid) AS MabKharid ,
			SUM(tbl.MabMaliatKharid) AS MabMaliatKharid ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedKharid) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabKharid) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatKharid) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabKharid+MabMaliatKharid) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptKharidAndBargashtKharidAggregation_Final AS tbl 
			LEFT OUTER JOIN dbo.CSVToTableStr(@GroupCode) AS tblK ON tblK.id COLLATE SQL_Latin1_General_CP1_CI_AS = tbl.GroupCode 
    GROUP BY tblk.id , 
            tbl.GroupCode , 
			tbl.GroupName
    ORDER BY tbl.GroupCode;	 
										  
END

GO

-- Procedure: [dbo].[RptKharidAndBarghashKharidKala]
IF OBJECT_ID(N'[dbo].[RptKharidAndBarghashKharidKala]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBarghashKharidKala] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBarghashKharidKala]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@GroupCode VARCHAR(MAX) = NULL  ,
	@Type VARCHAR(10) = '204,103'   
AS
BEGIN
	IF ( OBJECT_ID('#RptKharidAndAvamelKala_Base', 'U') ) IS NOT NULL   
            DROP TABLE  #RptKharidAndAvamelKala_Base;        
        CREATE TABLE #RptKharidAndAvamelKala_Base   
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  DateR NVARCHAR(100),
			  [Rank] INT ,   
              IdAnbar INT ,   
              IdKala INT ,   
			  Mab BIGINT ,   
              Takh BIGINT ,   
              Ted DECIMAL(18, 5),
			  EzafMashmol BIGINT,
			  KasrMashmol BIGINT,
			  Ezaf BIGINT,
			  Kasr BIGINT,
			  Maliat BIGINT,
			  Mashmol TINYINT,
			  DarsadMashmol NUMERIC(18,3),
			  Cshobe INT,
			  WeightKala NUMERIC(18,3)
            );     
        INSERT  INTO #RptKharidAndAvamelKala_Base   
                ( Factor ,   
                  [Type] , 
				  [Rank] ,   
                  IdAnbar ,   
                  IdKala ,   
                  Mab ,   
                  Takh ,   
                  Ted,
				  EzafMashmol,
				  KasrMashmol,
				  Ezaf,
				  Kasr,
				  Maliat,
				  Mashmol,
				  DarsadMashmol,
				  WeightKala
                )   
                SELECT  Factor , 
						[Type] , 
						RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
                        IdAnbr ,    
                        TR.Idkala ,    
                        SUM(Bed+Bes), 
                        SUM(Takh) ,    
                        SUM(TED),
						  0,
						  0,
						  0,
						  0,
						  0,
						dbo.TR.Mashmol,
						dbo.TR.DarsadMashmol,
						SUM(TED*WeightKala) AS WeightKala
                FROM    dbo.TR 
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                                   AND TR.Idkala = dbo.TblKala.IDKala 
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
						AND TR.Idkala > 0    
                        AND DateR BETWEEN @Date1 AND @Date2 
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
						GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
						ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
						
						
						
						
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactor;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactor		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactor 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
                GROUP BY tbl.Factor, tbl.[Type];   



				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgent; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgent 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgent   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 0 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				

				

			IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactorMashmol;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactorMashmol		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				
				
				IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgentMashmol; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgentMashmol 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgentMashmol   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				
				
				UPDATE tblKF SET 
				tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
				tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


				


				UPDATE tblKF SET 
				tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
				tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0






				IF ( OBJECT_ID('#RptKharidAndAvamelKala_Difference', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_Difference;   
				CREATE TABLE #RptKharidAndAvamelKala_Difference 
				(   
				 Factor INT ,   
				[Type] TINYINT , 
				Ezaf BIGINT ,
				Kasr BIGINT
				);    

				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type


				
			
		

				UPDATE tblD SET 
				tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblAm.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type





				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0


				UPDATE tblKF SET 
				tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
				tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
				DELETE FROM #RptKharidAndAvamelKala_Difference


				




				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				
				UPDATE tblD SET 
				tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblA.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgent AS tblA
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0

				

				UPDATE tblKF SET 
				tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
				tblKF.Kasr = tblKF.Kasr+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


			



			DELETE #RptKharidAndAvamelKala_MabFactorMashmol
			
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabMaliat; 
		CREATE TABLE #RptKharidAndAvamelKala_MabMaliat 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Mab BIGINT 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabMaliat   
                ( Factor ,   
                  [Type] , 
				  Mab
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed-dbo.TR.Bes) ELSE SUM(dbo.TR.Bes-dbo.TR.Bed) END
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	




				UPDATE tblKF SET 
				tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
				INNER JOIN #RptKharidAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_DifferenceMaliat;   
				CREATE TABLE #RptKharidAndAvamelKala_DifferenceMaliat 
				(   
				 Factor INT ,   
				 [Type] TINYINT , 
				 Mab BIGINT 
				);    

				INSERT INTO #RptKharidAndAvamelKala_DifferenceMaliat
				SELECT Factor,Type,SUM(Maliat) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				UPDATE tblD SET 
				tblD.Mab = tblM.Mab - tblD.Mab
				 FROM #RptKharidAndAvamelKala_MabMaliat AS tblM
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_DifferenceMaliat
				WHERE Mab = 0


				UPDATE tblKF SET 
				tblKF.Maliat = tblKF.Maliat+tblD.Mab
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_TasviyeFactorTmp;   
		CREATE TABLE #RptKharidAndAvamelKala_TasviyeFactorTmp		 
            (   
			  Shfactor INT ,   
              [Type] TINYINT , 
			  Code VARCHAR(100) 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_TasviyeFactorTmp 
                SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
                FROM    #RptKharidAndAvamelKala_Base AS tbl 
				LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
		IF (ISNULL(@Tasviye, '') <> '') 
		BEGIN 
			DELETE #RptKharidAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
		END 
			


			IF ( OBJECT_ID('#RptKharidAndBargashtKharidAggregation_Final', 'U') ) IS NOT NULL 
        DROP TABLE  #RptKharidAndBargashtKharidAggregation_Final;   
    CREATE TABLE #RptKharidAndBargashtKharidAggregation_Final 
        ( 
          IdKala INT , 
		  KalaName NVARCHAR(200) , 
          TedKharid DECIMAL(18, 5) , 
          MabKharid BIGINT , 
          TedBargasht DECIMAL(18, 5) , 
          MabBargasht BIGINT ,
		  MabMaliatKharid BIGINT,
		  MabMaliatBargasht BIGINT,
	      WeightKala NUMERIC(18,3)
        ); 
	INSERT INTO #RptKharidAndBargashtKharidAggregation_Final 
	        ( IdKala , 
	          KalaName , 
			  TedKharid , 
	          MabKharid , 
	          TedBargasht , 
	          MabBargasht ,
			  MabMaliatKharid,
			  MabMaliatBargasht,
			  WeightKala
	        ) 


			  SELECT 
               tr.IdKala ,
               ISNULL(dbo.TblKala.Name,'') KalaName ,
			   CASE tr.Type WHEN 103 THEN tr.Ted ELSE 0 END AS TedKharid ,
			   CASE tr.Type WHEN 103 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabKharid,
			   CASE tr.Type WHEN 204 THEN tr.Ted ELSE 0 END AS TedBargasht ,
			   CASE tr.Type WHEN 204 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol -Kasr+Ezaf ELSE 0 END AS MabBargasht,
			   CASE tr.Type WHEN 103 THEN Maliat ELSE 0 END AS MabMaliatKharid,
			   CASE tr.Type WHEN 204 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
			   CASE tr.Type WHEN 204 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
			   FROM #RptKharidAndAvamelKala_Base AS tr
               LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
               LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
               LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
			   WHERE 
                                     ( @IdAnbar IS NULL
                                          OR TR.IdAnbar IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdAnbar) )
                                        )
                                    AND ( @Moshtari IS NULL
                                          OR dbo.TblFactorOnvan.CustumCod IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@Moshtari) )
                                        )
									AND ( @GroupCode IS NULL
                                          OR ISNULL(dbo.TblKala.GroupCode,'') IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTableStr(@GroupCode) )
                                        )
									AND	( @Tasviye IS NULL 
						  OR EXISTS (SELECT * FROM #RptKharidAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type]))
	
	SELECT  CAST(ISNULL(tblK.id, 0) AS BIT) AS Tik , 
            tbl.IdKala , 
            tbl.KalaName , 
			CAST(SUM(tbl.TedKharid) AS FLOAT) AS TedKharid ,
            SUM(tbl.MabKharid) AS MabKharid ,
			SUM(tbl.MabMaliatKharid) AS MabMaliatKharid ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedKharid) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabKharid) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatKharid) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabKharid+MabMaliatKharid) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptKharidAndBargashtKharidAggregation_Final AS tbl 
			LEFT OUTER JOIN dbo.CSVToTable(@IdKala) AS tblK ON tblK.id = tbl.IdKala 
    GROUP BY CAST(ISNULL(tblK.id, 0) AS BIT) , 
            tbl.IdKala , 
			tbl.KalaName 
    ORDER BY tbl.IdKala;	 
										  
END

GO

-- Procedure: [dbo].[RptKharidAndBarghashKharidMoshtari]
IF OBJECT_ID(N'[dbo].[RptKharidAndBarghashKharidMoshtari]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBarghashKharidMoshtari] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBarghashKharidMoshtari]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@GroupCode VARCHAR(MAX) = NULL ,
	@Type VARCHAR(10) = '204,103'    
AS
BEGIN
	IF ( OBJECT_ID('#RptKharidAndAvamelKala_Base', 'U') ) IS NOT NULL   
            DROP TABLE  #RptKharidAndAvamelKala_Base;        
        CREATE TABLE #RptKharidAndAvamelKala_Base   
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  DateR NVARCHAR(100),
			  [Rank] INT ,   
              IdAnbar INT ,   
              IdKala INT ,   
			  Mab BIGINT ,   
              Takh BIGINT ,   
              Ted DECIMAL(18, 5),
			  EzafMashmol BIGINT,
			  KasrMashmol BIGINT,
			  Ezaf BIGINT,
			  Kasr BIGINT,
			  Maliat BIGINT,
			  Mashmol TINYINT,
			  DarsadMashmol NUMERIC(18,3),
			  Cshobe INT,
			  WeightKala NUMERIC(18,3)
            );     
        INSERT  INTO #RptKharidAndAvamelKala_Base   
                ( Factor ,   
                  [Type] , 
				  [Rank] ,   
                  IdAnbar ,   
                  IdKala ,   
                  Mab ,   
                  Takh ,   
                  Ted,
				  EzafMashmol,
				  KasrMashmol,
				  Ezaf,
				  Kasr,
				  Maliat,
				  Mashmol,
				  DarsadMashmol,
				  WeightKala
                )   
                SELECT  Factor , 
						[Type] , 
						RANK() OVER ( PARTITION BY TR.Factor ,dbo.TR.Type ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)) ,    
                        IdAnbr ,    
                        TR.Idkala ,    
                        SUM(Bed+Bes), 
                        SUM(Takh) ,    
                        SUM(TED),
						  0,
						  0,
						  0,
						  0,
						  0,
						dbo.TR.Mashmol,
						dbo.TR.DarsadMashmol,
						SUM(TED*WeightKala) AS WeightKala
                FROM    dbo.TR 
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar 
                                                   AND TR.Idkala = dbo.TblKala.IDKala 
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))   
						AND TR.Idkala > 0    
                        AND DateR BETWEEN @Date1 AND @Date2 
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 ) 
						GROUP BY Factor,Type,IdAnbr,TR.Idkala,dbo.TR.Mashmol,dbo.TR.DarsadMashmol
						ORDER BY Mashmol DESC,DarsadMashmol DESC,MIN(dbo.TR.Sodor)
						

					
						
						
						
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactor', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactor;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactor		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactor 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
                GROUP BY tbl.Factor, tbl.[Type];   



				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgent', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgent; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgent 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgent   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 0 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				

				

			IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabFactorMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabFactorMashmol;   
		CREATE TABLE #RptKharidAndAvamelKala_MabFactorMashmol		 
            (   
              Factor INT ,   
              [Type] TINYINT , 
			  Mab BIGINT   
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM(tbl.Mab)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				
				
				IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabAgentMashmol', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabAgentMashmol; 
		CREATE TABLE #RptKharidAndAvamelKala_MabAgentMashmol 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Ezaf BIGINT ,
			  Kasr BIGINT
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabAgentMashmol   
                ( Factor ,   
                  [Type] , 
				  Ezaf ,   
                  Kasr    
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed) ELSE SUM(dbo.TR.Bes) END,
						CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bes) ELSE SUM(dbo.TR.Bed) END 
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  AND tr.Type IN (SELECT * FROM dbo.CSVToTable(@Type))
						AND ( ISNULL(fa.Maliat, 0) = 0 )
						AND ( ISNULL(fa.Mashmol, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	
				
				
				UPDATE tblKF SET 
				tblKF.Ezaf = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Ezaf AS BIGINT),
				tblKF.Kasr = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblA.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactor AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgent AS tblA ON tblA.Factor = tblKF.Factor AND tblA.Type = tblKF.Type


				


				UPDATE tblKF SET 
				tblKF.EzafMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Ezaf AS BIGINT),
				tblKF.KasrMashmol = CAST(( CAST(tblKF.Mab AS DECIMAL(18, 3))   / CAST(tblMF.Mab AS DECIMAL(18, 3)) ) * tblAm.Kasr AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMF ON tblKF.Factor = tblMF.Factor AND tblKF.Type = tblMF.Type
				INNER JOIN #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm ON tblAm.Factor = tblKF.Factor AND tblAm.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0






				IF ( OBJECT_ID('#RptKharidAndAvamelKala_Difference', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_Difference;   
				CREATE TABLE #RptKharidAndAvamelKala_Difference 
				(   
				 Factor INT ,   
				[Type] TINYINT , 
				Ezaf BIGINT ,
				Kasr BIGINT
				);    

				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(EzafMashmol),SUM(KasrMashmol) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type


				
			
		

				UPDATE tblD SET 
				tblD.Ezaf = tblAm.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblAm.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgentMashmol AS tblAm
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblam.Factor = tblD.Factor AND tblam.Type = tblD.Type





				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0


				UPDATE tblKF SET 
				tblKF.EzafMashmol = tblKF.EzafMashmol+tblD.Ezaf,
				tblKF.KasrMashmol = tblKF.KasrMashmol+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1

			
				DELETE FROM #RptKharidAndAvamelKala_Difference


				




				INSERT INTO #RptKharidAndAvamelKala_Difference
				SELECT Factor,Type,SUM(Ezaf),SUM(Kasr) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				
				UPDATE tblD SET 
				tblD.Ezaf = tblA.Ezaf - tblD.Ezaf,
				tblD.Kasr = tblA.Kasr - tblD.Kasr
				 FROM #RptKharidAndAvamelKala_MabAgent AS tblA
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblA.Factor = tblD.Factor AND tblA.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_Difference
				WHERE Ezaf = 0 AND Kasr = 0

				

				UPDATE tblKF SET 
				tblKF.Ezaf = tblKF.Ezaf+tblD.Ezaf,
				tblKF.Kasr = tblKF.Kasr+tblD.Kasr
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_Difference AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


			



			DELETE #RptKharidAndAvamelKala_MabFactorMashmol
			
        INSERT  INTO #RptKharidAndAvamelKala_MabFactorMashmol 
                SELECT  tbl.Factor, tbl.[Type], 
                        SUM((tbl.Mab+tbl.EzafMashmol-tbl.KasrMashmol)*tbl.DarsadMashmol)   
                FROM    #RptKharidAndAvamelKala_Base AS tbl   
				WHERE tbl.Mashmol = 1 AND tbl.DarsadMashmol>0
                GROUP BY tbl.Factor, tbl.[Type];   
				
				 
   
		IF ( OBJECT_ID('#RptKharidAndAvamelKala_MabMaliat', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_MabMaliat; 
		CREATE TABLE #RptKharidAndAvamelKala_MabMaliat 
            (   
              Factor INT ,   
              [Type] TINYINT , 
              Mab BIGINT 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_MabMaliat   
                ( Factor ,   
                  [Type] , 
				  Mab
                )   
                SELECT  tbl.Factor , 
						tbl.[Type] , 
                        CASE tbl.[Type] WHEN 103 THEN SUM(dbo.TR.Bed-dbo.TR.Bes) ELSE SUM(dbo.TR.Bes-dbo.TR.Bed) END
                FROM    #RptKharidAndAvamelKala_MabFactor AS tbl   
                        INNER JOIN dbo.TR ON TR.Factor = tbl.Factor AND TR.Type = tbl.Type 
						LEFT JOIN dbo.TblFactorAvamelKharid AS fa ON fa.Id = dbo.TR.IdAmel
                WHERE    
                        Idkala = 0   
                        AND Tp1 > 0  
						AND ( ISNULL(fa.Maliat, 0) = 1 )
                GROUP BY tbl.Factor , tbl.[Type]  	




				UPDATE tblKF SET 
				tblKF.Maliat = CAST(( CAST((tblKF.Mab+EzafMashmol-KasrMashmol) * tblKF.DarsadMashmol AS DECIMAL(18, 3))   / CAST(tblMFM.Mab AS DECIMAL(18, 3)) ) * tblM.Mab AS BIGINT)
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_MabFactorMashmol AS tblMFM ON tblKF.Factor = tblMFM.Factor AND tblKF.Type = tblMFM.Type
				INNER JOIN #RptKharidAndAvamelKala_MabMaliat AS tblM ON tblM.Factor = tblKF.Factor AND tblM.Type = tblKF.Type
				WHERE tblKF.Mashmol = 1 AND tblKF.DarsadMashmol>0


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_DifferenceMaliat', 'U') ) IS NOT NULL 
					DROP TABLE  #RptKharidAndAvamelKala_DifferenceMaliat;   
				CREATE TABLE #RptKharidAndAvamelKala_DifferenceMaliat 
				(   
				 Factor INT ,   
				 [Type] TINYINT , 
				 Mab BIGINT 
				);    

				INSERT INTO #RptKharidAndAvamelKala_DifferenceMaliat
				SELECT Factor,Type,SUM(Maliat) FROM #RptKharidAndAvamelKala_Base
				GROUP BY Factor,Type

				UPDATE tblD SET 
				tblD.Mab = tblM.Mab - tblD.Mab
				 FROM #RptKharidAndAvamelKala_MabMaliat AS tblM
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblM.Factor = tblD.Factor AND tblM.Type = tblD.Type


				DELETE FROM #RptKharidAndAvamelKala_DifferenceMaliat
				WHERE Mab = 0


				UPDATE tblKF SET 
				tblKF.Maliat = tblKF.Maliat+tblD.Mab
				FROM #RptKharidAndAvamelKala_Base AS tblKF
				INNER JOIN #RptKharidAndAvamelKala_DifferenceMaliat AS tblD ON tblD.Factor = tblKF.Factor AND tblD.Type = tblKF.Type AND tblKF.Rank = 1


				IF ( OBJECT_ID('#RptKharidAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL 
			DROP TABLE  #RptKharidAndAvamelKala_TasviyeFactorTmp;   
		CREATE TABLE #RptKharidAndAvamelKala_TasviyeFactorTmp		 
            (   
			  Shfactor INT ,   
              [Type] TINYINT , 
			  Code VARCHAR(100) 
            );     
        INSERT  INTO #RptKharidAndAvamelKala_TasviyeFactorTmp 
                SELECT  tbl.Factor, tbl.[Type], CAST(ttr.Srfsl AS VARCHAR) + '-' + CAST(ttr.Moin AS VARCHAR) + '-' + CAST(ttr.HSB AS VARCHAR) COLLATE DATABASE_DEFAULT 
                           
                FROM    #RptKharidAndAvamelKala_Base AS tbl 
				LEFT JOIN dbo.TR AS ttr ON ttr.Factor = tbl.Factor AND ttr.[Type] = tbl.[Type] 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 
		 
		IF (ISNULL(@Tasviye, '') <> '') 
		BEGIN 
			DELETE #RptKharidAndAvamelKala_TasviyeFactorTmp WHERE Code COLLATE DATABASE_DEFAULT NOT IN (SELECT id COLLATE DATABASE_DEFAULT FROM dbo.CSVToTableStr(@Tasviye)) 
		END 
			
			

			IF ( OBJECT_ID('#RptKharidAndBargashtKharidAggregation_Final', 'U') ) IS NOT NULL
        DROP TABLE  #RptKharidAndBargashtKharidAggregation_Final;  
    CREATE TABLE #RptKharidAndBargashtKharidAggregation_Final
        (
		  CustomerId INT ,
		  CustomerName NVARCHAR(200) ,
          TedKharid DECIMAL(18, 5) ,
          MabKharid BIGINT ,
          TedBargasht DECIMAL(18, 5) ,
          MabBargasht BIGINT,
		  MabMaliatKharid BIGINT,
		  MabMaliatBargasht BIGINT,
	      WeightKala NUMERIC(18,3)
        );
	INSERT INTO #RptKharidAndBargashtKharidAggregation_Final
	        ( 
			  CustomerId ,
	          CustomerName ,
			  TedKharid ,
	          MabKharid ,
	          TedBargasht ,
	          MabBargasht,
			  MabMaliatKharid,
			  MabMaliatBargasht,
			  WeightKala
	        )


			  SELECT 
               ISNULL(TblFactorOnvan.CustumCod,0) as CustomerId ,
               ISNULL(LTRIM(RTRIM(TblPerson.Name+' '+ TblPerson.Famil)),'') COLLATE DATABASE_DEFAULT CustomerName ,
			   CASE tr.Type WHEN 103 THEN tr.Ted ELSE 0 END AS TedKharid ,
			   CASE tr.Type WHEN 103 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabKharid,
			   CASE tr.Type WHEN 204 THEN tr.Ted ELSE 0 END AS TedBargasht ,
			   CASE tr.Type WHEN 204 THEN TR.Mab+tr.EzafMashmol-tr.KasrMashmol-Kasr+Ezaf ELSE 0 END AS MabBargasht,
			   CASE tr.Type WHEN 103 THEN Maliat ELSE 0 END AS MabMaliatKharid,
			   CASE tr.Type WHEN 204 THEN Maliat ELSE 0 END AS MabMaliatBargasht,
			   CASE tr.Type WHEN 204 THEN tr.WeightKala*-1 ELSE tr.WeightKala END AS WeightKala
			   FROM #RptKharidAndAvamelKala_Base AS tr
               LEFT OUTER JOIN dbo.TblKala ON TR.Idkala = dbo.TblKala.IDKala AND TR.IdAnbar = dbo.TblKala.IDAnbar
               LEFT OUTER JOIN dbo.TblFactorOnvan ON TR.Type = dbo.TblFactorOnvan.Type AND TR.Factor = dbo.TblFactorOnvan.ShFactor
               LEFT OUTER JOIN dbo.TblPerson ON dbo.TblFactorOnvan.CustumCod = dbo.TblPerson.Sh_ozviat
			   WHERE  ( @IdKala IS NULL
                                          OR tr.IDKala IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdKala) )
                                        )
                                    AND ( @IdAnbar IS NULL
                                          OR TR.IdAnbar IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTable(@IdAnbar) )
                                        )
									
									AND ( @GroupCode IS NULL
                                          OR ISNULL(dbo.TblKala.GroupCode,'') IN (
                                          SELECT    *
                                          FROM      dbo.CSVToTableStr(@GroupCode) )
                                        )
									AND	( @Tasviye IS NULL 
						  OR EXISTS (SELECT * FROM #RptKharidAndAvamelKala_TasviyeFactorTmp AS tt WHERE tt.Shfactor = tr.Factor AND tt.[Type] = TR.[Type]))


	
	
	SELECT  CAST(ISNULL(tblM.id, 0) AS BIT) AS Tik ,
            tbl.CustomerId ,
            tbl.CustomerName ,
            CAST(SUM(tbl.TedKharid) AS FLOAT) AS TedKharid ,
            SUM(tbl.MabKharid) AS MabKharid ,
			SUM(tbl.MabMaliatKharid) AS MabMaliatKharid ,
            CAST(SUM(tbl.TedBargasht)  AS FLOAT) AS TedBargasht ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabMaliatBargasht) AS MabMaliatBargasht ,
			CAST(SUM(tbl.TedKharid) - SUM(tbl.TedBargasht) AS FLOAT) AS TedKol ,
			SUM(tbl.MabKharid) - SUM(tbl.MabBargasht) AS Mab,
			SUM(MabMaliatKharid) - SUM(MabMaliatBargasht) AS MabMaliat,
			SUM(tbl.MabKharid+MabMaliatKharid) - SUM(tbl.MabBargasht+MabMaliatBargasht) AS MabKol,
			SUM(tbl.WeightKala) AS WeightKala
            FROM    #RptKharidAndBargashtKharidAggregation_Final AS tbl
			LEFT OUTER JOIN dbo.CSVToTable(@Moshtari) AS tblM ON tblM.id = tbl.CustomerId
    GROUP BY CAST(ISNULL(tblM.id, 0) AS BIT) ,
            tbl.CustomerId ,
			tbl.CustomerName
    ORDER BY tbl.CustomerId;	
										  
END

GO

-- Procedure: [dbo].[RptKharidAndBarghashKharidTasviye]
IF OBJECT_ID(N'[dbo].[RptKharidAndBarghashKharidTasviye]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBarghashKharidTasviye] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBarghashKharidTasviye]
    @Date1 CHAR(10) , 
    @Date2 CHAR(10) , 
    @CShobe INT = 0 , 
    @IdKala NVARCHAR(MAX) = NULL , 
    @IdAnbar VARCHAR(MAX) = NULL , 
    @Moshtari VARCHAR(MAX) = NULL , 
	@Tasviye VARCHAR(MAX) = NULL,
	@Vizitor VARCHAR(MAX) = NULL,
	@Driver VARCHAR(MAX) = NULL ,
	@GroupCode VARCHAR(MAX) = NULL  ,
	@Type VARCHAR(10) = '204,103'   
	  
AS  
    BEGIN    
        IF ( OBJECT_ID('#RptKharidAndAvamelKala_Base', 'U') ) IS NOT NULL  
            DROP TABLE  #RptKharidAndAvamelKala_Base;       
        CREATE TABLE #RptKharidAndAvamelKala_Base  
            (  
              Shfactor INT ,  
              [Type] TINYINT ,
			  CustomerId INT ,
			  [Rank] INT ,  
              IdAnbar INT ,  
              IdKala INT , 
              Mab BIGINT ,  
              Takh BIGINT ,  
              Ted INT,
			  VizitorId INT,
			  DriverId INT,
			  GroupCode NVARCHAR(100)
            );    
        INSERT  INTO #RptKharidAndAvamelKala_Base  
                ( Shfactor ,  
                  [Type] ,
				  CustomerId ,
				  [Rank] ,  
                  IdAnbar ,  
                  IdKala ,  
                  Mab ,  
                  Takh ,  
                  Ted,
				  VizitorId,
				  DriverId,
				  GroupCode
                )  
                SELECT  Factor ,
						dbo.TR.[Type] ,
						ISNULL(tfo.CustumCod,0) ,
						RANK() OVER ( PARTITION BY TR.Factor,tr.Type ORDER BY MIN(Sodor) ) ,   
                        IdAnbr ,   
                        TR.Idkala , 
                        SUM(Bes + Bed) ,
                        SUM(Takh) ,   
                        SUM(TED),
						ISNULL(tfo.VizitorID,0),
						ISNULL(tfo.Driver,0),
						ISNULL(TblKala.GroupCode,'')
                FROM    dbo.TR
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar
                                                   AND TR.Idkala = dbo.TblKala.IDKala
												   LEFT OUTER JOIN dbo.TblFactorOnvan AS tfo ON dbo.TR.Factor = tfo.ShFactor AND dbo.TR.[Type] = tfo.[Type]
                WHERE   TR.[Type] IN (SELECT * FROM dbo.CSVToTable(@Type))  
						AND TR.Idkala > 0   
                        AND DateR BETWEEN @Date1 AND @Date2
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 )							  
				GROUP BY Factor, dbo.TR.[Type], tfo.CustumCod, IdAnbr, TR.Idkala,tfo.VizitorID,tfo.Driver,dbo.TblKala.GroupCode

		IF (ISNULL(@IdKala, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE IdKala NOT IN (SELECT * FROM dbo.CSVToTableStr(@IdKala))
		END	

		IF (ISNULL(@IdAnbar, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE IdAnbar NOT IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))
		END

		IF (ISNULL(@Moshtari, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE CustomerId NOT IN (SELECT * FROM dbo.CSVToTable(@Moshtari))
		END

		IF (ISNULL(@Vizitor, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE VizitorId NOT IN (SELECT * FROM dbo.CSVToTable(@Vizitor))
		END


		IF (ISNULL(@Driver, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE DriverId NOT IN (SELECT * FROM dbo.CSVToTable(@Driver))
		END

		IF (ISNULL(@GroupCode, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE GroupCode NOT IN (SELECT * FROM dbo.CSVToTableStr(@GroupCode))
		END

		IF ( OBJECT_ID('##RptKharidAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL
			DROP TABLE  #RptKharidAndAvamelKala_TasviyeFactorTmp;  
		CREATE TABLE #RptKharidAndAvamelKala_TasviyeFactorTmp		
            (  
			  Shfactor INT ,  
              [Type] TINYINT ,
			  MabKharid BIGINT ,
			  MabBargasht BIGINT ,
			  Srfsl INT ,
			  Moin INT ,
			  HSB INT 
            );    
        INSERT  INTO #RptKharidAndAvamelKala_TasviyeFactorTmp
                SELECT  ttr.Factor, ttr.[Type], SUM(ttr.Bes - ttr.Bed), 0, ttr.Srfsl, ttr.Moin, ttr.HSB
                FROM    dbo.TR AS ttr 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 AND EXISTS (SELECT * FROM #RptKharidAndAvamelKala_Base AS tbl WHERE ttr.Factor = tbl.Shfactor AND ttr.[Type] = tbl.[Type])
		GROUP BY ttr.Factor, ttr.[Type], ttr.Srfsl, ttr.Moin, ttr.HSB	

		DELETE #RptKharidAndAvamelKala_TasviyeFactorTmp
		WHERE NOT EXISTS (SELECT * FROM #RptKharidAndAvamelKala_Base AS tblBase WHERE tblBase.Shfactor = Shfactor AND tblBase.[Type] = [Type])
		
	UPDATE tbl
	SET tbl.MabBargasht = MabKharid * -1, tbl.MabKharid = 0
	FROM #RptKharidAndAvamelKala_TasviyeFactorTmp AS tbl WHERE [Type] = 204
	
	SELECT  CAST( CASE ISNULL(tblT.id, '') WHEN '' THEN 0 ELSE 1 END AS BIT) AS Tik ,
            tbl.Srfsl ,
            tbl.Moin ,
			tbl.HSB ,
			dbo.GetSahebHesab(tbl.Srfsl, tbl.Moin, tbl.HSB) AS HesabName ,
            SUM(tbl.MabKharid) AS MabKharid ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabKharid) - SUM(tbl.MabBargasht) AS MabKol
            FROM    #RptKharidAndAvamelKala_TasviyeFactorTmp AS tbl
			LEFT OUTER JOIN dbo.CSVToTableStr(@Tasviye) AS tblT ON tblT.id = CAST(tbl.Srfsl AS VARCHAR) + '-' + CAST(tbl.Moin AS VARCHAR) + '-' + CAST(tbl.HSB AS VARCHAR)  COLLATE DATABASE_DEFAULT
    GROUP BY CAST( CASE ISNULL(tblT.id, '') WHEN '' THEN 0 ELSE 1 END AS BIT) ,
            tbl.Srfsl ,
            tbl.Moin ,
			tbl.HSB ,
			dbo.GetSahebHesab(tbl.Srfsl, tbl.Moin, tbl.HSB) 
    ORDER BY tbl.Srfsl, tbl.Moin, tbl.HSB
   
    END;

GO

