-- Procedure: [dbo].[sp_Migrate_ARTICLE_To_TblBarCode]
IF OBJECT_ID(N'[dbo].[sp_Migrate_ARTICLE_To_TblBarCode]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_Migrate_ARTICLE_To_TblBarCode] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_Migrate_ARTICLE_To_TblBarCode]
    @TotalMigrated INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @StartTime DATETIME = GETDATE();
    DECLARE @InsertedCount INT = 0;
    DECLARE @UpdatedCount INT = 0;
    SET @TotalMigrated = 0;

    PRINT N'======================================================';
    PRINT N'🚀 شروع فرآیند مهاجرت دیتابیس: [Holoo1] -> [Sepehr_Update_14050610]';
    PRINT N'ماژول: جدول [ARTICLE] به جدول [TblBarCode] (حالت: upsert)';
    PRINT N'======================================================';

    -- 1. Validation Checks
    IF NOT EXISTS (SELECT 1 FROM sys.databases WHERE name = N'Holoo1')
    BEGIN
        RAISERROR(N'❌ پایگاه‌داده مبدأ [Holoo1] در سرور یافت نشد یا اتچ نیست.', 16, 1);
        RETURN -1;
    END

    IF OBJECT_ID(N'[Holoo1].[dbo].[ARTICLE]', 'U') IS NULL
    BEGIN
        RAISERROR(N'❌ جدول مبدأ [ARTICLE] در دیتابیس مبدأ یافت نشد.', 16, 1);
        RETURN -2;
    END

    IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[TblBarCode]', 'U') IS NULL
    BEGIN
        RAISERROR(N'❌ جدول مقصد [TblBarCode] در دیتابیس مقصد یافت نشد.', 16, 1);
        RETURN -3;
    END

    -- 2. Transaction Execution with Full TRY/CATCH
    BEGIN TRY
        BEGIN TRANSACTION;


        DECLARE @MaxId INT = ISNULL((SELECT MAX([IdKala]) FROM [Sepehr_Update_14050610].[dbo].[TblBarCode] WITH (NOLOCK)), 0);

        -- غیرفعال‌سازی تریگرها جهت اجرای آنی و بدون تداخل
        ALTER TABLE [Sepehr_Update_14050610].[dbo].[TblBarCode] DISABLE TRIGGER ALL;

        -- مرحله ۱: به‌روزرسانی رکوردهای موجود با اطلاعات جدید مبدأ (Update Phase)
        PRINT N'🔄 در حال به‌روزرسانی رکوردهای موجود در جدول مقصد...';
        UPDATE T SET
            T.[Barcod] = ISNULL(REPLACE(REPLACE(CAST(S.[A_Code_C] AS NVARCHAR(MAX)), N'ي', N'ی'), N'ك', N'ک'), '')
        FROM [Sepehr_Update_14050610].[dbo].[TblBarCode] AS T
        INNER JOIN [Holoo1].[dbo].[ARTICLE] AS S WITH (NOLOCK)
            ON T.[IdKala] = TRY_CAST(S.[A_Code] AS INT) AND LTRIM(RTRIM(T.[Barcod])) COLLATE Arabic_CI_AS = LTRIM(RTRIM(S.[A_Code_C])) COLLATE Arabic_CI_AS
        WHERE (([Delete] = 0 OR [Delete] IS NULL) AND A_Code_C IS NOT NULL AND LTRIM(RTRIM(A_Code_C)) <> '');

        SET @UpdatedCount = @@ROWCOUNT;

        -- مرحله ۲: درج رکوردهای جدیدی که در جدول مقصد وجود ندارند (Insert New Phase)
        PRINT N'➕ در حال درج رکوردهای جدید...';
        INSERT INTO [Sepehr_Update_14050610].[dbo].[TblBarCode] (
        [IdKala],
        [IdAnbar],
        [Barcod],
        [IdUnit],
        [CreatedUser],
        [CreatedTime]
        )
        SELECT
        ISNULL(TRY_CAST(S.[A_Code] AS INT), (@MaxId + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)))),
        '1',
        ISNULL(REPLACE(REPLACE(CAST(S.[A_Code_C] AS NVARCHAR(MAX)), N'ي', N'ی'), N'ك', N'ک'), ''),
        '1',
        '1',
        ''
        FROM [Holoo1].[dbo].[ARTICLE] AS S WITH (NOLOCK)
        WHERE NOT EXISTS (
            SELECT 1 FROM [Sepehr_Update_14050610].[dbo].[TblBarCode] T WITH (NOLOCK)
            WHERE T.[IdKala] = TRY_CAST(S.[A_Code] AS INT) AND LTRIM(RTRIM(T.[Barcod])) COLLATE Arabic_CI_AS = LTRIM(RTRIM(S.[A_Code_C])) COLLATE Arabic_CI_AS
        ) AND (([Delete] = 0 OR [Delete] IS NULL) AND A_Code_C IS NOT NULL AND LTRIM(RTRIM(A_Code_C)) <> '');

        SET @InsertedCount = @@ROWCOUNT;
        SET @TotalMigrated = @InsertedCount + @UpdatedCount;

        -- فعال‌سازی مجدد تریگرهای جدول مقصد
        ALTER TABLE [Sepehr_Update_14050610].[dbo].[TblBarCode] ENABLE TRIGGER ALL;

        -- ثبت در جدول رهگیری دائمی Migration_Holoo_BarcodeMap
        IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[Migration_Holoo_BarcodeMap]', 'U') IS NOT NULL
        BEGIN
            INSERT INTO [Sepehr_Update_14050610].[dbo].[Migration_Holoo_BarcodeMap] (
                HolooA_Code, SepehrIDKala, Barcod, Status
            )
            SELECT 
                S.A_Code, TRY_CAST(S.A_Code AS INT), LTRIM(RTRIM(S.A_Code_C)), N'Transferred'
            FROM [Holoo1].[dbo].[ARTICLE] S WITH (NOLOCK)
            INNER JOIN [Sepehr_Update_14050610].[dbo].[TblBarCode] B WITH (NOLOCK)
                ON B.IdKala = TRY_CAST(S.A_Code AS INT) AND LTRIM(RTRIM(B.Barcod)) COLLATE Arabic_CI_AS = LTRIM(RTRIM(S.A_Code_C)) COLLATE Arabic_CI_AS
            WHERE (S.[Delete] = 0 OR S.[Delete] IS NULL) 
              AND S.A_Code_C IS NOT NULL AND LTRIM(RTRIM(S.A_Code_C)) <> ''
              AND NOT EXISTS (
                  SELECT 1 FROM [Sepehr_Update_14050610].[dbo].[Migration_Holoo_BarcodeMap] M WITH (NOLOCK)
                  WHERE M.Barcod COLLATE Arabic_CI_AS = LTRIM(RTRIM(S.A_Code_C)) COLLATE Arabic_CI_AS
              );
        END

        -- Commit Transaction
        COMMIT TRANSACTION;

        DECLARE @DurationSec INT = DATEDIFF(SECOND, @StartTime, GETDATE());
        PRINT N'======================================================';
        PRINT N'✅ فرآیند انتقال با موفقیت به پایان رسید!';
        PRINT N'📊 تعداد رکوردهای درج‌شده جدید: ' + CAST(@InsertedCount AS NVARCHAR(20));
        PRINT N'🔄 تعداد رکوردهای به‌روزرسانی‌شده: ' + CAST(@UpdatedCount AS NVARCHAR(20));
        PRINT N'🎯 مجموع رکوردهای پردازش‌شده: ' + CAST(@TotalMigrated AS NVARCHAR(20));
        PRINT N'⏱️ زمان صرف‌شده: ' + CAST(@DurationSec AS NVARCHAR(10)) + N' ثانیه.';
        PRINT N'======================================================';

        SELECT 
            @InsertedCount AS [MigratedCount],
            @UpdatedCount AS [UpdatedCount],
            @TotalMigrated AS [TotalProcessed],
            DATEDIFF(MILLISECOND, @StartTime, GETDATE()) AS [ElapsedMs],
            N'موفق' AS [Status];

        RETURN 0;
    END TRY
    BEGIN CATCH
        -- Rollback on Error
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        -- اطمینان از فعال‌سازی مجدد تریگرها در صورت بروز خطا
        IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[TblBarCode]', 'U') IS NOT NULL
        BEGIN
            BEGIN TRY
                ALTER TABLE [Sepehr_Update_14050610].[dbo].[TblBarCode] ENABLE TRIGGER ALL;
            END TRY
            BEGIN CATCH
            END CATCH;
        END

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        DECLARE @ErrorLine INT = ERROR_LINE();

        PRINT N'❌ بروز خطا در هنگام انتقال داده‌ها:';
        PRINT N'پیام خطا: ' + @ErrorMessage;
        PRINT N'شماره خط: ' + CAST(@ErrorLine AS NVARCHAR(10));

        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
        RETURN -99;
    END CATCH
END;
GO

