            BEGIN CATCH
            END CATCH;
        END

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        DECLARE @ErrorLine INT = ERROR_LINE();

        PRINT N'❌ بروز خطا در هنگام انتقال داده‌ها:';
        PRINT N'پیام خطا: ' + @ErrorMessage;
        PRINT N'شماره خط: ' + CAST(@ErrorLine AS NVARCHAR(10));

        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
        RETURN -99;
    END CATCH
END;
GO

-- Procedure: [dbo].[sp_Migrate_ARTICLE_To_TblPrice]
IF OBJECT_ID(N'[dbo].[sp_Migrate_ARTICLE_To_TblPrice]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_Migrate_ARTICLE_To_TblPrice] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_Migrate_ARTICLE_To_TblPrice]
    @TotalMigrated INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @StartTime DATETIME = GETDATE();
    DECLARE @InsertedCount INT = 0;
    DECLARE @UpdatedCount INT = 0;
    SET @TotalMigrated = 0;

    PRINT N'======================================================';
    PRINT N'🚀 شروع فرآیند مهاجرت دیتابیس: [Holoo1] -> [Sepehr_Update_14050610]';
    PRINT N'ماژول: جدول [ARTICLE] به جدول [TblPrice] (حالت: upsert)';
    PRINT N'======================================================';

    -- 1. Validation Checks
    IF NOT EXISTS (SELECT 1 FROM sys.databases WHERE name = N'Holoo1')
    BEGIN
        RAISERROR(N'❌ پایگاه‌داده مبدأ [Holoo1] در سرور یافت نشد یا اتچ نیست.', 16, 1);
        RETURN -1;
    END

    IF OBJECT_ID(N'[Holoo1].[dbo].[ARTICLE]', 'U') IS NULL
    BEGIN
        RAISERROR(N'❌ جدول مبدأ [ARTICLE] در دیتابیس مبدأ یافت نشد.', 16, 1);
        RETURN -2;
    END

    IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[TblPrice]', 'U') IS NULL
    BEGIN
        RAISERROR(N'❌ جدول مقصد [TblPrice] در دیتابیس مقصد یافت نشد.', 16, 1);
        RETURN -3;
    END

    -- 2. Transaction Execution with Full TRY/CATCH
    BEGIN TRY
        BEGIN TRANSACTION;


        DECLARE @MaxId INT = ISNULL((SELECT MAX([IDKala]) FROM [Sepehr_Update_14050610].[dbo].[TblPrice] WITH (NOLOCK)), 0);

        -- غیرفعال‌سازی تریگرها جهت اجرای آنی و بدون تداخل
        ALTER TABLE [Sepehr_Update_14050610].[dbo].[TblPrice] DISABLE TRIGGER ALL;

        -- مرحله ۱: به‌روزرسانی رکوردهای موجود با اطلاعات جدید مبدأ (Update Phase)
        PRINT N'🔄 در حال به‌روزرسانی رکوردهای موجود در جدول مقصد...';
        UPDATE T SET
            T.[Price] = ISNULL(TRY_CAST(S.[Sel_Price] AS FLOAT), 0)
        FROM [Sepehr_Update_14050610].[dbo].[TblPrice] AS T
        INNER JOIN [Holoo1].[dbo].[ARTICLE] AS S WITH (NOLOCK)
            ON T.[IDKala] = TRY_CAST(S.[A_Code] AS INT) AND T.[IDAnbar] = 1 AND T.[IDLable] = 1
        WHERE (([Delete] = 0 OR [Delete] IS NULL) AND Sel_Price > 0);

        SET @UpdatedCount = @@ROWCOUNT;

        -- مرحله ۲: درج رکوردهای جدیدی که در جدول مقصد وجود ندارند (Insert New Phase)
        PRINT N'➕ در حال درج رکوردهای جدید...';
        INSERT INTO [Sepehr_Update_14050610].[dbo].[TblPrice] (
        [IDLable],
        [IDAnbar],
        [IDKala],
        [Price],
        [SiteSync],
        [BPMSSync],
        [ModifyTime]
        )
        SELECT
        '1',
        '1',
        ISNULL(TRY_CAST(S.[A_Code] AS INT), (@MaxId + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)))),
        ISNULL(TRY_CAST(S.[Sel_Price] AS FLOAT), 0),
        '0',
        '0',
        ''
        FROM [Holoo1].[dbo].[ARTICLE] AS S WITH (NOLOCK)
        WHERE NOT EXISTS (
            SELECT 1 FROM [Sepehr_Update_14050610].[dbo].[TblPrice] T WITH (NOLOCK)
            WHERE T.[IDKala] = TRY_CAST(S.[A_Code] AS INT) AND T.[IDAnbar] = 1 AND T.[IDLable] = 1
        ) AND (([Delete] = 0 OR [Delete] IS NULL) AND Sel_Price > 0);

        SET @InsertedCount = @@ROWCOUNT;
        SET @TotalMigrated = @InsertedCount + @UpdatedCount;

        -- فعال‌سازی مجدد تریگرهای جدول مقصد
        ALTER TABLE [Sepehr_Update_14050610].[dbo].[TblPrice] ENABLE TRIGGER ALL;

        -- مرحله ۳: به‌روزرسانی و درج قیمت سطح ۲ (همکاری) از Sel_Price2 هلو
        PRINT N'🔄 در حال پردازش قیمت‌های سطح ۲ (همکاری)...';
        UPDATE T SET
            T.[Price] = ISNULL(TRY_CAST(S.[Sel_Price2] AS FLOAT), 0)
        FROM [Sepehr_Update_14050610].[dbo].[TblPrice] AS T
        INNER JOIN [Holoo1].[dbo].[ARTICLE] AS S WITH (NOLOCK)
            ON T.[IDKala] = TRY_CAST(S.[A_Code] AS INT) AND T.[IDAnbar] = 1 AND T.[IDLable] = 2
        WHERE (S.[Delete] = 0 OR S.[Delete] IS NULL) AND S.Sel_Price2 > 0;

        INSERT INTO [Sepehr_Update_14050610].[dbo].[TblPrice] (
            [IDLable], [IDAnbar], [IDKala], [Price], [SiteSync], [BPMSSync], [ModifyTime]
        )
        SELECT
            2, 1, TRY_CAST(S.[A_Code] AS INT), ISNULL(TRY_CAST(S.[Sel_Price2] AS FLOAT), 0), 0, 0, ''
        FROM [Holoo1].[dbo].[ARTICLE] AS S WITH (NOLOCK)
        WHERE NOT EXISTS (
            SELECT 1 FROM [Sepehr_Update_14050610].[dbo].[TblPrice] T WITH (NOLOCK)
            WHERE T.[IDKala] = TRY_CAST(S.[A_Code] AS INT) AND T.[IDAnbar] = 1 AND T.[IDLable] = 2
        ) AND (S.[Delete] = 0 OR S.[Delete] IS NULL) AND S.Sel_Price2 > 0;

        -- ثبت در جدول رهگیری دائمی Migration_Holoo_PriceMap
        IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[Migration_Holoo_PriceMap]', 'U') IS NOT NULL
        BEGIN
            INSERT INTO [Sepehr_Update_14050610].[dbo].[Migration_Holoo_PriceMap] (
                HolooA_Code, SepehrIDKala, IDAnbar, IDLable, SourcePrice, TargetPrice, Status
            )
            SELECT 
                S.A_Code, TRY_CAST(S.A_Code AS INT), 1, 1, S.Sel_Price, T.Price, N'Transferred'
            FROM [Holoo1].[dbo].[ARTICLE] S WITH (NOLOCK)
            INNER JOIN [Sepehr_Update_14050610].[dbo].[TblPrice] T WITH (NOLOCK)
                ON T.IDKala = TRY_CAST(S.A_Code AS INT) AND T.IDAnbar = 1 AND T.IDLable = 1
            WHERE (S.[Delete] = 0 OR S.[Delete] IS NULL) AND S.Sel_Price > 0
              AND NOT EXISTS (
                  SELECT 1 FROM [Sepehr_Update_14050610].[dbo].[Migration_Holoo_PriceMap] M WITH (NOLOCK)
                  WHERE M.SepehrIDKala = T.IDKala AND M.IDLable = 1
              );

            INSERT INTO [Sepehr_Update_14050610].[dbo].[Migration_Holoo_PriceMap] (
                HolooA_Code, SepehrIDKala, IDAnbar, IDLable, SourcePrice, TargetPrice, Status
            )
            SELECT 
                S.A_Code, TRY_CAST(S.A_Code AS INT), 1, 2, S.Sel_Price2, T.Price, N'Transferred'
            FROM [Holoo1].[dbo].[ARTICLE] S WITH (NOLOCK)
            INNER JOIN [Sepehr_Update_14050610].[dbo].[TblPrice] T WITH (NOLOCK)
                ON T.IDKala = TRY_CAST(S.A_Code AS INT) AND T.IDAnbar = 1 AND T.IDLable = 2
            WHERE (S.[Delete] = 0 OR S.[Delete] IS NULL) AND S.Sel_Price2 > 0
              AND NOT EXISTS (
                  SELECT 1 FROM [Sepehr_Update_14050610].[dbo].[Migration_Holoo_PriceMap] M WITH (NOLOCK)
                  WHERE M.SepehrIDKala = T.IDKala AND M.IDLable = 2
              );
        END

        -- Commit Transaction
        COMMIT TRANSACTION;

        DECLARE @DurationSec INT = DATEDIFF(SECOND, @StartTime, GETDATE());
        PRINT N'======================================================';
        PRINT N'✅ فرآیند انتقال با موفقیت به پایان رسید!';
        PRINT N'📊 تعداد رکوردهای درج‌شده جدید: ' + CAST(@InsertedCount AS NVARCHAR(20));
        PRINT N'🔄 تعداد رکوردهای به‌روزرسانی‌شده: ' + CAST(@UpdatedCount AS NVARCHAR(20));
        PRINT N'🎯 مجموع رکوردهای پردازش‌شده: ' + CAST(@TotalMigrated AS NVARCHAR(20));
        PRINT N'⏱️ زمان صرف‌شده: ' + CAST(@DurationSec AS NVARCHAR(10)) + N' ثانیه.';
        PRINT N'======================================================';

        SELECT 
            @InsertedCount AS [MigratedCount],
            @UpdatedCount AS [UpdatedCount],
            @TotalMigrated AS [TotalProcessed],
            DATEDIFF(MILLISECOND, @StartTime, GETDATE()) AS [ElapsedMs],
            N'موفق' AS [Status];

        RETURN 0;
    END TRY
    BEGIN CATCH
        -- Rollback on Error
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        -- اطمینان از فعال‌سازی مجدد تریگرها در صورت بروز خطا
        IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[TblPrice]', 'U') IS NOT NULL
        BEGIN
            BEGIN TRY
                ALTER TABLE [Sepehr_Update_14050610].[dbo].[TblPrice] ENABLE TRIGGER ALL;
            END TRY
            BEGIN CATCH
            END CATCH;
        END

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        DECLARE @ErrorLine INT = ERROR_LINE();

        PRINT N'❌ بروز خطا در هنگام انتقال داده‌ها:';
        PRINT N'پیام خطا: ' + @ErrorMessage;
        PRINT N'شماره خط: ' + CAST(@ErrorLine AS NVARCHAR(10));

        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
        RETURN -99;
    END CATCH
END;
GO

-- Procedure: [dbo].[sp_Migrate_ARTICLE_To_TblTRAnbar]
