ALTER PROCEDURE dbo.sp_Migrate_Holoo_Persons
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @UpdatedCount INT = 0;
    DECLARE @InsertedCount INT = 0;

    IF OBJECT_ID('dbo.TblPerson', 'U') IS NOT NULL
        ALTER TABLE dbo.TblPerson DISABLE TRIGGER ALL;

    UPDATE P
    SET
        P.Name          = LEFT(ISNULL(H.C_Name,''),200),
        P.Tell          = LEFT(ISNULL(H.C_Tel,''),100),
        P.Mobile        = LEFT(ISNULL(H.C_Mobile,''),500),
        P.Addres_mk     = LEFT(ISNULL(H.C_Address,''),200),
        P.Addres_home   = LEFT(ISNULL(H.C_Address,''),200),
        P.Cod_Egh       = LEFT(ISNULL(H.Economic_Code,''),500),
        P.codmeli       = LEFT(ISNULL(H.National_Code,''),500),
        P.Dt_Tavalod    = LEFT(ISNULL(H.Birth_Date,''),10),
        P.Srfsl         = 103,
        P.Moin          = 1,
        P.Hesab         = CONVERT(BIGINT,H.C_Code),
        P.Personal_Code = H.C_Code
    FROM dbo.TblPerson P
    INNER JOIN [Holoo1].[dbo].[CUSTOMER] H
        ON P.Sh_ozviat = CONVERT(INT,H.C_Code)
    WHERE ISNULL(H.[Delete],0)=0
      AND H.C_Code <> ''
      AND H.C_Code NOT LIKE '%[^0-9]%';

    SET @UpdatedCount = @@ROWCOUNT;

    INSERT INTO dbo.TblPerson
    (
        Sh_ozviat,Name,Famil,Sh_sh,FatherName,
        Srfsl,Moin,Hesab,mahaleSodur,Dt_Tavalod,
        Tell,Addres_mk,Addres_home,job,post,
        Cod_Egh,codmeli,Type,Mobile,AliasName,
        group_Id,Etebar,CityId,InsurerId,PersonGroupId,
        Status,MarketerPercent,BlackList,BlackListDesc,
        SystemCode,Email,Website,MarriageDate,
        AutomaticSMS,EtebarM,HoghoghM,DarsadEtebar,
        CShobe,IDLable,DureTasviye,PreName,RegionId,
        Kala_Score,CreateUser,CreateTime,ModifyUser,
        ModifyTime,PersonGroupId2,PersonGroupId3,
        PersonGroupId4,Note,CntCost,CntProject,
        SiteSync,Personal_Code,BPMSSync
    )
    SELECT
        CONVERT(INT,H.C_Code),
        LEFT(ISNULL(H.C_Name,''),200),
        N'', '', N'',
        103, 1, CONVERT(BIGINT,H.C_Code),
        N'', LEFT(ISNULL(H.Birth_Date,''),10),
        LEFT(ISNULL(H.C_Tel,''),100),
        LEFT(ISNULL(H.C_Address,''),200),
        LEFT(ISNULL(H.C_Address,''),200),
        N'', '',
        LEFT(ISNULL(H.Economic_Code,''),500),
        LEFT(ISNULL(H.National_Code,''),500),
        ISNULL(H.C_type,0),
        LEFT(ISNULL(H.C_Mobile,''),500),
        LEFT(ISNULL(H.C_AliasName,''),500),
        0, CONVERT(BIGINT,ISNULL(H.Etebar,0)),
        ISNULL(H.City_Code,0), 0, 0,
        1, 0, ISNULL(H.InListSiah,0), N'',
        H.C_Code, LEFT(ISNULL(H.Email_Address,''),50), N'', '',
        0, 0, 0, 0,
        0, 0, ISNULL(H.MohlatTasvieh,0), 0, 0,
        0, 0, '', 0, '', 0, 0,
        0, LEFT(ISNULL(H.Comment,N''),1000), 0, 0,
        0, H.C_Code, 0
    FROM [Holoo1].[dbo].[CUSTOMER] H
    WHERE ISNULL(H.[Delete],0)=0
      AND H.C_Code <> ''
      AND H.C_Code NOT LIKE '%[^0-9]%'
      AND NOT EXISTS
      (
          SELECT 1
          FROM dbo.TblPerson P
          WHERE P.Sh_ozviat = CONVERT(INT,H.C_Code)
      );

    SET @InsertedCount = @@ROWCOUNT;

    IF OBJECT_ID('dbo.TblPerson', 'U') IS NOT NULL
        ALTER TABLE dbo.TblPerson ENABLE TRIGGER ALL;

    SELECT 
        N'اشخاص و طرف‌حساب‌ها' AS [ماژول],
        @UpdatedCount AS [تعداد ویرایش],
        @InsertedCount AS [تعداد درج جدید],
        (@UpdatedCount + @InsertedCount) AS [مجموع رکوردهای پردازش‌شده],
        N'✓ با موفقیت منتقل گردید' AS [وضعیت];
END;

GO

