    EXEC(N'CREATE PROCEDURE [dbo].[sp_Migrate_Selected_Modules_Pipeline] AS SELECT 1;');
GO

ALTER PROCEDURE dbo.sp_Migrate_Selected_Modules_Pipeline
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    CREATE TABLE #PipelineSummary (
        [ماژول] NVARCHAR(100),
        [تعداد ویرایش] INT,
        [تعداد درج جدید] INT,
        [مجموع رکوردهای پردازش‌شده] INT,
        [وضعیت] NVARCHAR(200)
    );

    BEGIN TRY
        PRINT N'🚀 آغاز اجرای پایپ‌لاین جامع انتقال اطلاعات...';

        -- ۱. کدینگ
        INSERT INTO #PipelineSummary EXEC dbo.sp_Migrate_Holoo_Sarfasl;

        -- ۲. کالا
        INSERT INTO #PipelineSummary EXEC dbo.sp_Migrate_Holoo_Kala;

        -- ۳. اشخاص
        INSERT INTO #PipelineSummary EXEC dbo.sp_Migrate_Holoo_Persons;

        PRINT N'✓ کلیه ماژول‌ها با موفقیت منتقل شدند.';

        SELECT * FROM #PipelineSummary;
    END TRY
    BEGIN CATCH
        DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@ErrMsg, 16, 1);
    END CATCH
END;

GO

-- Procedure: [dbo].[sp_Migrate_SND_LIST_To_TR]
IF OBJECT_ID(N'[dbo].[sp_Migrate_SND_LIST_To_TR]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_Migrate_SND_LIST_To_TR] AS SELECT 1;');
GO

ALTER PROCEDURE [dbo].[sp_Migrate_SND_LIST_To_TR]
    @TotalMigrated INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @StartTime DATETIME = GETDATE();
    DECLARE @InsertedCount INT = 0;
    DECLARE @UpdatedCount INT = 0;
    SET @TotalMigrated = 0;

    PRINT N'======================================================';
    PRINT N'🚀 شروع فرآیند مهاجرت دیتابیس: [Holoo1] -> [Sepehr_Update_14050610]';
    PRINT N'ماژول: جدول [SND_LIST] به جدول [TR] (حالت: upsert)';
    PRINT N'======================================================';

    -- 1. Validation Checks
    IF NOT EXISTS (SELECT 1 FROM sys.databases WHERE name = N'Holoo1')
    BEGIN
        RAISERROR(N'❌ پایگاه‌داده مبدأ [Holoo1] در سرور یافت نشد یا اتچ نیست.', 16, 1);
        RETURN -1;
    END

    IF OBJECT_ID(N'[Holoo1].[dbo].[SND_LIST]', 'U') IS NULL
    BEGIN
        RAISERROR(N'❌ جدول مبدأ [SND_LIST] در دیتابیس مبدأ یافت نشد.', 16, 1);
        RETURN -2;
    END

    IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[TR]', 'U') IS NULL
    BEGIN
        RAISERROR(N'❌ جدول مقصد [TR] در دیتابیس مقصد یافت نشد.', 16, 1);
        RETURN -3;
    END

    -- 2. Transaction Execution with Full TRY/CATCH
    BEGIN TRY
        BEGIN TRANSACTION;

        -- ۱. تنظیم قطعی ماهیت حساب‌ها در TblParam به واسطه (BdBs = 2) جهت رفع خطای ماهیت حساب بستانکار/بدهکار
        IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[TblParam]', 'U') IS NOT NULL
        BEGIN
            PRINT N'🔧 به‌روزرسانی ماهیت حساب‌ها در TblParam به وضعیت واسطه (BdBs = 2)...';
            UPDATE [Sepehr_Update_14050610].[dbo].[TblParam]
            SET BdBs = 2
            WHERE BdBs <> 2 OR BdBs IS NULL;
        END

        -- ۲. غیرفعال‌سازی موقت تریگرهای جداول مرتبط با ریز اسناد
        IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[Master]', 'U') IS NOT NULL
            BEGIN TRY ALTER TABLE [Sepehr_Update_14050610].[dbo].[Master] DISABLE TRIGGER ALL; END TRY BEGIN CATCH END CATCH;
        IF OBJECT_ID(N'[Sepehr_Update_14050610].[dbo].[TblSanad]', 'U') IS NOT NULL
            BEGIN TRY ALTER TABLE [Sepehr_Update_14050610].[dbo].[TblSanad] DISABLE TRIGGER ALL; END TRY BEGIN CATCH END CATCH;


        DECLARE @MaxId INT = ISNULL((SELECT MAX([Sodor]) FROM [Sepehr_Update_14050610].[dbo].[TR] WITH (NOLOCK)), 0);

        -- غیرفعال‌سازی تریگرها جهت اجرای آنی و بدون تداخل
        ALTER TABLE [Sepehr_Update_14050610].[dbo].[TR] DISABLE TRIGGER ALL;

        -- مرحله ۱: به‌روزرسانی رکوردهای موجود با اطلاعات جدید مبدأ (Update Phase)
        PRINT N'🔄 در حال به‌روزرسانی رکوردهای موجود در جدول مقصد...';
        UPDATE T SET
            T.[HSB] = ISNULL(TRY_CAST(S.[Tafzili_Code] AS BIGINT), 0),
            T.[DateR] = CASE WHEN S.[Date_Line] IS NOT NULL AND S.[Date_Line] > '1950-01-01' THEN SUBSTRING(dbo.MiladiToShamsi7(S.[Date_Line]), 1, 10) ELSE '1404/01/01' END,
            T.[Date] = CASE WHEN S.[Date_Line] IS NOT NULL AND S.[Date_Line] > '1950-01-01' THEN SUBSTRING(dbo.MiladiToShamsi7(S.[Date_Line]), 1, 10) ELSE '1404/01/01' END,
            T.[Serial] = LEFT(ISNULL(REPLACE(REPLACE(CAST(S.[Sanad_Code] AS NVARCHAR(MAX)), N'ي', N'ی'), N'ك', N'ک'), ''), 50),
            T.[Sharh] = LEFT(ISNULL(REPLACE(REPLACE(CAST(S.[Comment_Line] AS NVARCHAR(MAX)), N'ي', N'ی'), N'ك', N'ک'), ''), 1000),
            T.[SanadM] = ISNULL(TRY_CAST(S.[Sanad_Code] AS INT), 0),
            T.[Time] = CASE WHEN S.[Date_Line] IS NOT NULL THEN CONVERT(VARCHAR(8), S.[Date_Line], 108) ELSE '' END,
            T.[Bed] = ISNULL(TRY_CAST(S.[Bed] AS BIGINT), 0),
            T.[Bes] = ISNULL(TRY_CAST(S.[Bes] AS BIGINT), 0)
        FROM [Sepehr_Update_14050610].[dbo].[TR] AS T
        INNER JOIN [Holoo1].[dbo].[SND_LIST] AS S WITH (NOLOCK)
            ON T.[SanadM] = TRY_CAST(S.[Sanad_Code] AS INT) AND T.[Row] = ISNULL(TRY_CAST(S.[Index] AS INT), 1)
        WHERE (Sanad_Code > 0);

        SET @UpdatedCount = @@ROWCOUNT;

        -- مرحله ۲: درج رکوردهای جدیدی که در جدول مقصد وجود ندارند (Insert New Phase)
        PRINT N'➕ در حال درج رکوردهای جدید...';
        INSERT INTO [Sepehr_Update_14050610].[dbo].[TR] (
        [Sodor],
        [Srfsl],
        [Moin],
        [HSB],
        [GRP],
        [DateR],
        [Date],
        [Serial],
        [Sharh],
        [Idkala],
        [Factor],
