        [MacAddress],
        [Maliat],
        [TedTahvily],
        [TypeSanadBank],
        [TRDureTasviye],
        [ExpireDate],
        [Sodor_Id],
        [NumberFactor],
        [TypeFactor],
        [ShiftId],
        [kala_Score]
        )
        SELECT
        (@MaxId + ROW_NUMBER() OVER (ORDER BY (SELECT NULL))),
        ISNULL(TRY_CAST(S.[Col_Code] AS INT), 0),
        ISNULL(TRY_CAST(S.[Moien_Code] AS INT), 0),
        ISNULL(TRY_CAST(S.[Tafzili_Code] AS BIGINT), 0),
        '1',
        CASE WHEN S.[Date_Line] IS NOT NULL AND S.[Date_Line] > '1950-01-01' THEN SUBSTRING(dbo.MiladiToShamsi7(S.[Date_Line]), 1, 10) ELSE '1404/01/01' END,
        CASE WHEN S.[Date_Line] IS NOT NULL AND S.[Date_Line] > '1950-01-01' THEN SUBSTRING(dbo.MiladiToShamsi7(S.[Date_Line]), 1, 10) ELSE '1404/01/01' END,
        LEFT(ISNULL(REPLACE(REPLACE(CAST(S.[Sanad_Code] AS NVARCHAR(MAX)), N'ي', N'ی'), N'ك', N'ک'), ''), 50),
        LEFT(ISNULL(REPLACE(REPLACE(CAST(S.[Comment_Line] AS NVARCHAR(MAX)), N'ي', N'ی'), N'ك', N'ک'), ''), 1000),
        (@MaxId + ROW_NUMBER() OVER (ORDER BY (SELECT NULL))),
        '0',
