        CASE WHEN S.[Date_Line] IS NOT NULL THEN CONVERT(VARCHAR(8), S.[Date_Line], 108) ELSE '' END,
        '0',
        ISNULL(TRY_CAST(S.[Bed] AS BIGINT), 0),
        ISNULL(TRY_CAST(S.[Bes] AS BIGINT), 0),
        '0',
        '0',
        '0',
