GO

-- ============================================================================
-- بخش دوم: ایجاد پروسیجر ثبت متادیتا و پارامترها با ReportId = 100
-- ============================================================================
ALTER PROCEDURE [dbo].[sp_Register_Report_ShowFactorsMoved]
    @ReportName NVARCHAR(150) = N'گزارش اقلام جابجایی بین انبارها (شعب)',
    @FixedReportId INT = 100,
    @NewReportId INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ProcName NVARCHAR(50) = N'sp_tblreport_ShowFactorsMoved';
    DECLARE @GroupName NVARCHAR(100) = N'فیلترهای گزارش جابجایی کالا بین انبارها';
    DECLARE @GroupId INT = @FixedReportId; -- گروه فیلترها: ۱۰۰
    DECLARE @ItemId INT = NULL;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- ۱. ثبت یا واکشی گروه فیلترها در PayRol_TblGroupItem با شناسه ۱۰۰
        IF EXISTS (SELECT 1 FROM dbo.PayRol_TblGroupItem WHERE Id = @GroupId)
        BEGIN
            UPDATE dbo.PayRol_TblGroupItem
            SET Name = @GroupName, Type = '1'
            WHERE Id = @GroupId;
        END
        ELSE
        BEGIN
            INSERT INTO dbo.PayRol_TblGroupItem (Id, Name, Type)
            VALUES (@GroupId, @GroupName, '1');
        END

        -- ۲. پاک‌سازی مقادیر پیش‌فرض و آیتم‌های قبلی این گروه
        DELETE FROM dbo.PayRol_TblItemsDefaultInfo 
        WHERE Items_Id IN (SELECT Id FROM dbo.PayRol_TblItems WHERE GroupItem_Id = @GroupId);

        DELETE FROM dbo.PayRol_TblItems 
        WHERE GroupItem_Id = @GroupId;

        -- ۳. ثبت فیلترهای ورودی در PayRol_TblItems
        
        -- ۳.۱. از تاریخ
        SELECT @ItemId = ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItems;
        INSERT INTO dbo.PayRol_TblItems (
            Id, GroupItem_Id, Name, Type, State, MaxCharacter, Description, ErrorMsg, EnName, ProcedureName
        )
        VALUES (
            @ItemId, @GroupId, N'از تاریخ', 3, 0, 10, N'تاریخ شروع بازه شمسی', N'فرمت تاریخ صحیح نیست', '@DFrom', ''
        );
        INSERT INTO dbo.PayRol_TblItemsDefaultInfo (Id, Items_Id, Value)
        VALUES ((SELECT ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItemsDefaultInfo), @ItemId, N'1404/01/01');

        -- ۳.۲. تا تاریخ
        SELECT @ItemId = ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItems;
        INSERT INTO dbo.PayRol_TblItems (
            Id, GroupItem_Id, Name, Type, State, MaxCharacter, Description, ErrorMsg, EnName, ProcedureName
        )
        VALUES (
            @ItemId, @GroupId, N'تا تاریخ', 3, 0, 10, N'تاریخ پایان بازه شمسی', N'فرمت تاریخ صحیح نیست', '@DTo', ''
        );
        INSERT INTO dbo.PayRol_TblItemsDefaultInfo (Id, Items_Id, Value)
        VALUES ((SELECT ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItemsDefaultInfo), @ItemId, N'1404/12/29');

        -- ۳.۳. انتخاب شعبه
        SELECT @ItemId = ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItems;
        INSERT INTO dbo.PayRol_TblItems (
            Id, GroupItem_Id, Name, Type, State, MaxCharacter, Description, ErrorMsg, EnName, ProcedureName
        )
        VALUES (
            @ItemId, @GroupId, N'انتخاب شعبه', 4, 0, 10, N'فیلتر بر اساس شعبه خاص یا تمام شعب', N'', '@CShobe', 'TblCompanyShobe'
        );
        INSERT INTO dbo.PayRol_TblItemsDefaultInfo (Id, Items_Id, Value)
        VALUES ((SELECT ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItemsDefaultInfo), @ItemId, N'0');

        -- ۳.۴. انتخاب کالا
        SELECT @ItemId = ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItems;
        INSERT INTO dbo.PayRol_TblItems (
            Id, GroupItem_Id, Name, Type, State, MaxCharacter, Description, ErrorMsg, EnName, ProcedureName
        )
        VALUES (
            @ItemId, @GroupId, N'انتخاب کالا', 4, 0, 10, N'فیلتر بر اساس کالای خاص یا تمام کالاها', N'', '@IdKala', 'TblKala'
        );
        INSERT INTO dbo.PayRol_TblItemsDefaultInfo (Id, Items_Id, Value)
        VALUES ((SELECT ISNULL(MAX(Id), 0) + 1 FROM dbo.PayRol_TblItemsDefaultInfo), @ItemId, N'0');

        -- ۴. ثبت یا به‌روزرسانی گزارش در TblReports با ReportId = 100
        DELETE FROM dbo.TblReports WHERE ProcedureName = @ProcName;
        DELETE FROM dbo.TblReports WHERE ReportId = @FixedReportId;

        INSERT INTO dbo.TblReports (ReportId, ProcedureName, ReportName, Group_Id, BodyCommands)
        VALUES (@FixedReportId, @ProcName, @ReportName, @GroupId, N'EXEC dbo.' + @ProcName);

        SET @NewReportId = @FixedReportId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        RAISERROR(N'❌ خطا در فرآیند ثبت متادیتای گزارش: %s', 16, 1, @ErrorMsg);
        RETURN -1;
    END CATCH;
END;

GO

-- Procedure: [dbo].[sp_Report_GardeshVaMorjooeiKala]
IF OBJECT_ID(N'[dbo].[sp_Report_GardeshVaMorjooeiKala]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_Report_GardeshVaMorjooeiKala] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_Report_GardeshVaMorjooeiKala]
    @FromDate VARCHAR(10) = '',
    @ToDate VARCHAR(10) = '',
    @IDKala INT = 0,
    @IDAnbar INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- پاکسازی و تنظیم پیش‌فرض تاریخ‌ها
    IF ISNULL(@FromDate, '') = '' SET @FromDate = '1300/01/01';
    IF ISNULL(@ToDate, '') = '' SET @ToDate = '1500/12/29';

    -- جدول موقت خلاصه تراکنش‌ها به تفکیک کالا و انبار
    CREATE TABLE #TmpTurnover (
        IDAnbar INT,
        IDKala INT,
        InitStock NUMERIC(18, 3) DEFAULT 0,      -- موجودی ابتدای دوره (قبل از FromDate)
        BuyQty NUMERIC(18, 3) DEFAULT 0,         -- خرید (Type = 100)
        BuyReturnQty NUMERIC(18, 3) DEFAULT 0,   -- برگشت از خرید (Type = 101)
        HavaleInQty NUMERIC(18, 3) DEFAULT 0,    -- سایر ورود / حواله ورود (Type = 102)
        SaleQty NUMERIC(18, 3) DEFAULT 0,        -- فروش (Type = 200)
        SaleReturnQty NUMERIC(18, 3) DEFAULT 0,  -- برگشت از فروش / مرجوعی مشتری (Type = 201)
        HavaleOutQty NUMERIC(18, 3) DEFAULT 0,   -- سایر خروج / حواله خروج (Type = 202)
        ZayeatQty NUMERIC(18, 3) DEFAULT 0       -- ضایعات و مرجوعی (Type = 206)
    );

    -- ۱. موجودی ابتدای دوره (تمام تراکنش‌های پیش از FromDate)
    INSERT INTO #TmpTurnover (IDAnbar, IDKala, InitStock)
    SELECT 
        tr.IDAnbar,
        tr.IDKala,
        SUM(
            CASE 
                -- تراکنش‌های ورود به انبار: خرید(100)، برگشت از فروش(201)، حواله ورود(102)
                WHEN tr.Type IN (100, 201, 102) THEN ISNULL(tr.Tedad, 0)
                -- تراکنش‌های خروج از انبار: فروش(200)، برگشت از خرید(101)، حواله خروج(202)، ضایعات(206)
                WHEN tr.Type IN (200, 101, 202, 206) THEN -ISNULL(tr.Tedad, 0)
                ELSE 0 
            END
        ) AS InitStock
    FROM dbo.TblTRAnbar tr
    LEFT JOIN dbo.TblFactor f ON tr.ShFactor = f.ShFactor
    WHERE ISNULL(f.Date, tr.Timesabt) < @FromDate
      AND (@IDKala = 0 OR tr.IDKala = @IDKala)
      AND (@IDAnbar = 0 OR tr.IDAnbar = @IDAnbar)
    GROUP BY tr.IDAnbar, tr.IDKala;

    -- ۲. تراکنش‌های درون بازه (از FromDate تا ToDate)
    INSERT INTO #TmpTurnover (
        IDAnbar, IDKala, BuyQty, BuyReturnQty, HavaleInQty, 
        SaleQty, SaleReturnQty, HavaleOutQty, ZayeatQty
    )
    SELECT 
        tr.IDAnbar,
        tr.IDKala,
        SUM(CASE WHEN tr.Type = 100 THEN ISNULL(tr.Tedad, 0) ELSE 0 END) AS BuyQty,
        SUM(CASE WHEN tr.Type = 101 THEN ISNULL(tr.Tedad, 0) ELSE 0 END) AS BuyReturnQty,
        SUM(CASE WHEN tr.Type = 102 THEN ISNULL(tr.Tedad, 0) ELSE 0 END) AS HavaleInQty,
        SUM(CASE WHEN tr.Type = 200 THEN ISNULL(tr.Tedad, 0) ELSE 0 END) AS SaleQty,
        SUM(CASE WHEN tr.Type = 201 THEN ISNULL(tr.Tedad, 0) ELSE 0 END) AS SaleReturnQty,
        SUM(CASE WHEN tr.Type = 202 THEN ISNULL(tr.Tedad, 0) ELSE 0 END) AS HavaleOutQty,
        SUM(CASE WHEN tr.Type = 206 THEN ISNULL(tr.Tedad, 0) ELSE 0 END) AS ZayeatQty
    FROM dbo.TblTRAnbar tr
    LEFT JOIN dbo.TblFactor f ON tr.ShFactor = f.ShFactor
    WHERE ISNULL(f.Date, tr.Timesabt) BETWEEN @FromDate AND @ToDate
      AND (@IDKala = 0 OR tr.IDKala = @IDKala)
      AND (@IDAnbar = 0 OR tr.IDAnbar = @IDAnbar)
    GROUP BY tr.IDAnbar, tr.IDKala;

    -- ۳. تجمیع نهایی و ترکیب با اطلاعات کالا، انبار و واحد سنجش
    SELECT 
        k.IDKala AS [کد کالا],
        k.Name AS [نام کالا],
        a.ID AS [کد انبار],
        a.Name AS [نام انبار],
        ISNULL(u.Name, 'عدد') AS [واحد],
        CAST(SUM(t.InitStock) AS NUMERIC(18, 2)) AS [ابتدای دوره],
        CAST(SUM(t.BuyQty) AS NUMERIC(18, 2)) AS [خرید],
        CAST(SUM(t.SaleReturnQty) AS NUMERIC(18, 2)) AS [برگشت از فروش (مرجوعی)],
        CAST(SUM(t.HavaleInQty) AS NUMERIC(18, 2)) AS [سایر ورود],
        CAST(SUM(t.BuyQty + t.SaleReturnQty + t.HavaleInQty) AS NUMERIC(18, 2)) AS [کل ورود دوره],
        CAST(SUM(t.SaleQty) AS NUMERIC(18, 2)) AS [فروش],
        CAST(SUM(t.BuyReturnQty) AS NUMERIC(18, 2)) AS [برگشت از خرید],
        CAST(SUM(t.HavaleOutQty) AS NUMERIC(18, 2)) AS [سایر خروج],
        CAST(SUM(t.ZayeatQty) AS NUMERIC(18, 2)) AS [ضایعات],
        CAST(SUM(t.SaleQty + t.BuyReturnQty + t.HavaleOutQty + t.ZayeatQty) AS NUMERIC(18, 2)) AS [کل خروج دوره],
        -- موجودی پایان دوره = ابتدای دوره + ورود - خروج
        CAST(
            SUM(t.InitStock) 
            + SUM(t.BuyQty + t.SaleReturnQty + t.HavaleInQty) 
            - SUM(t.SaleQty + t.BuyReturnQty + t.HavaleOutQty + t.ZayeatQty)
        AS NUMERIC(18, 2)) AS [موجودی پایان دوره]
    FROM #TmpTurnover t
    INNER JOIN dbo.TblKala k ON t.IDKala = k.IDKala
    LEFT JOIN dbo.TblAnbar a ON t.IDAnbar = a.ID
    LEFT JOIN dbo.TblUnit u ON k.Unit1 = u.ID
    GROUP BY k.IDKala, k.Name, a.ID, a.Name, u.Name
    ORDER BY a.ID, k.IDKala;

    DROP TABLE #TmpTurnover;
END;
GO

-- Procedure: [dbo].[sp_Report_TestCustomerDebtGate]
IF OBJECT_ID(N'[dbo].[sp_Report_TestCustomerDebtGate]', N'P') IS NULL
