ALTER PROCEDURE [dbo].[sp_Report_TestCustomerDebtGate]
    @DFrom NVARCHAR(10) = NULL,
    @DTo NVARCHAR(10) = NULL,
    @IdShakhs INT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    SET @DFrom = ISNULL(NULLIF(LTRIM(RTRIM(@DFrom)), ''), '1400/01/01');
    SET @DTo = ISNULL(NULLIF(LTRIM(RTRIM(@DTo)), ''), '1405/12/29');
    SET @IdShakhs = ISNULL(@IdShakhs, 0);

    ;WITH CTE_CustomerBalance AS (
        SELECT 
            tr.Taraf AS IdPerson,
            COUNT(DISTINCT tr.Factor) AS FactorCount,
            SUM(ISNULL(tr.Bed, 0)) AS TotalBed,
            SUM(ISNULL(tr.Bes, 0)) AS TotalBes,
            SUM(ISNULL(tr.Bed, 0) - ISNULL(tr.Bes, 0)) AS CurrentDebt
        FROM dbo.TR AS tr WITH (NOLOCK)
        WHERE (tr.DateR BETWEEN @DFrom AND @DTo)
          AND tr.Taraf > 0
          AND (@IdShakhs = 0 OR tr.Taraf = @IdShakhs)
        GROUP BY tr.Taraf
    )
    SELECT 
        p.Sh_ozviat AS [کد مشتری],
        ISNULL(p.Name + ' ' + ISNULL(p.Famil, ''), N'نامشخص') AS [نام و نام خانوادگی],
        ISNULL(NULLIF(p.Mobile, ''), ISNULL(NULLIF(p.Tell, ''), '---')) AS [شماره تماس],
        b.FactorCount AS [تعداد فاکتورها],
        CAST(b.TotalBed AS DECIMAL(18, 0)) AS [مجموع بدهکاری],
        CAST(b.TotalBes AS DECIMAL(18, 0)) AS [مجموع بستانکاری],
        CAST(b.CurrentDebt AS DECIMAL(18, 0)) AS [مانده حساب فعلی],
        CASE 
            WHEN b.CurrentDebt > 0 THEN N'بدهکار'
            WHEN b.CurrentDebt < 0 THEN N'بستانکار'
            ELSE N'تسویه'
        END AS [وضعیت حساب]
    FROM CTE_CustomerBalance AS b
    INNER JOIN dbo.TblPerson AS p WITH (NOLOCK) ON p.Sh_ozviat = b.IdPerson
    ORDER BY ABS(b.CurrentDebt) DESC;
END;
GO

-- Procedure: [dbo].[GetFactorForushKala_New]
IF OBJECT_ID(N'[dbo].[GetFactorForushKala_New]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[GetFactorForushKala_New] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[GetFactorForushKala_New] 
@factor INT,@Type TINYINT,@CShobe int=0,@typeMasraf int = 2,@MabPardakht bigint out,@sumTed NUMERIC(30,15) out,@sumAglam int out,@summasraf bigint out, @sumTakh bigint out,@sumKhales bigint out,@sumEzaf bigint out,@sumKasr bigint out 
AS 
 
DECLARE @Cshobe1 INT = @CShobe,@Cshobe2 INT = @CShobe 
 
IF(@CShobe=0) 
BEGIN 
	SET @CShobe1 = 0 
	SET @Cshobe2 = 99999 
END 
 
DECLARE @automaliat INT = 0 
IF(@Type = 203 OR @Type = 104 OR @Type = 1) 
	SELECT @automaliat = COUNT(*) FROM dbo.TblFactorAvamel WHERE Maliat = 1 AND AutoSave = 1 
 
IF(@Type=1) 
BEGIN 
		SELECT 
		TR.IdAnbar AS IdAnbr,  
		TblAnbar.Name,  
		TR.Idkala,  
		TblKala.Name + ' ' + ISNULL(tr.Text,'') COLLATE DATABASE_DEFAULT as KalaName, 
		CAST(dbo.RoundDecimal(TR.TED, TR.Nerkh) AS FLOAT) AS Ted, 
		CAST(TR.Ted2 AS FLOAT) AS Ted2, 
		dbo.GetUnit1(TR.IdAnbar, TR.Idkala, ISNULL(tr.Unit,0)) AS Unit, 
		tr.TED AS TedKol,
		CAST(CASE WHEN isnull(TblPrice.Price,0)>0 THEN isnull(TblPrice.Price,0) ELSE ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) END  AS BIGINT) as Fi, 
		CAST(ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) AS BIGINT) as FiForosh, 
		CONVERT(BIGINT, TR.TED * (CASE WHEN isnull(TblPrice.Price,0)>0 THEN isnull(TblPrice.Price,0) ELSE ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) END)) as MabKol,  
		CONVERT(BIGINT, TR.TED * (CASE WHEN isnull(TblPrice.Price,0)>0 THEN isnull(TblPrice.Price,0) ELSE ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) END)-(TR.Bes+tr.bed+TR.Takh-TR.Maliat)) as Takh, 
		TR.Takh as TakhTR, 
		TR.Maliat, 
		TR.Bes+TR.Bed AS Mab, 
		CASE WHEN @automaliat>0 THEN CASE WHEN Mashmol = 1 THEN TR.Bes+TR.Bed + FLOOR((TR.Bes+TR.Bed) * DarsadMashmol/100) ELSE TR.Bes+TR.Bed END ELSE 0 END AS MabByMaliat, 
		TR.Id AS Sodor, 
		TR.CreateTime Time, 
		TR.Row ,
		0 AS DarsadTakhNew,
		0 AS Refid
		FROM             
								 dbo.TblPishFactor AS TR   
								 LEFT JOIN TblKala  
								 LEFT JOIN TblAnbar ON TblKala.IDAnbar = TblAnbar.ID ON TR.Idkala = TblKala.IDKala AND TR.IdAnbar = TblKala.IDAnbar AND TR.IdAnbar = TblAnbar.ID 
								 LEFT JOIN TblPrice on tr.IdAnbar=TblPrice.IDAnbar and tr.Idkala=TblPrice.IDKala and TblPrice.IDLable=@typeMasraf 
								 LEFT JOIN TblUnit on TblKala.Unit1=TblUnit.ID 
								 LEFT JOIN dbo.TblUnit AS unit2 ON unit2.ID = dbo.TblKala.Unit2 
		WHERE        (TR.Factor = @factor) AND (TR.Idkala > 0) AND (TR.Type = @Type) AND (TR.CShobe BETWEEN @CShobe1 AND @Cshobe2 OR TR.CShobe=0) 
		ORDER BY TR.Row DESC, TR.Sodor DESC 
END 
ELSE 
BEGIN 
 
		SELECT  
		TR.IdAnbr,  
		TblAnbar.Name,  
		TR.Idkala,  
		TblKala.Name + ' ' + ISNULL(td.Text,'') COLLATE DATABASE_DEFAULT as KalaName, 
		CAST(dbo.RoundDecimal(TR.TED, TR.Nerkh) AS FLOAT) AS Ted, 
		CAST(TR.Ted2 AS FLOAT) AS Ted2, 
		dbo.GetUnit1(TR.IdAnbr, TR.Idkala, ISNULL(td.Unit,0)) AS Unit, 
		tr.TED AS TedKol,
		CAST(CASE WHEN tr.Price2>0 THEN tr.Price2 WHEN isnull(TblPrice.Price,0)>0 THEN isnull(TblPrice.Price,0) ELSE ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) END  AS BIGINT) as Fi, 
		CAST(ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) AS BIGINT) as FiForosh, 
		CAST(ROUND(CAST(CASE WHEN tr.Price2>0 THEN tr.Price2 WHEN isnull(TblPrice.Price,0)>0 THEN isnull(TblPrice.Price,0) ELSE ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) END  AS BIGINT) * tr.TED,0) AS BIGINT) AS MabKol,  
		CONVERT(BIGINT, TR.TED * (CASE WHEN tr.Price2>0 THEN tr.Price2 WHEN isnull(TblPrice.Price,0)>0 THEN isnull(TblPrice.Price,0) ELSE ROUND((TR.Bes+TR.Bed + TR.Takh - TR.Maliat) * 1/ dbo.TryNotZero(TR.TED),0) END)-(TR.Bes+tr.bed+TR.Takh-TR.Maliat)) as Takh, 
		TR.Takh as TakhTR, 
		TR.Maliat, 
		dbo.TR.Bes+dbo.TR.Bed AS Mab, 
		CASE WHEN @automaliat>0 THEN CASE WHEN Mashmol = 1 THEN TR.Bes+TR.Bed + FLOOR((TR.Bes+TR.Bed) * DarsadMashmol/100) ELSE TR.Bes+TR.Bed END ELSE 0 END AS MabByMaliat, 
		TR.Sodor, 
		TR.Time, 
		TR.Row ,
		0 AS DarsadTakhNew,
		CASE WHEN @Type=104 THEN Tolid_Id ELSE TblPishFactor_ID END AS Refid
		FROM             
								 TR   
								 LEFT JOIN TblKala  
								 LEFT JOIN TblAnbar ON TblKala.IDAnbar = TblAnbar.ID ON TR.Idkala = TblKala.IDKala AND TR.IdAnbr = TblKala.IDAnbar AND TR.IdAnbr = TblAnbar.ID 
								 LEFT JOIN TblPrice on tr.IdAnbr=TblPrice.IDAnbar and tr.Idkala=TblPrice.IDKala and TblPrice.IDLable=@typeMasraf 
								 LEFT JOIN TblUnit on TblKala.Unit1=TblUnit.ID 
								 LEFT JOIN TRDetail as td on td.Sodor=tr.Sodor 
								 LEFT JOIN dbo.TblUnit AS unit2 ON unit2.ID = dbo.TblKala.Unit2 
		WHERE        (TR.Factor = @factor) AND (TR.Idkala > 0) AND (TR.Type = @Type) AND (TR.CShobe BETWEEN @CShobe1 AND @Cshobe2 OR TR.CShobe=0) 
		ORDER BY TR.Row DESC, TR.Sodor DESC 
END 
 
 
 
 
 

GO

-- Procedure: [dbo].[GetFactorKala]
IF OBJECT_ID(N'[dbo].[GetFactorKala]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[GetFactorKala] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[GetFactorKala]
    @factor INT,
    @Type TINYINT,
    @CShobe INT,
    @LableMasraf INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @cshobe1 INT = @CShobe, @cshobe2 INT = @CShobe;
    IF (@CShobe = 0)
        SET @cshobe2 = 99999999;

    DECLARE @CalcSubtotal VARCHAR(5) = ISNULL(
        (SELECT Value FROM dbo.TblParameters WHERE Name = 'CalcSubtotal'), 'False'
    );


    -- Temp table های بهینه با ایندکس داخلی
    IF OBJECT_ID('tempdb..#tempAnbar') IS NOT NULL DROP TABLE #tempAnbar;
    CREATE TABLE #tempAnbar (
        Sodor INT PRIMARY KEY,
        FactorAnbar NVARCHAR(100)
    );

    INSERT INTO #tempAnbar(Sodor, FactorAnbar)
    SELECT t.Sodor, MAX(ISNULL(td.ShFactor, 0))
    FROM dbo.TR t
    INNER JOIN dbo.TRAnbar_Del td
        ON t.TRAnbar_Id = td.ID AND td.TRId_Havale > 0
    WHERE t.Factor = @factor AND t.Type = @Type
    GROUP BY t.Sodor;

    IF OBJECT_ID('tempdb..#tempPishFactor') IS NOT NULL DROP TABLE #tempPishFactor;
    CREATE TABLE #tempPishFactor (
        Sodor INT PRIMARY KEY,
        PishFactor NVARCHAR(100)
    );

    INSERT INTO #tempPishFactor(Sodor, PishFactor)
    SELECT t.Sodor, MAX(ISNULL(pd.Factor, 0))
    FROM dbo.TR t
    INNER JOIN dbo.TblPishFactor pd
        ON pd.Id = t.TblPishFactor_ID
    WHERE t.Factor = @factor AND t.Type = @Type
    GROUP BY t.Sodor;

    IF OBJECT_ID('tempdb..#tempPishFactorAnbar') IS NOT NULL DROP TABLE #tempPishFactorAnbar;
    CREATE TABLE #tempPishFactorAnbar (
        Sodor INT PRIMARY KEY,
        PishFactor NVARCHAR(100)
    );

    INSERT INTO #tempPishFactorAnbar(Sodor, PishFactor)
    SELECT t.Sodor, MAX(ISNULL(pd.Factor, 0))
    FROM dbo.TR t
    INNER JOIN dbo.TRAnbar_Del td
        ON t.TRAnbar_Id = td.ID AND td.TRId_Havale > 0
    INNER JOIN dbo.TblPishFactor pd
        ON pd.Id = td.TblPishFactor_ID
    WHERE t.Factor = @factor AND t.Type = @Type
    GROUP BY t.Sodor;

    -- Query اصلی با JOIN های بهینه
    SELECT
        tr.IdAnbr,
        anbar.Name,
        tr.Idkala,
        kala.Name + '  ' + ISNULL(trd.Text, '') COLLATE SQL_Latin1_General_CP1_CI_AS 
            + CASE WHEN tr.Nerkh <> 1 THEN ' - ' + CAST(CAST(tr.TED AS DECIMAL) AS VARCHAR(20)) 
            + ' ' + dbo.GetUnitNew(tr.IdAnbr, tr.Idkala, 0,0) ELSE '' END AS KalaName,
        ISNULL(CASE WHEN Mashmol = 1 THEN DarsadMashmol ELSE 0 END,0) AS DarsadMashmol,
        tr.Nerkh,
        CAST(dbo.RoundDecimal(tr.TED, tr.Nerkh) AS FLOAT) AS Ted,
        CAST(dbo.RoundDecimal(tr.TedTahvily, tr.Nerkh) AS FLOAT) AS TedTahvily,
        CAST(dbo.RoundDecimal(tr.TED, tr.Nerkh) - dbo.RoundDecimal(tr.TedTahvily, tr.Nerkh) AS FLOAT) AS TedMande,
        tr.Ted2,
        tr.TED AS TedKol,
        dbo.GetUnitNew(tr.IdAnbr, tr.Idkala, ISNULL(trd.Unit,0), tr.Nerkh) AS Unit,
        CASE WHEN @CalcSubtotal = 'True' 
            THEN CAST(ROUND((tr.Bes + tr.Bed + tr.Takh - tr.Maliat) * 1.0 / dbo.TryNotZero(tr.Ted2),0) AS BIGINT)
            ELSE CAST(ROUND((tr.Bes + tr.Bed + tr.Takh - tr.Maliat) * 1.0 / dbo.TryNotZero(dbo.RoundDecimal(tr.TED, tr.Nerkh)),0) AS BIGINT)
        END AS Fi,
		tr.Bes + tr.Bed + tr.Takh - tr.Maliat AS Mabkol,
        tr.Takh,
        CAST(ROUND((tr.Takh*100.0)/dbo.TryNotZero(tr.Takh + tr.Bed + tr.Bes),3) AS NUMERIC(18,3)) AS DarsadTakh,
        tr.Maliat,
        CAST(ROUND((tr.Bes + tr.Bed) *1.0 / dbo.TryNotZero(dbo.RoundDecimal(tr.TED, tr.Nerkh)),0) AS BIGINT) AS FiTamam,
        tr.Bes + tr.Bed AS Mab,
        CASE WHEN Mashmol = 1 THEN CAST(FLOOR((tr.Bes + tr.Bed) * ((tr.DarsadMashmol/100.0)+1)) AS BIGINT) 
        ELSE tr.Bes + tr.Bed END AS MabByMaliat,
        CAST(ROUND(ISNULL(trd.BedArz + trd.BesArz,0) * 1.0 / dbo.TryNotZero(dbo.RoundDecimal(tr.TED, tr.Nerkh)),3) AS NUMERIC(30,15)) AS FiTamamArz,
        ISNULL(trd.BedArz + trd.BesArz,0) AS MabArz,
        ISNULL(arz.Name,'') AS ArzName,
        tr.Sodor,
        tr.Sharh,
        ISNULL(trd.Text,'') AS Text,
        tr.Mabkh,
        ISNULL(pm.Price,0) AS FiMasraf,
        tr.Serial,
        tr.ExpireDate,
        ISNULL(tempAnbar.FactorAnbar,'') + '/' + ISNULL(tempPishFactor.PishFactor, ISNULL(tempPishFactorAnbar.PishFactor,'')) AS FactorAnbar,
        ISNULL(trd.Length,0) AS Length,
        ISNULL(trd.Width,0) AS Width,
        ISNULL(trd.Diameter,0) AS Diameter,
        ISNULL(trd.Tedad,0) AS Tedad,
        ISNULL(trd.OtherUnitId1,0) AS OtherUnitId1,
        ISNULL(trd.OtherUnitId2,0) AS OtherUnitId2,
        tr.Row,
		ISNULL(kala.Model,'') AS Model,
		tr.Description,
		tr.Price2
    FROM dbo.TR AS tr
    LEFT JOIN TRDetail AS trd ON trd.Sodor = tr.Sodor
    LEFT JOIN TblKala AS kala ON tr.Idkala = kala.IDKala AND tr.IdAnbr = kala.IDAnbar
    LEFT JOIN TblAnbar AS anbar ON kala.IDAnbar = anbar.ID
    LEFT JOIN TblArz AS arz ON arz.Id = trd.ArzId
    LEFT JOIN #tempAnbar AS tempAnbar ON tr.Sodor = tempAnbar.Sodor
    LEFT JOIN #tempPishFactor AS tempPishFactor ON tr.Sodor = tempPishFactor.Sodor
    LEFT JOIN #tempPishFactorAnbar AS tempPishFactorAnbar ON tr.Sodor = tempPishFactorAnbar.Sodor
    LEFT JOIN TblPrice AS pm ON pm.IDAnbar = tr.IdAnbr AND pm.IDKala = tr.Idkala AND pm.IDLable = @LableMasraf
    WHERE tr.Factor = @factor 
      AND tr.Idkala > 0
      AND tr.Type = @Type
      AND (tr.CShobe BETWEEN @cshobe1 AND @cshobe2 OR tr.CShobe = 0)
    ORDER BY tr.Row, tr.Sodor;

END

GO

-- Procedure: [dbo].[GetFactorKala_GheymatOmda]
IF OBJECT_ID(N'[dbo].[GetFactorKala_GheymatOmda]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[GetFactorKala_GheymatOmda] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[GetFactorKala_GheymatOmda]
@factor INT,
@Type TINYINT,
@CShobe int,
@LableMasraf INT
AS
declare @cshobe1 int = @cshobe, @cshobe2 int = @cshobe
if(@cshobe=0)
	set @cshobe2 = 99999999

	


 IF OBJECT_ID('tempdb.dbo.#tempAnbar', 'U') IS NOT NULL 
                DROP TABLE #tempAnbar; 
     CREATE TABLE #tempAnbar (Sodor INT,FactorAnbar NVARCHAR(100))


	INSERT INTO #tempAnbar
	SELECT t.Sodor,MAX(CAST(ISNULL(td.ShFactor,0) AS NVARCHAR(100))) FROM dbo.TR AS t
	INNER JOIN dbo.TRAnbar_Del AS td ON t.TRAnbar_Id = td.ID AND td.TRId_Havale>0
	WHERE t.Factor = @factor AND t.Type = @Type
	GROUP BY t.Sodor



	 IF OBJECT_ID('tempdb.dbo.#tempPishFactor', 'U') IS NOT NULL 
                DROP TABLE #tempPishFactor; 
     CREATE TABLE #tempPishFactor (Sodor INT,PishFactor NVARCHAR(100))


	INSERT INTO #tempPishFactor
	SELECT t.Sodor,MAX(CAST(ISNULL(pd.Factor,0) AS NVARCHAR(100))) FROM dbo.TR AS t
	INNER JOIN dbo.TblPishFactor AS pd ON pd.Id = t.TblPishFactor_ID
	WHERE t.Factor = @factor AND t.Type = @Type
	GROUP BY t.Sodor


	IF OBJECT_ID('tempdb.dbo.#tempPishFactorAnbar', 'U') IS NOT NULL 
                DROP TABLE #tempPishFactorAnbar; 
     CREATE TABLE #tempPishFactorAnbar (Sodor INT,PishFactor NVARCHAR(100))


	INSERT INTO #tempPishFactorAnbar
	SELECT t.Sodor,MAX(CAST(ISNULL(pd.Factor,0) AS NVARCHAR(100))) FROM dbo.TR AS t
	INNER JOIN dbo.TRAnbar_Del AS td ON t.TRAnbar_Id = td.ID AND td.TRId_Havale>0
	INNER JOIN dbo.TblPishFactor AS pd ON pd.Id = td.TblPishFactor_ID
	WHERE t.Factor = @factor AND t.Type = @Type
	GROUP BY t.Sodor

SELECT          
TR.IdAnbr,
TblAnbar.Name,
TR.Idkala,
CASE when ISNULL(trd.Text,'')<>'' then TblKala.Name + ' - ' + ISNULL(trd.Text,'') COLLATE SQL_Latin1_General_CP1_CI_AS else TblKala.Name END + CASE WHEN tr.Mashmol = 1 THEN ' (مشمول مالیات)' ELSE '' END + CASE WHEN tr.Nerkh<>1 THEN ' - ' + CAST(CAST(tr.TED AS DECIMAL) AS VARCHAR(20))+' '+dbo.GetUnitNew(TR.IdAnbr, TR.Idkala, 0,0) ELSE '' END AS kalaname,
CASE WHEN Mashmol = 1 THEN DarsadMashmol ELSE 0 END AS DarsadMashmol,
dbo.TR.Nerkh,
CAST(dbo.RoundDecimal(TR.TED, TR.Nerkh) AS FLOAT) AS Ted,
CAST(dbo.RoundDecimal(TR.TedTahvily, TR.Nerkh) AS FLOAT) AS TedTahvily,
CAST(dbo.RoundDecimal(TR.TED, TR.Nerkh) - dbo.RoundDecimal(TR.TedTahvily, TR.Nerkh) AS FLOAT) AS TedMande,
TR.Ted2,
dbo.TR.TED AS TedKol,
dbo.GetUnitNew(TR.IdAnbr, TR.Idkala, ISNULL(trd.Unit,0),tr.Nerkh) AS Unit,
CAST(ROUND((TR.Bed + TR.Bes + TR.Takh - dbo.TR.Maliat) *1/ dbo.TryNotZero(dbo.TR.TED),0) AS BIGINT) AS Fi,
tr.Bes + tr.Bed + tr.Takh - tr.Maliat AS Mabkol,
TR.Takh,
CAST(ROUND((TR.Takh*100.0)/dbo.TryNotZero(TR.Takh + TR.Bed+ TR.Bes),0) AS INT) AS DarsadTakh,
TR.Maliat,
CAST(ROUND((dbo.TR.Bes + dbo.TR.Bed) *1/ dbo.TryNotZero(dbo.TR.TED),0) AS BIGINT)  AS FiTamam,
TR.Bes+dbo.TR.Bed AS Mab,
	CASE WHEN Mashmol = 1 THEN CAST(FLOOR((TR.Bes+dbo.TR.Bed) * ((tr.DarsadMashmol/100.0)+1)) AS BIGINT) ELSE TR.Bes+dbo.TR.Bed END  AS MabByMaliat,
CAST(ROUND(ISNULL(trd.BedArz + trd.BesArz,0) *1.0/  dbo.TryNotZero(dbo.TR.TED),3) AS numeric(30,15)) AS FiTamamArz,
ISNULL(trd.BedArz + trd.BesArz,0) AS MabArz,
ISNULL(arz.Name,'') AS ArzName,
TR.Sodor,
TR.Sharh,
ISNULL(trd.Text,'') AS Text,
TR.Mabkh,
ISNULL(pm.Price,0) as FiMasraf,
dbo.TR.Serial,
dbo.TR.ExpireDate,
REPLACE(ISNULL(tempAnbar.FactorAnbar,'') + '/' + ISNULL(tempPishFactor.PishFactor,ISNULL(tempPishFactorAnbar.PishFactor,'')),'/','') AS FactorAnbar,
ISNULL(trd.Length,0) AS Length,
ISNULL(trd.Width,0) AS Width,
ISNULL(trd.Diameter,0) AS Diameter,
ISNULL(trd.Tedad,0) AS Tedad,
ISNULL(trd.OtherUnitId1,0) AS OtherUnitId1,
ISNULL(trd.OtherUnitId2,0) AS OtherUnitId2,
TR.Row,
ISNULL(dbo.TblKala.Model,'') AS Model,
tr.Description,
tr.Price2
	FROM             
							 TR 
							 LEFT JOIN TRDetail AS trd ON trd.Sodor = TR.Sodor 
							 LEFT JOIN TblKala ON TR.Idkala = TblKala.IDKala AND TR.IdAnbr = TblKala.IDAnbar
							 LEFT JOIN TblAnbar ON TblKala.IDAnbar = TblAnbar.ID 
							 LEFT JOIN dbo.TblArz AS arz ON arz.Id = trd.ArzId
							 LEFT JOIN #tempAnbar AS tempAnbar ON tr.Sodor = tempAnbar.Sodor
							 LEFT JOIN #tempPishFactor AS tempPishFactor ON tr.Sodor = tempPishFactor.Sodor
							 LEFT JOIN #tempPishFactorAnbar AS tempPishFactorAnbar ON tr.Sodor = tempPishFactorAnbar.Sodor
							 LEFT JOIN dbo.TblPrice AS pm ON pm.IDAnbar = tr.IdAnbr AND pm.IDKala = tr.Idkala AND pm.IDLable = @LableMasraf
	WHERE        (TR.Factor = @factor) AND (TR.Idkala > 0) AND (TR.Type = @Type) AND (TR.CShobe between @cshobe1 and @cshobe2 OR TR.CShobe=0)
	ORDER BY TR.Row,tr.Sodor



GO

-- Procedure: [dbo].[Rpt_FactoreMoshtari]
IF OBJECT_ID(N'[dbo].[Rpt_FactoreMoshtari]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[Rpt_FactoreMoshtari] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[Rpt_FactoreMoshtari]
    @personid INT ,
    @type INT ,
    @idanbar1 INT ,
    @idanbar2 INT ,
    @idkala1 INT ,
    @idkala2 INT ,
    @date1 VARCHAR(10) ,
    @date2 VARCHAR(10) ,
    @Code VARCHAR(500) ,
    @CShobe INT = 0
AS
    SELECT  R.ShFactor ,
            R.Shsodor ,
            R.Date ,
            R.kalagroups ,
            R.Name ,
            R.Tedad ,
            R.Fi ,
            R.Mablaghekol ,
			R.DarsadMaliat,
            R.UnitName ,
            R.Maliat ,
            R.Mablaghekol + R.Maliat AS Khales
    FROM    ( SELECT    TblFactor.ShFactor ,
                        TblTRAnbar.ID AS Shsodor ,
                        TblFactor.Date ,
                        ISNULL(REPLACE(TblKala.KalaGroups, '/', ' '), '') AS kalagroups ,
                        TblKala.Name ,
                        TblTRAnbar.Tedad ,
                        dbo.GetUnit(dbo.TblKala.IDAnbar, dbo.TblKala.IDKala, 0) AS UnitName ,
                        CONVERT(BIGINT, ROUND(TblTRAnbar.Mablaghekol
                                              / TblTRAnbar.Tedad, 0)) AS Fi ,
                        Mablaghekol ,
						CASE WHEN dbo.TblKala.maliyat = 1 THEN dbo.TblKala.DarsadMaliat ELSE 0 END AS DarsadMaliat,
                        CAST(ROUND(CASE WHEN dbo.TblKala.maliyat = 1
                                        THEN Mablaghekol
                                        ELSE 0
                                   END * dbo.TblKala.DarsadMaliat / 100.0, 0) AS BIGINT) AS Maliat
              FROM      dbo.TblTRAnbar
                        LEFT JOIN dbo.TblFactor ON dbo.TblTRAnbar.ShFactor = dbo.TblFactor.ShFactor
                                                   AND dbo.TblTRAnbar.Type = dbo.TblFactor.Type
                        LEFT JOIN TblKala ON TblTRAnbar.IDKala = TblKala.IDKala
                                             AND TblTRAnbar.IDAnbar = TblKala.IDAnbar
              WHERE     ( ISNULL(TblFactor.IDForoshande, 0) = @personid )
                        AND ( TblTRAnbar.IDAnbar BETWEEN @idanbar1
                                                 AND     @idanbar2 )
                        AND ( TblTRAnbar.IDKala BETWEEN @idkala1 AND @idkala2 )
                        AND ( TblTRAnbar.TimeP BETWEEN @date1 AND @date2 )
                        AND ( TblTRAnbar.Type = @type )
                        AND ( TblKala.GroupCode LIKE @Code )
              UNION ALL
              SELECT    TR.Factor AS ShFactor ,
                        TR.Sodor AS Shsodor ,
                        TR.DateR COLLATE DATABASE_DEFAULT AS Date ,
                        ISNULL(REPLACE(TblKala.KalaGroups, '/', ' '), '') AS kalagroups ,
                        TblKala.Name ,
                        TR.TED AS Tedad ,
                        dbo.GetUnit(dbo.TblKala.IDAnbar, dbo.TblKala.IDKala, 0) UnitName ,
                        CONVERT(BIGINT, ROUND(( TR.Bed + TR.Bes ) / TR.TED, 0)) AS Fi ,
                        ( TR.Bed + TR.Bes ) AS Mablaghekol ,
						CASE WHEN dbo.TblKala.maliyat = 1 THEN dbo.TblKala.DarsadMaliat ELSE 0 END AS DarsadMaliat,
                        CAST(ROUND(CASE WHEN TblKala.maliyat = 1
                                        THEN ( TR.Bed + TR.Bes )
                                        ELSE 0
                                   END * dbo.TblKala.DarsadMaliat / 100.0, 0) AS BIGINT) AS Maliat
              FROM      TR
                        LEFT OUTER JOIN TblFactorOnvan ON TR.Factor = TblFactorOnvan.ShFactor
                                                          AND TR.Type = TblFactorOnvan.Type
                        LEFT OUTER JOIN TblKala ON TR.Idkala = TblKala.IDKala
                                                   AND TR.IdAnbr = TblKala.IDAnbar
              WHERE     ( TblFactorOnvan.CustumCod = @personid )
                        AND ( TR.IdAnbr BETWEEN @idanbar1 AND @idanbar2 )
                        AND ( TR.Idkala BETWEEN @idkala1 AND @idkala2 )
                        AND ( TR.DateR BETWEEN @date1 AND @date2 )
                        AND ( TR.Type = @type )
                        AND ( TblKala.GroupCode LIKE @Code )
            ) AS R
    ORDER BY [Date] ,
            Shsodor
    OPTION  ( RECOMPILE );
    RETURN;







GO

-- Procedure: [dbo].[RptChkDarResid]
IF OBJECT_ID(N'[dbo].[RptChkDarResid]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptChkDarResid] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptChkDarResid]
    @Sanad INT ,@CShobe INT
AS

	DECLARE @MinCShobe INT = 0,@MaxCShobe INT = 2147483647
	IF(@CShobe > 0)
	BEGIN
		SET @MinCShobe=@CShobe
		SET @MaxCShobe=@CShobe
	END
    DECLARE @DateR NVARCHAR(100) = '';
    SELECT  @DateR = DateR
    FROM    dbo.TR
    WHERE   SanadM = @Sanad;

    SELECT  chd.Id ,
            ISNULL(TblBank.Name,'') AS Name ,
            chd.shob ,
            chd.serial ,
            chd.DateChek ,
            chd.mab ,
            chd.numhesab ,
            chd.sharh ,
            ISNULL(TblCheck_State.name,'') AS state ,
            TblCheck_State.Id AS stateid ,
            chd.DatePas ,
            CONVERT(VARCHAR(50), chd.hsb1) AS hsb1 ,
            chd.hsb2 ,
            '' AS mabh ,
            @Sanad AS SanadM ,
            @DateR AS DateR ,
            TblBank.Id AS Bank,
			ISNULL(p.Name,'') + ' '+ISNULL(p.Famil,'') AS PersonName,
			CAST(1 AS bit) AS Selected
    FROM    [Check] AS chd
            LEFT JOIN TblBank ON chd.Bank = TblBank.Id
            LEFT JOIN TblCheck_State ON chd.State = TblCheck_State.Id
			LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = chd.PersonId
    WHERE   chd.Id IN ( SELECT  c.Id
                            FROM    [Check] AS c
                                    INNER JOIN TR AS t ON c.Id = t.IDCheck
                                                          AND t.TpCheck = 0
                            WHERE   t.SanadM = @Sanad
                            GROUP BY c.Id )
							AND (chd.CShobe BETWEEN @MinCShobe AND @MaxCShobe OR chd.CShobe = 0)
		ORDER BY chd.Id


GO

-- Procedure: [dbo].[RptChkParResid]
IF OBJECT_ID(N'[dbo].[RptChkParResid]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptChkParResid] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptChkParResid]
    @Sanad INT,@CShobe INT,@Ids NVARCHAR(MAX) = ''
AS

	DECLARE @MinCShobe INT = 0,@MaxCShobe INT = 2147483647
	IF(@CShobe > 0)
	BEGIN
		SET @MinCShobe=@CShobe
		SET @MaxCShobe=@CShobe
	END

    DECLARE @DateR NVARCHAR(100) = '';
    SELECT  @DateR = DateR
    FROM    dbo.TR
    WHERE   SanadM = @Sanad;

    SELECT  chp.Id ,
            ISNULL(TblBank.Name,'') AS Name ,
            chp.serial ,
            chp.DateChek ,
            chp.mab ,
            chp.numhesab ,
            chp.sharh ,
            ISNULL(TblCheck_State.name,'') AS state ,
            TblCheck_State.Id AS stateid ,
            chp.DatePas ,
            CONVERT(VARCHAR(50), chp.hsb1) AS hsb1 ,
            chp.hsb2 ,
            '' AS mabh ,
            @Sanad AS SanadM ,
            @DateR AS DateR ,
            TblBank.Id AS Bank,
			ISNULL(p.Name,'') + ' '+ISNULL(p.Famil,'') AS PersonName,
			CAST(0 AS bit) AS Selected
    FROM    dbo.CheckPardakht AS chp
            LEFT JOIN TblBank ON chp.Bank = TblBank.Id
            LEFT JOIN TblCheck_State ON chp.State = TblCheck_State.Id
			LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = chp.PersonId
    WHERE   chp.Id IN ( SELECT  c.Id
                            FROM    CheckPardakht AS c
                                    INNER JOIN TR AS t ON c.Id = t.IDCheck
                                                          AND t.TpCheck = 1
                            WHERE   t.SanadM = @Sanad
                            GROUP BY c.Id )

		AND (chp.CShobe BETWEEN @MinCShobe AND @MaxCShobe OR chp.CShobe = 0)
		ORDER BY DateChek

GO

-- Procedure: [dbo].[RptChkParResid_ById]
IF OBJECT_ID(N'[dbo].[RptChkParResid_ById]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptChkParResid_ById] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptChkParResid_ById]
    @Ids NVARCHAR(MAX) = ''
AS

BEGIN
	SELECT  chp.Id ,
            ISNULL(TblBank.Name,'') AS Name ,
            chp.serial ,
            chp.DateChek ,
            chp.mab ,
            chp.numhesab ,
            chp.sharh ,
            ISNULL(TblCheck_State.name,'') AS state ,
            TblCheck_State.Id AS stateid ,
            chp.DatePas ,
            CONVERT(VARCHAR(50), chp.hsb1) AS hsb1 ,
            chp.hsb2 ,
            '' AS mabh ,
            ISNULL(t.SanadM,0) AS SanadM ,
            chp.DateR AS DateR ,
            TblBank.Id AS Bank,
			ISNULL(p.Name,'') + ' '+ISNULL(p.Famil,'') AS PersonName,
			CAST(0 AS bit) AS Selected
    FROM    dbo.CheckPardakht AS chp
            LEFT JOIN TblBank ON chp.Bank = TblBank.Id
            LEFT JOIN TblCheck_State ON chp.State = TblCheck_State.Id
			LEFT JOIN tr AS t ON t.Sodor = chp.sodur
			LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = chp.PersonId
    WHERE   chp.Id IN ( SELECT  * FROM dbo.CSVToTable(@Ids) )
		ORDER BY DateChek
END

GO

-- Procedure: [dbo].[RptFacorOnvan]
IF OBJECT_ID(N'[dbo].[RptFacorOnvan]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptFacorOnvan] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptFacorOnvan] 
	@factor INT , 
	@type TINYINT    
AS 
BEGIN

    SET NOCOUNT ON;    
    DECLARE @PriceForosh INT = 0 , 
        @PriceMasraf INT = 0; 
    SELECT  @PriceForosh = CAST(Value AS INT) 
    FROM    dbo.TblParameters 
    WHERE   Name = 'ShowMabInKala'; 
    SELECT  @PriceMasraf = CAST(Value AS INT) 
    FROM    dbo.TblParameters 
    WHERE   Name = 'ShowMabInKalaMasraf'; 

    IF OBJECT_ID('tempdb.dbo.#temp', 'U') IS NOT NULL 
        DROP TABLE #temp; 
    CREATE TABLE #temp 
        ( 
          IdAnbar INT , 
          IdKala INT , 
          Tp1 INT , 
          Bed BIGINT , 
          Bes BIGINT , 
          Ted NUMERIC(30,15) , 
          CntCostName NVARCHAR(500) , 
          CntProjectName NVARCHAR(500) , 
          PriceForosh DECIMAL , 
          PriceMasraf DECIMAL , 
          Time NVARCHAR(100),
		  BedArz NUMERIC(18,3),
		  BesArz NUMERIC(18,3)
        ); 
 
    IF ( @type = 1 ) 
        BEGIN 
            INSERT  INTO #temp 
                    SELECT  t.IdAnbar , 
                            t.IdKala , 
                            tp , 
                            Bed , 
                            Bes , 
                            Ted , 
                            '' AS CntCostName , 
                            '' AS CntProjectName , 
                            ISNULL(pf.Price, 0) AS PriceForosh , 
                            ISNULL(pm.Price, 0) AS PriceMasraf , 
                            t.CreateTime,
							ISNULL(t.BedArz,0),
							ISNULL(t.BesArz,0)
                    FROM    dbo.TblPishFactor AS t 
                            LEFT JOIN dbo.TblPrice AS pf ON pf.IDAnbar = t.IdAnbar 
                                                            AND pf.IDKala = t.IdKala 
                                                            AND pf.IDLable = @PriceForosh 
                            LEFT JOIN dbo.TblPrice AS pm ON pm.IDAnbar = t.IdAnbar 
                                                            AND pm.IDKala = t.IdKala 
                                                            AND pm.IDLable = @PriceMasraf 
                    WHERE   Factor = @factor 
                            AND Type = @type; 
        END; 
    ELSE 
        BEGIN 
            INSERT  INTO #temp 
                    SELECT  IdAnbr , 
                            t.Idkala , 
                            Tp1 , 
                            Bed , 
                            Bes , 
                            TED , 
                            ISNULL(c.Name, '') AS CntCostName , 
                            ISNULL(p.Name, '') AS CntProjectName , 
                            ISNULL(pf.Price, 0) AS PriceForosh , 
                            ISNULL(pm.Price, 0) AS PriceMasraf , 
                            Time,
							ISNULL(td.BedArz,0),
							ISNULL(td.BesArz,0)
                    FROM    dbo.TR AS t 
                            LEFT JOIN dbo.CntCost AS c ON t.CntHaz = c.Id 
                            LEFT JOIN dbo.CntProject AS p ON t.CntProject = p.Id 
                            LEFT JOIN dbo.TblPrice AS pf ON pf.IDAnbar = t.IdAnbr 
                                                            AND pf.IDKala = t.Idkala 
                                                            AND pf.IDLable = @PriceForosh 
                            LEFT JOIN dbo.TblPrice AS pm ON pm.IDAnbar = t.IdAnbr 
                                                            AND pm.IDKala = t.Idkala 
                                                            AND pm.IDLable = @PriceMasraf 
							LEFT JOIN dbo.TRDetail AS td ON td.Sodor = t.Sodor
                    WHERE   Factor = @factor 
                            AND Type = @type; 
        END; 

    DECLARE @CntProjectName NVARCHAR(100) = '' , 
        @CntCostName NVARCHAR(100) = ''; 
    SELECT  @CntProjectName = ISNULL(MAX(CntProjectName), 0) , 
            @CntCostName = ISNULL(MAX(CntCostName), 0) 
    FROM    #temp; 
 
    DECLARE @MandeGhabl BIGINT = 0 , 
        @tpMandeGhabl VARCHAR(10) = ''; 
    DECLARE @MandeToday BIGINT = 0 , 
        @tpMandeToday VARCHAR(10) = ''; 

	  DECLARE @MandeGhablCntCost BIGINT = 0 , 
        @tpMandeGhablCntCost VARCHAR(10) = ''; 
    DECLARE @MandeTodayCntCost BIGINT = 0 , 
        @tpMandeTodayCntCost VARCHAR(10) = ''; 

    DECLARE @t TABLE 
    ( 
        Id INT , 
        Mande BIGINT , 
        Tp NVARCHAR(500) 
    ); 
	DECLARE @MandeNow BIT = 0
	SELECT @MandeNow = CAST(ISNULL(Value,0) AS BIT) FROM dbo.TblParameters WHERE Name = 'MandeNow'
	IF(@MandeNow=1)
	BEGIN
		INSERT  INTO @t 
			EXEC dbo.GetMandeBedehiFactorToday @factor, @type; 
	END
	ELSE
	BEGIN
		INSERT  INTO @t 
			EXEC dbo.GetMandeBedehiFactor @factor, @type; 
	END
 
    SELECT  @MandeGhabl = Mande , 
            @tpMandeGhabl = Tp 
    FROM    @t 
    WHERE   Id = 1; 
    SELECT  @MandeToday = Mande , 
            @tpMandeToday = Tp 
    FROM    @t 
    WHERE   Id = 2; 
	 SELECT  @MandeGhablCntCost = Mande , 
            @tpMandeGhablCntCost = Tp 
    FROM    @t 
    WHERE   Id = 3; 
    SELECT  @MandeTodayCntCost = Mande , 
            @tpMandeTodayCntCost = Tp 
    FROM    @t 
    WHERE   Id = 4; 
 


 
    DECLARE @MabFactor BIGINT = 0 , 
        @MabAmel BIGINT = 0 , 
        @MabTasviye BIGINT = 0 , 
        @MabEzaf BIGINT = 0 , 
        @MabKasr BIGINT = 0 , 
        @MabMaliat BIGINT = 0; 

    IF ( @type BETWEEN 200 AND 299 OR @type = 1 ) 
        BEGIN 
            SELECT  @MabFactor = ISNULL(SUM(Bes - Bed), 0) 
            FROM    #temp 
            WHERE   IdAnbar > 0; 
            SELECT  @MabAmel = ISNULL(SUM(Bes - Bed), 0) 
            FROM    #temp 
            WHERE   Tp1 > 0; 
            SELECT  @MabEzaf = ISNULL(SUM(Bes), 0) 
            FROM    #temp 
            WHERE   Tp1 > 0; 
            SELECT  @MabKasr = ISNULL(SUM(Bed), 0) 
            FROM    #temp 
            WHERE   Tp1 > 0; 
            SELECT  @MabTasviye = ISNULL(SUM(Bed - Bes), 0) 
            FROM    #temp 
            WHERE   IdAnbar = 0 
                    AND Tp1 = 0; 
        END; 
    ELSE 
        BEGIN 
            SELECT  @MabFactor = ISNULL(SUM(Bed - Bes), 0) 
            FROM    #temp 
            WHERE   IdAnbar > 0; 
            SELECT  @MabAmel = ISNULL(SUM(Bed - Bes), 0) 
            FROM    #temp 
            WHERE   Tp1 > 0; 
            SELECT  @MabEzaf = ISNULL(SUM(Bed), 0) 
            FROM    #temp 
            WHERE   Tp1 > 0; 
            SELECT  @MabKasr = ISNULL(SUM(Bes), 0) 
            FROM    #temp 
            WHERE   Tp1 > 0; 
            SELECT  @MabTasviye = ISNULL(SUM(Bes - Bed), 0) 
            FROM    #temp 
            WHERE   IdAnbar = 0 
                    AND Tp1 = 0; 
        END; 
 
 
    DECLARE @Khales BIGINT = 0;
	DECLARE @KhalesArz NUMERIC(18,3) = 0 
    DECLARE @TimeSave NVARCHAR(500); 
 
   
    SELECT  @Khales = ISNULL(ABS(SUM(Bed - Bes)), 0) , 
            @TimeSave = RIGHT(MIN(Time), 5) ,
			@KhalesArz = ISNULL(ABS(SUM(BedArz - BesArz)), 0) 
    FROM    #temp 
    WHERE   ( IdAnbar > 0 
              OR Tp1 > 0 
            ); 
 
 
    
 
    DECLARE @SumMasraf BIGINT = 0 , 
        @SumForosh BIGINT = 0; 
    SELECT  @SumMasraf = SUM(Ted * PriceMasraf) , 
            @SumForosh = SUM(Ted * PriceForosh) 
    FROM    #temp 
    WHERE   ( IdAnbar > 0 ); 
 
	DECLARE @H INT=0
	SELECT @H= MAX(TRDureTasviye) FROM tr WHERE type=@type AND Factor=@factor



    SELECT  TblFactorOnvan.ShFactor , 
            TblFactorOnvan.CustumCod , 
            ISNULL(pn.Value,'') +' '+ ISNULL(CustumCod.Name, '') + ' ' + ISNULL(CustumCod.Famil, '') + ' ' +dbo.TblFactorOnvan.CustumName  COLLATE SQL_Latin1_General_CP1_CI_AS AS Name , 
            TblFactorOnvan.CustumName , 
            TblFactorOnvan.DateFactor , 
            CASE WHEN LEN(TblFactorOnvan.DateFactor) <> 10 THEN '' ELSE dbo.[UDF_Julian_To_Gregorian](dbo.[UDF_Persian_To_Julian](TblFactorOnvan.DateFactor))END AS DateFactorM , 
            ISNULL(CustumCod.Sh_ozviat, 0) AS Sh_ozviat , 
            dbo.Func_GetTells(TblFactorOnvan.CustumCod) AS Tell , 
            CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.Address))) > 0 THEN dbo.TblFactorOnvan.Address ELSE ISNULL(address.Tell,'') END COLLATE SQL_Latin1_General_CP1_CI_AS AS address , 
            '' AS Addres_mk , 
            '' AS Addres_home , 
            CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.Mobile))) > 0 THEN dbo.TblFactorOnvan.Mobile ELSE dbo.Func_GetMobiles(TblFactorOnvan.CustumCod)  END COLLATE SQL_Latin1_General_CP1_CI_AS AS Mobile , 
            ISNULL(dbo.PersonTellNew(CustumCod.Sh_ozviat, 2), '') AS MobilePerson , 
            ISNULL(pelak.Tell, '') AS PelakPerson , 
            ISNULL(card.Tell, '') AS CardPerson , 
            TblFactorOnvan.Type , 
            TblFactorOnvan.Sanad , 
            ISNULL(dbo.GetTypeSefareshName(TblFactorOnvan.TypeSefaresh), '') + ' '+ ISNULL(dbo.TblRestaurant_GetName(TblFactorOnvan.BargeKhoruj), '') + ' ' + TblFactorOnvan.Sharh COLLATE SQL_Latin1_General_CP1_CI_AS AS Sharh , 
            TblFactorOnvan.Sharh AS SharhFactor , 
            ISNULL(dbo.GetTypeSefareshName(TblFactorOnvan.TypeSefaresh), '') + ' '+ ISNULL(dbo.TblRestaurant_GetName(TblFactorOnvan.BargeKhoruj), '')  COLLATE SQL_Latin1_General_CP1_CI_AS AS Location , 
            TblFactorOnvan.TypePardakht , 
			ISNULL(TTP.Name,'') AS TypePardakhtName,
            ISNULL(City.Name, '') AS Shahr , 
            ISNULL(Ostan.Name, '') AS Ostan , 
            '' AS Shahrestan , 
            ISNULL(CustumCod.Cod_Egh, '') AS Cod_Egh , 
            ISNULL(CustumCod.codmeli, '') AS codmeli , 
            CASE WHEN LEN(dbo.TblFactorOnvan.PostalCode)>0 THEN TblFactorOnvan.PostalCode ELSE ISNULL(Post.Tell, '') END AS Post , 
            TblFactorOnvan.BargeKhoruj , 
            ISNULL(City.CityCode, 0) AS CityCode , 
            ISNULL(City.Name, '') AS CityName , 
            ISNULL(UserIDAdd.FulName, '') AS UserAdd , 
            ISNULL(UserIDEdit.FulName, '') AS UserEdit , 
            ISNULL(UserIDAdd.Id, 0) AS UserAddID , 
            ISNULL(UserIDEdit.Id, 0) AS UserEditID , 
            TblFactorOnvan.sarfasl , 
            TblFactorOnvan.moin , 
            TblFactorOnvan.hsb , 
            @SumForosh AS SumPriceMasraf , 
            @SumMasraf AS SumPriceForosh , 
            dbo.TblFactorOnvan.TedPerson , 
            dbo.TblFactorOnvan.Description , 
            dbo.TblFactorOnvan.FactorCust , 
            ISNULL(CustumCod.FatherName, '') AS FatherName , 
            ISNULL(CustumCod.Sh_sh, '') AS Sh_sh , 
            ISNULL(CustumCod.mahaleSodur, '') AS mahaleSodur , 
            ISNULL(CustumCod.job, '') AS job , 
            ISNULL(CustumCod.Dt_Tavalod, '') AS Dt_Tavalod , 
            dbo.GetTodayNew() AS TimeNow , 
            dbo.GetTodayNewTime() AS TimeP , 
			@CntCostName AS CntCostName , 
            @CntProjectName AS CntProjectName , 
            @MandeGhabl AS MandeGhabl , 
            @tpMandeGhabl AS tpMandeGhabl , 
            CASE WHEN TblFactorOnvan.CustumCod = 1 THEN @Khales ELSE @MandeToday END AS MandeToday , 
            CASE WHEN TblFactorOnvan.CustumCod = 1 THEN N'بد' ELSE @tpMandeToday END AS tpMandeToday , 
			@MandeGhablCntCost AS MandeGhablCntCost , 
            @tpMandeGhablCntCost AS tpMandeGhablCntCost , 
            CASE WHEN TblFactorOnvan.CustumCod = 1 THEN @Khales ELSE @MandeTodayCntCost END AS MandeTodayCntCost , 
            CASE WHEN TblFactorOnvan.CustumCod = 1 THEN N'بد' ELSE @tpMandeTodayCntCost END AS tpMandeTodayCntCost , 
            @MabFactor AS MabFactor , 
            @MabAmel AS MabAmel , 
            @MabEzaf AS MabEzaf , 
            @MabKasr AS MabKasr , 
            @MabTasviye AS MabTasviye , 
            @Khales AS Khales , 
			@KhalesArz AS KhalesArz,
            @TimeSave AS TimeSave , 
            CustumCod2.Sh_ozviat AS CustumCod2Code , 
            ISNULL(CustumCod2.Name + ' ' + CustumCod2.Famil, '') AS CustumCod2Name , 
            ISNULL(dbo.PersonTellNew(CustumCod2.Sh_ozviat, 1), '') AS CustumCod2Tell , 
            ISNULL(dbo.PersonTellNew(CustumCod2.Sh_ozviat, 2), '') AS CustumCod2Mobile , 
            ISNULL(dbo.PersonTellNew(CustumCod2.Sh_ozviat, 3), '') AS CustumCod2Pelak , 
            ISNULL(dbo.PersonTellNew(CustumCod2.Sh_ozviat, 4), '') AS CustumCod2Card , 
            Clearance.Sh_ozviat AS ClearanceCode , 
            ISNULL(Clearance.Name + ' ' + Clearance.Famil, '') AS ClearanceName , 
            ISNULL(dbo.PersonTellNew(Clearance.Sh_ozviat, 1), '') AS ClearanceTell , 
            ISNULL(dbo.PersonTellNew(Clearance.Sh_ozviat, 2), '') AS ClearanceMobile , 
            ISNULL(dbo.PersonTellNew(Clearance.Sh_ozviat, 3), '') AS ClearancePelak , 
            ISNULL(dbo.PersonTellNew(Clearance.Sh_ozviat, 4), '') AS ClearanceCard , 
            Clearance2.Sh_ozviat AS Clearance2Code , 
            ISNULL(Clearance2.Name + ' ' + Clearance2.Famil, '') AS Clearance2Name , 
            ISNULL(dbo.PersonTellNew(Clearance2.Sh_ozviat, 1), '') AS Clearance2Tell , 
            ISNULL(dbo.PersonTellNew(Clearance2.Sh_ozviat, 2), '') AS Clearance2Mobile , 
            ISNULL(dbo.PersonTellNew(Clearance2.Sh_ozviat, 3), '') AS Clearance2Pelak , 
            ISNULL(dbo.PersonTellNew(Clearance2.Sh_ozviat, 4), '') AS Clearance2Card , 
            Driver.Sh_ozviat AS DriverCode , 
            ISNULL(Driver.Name + ' ' + Driver.Famil, '') AS DriverName , 
            ISNULL(dbo.PersonTellNew(Driver.Sh_ozviat, 1), '') AS DriverTell , 
            ISNULL(dbo.PersonTellNew(Driver.Sh_ozviat, 2), '') AS DriverMobile , 
            ISNULL(dbo.PersonTellNew(Driver.Sh_ozviat, 3), '') AS DriverPelak , 
            ISNULL(dbo.PersonTellNew(Driver.Sh_ozviat, 4), '') AS DriverCard , 
            Driver2.Sh_ozviat AS Driver2Code , 
            ISNULL(Driver2.Name + ' ' + Driver2.Famil, '') AS Driver2Name , 
            ISNULL(dbo.PersonTellNew(Driver2.Sh_ozviat, 1), '') AS Driver2Tell , 
            ISNULL(dbo.PersonTellNew(Driver2.Sh_ozviat, 2), '') AS Driver2Mobile , 
            ISNULL(dbo.PersonTellNew(Driver2.Sh_ozviat, 3), '') AS Driver2Pelak , 
            ISNULL(dbo.PersonTellNew(Driver2.Sh_ozviat, 4), '') AS Driver2Card , 
            dbo.TblFactorOnvan.Date2 , 
            ISNULL(Border.Name, '') AS BorderName , 
            ISNULL(Vizitor.Name + ' ' + Vizitor.Famil, '') AS VizitorName , 
            dbo.GetPersonPreviousScore(TblFactorOnvan.CustumCod,TblFactorOnvan.ShFactor) AS EmtiazAvalie , 
            dbo.GetPersonFactorRecievedScore(TblFactorOnvan.CustumCod, TblFactorOnvan.ShFactor) AS EmtiazKasb , 
            dbo.GetPersonFactorUsedScore(TblFactorOnvan.CustumCod,TblFactorOnvan.ShFactor) AS EmtiazMasraf , 
            dbo.GetPersonCurrentScore(TblFactorOnvan.CustumCod,dbo.TblFactorOnvan.ShFactor) AS EmtiazToday , 
            dbo.GetPersonFactorScore(TblFactorOnvan.CustumCod,TblFactorOnvan.ShFactor) AS EmtiazFactor, 
			ISNULL(TblFactorOnvan.RefId,0) AS RefId, 
			ISNULL(TF.ShFactor,0) AS NewShFactor,
			dbo.TblFactorOnvan.CShobe,
			dbo.GetSahebHesab(dbo.TblFactorOnvan.sarfasl,dbo.TblFactorOnvan.moin,dbo.TblFactorOnvan.hsb) AS HesabName,
			dbo.TblRegion_GetName(dbo.TblFactorOnvan.RegionId) AS RegionName,
			TblFactorOnvan.ChangeStateTime,
			CASE WHEN TblFactorOnvan.TypePardakht = 0 THEN 1 ELSE 0 END AS Noe,
			dbo.IsCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,1) AS IsNaghd,
			dbo.IsCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,2) AS IsBank,
			dbo.IsCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,3) AS IsCHECK,
			dbo.IsCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,4) AS IsNasiye,
			dbo.MabCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,1) AS MabNaghd,
			dbo.MabCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,2) AS MabBank,
			dbo.MabCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,3) AS MabCHECK,
			dbo.MabCodeTarazinFactor(TblFactorOnvan.ShFactor,TblFactorOnvan.Type,4) AS MabNasiye,
			dbo.RasTasviye(dbo.TblFactorOnvan.ShFactor,dbo.TblFactorOnvan.Type) AS RasTasviye,
			ISNULL(l.Name,'') AS TypeForoshName,
			TblFactorOnvan.TasviyeSharh,
			CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.CodeMeli))) > 0 THEN dbo.TblFactorOnvan.CodeMeli ELSE ISNULL(CustumCod.codmeli,'')  END COLLATE SQL_Latin1_General_CP1_CI_AS AS CodeMeli,
			ISNULL(tax.TaxId,'') AS TaxId,
			ISNULL(Drivermobile.Tell,'') AS Drivermobile,
			ISNULL(Vizitormobile.Tell,'') AS Vizitormobile,
			@H AS Dure,
			TblFactorOnvan.FishNumber,
			ISNULL(cs.Name,'') AS CshobeName
    FROM    TblFactorOnvan 
            LEFT OUTER JOIN TblUser AS UserIDEdit ON TblFactorOnvan.UserIDEdit = UserIDEdit.Id 
            LEFT OUTER JOIN TblUser AS UserIDAdd ON TblFactorOnvan.UserIDAdd = UserIDAdd.Id 
            LEFT OUTER JOIN dbo.TblPerson AS CustumCod ON TblFactorOnvan.CustumCod = CustumCod.Sh_ozviat 
            LEFT OUTER JOIN dbo.TblPerson AS CustumCod2 ON CustumCod2.Sh_ozviat = dbo.TblFactorOnvan.CustumCod2 
            LEFT OUTER JOIN dbo.TblPerson AS Clearance ON Clearance.Sh_ozviat = dbo.TblFactorOnvan.ClearanceId 
            LEFT OUTER JOIN dbo.TblPerson AS Clearance2 ON Clearance2.Sh_ozviat = dbo.TblFactorOnvan.ClearanceId2 
            LEFT OUTER JOIN dbo.TblPerson AS Driver ON TblFactorOnvan.Driver = Driver.Sh_ozviat 
            LEFT OUTER JOIN dbo.TblPerson AS Driver2 ON Driver2.Sh_ozviat = dbo.TblFactorOnvan.Driver2 
            LEFT OUTER JOIN dbo.TblPerson AS Vizitor ON Vizitor.Sh_ozviat = dbo.TblFactorOnvan.VizitorID 
            LEFT OUTER JOIN dbo.Tbl_City AS Border ON Border.Id = dbo.TblFactorOnvan.BorderId 
            LEFT OUTER JOIN Tbl_City AS City ON City.Id = CustumCod.CityId 
            LEFT OUTER JOIN Tbl_Ostan AS Ostan ON Ostan.Id = City.Ostan_Id 
			LEFT OUTER JOIN dbo.TblFactorOnvan AS TF ON TblFactorOnvan.RefId = TF.RefId AND 103 = TF.Type AND dbo.TblFactorOnvan.RefId>0 
			LEFT OUTER JOIN dbo.TblPreName AS pn ON pn.Id = CustumCod.PreName 
			LEFT OUTER JOIN dbo.TblTypePardakht AS TTP ON TTP.Id = dbo.TblFactorOnvan.TypePardakht 
			LEFT OUTER JOIN dbo.Func_PersonTell(3) AS pelak ON pelak.ShOzviat = TblFactorOnvan.CustumCod
			LEFT OUTER JOIN dbo.Func_PersonTell(4) AS card ON card.ShOzviat = TblFactorOnvan.CustumCod
			LEFT OUTER JOIN dbo.Func_PersonTell(5) AS address ON address.ShOzviat = TblFactorOnvan.CustumCod
			LEFT OUTER JOIN dbo.TblLable AS l ON l.ID = dbo.TblFactorOnvan.TypeForush
			LEFT OUTER JOIN dbo.Func_PersonTell(2) AS Drivermobile ON Drivermobile.ShOzviat = TblFactorOnvan.Driver
			LEFT OUTER JOIN dbo.Func_PersonTell(2) AS Vizitormobile ON Vizitormobile.ShOzviat = TblFactorOnvan.VizitorID
			LEFT OUTER JOIN dbo.TblMiddelFactorTaxGov AS tax ON tax.FactorId = dbo.TblFactorOnvan.ShFactor AND tax.FactorType = dbo.TblFactorOnvan.Type AND tax.Cancel = 0 AND tax.insId IN (1,2,4) AND tax.StatusId = 'SUCCESS'
			LEFT OUTER JOIN dbo.Func_PersonTell(6) AS Post ON Post.ShOzviat = TblFactorOnvan.CustumCod
			LEFT OUTER JOIN dbo.TblCompanyShobe AS cs ON cs.Id = dbo.TblFactorOnvan.CShobe
    WHERE   ( TblFactorOnvan.Type = @type ) AND ( TblFactorOnvan.ShFactor = @factor );  
END
    
 

GO

-- Procedure: [dbo].[RptFacorOnvanNew]
IF OBJECT_ID(N'[dbo].[RptFacorOnvanNew]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptFacorOnvanNew] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptFacorOnvanNew]
    (
      @factor INT ,
      @type TINYINT    
    )
AS 

    SET NOCOUNT ON;    
    DECLARE @MSG NVARCHAR(100) = '';


    DECLARE @PriceForosh INT = 0 ,
        @PriceMasraf INT = 0; 
    SELECT  @PriceForosh = CAST(Value AS INT)
    FROM    dbo.TblParameters
    WHERE   Name = 'ShowMabInKala'; 
    SELECT  @PriceMasraf = CAST(Value AS INT)
    FROM    dbo.TblParameters
    WHERE   Name = 'ShowMabInKalaMasraf'; 
 
    IF OBJECT_ID('tempdb.dbo.#temp', 'U') IS NOT NULL
        DROP TABLE #temp; 
    CREATE TABLE #temp
        (
          IdAnbar INT ,
          IdKala INT ,
          Tp1 INT ,
          Bed BIGINT ,
          Bes BIGINT ,
          Ted NUMERIC(30, 15) ,
          CntCostName NVARCHAR(500) ,
          CntProjectName NVARCHAR(500) ,
          PriceForosh DECIMAL ,
          PriceMasraf DECIMAL ,
          Time NVARCHAR(100)
        ); 
 
    IF ( @type = 1 )
        BEGIN 
            INSERT  INTO #temp
                    SELECT  t.IdAnbar ,
                            t.IdKala ,
                            tp ,
                            Bed ,
                            Bes ,
                            Ted ,
                            '' AS CntCostName ,
                            '' AS CntProjectName ,
                            ISNULL(pf.Price, 0) AS PriceForosh ,
                            ISNULL(pm.Price, 0) AS PriceMasraf ,
                            t.CreateTime
                    FROM    dbo.TblPishFactor AS t
                            LEFT JOIN dbo.TblPrice AS pf ON pf.IDAnbar = t.IdAnbar
                                                            AND pf.IDKala = t.IdKala
                                                            AND pf.IDLable = @PriceForosh
                            LEFT JOIN dbo.TblPrice AS pm ON pm.IDAnbar = t.IdAnbar
                                                            AND pm.IDKala = t.IdKala
                                                            AND pm.IDLable = @PriceMasraf
                    WHERE   Factor = @factor
                            AND Type = @type; 
        END; 
    ELSE
        BEGIN 
            INSERT  INTO #temp
                    SELECT  IdAnbr ,
                            t.Idkala ,
                            Tp1 ,
                            Bed ,
                            Bes ,
                            TED ,
                            ISNULL(c.Name, '') AS CntCostName ,
                            ISNULL(p.Name, '') AS CntProjectName ,
                            ISNULL(pf.Price, 0) AS PriceForosh ,
                            ISNULL(pm.Price, 0) AS PriceMasraf ,
                            Time
                    FROM    dbo.TR AS t
                            LEFT JOIN dbo.CntCost AS c ON t.CntHaz = c.Id
                            LEFT JOIN dbo.CntProject AS p ON t.CntProject = p.Id
                            LEFT JOIN dbo.TblPrice AS pf ON pf.IDAnbar = t.IdAnbr
                                                            AND pf.IDKala = t.Idkala
                                                            AND pf.IDLable = @PriceForosh
                            LEFT JOIN dbo.TblPrice AS pm ON pm.IDAnbar = t.IdAnbr
                                                            AND pm.IDKala = t.Idkala
                                                            AND pm.IDLable = @PriceMasraf
                    WHERE   Factor = @factor
                            AND Type = @type; 
        END; 
   
 
 
 
    DECLARE @MandeGhabl BIGINT = 0 ,
        @tpMandeGhabl VARCHAR(10) = ''; 
    DECLARE @MandeToday BIGINT = 0 ,
        @tpMandeToday VARCHAR(10) = ''; 
    DECLARE @t TABLE
        (
          Id INT ,
          Mande BIGINT ,
          Tp NVARCHAR(500)
        ); 
    DECLARE @MandeNow BIT = 0;
    SELECT  @MandeNow = CAST(ISNULL(Value, 0) AS BIT)
    FROM    dbo.TblParameters
    WHERE   Name = 'MandeNow';
    IF ( @MandeNow = 1 )
        BEGIN
            INSERT  INTO @t
                    EXEC dbo.GetMandeBedehiFactorToday @factor, @type; 
        END;
    ELSE
        BEGIN
            INSERT  INTO @t
                    EXEC dbo.GetMandeBedehiFactor @factor, @type; 
        END;
 
    SELECT  @MandeGhabl = Mande ,
            @tpMandeGhabl = Tp
    FROM    @t
    WHERE   Id = 1; 
    SELECT  @MandeToday = Mande ,
            @tpMandeToday = Tp
    FROM    @t
    WHERE   Id = 2; 
 
    DECLARE @MabFactor BIGINT = 0 ,
        @MabAmel BIGINT = 0 ,
        @MabTasviye BIGINT = 0 ,
        @MabEzaf BIGINT = 0 ,
        @MabKasr BIGINT = 0 ,
        @MabMaliat BIGINT = 0; 
    IF ( @type BETWEEN 200 AND 299 )
        BEGIN 
            SELECT  @MabFactor = ISNULL(SUM(Bes - Bed), 0)
            FROM    #temp
            WHERE   IdAnbar > 0; 
            SELECT  @MabAmel = ISNULL(SUM(Bes - Bed), 0)
            FROM    #temp
            WHERE   Tp1 > 0; 
            SELECT  @MabEzaf = ISNULL(SUM(Bes), 0)
            FROM    #temp
            WHERE   Tp1 > 0; 
            SELECT  @MabKasr = ISNULL(SUM(Bed), 0)
            FROM    #temp
            WHERE   Tp1 > 0; 
            SELECT  @MabTasviye = ISNULL(SUM(Bed - Bes), 0)
            FROM    #temp
            WHERE   IdAnbar = 0
                    AND Tp1 = 0; 
        END; 
    ELSE
        BEGIN 
            SELECT  @MabFactor = ISNULL(SUM(Bed - Bes), 0)
            FROM    #temp
            WHERE   IdAnbar > 0; 
            SELECT  @MabAmel = ISNULL(SUM(Bed - Bes), 0)
            FROM    #temp
            WHERE   Tp1 > 0; 
            SELECT  @MabEzaf = ISNULL(SUM(Bed), 0)
            FROM    #temp
            WHERE   Tp1 > 0; 
            SELECT  @MabKasr = ISNULL(SUM(Bes), 0)
            FROM    #temp
            WHERE   Tp1 > 0; 
            SELECT  @MabTasviye = ISNULL(SUM(Bes - Bed), 0)
            FROM    #temp
            WHERE   IdAnbar = 0
                    AND Tp1 = 0; 
        END; 
 
    DECLARE @Khales BIGINT = 0; 
    DECLARE @TimeSave NVARCHAR(500); 
 
   
    SELECT  @Khales = ISNULL(ABS(SUM(Bed - Bes)), 0) ,
            @TimeSave = RIGHT(MIN(Time), 5)
    FROM    #temp
    WHERE   ( IdAnbar > 0
              OR Tp1 > 0
            ); 

    DECLARE @SumMasraf BIGINT = 0 ,
        @SumForosh BIGINT = 0; 
    SELECT  @SumMasraf = SUM(Ted * PriceMasraf) ,
            @SumForosh = SUM(Ted * PriceForosh)
    FROM    #temp
    WHERE   ( IdAnbar > 0 ); 
 
    SELECT  TblFactorOnvan.ShFactor ,
            TblFactorOnvan.CustumCod ,
            CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.CustumName))) = 0
                 THEN ISNULL(CustumCod.Name, '') + ' '
                      + ISNULL(CustumCod.Famil, '') + ' '
                      + ISNULL(CustomerClub.CustomerName, '') + ' '
                      + ISNULL(CustomerClub.CustomerFamily, '')
                 ELSE dbo.TblFactorOnvan.CustumName 
            END COLLATE SQL_Latin1_General_CP1_CI_AS AS Name ,
            CustumName ,
            TblFactorOnvan.DateFactor ,
            ISNULL(CustumCod.Sh_ozviat, 0) AS Sh_ozviat ,
            dbo.PersonTellNew(CustumCod.Sh_ozviat, 1) AS Tell ,
            CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.Address))) > 0
                 THEN dbo.TblFactorOnvan.Address
                 ELSE dbo.PersonTellNew(CustumCod.Sh_ozviat, 5)
            END COLLATE SQL_Latin1_General_CP1_CI_AS AS address ,
            '' AS Addres_mk ,
            '' AS Addres_home ,
            CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.Mobile))) > 0
                 THEN dbo.TblFactorOnvan.Mobile
                 ELSE ISNULL(dbo.PersonTellNew(CustumCod.Sh_ozviat, 2) COLLATE SQL_Latin1_General_CP1_CI_AS,
                             '')
            END COLLATE SQL_Latin1_General_CP1_CI_AS AS Mobile ,
            ISNULL(dbo.PersonTellNew(CustumCod.Sh_ozviat, 2), '') AS MobilePerson ,
            TblFactorOnvan.Type ,
            TblFactorOnvan.Sanad ,
            ISNULL(dbo.GetTypeSefareshName(TypeSefaresh), '') + ' '
            + ISNULL(dbo.TblRestaurant_GetName(BargeKhoruj), '') + ' '
            + TblFactorOnvan.Sharh COLLATE SQL_Latin1_General_CP1_CI_AS AS Sharh ,
            TblFactorOnvan.Sharh AS SharhFactor ,
            ISNULL(dbo.GetTypeSefareshName(TypeSefaresh), '') + ' '
            + ISNULL(dbo.TblRestaurant_GetName(BargeKhoruj), '')  COLLATE SQL_Latin1_General_CP1_CI_AS AS Location ,
            TblFactorOnvan.TypePardakht ,
            ISNULL(City.Name, '') AS Shahr ,
            ISNULL(Ostan.Name, '') AS Ostan ,
            '' AS Shahrestan ,
            ISNULL(CustumCod.Cod_Egh, '') AS Cod_Egh ,
            ISNULL(CustumCod.codmeli, '') AS codmeli ,
            ISNULL(CustumCod.post, '') AS Post ,
            TblFactorOnvan.BargeKhoruj ,
            ISNULL(City.CityCode, 0) AS CityCode ,
            ISNULL(City.Name, '') AS CityName ,
            ISNULL(UserIDAdd.FulName, '') AS UserAdd ,
            ISNULL(UserIDEdit.FulName, '') AS UserEdit ,
            ISNULL(UserIDAdd.UserName, 0) AS UserAddID ,
            ISNULL(UserIDEdit.UserName, 0) AS UserEditID ,
            TblFactorOnvan.sarfasl ,
            TblFactorOnvan.moin ,
            TblFactorOnvan.hsb ,
            @SumForosh AS SumPriceMasraf ,
            @SumMasraf AS SumPriceForosh ,
            dbo.TblFactorOnvan.TedPerson ,
            dbo.TblFactorOnvan.Description ,
            dbo.TblFactorOnvan.FactorCust ,
            ISNULL(CustumCod.FatherName, '') AS FatherName ,
            ISNULL(CustumCod.Sh_sh, '') AS Sh_sh ,
            ISNULL(CustumCod.mahaleSodur, '') AS mahaleSodur ,
            ISNULL(CustumCod.job, '') AS job ,
            ISNULL(CustumCod.Dt_Tavalod, '') AS Dt_Tavalod ,
            dbo.GetTodayNew() AS TimeNow ,
            dbo.GetTodayNewTime() AS TimeP ,
            @MandeGhabl AS MandeGhabl ,
            @tpMandeGhabl AS tpMandeGhabl ,
            CASE WHEN TblFactorOnvan.CustumCod = 1 THEN @MandeToday
                 ELSE @MandeToday
            END AS MandeToday ,
            CASE WHEN TblFactorOnvan.CustumCod = 1 THEN @tpMandeToday
                 ELSE @tpMandeToday
            END AS tpMandeToday ,
            @Khales AS Khales ,
            @TimeSave AS TimeSave ,
            @MabAmel AS MabAmel ,
            @MabEzaf AS MabEzaf ,
            @MabKasr AS MabKasr ,
            @MabTasviye AS MabTasviye ,
            ISNULL(Vizitor.Name + ' ' + Vizitor.Famil, '') AS VizitorName ,
            @MSG AS MSG ,
            dbo.GetFactorScore(dbo.TblFactorOnvan.Mobile) AS Score ,
            ISNULL(dbo.BedehiByCustomHsb(TblFactorOnvan.CustumCod,
                                         TblFactorOnvan.ShFactor,
                                         TblFactorOnvan.Type,
                                         TblFactorOnvan.DateFactor), 0) AS Bedehi2 ,
            CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.CodeMeli))) > 0
                 THEN dbo.TblFactorOnvan.CodeMeli
                 ELSE ISNULL(CustumCod.codmeli, '')
            END COLLATE SQL_Latin1_General_CP1_CI_AS AS CodeMeli ,
            dbo.MabCodeTarazinFactor(TblFactorOnvan.ShFactor,
                                     TblFactorOnvan.Type, 4) AS MabNasiye ,
            FishNumber ,
            dbo.GetTypeSefareshName(dbo.TblFactorOnvan.TypeSefaresh) AS TypeSefareshName ,
            FactorSite
    FROM    TblFactorOnvan
            LEFT OUTER JOIN TblUser AS UserIDEdit ON TblFactorOnvan.UserIDEdit = UserIDEdit.Id
            LEFT OUTER JOIN TblUser AS UserIDAdd ON TblFactorOnvan.UserIDAdd = UserIDAdd.Id
            LEFT OUTER JOIN dbo.TblPerson AS CustumCod ON TblFactorOnvan.CustumCod = CustumCod.Sh_ozviat
            LEFT OUTER JOIN dbo.TblPerson AS Vizitor ON Vizitor.Sh_ozviat = dbo.TblFactorOnvan.VizitorID
            LEFT OUTER JOIN Tbl_City AS City ON City.Id = CustumCod.CityId
            LEFT OUTER JOIN Tbl_Ostan AS Ostan ON Ostan.Id = City.Ostan_Id
            LEFT OUTER JOIN dbo.CustomerClub ON CustomerClub.Mobile = TblFactorOnvan.Mobile
    WHERE   ( TblFactorOnvan.Type = @type )
            AND ( TblFactorOnvan.ShFactor = @factor );  
 

GO

-- Procedure: [dbo].[RptKharidAndBargashtKharidTasviye]
IF OBJECT_ID(N'[dbo].[RptKharidAndBargashtKharidTasviye]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptKharidAndBargashtKharidTasviye] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptKharidAndBargashtKharidTasviye]
    @Date1 CHAR(10),
    @Date2 CHAR(10),
    @CShobe INT = 0 ,
    @CodeKala NVARCHAR(MAX) = NULL ,
    @IdAnbar VARCHAR(MAX) = NULL ,
    @Moshtari VARCHAR(MAX) = NULL ,
	@Tasviye VARCHAR(MAX) = NULL 
	  
AS  
    BEGIN    
        IF ( OBJECT_ID('#RptKharidAndAvamelKala_Base', 'U') ) IS NOT NULL  
            DROP TABLE  #RptKharidAndAvamelKala_Base;       
        CREATE TABLE #RptKharidAndAvamelKala_Base  
            (  
              Shfactor INT ,  
              [Type] TINYINT ,
			  CustomerId INT ,
			  [Rank] INT ,  
              IdAnbar INT ,  
              IdKala INT , 
              Mab BIGINT ,  
              Takh BIGINT ,  
              Ted INT 
            );    
        INSERT  INTO #RptKharidAndAvamelKala_Base  
                ( Shfactor ,  
                  [Type] ,
				  CustomerId ,
				  [Rank] ,  
                  IdAnbar ,  
                  IdKala ,  
                  Mab ,  
                  Takh ,  
                  Ted 
                )  
                SELECT  Factor ,
						dbo.TR.[Type] ,
						tfo.CustumCod ,
						RANK() OVER ( PARTITION BY TR.Factor ORDER BY MIN(Sodor) ) ,   
                        IdAnbr ,   
                        TR.Idkala , 
                        SUM(Bed + Bes) ,
                        SUM(Takh) ,   
                        SUM(TED) 
						
                FROM    dbo.TR
                    LEFT OUTER JOIN dbo.TblKala ON TR.IdAnbr = dbo.TblKala.IDAnbar
                                                   AND TR.Idkala = dbo.TblKala.IDKala
												   LEFT OUTER JOIN dbo.TblFactorOnvan AS tfo ON dbo.TR.Factor = tfo.ShFactor AND dbo.TR.[Type] = tfo.[Type]
                WHERE   TR.[Type] IN (103,204)  
						AND TR.Idkala > 0   
                        AND DateR BETWEEN @Date1 AND @Date2
						AND ( @CShobe = 0 OR TR.CShobe = @CShobe OR TR.CShobe = 0 )							  
				GROUP BY Factor, dbo.TR.[Type], tfo.CustumCod, IdAnbr, TR.Idkala

		IF (ISNULL(@CodeKala, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE IdKala NOT IN (SELECT * FROM dbo.CSVToTableStr(@CodeKala))
		END	

		IF (ISNULL(@IdAnbar, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE IdAnbar NOT IN (SELECT * FROM dbo.CSVToTable(@IdAnbar))
		END

		IF (ISNULL(@Moshtari, '') <> '')
		BEGIN
			DELETE #RptKharidAndAvamelKala_Base WHERE CustomerId NOT IN (SELECT * FROM dbo.CSVToTable(@Moshtari))
		END

		IF ( OBJECT_ID('##RptKharidAndAvamelKala_TasviyeFactorTmp', 'U') ) IS NOT NULL
			DROP TABLE  #RptKharidAndAvamelKala_TasviyeFactorTmp;  
		CREATE TABLE #RptKharidAndAvamelKala_TasviyeFactorTmp		
            (  
			  Shfactor INT ,  
              [Type] TINYINT ,
			  MabKharid BIGINT ,
			  MabBargasht BIGINT ,
			  Srfsl INT ,
			  Moin INT ,
			  HSB INT 
            );    
        INSERT  INTO #RptKharidAndAvamelKala_TasviyeFactorTmp
                SELECT  ttr.Factor, ttr.[Type], SUM(ttr.Bes - ttr.Bed), 0, ttr.Srfsl, ttr.Moin, ttr.HSB
                FROM    dbo.TR AS ttr 
				WHERE ttr.Idkala = 0 AND ttr.Tp1 = 0 AND EXISTS (SELECT * FROM #RptKharidAndAvamelKala_Base AS tbl WHERE ttr.Factor = tbl.Shfactor AND ttr.[Type] = tbl.[Type])
		GROUP BY ttr.Factor, ttr.[Type], ttr.Srfsl, ttr.Moin, ttr.HSB	

		DELETE #RptKharidAndAvamelKala_TasviyeFactorTmp
		WHERE NOT EXISTS (SELECT * FROM #RptKharidAndAvamelKala_Base AS tblBase WHERE tblBase.Shfactor = Shfactor AND tblBase.[Type] = [Type])
		
	UPDATE tbl
	SET tbl.MabBargasht = MabKharid * -1, tbl.MabKharid = 0
	FROM #RptKharidAndAvamelKala_TasviyeFactorTmp AS tbl WHERE [Type] = 204
	
	SELECT  CAST( CASE ISNULL(tblT.id, '') WHEN '' THEN 0 ELSE 1 END AS BIT) AS Tik ,
            tbl.Srfsl ,
            tbl.Moin ,
			tbl.HSB ,
			dbo.GetSahebHesab(tbl.Srfsl, tbl.Moin, tbl.HSB) AS HesabName ,
            SUM(tbl.MabKharid) AS MabKharid ,
            SUM(tbl.MabBargasht) AS MabBargasht ,
			SUM(tbl.MabKharid) - SUM(tbl.MabBargasht) AS MabKol
            FROM    #RptKharidAndAvamelKala_TasviyeFactorTmp AS tbl
			LEFT OUTER JOIN dbo.CSVToTableStr(@Tasviye) AS tblT ON tblT.id = CAST(tbl.Srfsl AS VARCHAR) + '-' + CAST(tbl.Moin AS VARCHAR) + '-' + CAST(tbl.HSB AS VARCHAR)  COLLATE DATABASE_DEFAULT
    GROUP BY CAST( CASE ISNULL(tblT.id, '') WHEN '' THEN 0 ELSE 1 END AS BIT) ,
            tbl.Srfsl ,
            tbl.Moin ,
			tbl.HSB ,
			dbo.GetSahebHesab(tbl.Srfsl, tbl.Moin, tbl.HSB) 
    ORDER BY tbl.Srfsl, tbl.Moin, tbl.HSB
   
    END;

GO

-- Procedure: [dbo].[RptListFactor_TaxGov]
IF OBJECT_ID(N'[dbo].[RptListFactor_TaxGov]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptListFactor_TaxGov] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptListFactor_TaxGov] 
    @factor1 INT ,
    @factor2 INT ,
    @date1 NVARCHAR(10) ,
    @date2 NVARCHAR(10),
	@TypeSend INT,
	@Tashkhis1 INT,
	@Tashkhis2 INT,
	@SRF1 INT,
	@SRF2 INT,
	@TypeTasviye INT,
	@FactorTasviye BIT,
	@CusomerID VARCHAR(MAX),
	@TypeCustom TINYINT,
	@StateFactor INT,
	@UserGroups NVARCHAR(MAX),
	@Anbar1 INT,
	@Anbar2 INT
AS
    BEGIN
		DECLARE @TypeFactor TINYINT = 203
		DECLARE @Moaff BIT
		SELECT @Moaff=ISNULL(Moaff,0) from dbo.TblSettingsTax WHERE Id=1
		 DECLARE @UserIds NVARCHAR(MAX) = '';
        SELECT  @UserIds = @UserIds + ISNULL(CAST(UserId AS NVARCHAR(100)), '')
                + ','
        FROM    dbo.TblGroupUsers
        WHERE   GroupId IN ( SELECT *
                             FROM   dbo.CSVToTable(@UserGroups) );

	
		IF(@factor1 = 0 AND @factor2 = 0)
		BEGIN
		    SET @factor1 = 1
			SET @factor2 =999999999
		END
		IF(@Tashkhis1 = 0 AND @Tashkhis2 = 0)
		BEGIN
		    SET @Tashkhis1 = 0
			SET @Tashkhis2 =99999
		END

		IF(@SRF1 = 0 AND @SRF2 = 0)
		BEGIN
		    SET @SRF1 = 0
			SET @SRF2 =99999
		END

		IF(@Anbar1 = 0 AND @Anbar2 = 0)
		BEGIN
		    SET @Anbar1 = 0
			SET @Anbar2 =99999
		END

        DECLARE @codemeli NVARCHAR(100)= N'',@CodeShobe VARCHAR(50) = '',@typeCompany INT = 0,@NoAmelAfzayesh BIT = 0

		SELECT @typeCompany = ISNULL(Value,0) FROM dbo.TblParameterTax
		WHERE Name = 'TypeCompany'

	

		SELECT @NoAmelAfzayesh = ISNULL(Value,0) FROM dbo.TblParameterTax
		WHERE Name = 'NoAmelAfzayesh'


		IF(@typeCompany = 0)
		BEGIN
			SELECT  @codemeli = codemeli,@CodeShobe = CodeShobe
			FROM    dbo.TblCompany
			WHERE   Id = 1;
		END
		ELSE
		BEGIN
			SELECT  @codemeli = CodeEghtesadi,@CodeShobe = CodeShobe
			FROM    dbo.TblCompany
			WHERE   Id = 1;
		END

		


		DECLARE @CalsWays BIT = 0
		SELECT @CalsWays = ISNULL(CalsWays,0) FROM dbo.TblSettingsTax

		
		


		IF OBJECT_ID('#FactorTasvie', 'U') IS NOT NULL
				DROP TABLE #FactorTasvie;	
		 CREATE TABLE #FactorTasvie
            (
			  Factor INT,
			  Type TINYINT
            );
			IF(@FactorTasviye = 1)
			BEGIN
			    INSERT INTO #FactorTasvie
				SELECT
				Factor,
				t.Type
				FROM dbo.TR AS t
				LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = t.Factor AND fo.Type = t.Type
				LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				WHERE 
				t.Factor BETWEEN @factor1 AND @factor2
				AND t.DateR BETWEEN @date1 AND @date2
				AND t.Type = @TypeFactor 
				AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
				AND (ISNULL(p.BuyerType,0) = @TypeCustom OR @TypeCustom =0 OR p.BuyerType IS NULL)
				AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
				GROUP BY Factor,t.Type
				HAVING SUM(t.Bed-t.Bes) = 0
				OPTION  ( RECOMPILE );
                
			END
			ELSE
			BEGIN
			    INSERT INTO #FactorTasvie
				SELECT
				Factor,
				t.Type
				FROM dbo.TR AS t 
				LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = t.Factor AND fo.Type = t.Type
				LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				WHERE 
				t.Factor BETWEEN @factor1 AND @factor2
				AND t.DateR BETWEEN @date1 AND @date2
				AND t.Type = @TypeFactor 
				AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
				AND (ISNULL(p.BuyerType,0) = @TypeCustom OR @TypeCustom =0 OR p.BuyerType IS NULL)
				AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
				GROUP BY Factor,t.Type
				OPTION  ( RECOMPILE );
			END


				IF OBJECT_ID('#TasviyeName', 'U') IS NOT NULL
				DROP TABLE #TasviyeName;	
		 CREATE TABLE #TasviyeName
            (
			  Factor INT,
			  Type INT,
			  HSBName NVARCHAR(500)
            );
			INSERT INTO #TasviyeName
			SELECT t.Factor,t.Type,MAX(p.Name+' '+p.Famil) AS HSBName FROM dbo.TR AS t
			INNER JOIN dbo.Master AS m ON m.Srfsl = t.Srfsl AND m.Moin = t.Moin AND m.HSB = t.HSB
			INNER JOIN dbo.TblPerson AS p ON p.Sh_ozviat = m.personcod
			INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
			WHERE   t.Factor BETWEEN @factor1 AND @factor2 AND DateR BETWEEN @date1 AND @date2
							AND t.Type = @TypeFactor
							AND  IdAnbr = 0 AND Tp1 = 0
			GROUP BY t.Factor,t.Type
		

		IF OBJECT_ID('tempdb.dbo.#maintr', 'U') IS NOT NULL
				DROP TABLE #maintr;	
		 CREATE TABLE #maintr
            (
			  Factor INT ,
			  Bed BIGINT,
              Bes BIGINT,
			  Takh BIGINT,
			  DarsadMashmol NUMERIC(18,3),
			  Mashmol TINYINT,
			  IdAnbr INT,
			  Idkala INT,
			  Ted NUMERIC(18,5),
			  Kasr BIGINT,
			  OtherTaxAmount BIGINT,
			  OtherFundsAmount BIGINT
            );


			IF(@NoAmelAfzayesh=1)
			BEGIN
				INSERT INTO #maintr
				SELECT
				 t.Factor,
				 Bed,
				Bes,
				Takh,
				ISNULL(DarsadMashmol,0) AS DarsadMashmol,
				Mashmol,
				IdAnbr,
				Idkala,
				TED,
				0,
				ISNULL(OtherTaxAmount,0) AS OtherTaxAmount,
				ISNULL(OtherFundsAmount,0) AS OtherFundsAmount
				FROM dbo.TR AS t
				INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
				WHERE t.Type = @TypeFactor AND DateR BETWEEN @date1 AND @date2 AND t.Factor BETWEEN @factor1 AND @factor2 AND IdAnbr>0 AND Srfsl BETWEEN @SRF1 AND @SRF2 AND Tashkhis BETWEEN @Tashkhis1 AND @Tashkhis2 AND IdAnbr BETWEEN @Anbar1 AND @Anbar2
				OPTION  ( RECOMPILE );
			END
			ELSE
			BEGIN
				INSERT INTO #maintr
				SELECT
				 t.Factor,
				 Bed,
				Bes,
				Takh,
				ISNULL(DarsadMashmol,0) AS DarsadMashmol,
				Mashmol,
				IdAnbr,
				Idkala,
				TED,
				0,
				ISNULL(OtherTaxAmount,0) AS OtherTaxAmount,
				ISNULL(OtherFundsAmount,0) AS OtherFundsAmount
				FROM dbo.TR AS t
				INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
				WHERE t.Type = @TypeFactor AND DateR BETWEEN @date1 AND @date2 AND t.Factor BETWEEN @factor1 AND @factor2 AND IdAnbr>0 AND Srfsl BETWEEN @SRF1 AND @SRF2 AND Tashkhis BETWEEN @Tashkhis1 AND @Tashkhis2 AND IdAnbr BETWEEN @Anbar1 AND @Anbar2
				UNION ALL
				SELECT
				t.Factor,
				Bed,
				Bes,
				Takh,
				ISNULL(fa.DarsadMaliat,0) AS DarsadMashmol,
				ISNULL(fa.Mashmol,0) AS  Mashmol,
				0 AS IdAnbr,
				t.IdAmel AS Idkala,
				1 AS TED,
				0,
				0,
				0 FROM dbo.TR AS t
				INNER JOIN dbo.TblFactorAvamel AS fa ON fa.Id = t.IdAmel
				INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
				WHERE t.Type = @TypeFactor AND DateR BETWEEN @date1 AND @date2 AND t.Factor BETWEEN @factor1 AND @factor2 AND t.Tp1>0 AND  Tashkhis BETWEEN @Tashkhis1 AND @Tashkhis2
				AND fa.State = 0 AND fa.Maliat = 0 AND ISNULL(fa.OtherTax,0) = 0 AND ISNULL(fa.OtherFunds,0) = 0
				OPTION  ( RECOMPILE );
			END


		
		 IF OBJECT_ID('tempdb.dbo.#SumMab', 'U') IS NOT NULL
			DROP TABLE #SumMab;	
		 CREATE TABLE #SumMab
            (
			  Factor INT ,
			  Mab NUMERIC(30,15)
            );

			

			IF OBJECT_ID('tempdb.dbo.#Kosorat', 'U') IS NOT NULL
				DROP TABLE #Kosorat;	
		 CREATE TABLE #Kosorat
            (
			  Factor INT ,
			  Mab NUMERIC(30,15)
            );


		

			
			


				INSERT INTO #Kosorat
				SELECT t.Factor,SUM(t.Bed) AS Mab FROM dbo.TR AS t
				INNER JOIN dbo.TblFactorAvamel AS fa ON fa.Id = t.IdAmel
				INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
				WHERE t.Type = @TypeFactor AND DateR BETWEEN @date1 AND @date2 AND t.Factor BETWEEN @factor1 AND @factor2 AND t.IdAnbr = 0 AND t.Tp1>0 AND Tashkhis BETWEEN @Tashkhis1 AND @Tashkhis2
				AND t.Bed>0 AND fa.Mashmol = 1 AND fa.State  = 1
				GROUP BY t.Factor
				OPTION  ( RECOMPILE );

				INSERT INTO #SumMab
				SELECT Factor,SUM(Bes) FROM #maintr
				WHERE Mashmol = 1
				GROUP BY Factor
				OPTION  ( RECOMPILE );



				UPDATE #maintr SET Kasr =  CASE WHEN sumtr.mab>0 THEN ROUND((CAST(tr.Bes AS NUMERIC(30,15)) / sumtr.Mab) * kasr.Mab,0) ELSE 0 END   FROM #maintr AS tr
				INNER JOIN #SumMab AS sumtr ON tr.Factor = sumtr.Factor
				INNER JOIN #Kosorat AS kasr ON kasr.Factor = tr.Factor
				WHERE Mashmol = 1





			
				UPDATE #maintr SET Bes = Bes-Kasr,Takh = Takh + Kasr,Kasr = 0

				

				DELETE #Kosorat
				INSERT INTO #Kosorat
				SELECT t.Factor,SUM(t.Bed) AS Mab FROM dbo.TR AS t
				INNER JOIN dbo.TblFactorAvamel AS fa ON fa.Id = t.IdAmel
				INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
				WHERE t.Type = @TypeFactor AND DateR BETWEEN @date1 AND @date2 AND t.Factor BETWEEN @factor1 AND @factor2 AND t.IdAnbr = 0 AND t.Tp1>0 AND Tashkhis BETWEEN @Tashkhis1 AND @Tashkhis2
				AND t.Bed>0 AND fa.Mashmol = 0 AND fa.State  = 1
				GROUP BY t.Factor
				OPTION  ( RECOMPILE );

				DELETE #SumMab
				INSERT INTO #SumMab
				SELECT Factor,SUM(Bes) FROM #maintr
				WHERE Mashmol = 0
				GROUP BY Factor
				OPTION  ( RECOMPILE );


				UPDATE #maintr SET Kasr =  CASE WHEN sumtr.mab>0 THEN ROUND((CAST(tr.Bes AS NUMERIC(30,15)) / sumtr.Mab) * kasr.Mab,0) ELSE 0 END   FROM #maintr AS tr
				INNER JOIN #SumMab AS sumtr ON tr.Factor = sumtr.Factor
				INNER JOIN #Kosorat AS kasr ON kasr.Factor = tr.Factor
				WHERE Mashmol = 0




			
				UPDATE #maintr SET Bes = Bes -Kasr,Takh = Takh + Kasr,Kasr = 0


			IF(@CalsWays = 1 AND @Moaff=0)
			BEGIN
				UPDATE #maintr SET Bed = ROUND(Bed/(1+ROUND(DarsadMashmol/100.0,2)),0)
				WHERE Mashmol = 1 AND DarsadMashmol>0 AND Bed>0

				UPDATE #maintr SET Bes = ROUND(Bes/(1+ROUND(DarsadMashmol/100.0,2)),0)
				WHERE Mashmol = 1 AND DarsadMashmol>0 AND Bes>0
			END


		IF OBJECT_ID('tempdb.dbo.#tr', 'U') IS NOT NULL
				DROP TABLE #tr;	
		 CREATE TABLE #tr
            (
			  Factor INT ,
             fee NUMERIC(23,8) ,
			  prdis BIGINT,
              dis BIGINT,
			  adis BIGINT,
			  DarsadMashmol NUMERIC(18,3),
			  Mashmol TINYINT,
			  IdAnbr INT,
			  Idkala INT,
			  Ted NUMERIC(20,5),
			  odam BIGINT,
			  olam BIGINT
            );

			

		
				INSERT INTO #tr
				SELECT Factor,
				dbo.Func_Tax_RoundFi((Bes+Takh)/TED) AS fee,
				CAST(FLOOR(dbo.Func_Tax_RoundFi((Bes+Takh)/TED) * TED) AS BIGINT) AS prdis,
				Takh AS dis,
				CAST(FLOOR(dbo.Func_Tax_RoundFi((Bes+Takh)/TED) * TED) AS BIGINT)-Takh AS adis,
				DarsadMashmol,
				Mashmol,
				IdAnbr,
				Idkala,
				TED,
				OtherTaxAmount AS odam,
				OtherFundsAmount AS olam
				 FROM #maintr
				WHERE   Bes>0
				OPTION  ( RECOMPILE );
		
		


        IF OBJECT_ID('tempdb.dbo.#t1', 'U') IS NOT NULL
				DROP TABLE #t1;	
		 CREATE TABLE #t1
            (
              Factor INT ,
              tprdis BIGINT ,
              tdis BIGINT ,
              tadis BIGINT ,
              tvam BIGINT,
			  todam BIGINT
            );
       

		
				 INSERT  INTO #t1
                SELECT  Factor ,
                        SUM(TR.prdis) AS tprdis ,
                        SUM(TR.dis) AS tdis ,
                        SUM(tr.adis) AS tadis ,
                        SUM(CAST(FLOOR(tr.adis * (DarsadMashmol*Mashmol) / 100.0) AS BIGINT)) AS tvam,
						SUM((tr.odam*tr.Ted)+(tr.olam*tr.Ted)) AS todam 
                FROM    #tr AS tr

                GROUP BY Factor
				OPTION  ( RECOMPILE );



      

		
        IF OBJECT_ID('tempdb.dbo.#t3', 'U') IS NOT NULL
				DROP TABLE #t3;	
		 CREATE TABLE #t3
            (
              Factor INT ,
              cap BIGINT
            );

		
			IF(@TypeTasviye = 0)
			BEGIN
				INSERT  INTO #t3
					SELECT  t.Factor ,
							SUM(Bed - Bes) AS cap
					FROM    dbo.TR AS t
							INNER JOIN dbo.TblParam AS p ON p.Srfsl = t.Srfsl
															AND p.Moin = t.Moin
							INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
					WHERE   t.Factor BETWEEN @factor1 AND @factor2 AND DateR BETWEEN @date1 AND @date2
							AND t.Type = @TypeFactor
							AND  IdAnbr = 0 AND Tp1 = 0 AND p.Cscod LIKE '101-101-101%'
					GROUP BY t.Factor
					OPTION  ( RECOMPILE );
			END
			ELSE IF(@TypeTasviye = 1)
			BEGIN
				INSERT  INTO #t3
					SELECT Factor,SUM(tadis+tvam) FROM #t1
					GROUP BY Factor
			END
			ELSE IF(@TypeTasviye = 2)
			BEGIN
				INSERT  INTO #t3
					SELECT Factor,0 FROM #t1
					GROUP BY Factor
			END 
		

	    IF OBJECT_ID('tempdb.dbo.#t4', 'U') IS NOT NULL
				DROP TABLE #t4;	
		 CREATE TABLE #t4
            (
              Factor INT ,
              Mande BIGINT
            );


			
				INSERT INTO #t4
				SELECT t.Factor,SUM(t.Bes-t.Bed) AS Mande FROM dbo.TR AS t
				INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
				WHERE   t.Factor BETWEEN @factor1 AND @factor2 AND DateR BETWEEN @date1 AND @date2
				AND t.Type = @TypeFactor
				AND (IdAnbr>0 OR t.Tp1>0)
				GROUP BY t.Factor
				OPTION  ( RECOMPILE );
			
	



	IF OBJECT_ID('tempdb.dbo.#tblSended', 'U') IS NOT NULL
				DROP TABLE #tblSended;	
		 CREATE TABLE #tblSended
            (
              Id INT 
            );


			IF OBJECT_ID('tempdb.dbo.#tblFactorSended', 'U') IS NOT NULL
				DROP TABLE #tblFactorSended;	
		 CREATE TABLE #tblFactorSended
            (
              Factor INT
            );



				IF OBJECT_ID('tempdb.dbo.#tblFactorSended2', 'U') IS NOT NULL
				DROP TABLE #tblFactorSended2;	
		 CREATE TABLE #tblFactorSended2
            (
              Factor INT
            );


	
	IF(@TypeSend = 0 OR @TypeSend = 10)
	BEGIN
		INSERT INTO #tblFactorSended
		SELECT fo.ShFactor FROM dbo.TblMiddelFactorTaxGov AS tax
		INNER JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		WHERE   
		fo.ShFactor BETWEEN @factor1 AND @factor2 
		AND fo.DateFactor BETWEEN @date1 AND @date2 
        AND fo.Type = @TypeFactor AND ((tax.StatusId IN ('IN_PROGRESS','SUCCESS','NOT_FOUND') AND tax.Cancel = 0) OR (tax.StatusId IN ('SUCCESS'))) AND tax.insId IN (1,2) 
		GROUP BY fo.ShFactor
		OPTION  ( RECOMPILE );

		INSERT INTO #tblFactorSended2
		SELECT fo.ShFactor FROM dbo.TblMiddelFactorTaxGov AS tax
		INNER JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		WHERE   
		fo.ShFactor BETWEEN @factor1 AND @factor2 
		AND fo.DateFactor BETWEEN @date1 AND @date2 
        AND fo.Type = @TypeFactor AND tax.StatusId IN ('IN_PROGRESS','SUCCESS','NOT_FOUND')  AND tax.Cancel = 0 AND tax.insId IN (1,2)
		GROUP BY fo.ShFactor
	END
	


	--صورت حساب های در حال ارسال
	IF(@TypeSend = 1)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.BuyerType,0) = @TypeCustom OR @TypeCustom =0 OR p.BuyerType IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'IN_PROGRESS' AND tax.insId IN (1,2,3) AND tax.Cancel = 0
		OPTION  ( RECOMPILE );
	END
	--صورت حساب های نامعلوم
	ELSE IF(@TypeSend = 2)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.BuyerType,0) = @TypeCustom OR @TypeCustom =0 OR p.BuyerType IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'NOT_FOUND' AND tax.insId IN (1,2,3) AND tax.Cancel = 0
		OPTION  ( RECOMPILE );
	END
