	--ارسال نشده
	IF(@TypeSend = 0)
	BEGIN
			SELECT 
		   CAST(0 AS bit) AS Selected,
		   '' AS EventName,
		   Res.ShFactor ,
		   Res.inno,
		   Res.StateFactor,
		   ISNULL(statename.Value,'') AS StateFactorName,
		   Res.insName,
		   Res.TaxId,
		   Res.DateFactor,
		   Res.CustumCod,
		   Res.CustomName,
		   Res.TarafHesab,
           Res.tins ,
