				ISNULL(tn.HSBName,'') AS TarafHesab,
                @codemeli AS tins ,
				@CodeShobe AS sbc,
                p.BuyerType AS tob ,
				case when isnull(fo.CodeMeli,'') = '' THEN p.codmeli
					 ELSE fo.CodeMeli
				END AS bid ,
				case when isnull(fo.CodeMeli,'') = '' then 
														CASE WHEN LEN(p.Cod_Egh) = 0 AND p.Type=0 AND LEN(p.codmeli)>0 THEN p.codmeli+'0001' 
														WHEN  p.Type=1 AND LEN(p.codmeli)>0 THEN p.codmeli 
														ELSE p.Cod_Egh 
														END
					 else fo.CodeMeli+'0001' 
				end AS tinb,
				case when isnull(fo.PostalCode,'') = '' then ISNULL(post.Tell,'')
					 ELSE fo.PostalCode
				END AS bpc,
				p.CodeShobe AS bbc,
                ISNULL(t1.tprdis,0) AS tprdis,
				ISNULL(t1.tdis,0) AS tdis,
				ISNULL(t1.tadis,0) AS tadis,
				CASE WHEN @Moaff=0 THEN ISNULL(t1.tvam,0) ELSE 0 END AS tvam,
				ISNULL(t1.todam,0) AS todam,
				ISNULL(t1.tadis,0) + (CASE WHEN @Moaff=0 THEN ISNULL(t1.tvam,0) ELSE 0 END) + ISNULL(t1.todam,0) AS tbill,
				ISNULL(t4.Mande,0) AS Mande,
				CASE WHEN ISNULL(t3.cap,0) - ISNULL(t1.tvam,0)<0 THEN 0 ELSE CASE WHEN (ISNULL(t3.cap,0) - ISNULL(t1.tvam,0))>ISNULL(t1.tadis,0) THEN ISNULL(t1.tadis,0) ELSE ISNULL(t3.cap,0) - ISNULL(t1.tvam,0) end END AS cap,
				ISNULL(t1.tadis,0) - (CASE WHEN ISNULL(t3.cap,0) - ISNULL(t1.tvam,0)<0 THEN 0 ELSE CASE WHEN (ISNULL(t3.cap,0) - ISNULL(t1.tvam,0))>ISNULL(t1.tadis,0) THEN ISNULL(t1.tadis,0) ELSE ISNULL(t3.cap,0) - ISNULL(t1.tvam,0) end END) AS insp,
				0 AS Savedsetm,
				'' AS SavedsetmName,
				'' AS ReferenceNumber,
				fo.DateFactor AS SavedDateFactor,
				0 AS insId,
				0 AS UniqIdRow,
				'' AS JsonCode,
				fo.IrTaxId AS IrTaxid,
				 '' AS intyId,
				'' AS intyName,
				'' AS inpId,
				'' AS inpName,
				'' AS CreateTime,
				'' AS LastInquiryDate,
				'' AS SerialNumber
        FROM    dbo.TblFactorOnvan AS fo
				INNER JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				INNER JOIN #FactorTasvie AS ft ON ft.Factor = fo.ShFactor AND ft.Type = fo.Type
				LEFT JOIN #t1 AS t1 ON t1.Factor = fo.ShFactor
				LEFT JOIN dbo.Func_PersonTell(6) AS post ON post.ShOzviat = fo.CustumCod
				LEFT JOIN #t3 AS t3 ON t3.Factor = fo.ShFactor
				LEFT JOIN #t4 AS t4 ON t4.Factor = fo.ShFactor
				LEFT JOIN #tblFactorSended AS md ON md.Factor = fo.ShFactor
				LEFT JOIN #TasviyeName AS tn ON tn.Factor = fo.ShFactor AND tn.Type = fo.Type

           WHERE   fo.ShFactor BETWEEN @factor1 AND @factor2 AND fo.DateFactor BETWEEN @date1 AND @date2
                AND fo.Type = @TypeFactor AND ISNULL(md.Factor,0) = 0) AS Res
				LEFT JOIN dbo.TblInfoTax AS tobname ON tobname.Id = Res.tob AND tobname.TpId = 5
				LEFT JOIN dbo.TblInfoTax AS setmName ON setmName.Id = CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AND setmName.TpId = 4
				LEFT JOIN dbo.TblInfoTax AS statename ON statename.Id = Res.StateFactor AND statename.TpId = 7
				WHERE Res.tbill > 0
				ORDER BY Res.ShFactor
				OPTION  ( RECOMPILE );
		END
