		Res.LastInquiryDate,
		Res.SerialNumber
		FROM (
    SELECT  tax.FactorId AS ShFactor  ,
			CAST(ISNULL(tax.inno, tax.RandomSerial) AS NVARCHAR(100)) AS inno ,
			ISNULL(fo.StateFactor,0) AS StateFactor,
			ISNULL(insName.Value,'') AS insName,
			tax.TaxId,
			tax.SavedDateFactor AS DateFactor,
			CASE WHEN ISNULL(tax.PersonId,0)>0 THEN ISNULL(tax.PersonId,0) ELSE fo.CustumCod END AS CustumCod,
			ISNULL(tn.HSBName,'') AS TarafHesab,
			CASE WHEN  LEN(ISNULL(tax.PersonName,''))>0 THEN ISNULL(tax.PersonName,'') COLLATE DATABASE_DEFAULT ELSE ISNULL(p.Name +' '+p.Famil,'') COLLATE DATABASE_DEFAULT END AS CustomName,
            CASE WHEN LEN(ISNULL(tax.tins,''))>0 THEN ISNULL(tax.tins,'') ELSE @codemeli END  AS tins ,
			CASE WHEN LEN(ISNULL(tax.sbc,''))>0 THEN ISNULL(tax.sbc,'') ELSE @CodeShobe END AS sbc,
            CASE WHEN ISNULL(tax.tob,0)>0 THEN ISNULL(tax.tob,0) ELSE p.BuyerType END  AS tob ,
            CASE WHEN  LEN(ISNULL(tax.bid,''))>0 THEN ISNULL(tax.bid,'') COLLATE DATABASE_DEFAULT ELSE p.codmeli COLLATE DATABASE_DEFAULT END  AS bid ,
            CASE WHEN  LEN(ISNULL(tax.tinb,''))>0 THEN ISNULL(tax.tinb,'') COLLATE DATABASE_DEFAULT ELSE p.Cod_Egh COLLATE DATABASE_DEFAULT END   AS tinb ,
			CASE WHEN  LEN(ISNULL(tax.bpc,''))>0 THEN ISNULL(tax.bpc,'') COLLATE DATABASE_DEFAULT ELSE ISNULL(post.Tell,'') COLLATE DATABASE_DEFAULT END  AS bpc,
			CASE WHEN  LEN(ISNULL(tax.bbc,''))>0 THEN ISNULL(tax.bbc,'') COLLATE DATABASE_DEFAULT ELSE p.CodeShobe COLLATE DATABASE_DEFAULT END  AS bbc,
            ISNULL(t1.tprdis,0) AS tprdis,
