			ISNULL(t1.tadis,0) + (CASE WHEN @Moaff=0 THEN ISNULL(t1.tvam,0) ELSE 0 END) + ISNULL(t1.todam,0) AS tbill,
			ISNULL(t4.Mande,0) AS Mande,
			CASE WHEN ISNULL(t3.cap,0) - ISNULL(t1.tvam,0)<0 THEN 0 ELSE CASE WHEN (ISNULL(t3.cap,0) - ISNULL(t1.tvam,0))>ISNULL(t1.tadis,0) THEN ISNULL(t1.tadis,0) ELSE ISNULL(t3.cap,0) - ISNULL(t1.tvam,0) end END AS cap,
			ISNULL(t1.tadis,0) - (CASE WHEN ISNULL(t3.cap,0) - ISNULL(t1.tvam,0)<0 THEN 0 ELSE CASE WHEN (ISNULL(t3.cap,0) - ISNULL(t1.tvam,0))>ISNULL(t1.tadis,0) THEN ISNULL(t1.tadis,0) ELSE ISNULL(t3.cap,0) - ISNULL(t1.tvam,0) end END) AS insp,
			ISNULL(tax.setm,0) AS Savedsetm,
			ISNULL(SavedsetmName.Value,'') AS SavedsetmName,
			tax.ReferenceNumber AS ReferenceNumber,
			tax.SavedDateFactor,
			ISNULL(tax.insId,0) AS insId,
			tax.Id AS UniqIdRow,
			tax.JsonCode,
			tax.IrTaxid,
			ISNULL(tax.intyId,0) AS intyId,
			ISNULL(intyName.Value,'') AS intyName,
			ISNULL(tax.inpId,0) AS inpId,
			ISNULL(inpName.Value,'') AS inpName,
			ISNULL(tax.CreateTime,'') AS CreateTime,
			ISNULL(tax.LastInquiryDate,'') AS LastInquiryDate,
			ISNULL(tax.SerialNumber,'') AS SerialNumber
              
    FROM    dbo.TblMiddelFactorTaxGov AS tax
			INNER JOIN #tblSended AS ts ON ts.Id = tax.Id
			LEFT JOIN dbo.TblFactorOnvan AS fo ON tax.FactorId = fo.ShFactor AND tax.FactorType = fo.Type
			LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
			LEFT JOIN #t1 AS t1 ON t1.Factor = fo.ShFactor
			LEFT JOIN #t3 AS t3 ON t3.Factor = fo.ShFactor
			LEFT JOIN #t4 AS t4 ON t4.Factor = fo.ShFactor
			LEFT JOIN dbo.TblInfoTax AS insName ON insName.Id = tax.insId AND insName.TpId = 1
			LEFT JOIN dbo.TblInfoTax AS intyName ON intyName.Id = tax.intyId AND intyName.TpId = 2
			LEFT JOIN dbo.TblInfoTax AS inpName ON inpName.Id = tax.inpId AND inpName.TpId = 3
			LEFT JOIN dbo.TblInfoTax AS SavedsetmName ON SavedsetmName.Id = tax.setm AND SavedsetmName.TpId = 4
			LEFT JOIN dbo.Func_PersonTell(6) AS post ON post.ShOzviat = fo.CustumCod
			LEFT JOIN #TasviyeName AS tn ON tn.Factor = fo.ShFactor AND tn.Type = fo.Type
			) AS Res
			LEFT JOIN dbo.TblInfoTax AS tobname ON tobname.Id = Res.tob AND tobname.TpId = 5
			LEFT JOIN dbo.TblInfoTax AS setmName ON setmName.Id = CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AND setmName.TpId = 4
			LEFT JOIN dbo.TblInfoTax AS statename ON statename.Id = Res.StateFactor AND statename.TpId = 7
			ORDER BY Res.ShFactor
			OPTION  ( RECOMPILE );
	END
		
    END;


GO

-- Procedure: [dbo].[RptListFactor_WorkbookTax]
IF OBJECT_ID(N'[dbo].[RptListFactor_WorkbookTax]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptListFactor_WorkbookTax] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptListFactor_WorkbookTax]
   @Period VARCHAR(100)
AS
    BEGIN
		SELECT tax.TaxId ,
               tax.Inty ,
               tax.Inp ,
               tax.Ins ,
               tax.StateBill ,
               tax.DateBill ,
			       tax.tinb ,
              tax.Bill-tax.tax AS tadis,
			   tax.tax ,
			tax.Bill ,
               tax.CustomerName ,
               tax.tob ,
               tax.setm ,
               tax.IrTaxId,
			   ISNULL(md.FactorId,0) AS FactorId,
			   ISNULL(md.FactorType,0) AS FactorType,
			   ISNULL(tp.Name,'') AS FactorTypeName,
			   ISNULL(fo.DateFactor,'') AS DateFactor,
			   ISNULL(p.Name + ' '+p.Famil,'') AS PersonName,
			   CAST(0 AS BIGINT) AS  Mab,
			   CAST(0 AS BIGINT) AS  MabMaliat,
			   CAST(0 AS BIGINT) AS MabKol,
			   ISNULL(md.StatusId,'') AS StatusId,
			   ISNULL(CancelName.Value, '') AS CancelName 
			   FROM dbo.TblWorkbookTax AS tax
			   LEFT JOIN dbo.TblMiddelFactorTaxGov AS md ON md.TaxId = tax.TaxId AND md.Flag = 0
			   LEFT JOIN dbo.TblInfoTax AS CancelName ON CancelName.Id = md.Cancel AND CancelName.TpId = 6
			   LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = ISNULL(md.FactorId,0) AND fo.Type = ISNULL(md.FactorType,0)
			   LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
			   LEFT JOIN dbo.TblTypeTR AS tp ON tp.ID = ISNULL(md.FactorType,0)
		WHERE period = @Period AND NOT(tax.StateBill = N'باطل شده' OR tax.Ins = N'ابطالی')
		ORDER BY md.TaxId
    END;


















GO

-- Procedure: [dbo].[RptListFactorBak_TaxGov]
IF OBJECT_ID(N'[dbo].[RptListFactorBak_TaxGov]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptListFactorBak_TaxGov] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptListFactorBak_TaxGov] 
    @factor1 INT ,
    @factor2 INT ,
    @date1 NVARCHAR(10) ,
    @date2 NVARCHAR(10),
	@TypeSend INT,
	@Tashkhis1 INT,
	@Tashkhis2 INT,
	@SRF1 INT,
	@SRF2 INT,
	@TypeTasviye INT,
	@FactorTasviye BIT,
	@CusomerID VARCHAR(MAX),
	@TypeCustom TINYINT,
	@StateFactor INT,
	@UserGroups NVARCHAR(MAX) = '',
	@Anbar1 INT,
	@Anbar2 INT
AS
    BEGIN
			DECLARE @TypeFactor INT = 104

		


	
		 DECLARE @UserIds NVARCHAR(MAX) = '';
        SELECT  @UserIds = @UserIds + ISNULL(CAST(UserId AS NVARCHAR(100)), '')
                + ','
        FROM    dbo.TblGroupUsers
        WHERE   GroupId IN ( SELECT *
                             FROM   dbo.CSVToTable(@UserGroups) );

		SET @TypeCustom = CASE WHEN @TypeCustom = 1 THEN 0 WHEN @TypeCustom = 2 THEN 1 WHEN @TypeCustom = 3 THEN 5 WHEN @TypeCustom = 4 THEN 6 ELSE NULL END

	
		IF(@factor1 = 0 AND @factor2 = 0)
		BEGIN
		    SET @factor1 = 1
			SET @factor2 =999999999
		END
		IF(@Tashkhis1 = 0 AND @Tashkhis2 = 0)
		BEGIN
		    SET @Tashkhis1 = 0
			SET @Tashkhis2 =99999
		END

		IF(@SRF1 = 0 AND @SRF2 = 0)
		BEGIN
		    SET @SRF1 = 0
			SET @SRF2 =99999
		END

			IF(@Anbar1 = 0 AND @Anbar2 = 0)
		BEGIN
		    SET @Anbar1 = 0
			SET @Anbar2 =99999
		END



		IF OBJECT_ID('#TblIrTaxId', 'U') IS NOT NULL
				DROP TABLE #TblIrTaxId;	
		 CREATE TABLE #TblIrTaxId
            (
			  Factor INT,
			  TypeFactor INT,
			  SaleFactor INT,
			  IrTaxid NVARCHAR(100)
            );
			INSERT INTO #TblIrTaxId
			SELECT Res.Factor,Res.Type,Res.SaleFactor AS SaleFactor,ISNULL(tm.TaxId,'') AS IrTaxid FROM (
			SELECT tbak.Factor,tbak.Type,MAX(tm.Id) AS Idtm,t.Factor AS SaleFactor FROM dbo.TR AS tbak
			INNER JOIN dbo.TR AS t ON tbak.Tolid_Id = t.Sodor
			LEFT JOIN dbo.TblMiddelFactorTaxGov AS tm ON tm.FactorId = t.Factor AND tm.FactorType = t.Type
			WHERE 
			tbak.Factor BETWEEN @factor1 AND @factor2
			AND tbak.DateR BETWEEN @date1 AND @date2
			AND tbak.Type = @TypeFactor 
			AND ISNULL(tm.StatusId,'SUCCESS') = 'SUCCESS' 
			AND ISNULL(tm.insId,1) IN (1,2) AND ISNULL(tm.Cancel,0) = 0
			AND ISNULL(tm.FactorType,203) = 203
			GROUP BY tbak.Factor,t.Factor,tbak.Type) AS Res
			LEFT JOIN dbo.TblMiddelFactorTaxGov AS tm ON tm.Id = Res.Idtm


			UPDATE dbo.TblFactorOnvan SET RefFactor = tax.SaleFactor FROM dbo.TblFactorOnvan AS fo
			INNER JOIN #TblIrTaxId AS tax ON tax.Factor = fo.ShFactor AND tax.TypeFactor = fo.Type
			WHERE Type = @TypeFactor AND ISNULL(RefFactor,0) = 0

			UPDATE dbo.TblFactorOnvan SET IrTaxId = tax.IrTaxid FROM dbo.TblFactorOnvan AS fo
			INNER JOIN #TblIrTaxId AS tax ON tax.Factor = fo.ShFactor AND tax.TypeFactor = fo.Type
			WHERE Type = @TypeFactor AND LEN(ISNULL(fo.IrTaxId,'')) = ''

       DECLARE @codemeli NVARCHAR(100)= N'',@CodeShobe VARCHAR(50) = '',@typeCompany INT = 0,@NoEbtalFactorToNoState BIT = 0

		SELECT @typeCompany = ISNULL(Value,0) FROM dbo.TblParameterTax
		WHERE Name = 'TypeCompany'

		SELECT @NoEbtalFactorToNoState = ISNULL(Value,0) FROM dbo.TblParameterTax
		WHERE Name = 'NoEbtalFactorToNoState'


		IF(@typeCompany = 0)
		BEGIN
			SELECT  @codemeli = codemeli,@CodeShobe = CodeShobe
			FROM    dbo.TblCompany
			WHERE   Id = 1;
		END
		ELSE
		BEGIN
			SELECT  @codemeli = CodeEghtesadi,@CodeShobe = CodeShobe
			FROM    dbo.TblCompany
			WHERE   Id = 1;
		END

		


		DECLARE @CalsWays BIT = 0
		SELECT @CalsWays = ISNULL(CalsWays,0) FROM dbo.TblSettingsTax

		
		


		IF OBJECT_ID('#FactorTasvie', 'U') IS NOT NULL
				DROP TABLE #FactorTasvie;	
		 CREATE TABLE #FactorTasvie
            (
			  Factor INT,
			  Type INT
            );
			IF(@FactorTasviye = 1)
			BEGIN
			    INSERT INTO #FactorTasvie
				SELECT
				Factor,
				t.Type
				FROM dbo.TR AS t
				LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = t.Factor AND fo.Type = t.Type
				LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				WHERE 
				t.Factor BETWEEN @factor1 AND @factor2
				AND t.DateR BETWEEN @date1 AND @date2
				AND t.Type = @TypeFactor 
				AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
				AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
				AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
				GROUP BY Factor,t.Type
				HAVING SUM(t.Bed-t.Bes) = 0
                
			END
			ELSE
			BEGIN
			    INSERT INTO #FactorTasvie
				SELECT
				Factor,
				t.Type
				FROM dbo.TR AS t 
				LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = t.Factor AND fo.Type = t.Type
				LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				WHERE 
				t.Factor BETWEEN @factor1 AND @factor2
				AND t.DateR BETWEEN @date1 AND @date2
				AND t.Type = @TypeFactor 
				AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
				AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
				AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
				GROUP BY Factor,t.Type
			END



			IF OBJECT_ID('tempdb.dbo.#maintr', 'U') IS NOT NULL
				DROP TABLE #maintr;	
		 CREATE TABLE #maintr
            (
			  Factor INT,
			  Type INT
			  )



			INSERT INTO #maintr
			SELECT
			 t.Factor,
			 t.Type
			 FROM dbo.TR AS t
			 INNER JOIN #FactorTasvie AS ft ON ft.Factor = t.Factor AND ft.Type = t.Type
			 WHERE t.Type = @TypeFactor AND DateR BETWEEN @date1 AND @date2 AND t.Factor BETWEEN @factor1 AND @factor2 AND (IdAnbr>0) AND Srfsl BETWEEN @SRF1 AND @SRF2 AND Tashkhis BETWEEN @Tashkhis1 AND @Tashkhis2 AND t.IdAnbr BETWEEN @Anbar1 AND @Anbar2
			 GROUP BY t.Factor,t.Type
		
		IF OBJECT_ID('tempdb.dbo.#tblSended', 'U') IS NOT NULL
				DROP TABLE #tblSended;	
		 CREATE TABLE #tblSended
            (
              Id INT 
            );



				IF OBJECT_ID('tempdb.dbo.#tblFactorSended', 'U') IS NOT NULL
				DROP TABLE #tblFactorSended;	
		 CREATE TABLE #tblFactorSended
            (
              Factor INT
            );


			
				IF OBJECT_ID('tempdb.dbo.#tblFactorSended2', 'U') IS NOT NULL
				DROP TABLE #tblFactorSended2;	
		 CREATE TABLE #tblFactorSended2
            (
              Factor INT
            );


	IF(@TypeSend = 0 OR @TypeSend = 10)
	BEGIN
		INSERT INTO #tblFactorSended
		SELECT fo.ShFactor FROM dbo.TblMiddelFactorTaxGov AS tax
		INNER JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		WHERE   
		fo.ShFactor BETWEEN @factor1 AND @factor2 
		AND fo.DateFactor BETWEEN @date1 AND @date2 
        AND fo.Type = @TypeFactor AND ((tax.StatusId IN ('IN_PROGRESS','SUCCESS','NOT_FOUND') AND tax.Cancel = 0) OR (tax.StatusId IN ('SUCCESS'))) AND tax.insId IN (4,2) 
		GROUP BY fo.ShFactor
		OPTION  ( RECOMPILE );

		INSERT INTO #tblFactorSended2
		SELECT fo.ShFactor FROM dbo.TblMiddelFactorTaxGov AS tax
		INNER JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		WHERE   
		fo.ShFactor BETWEEN @factor1 AND @factor2 
		AND fo.DateFactor BETWEEN @date1 AND @date2 
        AND fo.Type = @TypeFactor AND tax.StatusId IN ('IN_PROGRESS','SUCCESS','NOT_FOUND')  AND tax.Cancel = 0 AND tax.insId IN (4,2)
		GROUP BY fo.ShFactor
	END


	--صورت حساب های در حال ارسال
	IF(@TypeSend = 1)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'IN_PROGRESS' AND tax.insId IN (4,2,3) AND tax.Cancel = 0
	END
	--صورت حساب های نامعلوم
	ELSE IF(@TypeSend = 2)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'NOT_FOUND' AND tax.insId IN (4,2,3) AND tax.Cancel = 0
	END
	--صورت حساب های اصلی ارسال شده
	ELSE IF(@TypeSend = 3)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'SUCCESS' AND tax.insId IN (4) AND tax.Cancel = 0
	END

	
	--صورت حساب های ابطالی ارسال شده
	ELSE IF(@TypeSend = 4)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'SUCCESS' AND tax.insId IN (3) AND tax.Cancel = 0
	END
	--صورت حساب های اصلاحی ارسال شده
	ELSE IF(@TypeSend = 5)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'SUCCESS' AND tax.insId IN (2) AND tax.Cancel = 0
	END
	--صورت حساب های ابطال شده
	ELSE IF(@TypeSend = 6)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'SUCCESS' AND tax.insId IN (4,2,3) AND tax.Cancel = 1
	END
	--صورت حساب های ابطال شده در حال ارسال
	ELSE IF(@TypeSend = 7)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'IN_PROGRESS' AND tax.insId IN (4,2,3) AND tax.Cancel = 1
	END
	--صورت حساب های ابطال شده نامعلوم
	ELSE IF(@TypeSend = 8)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'NOT_FOUND' AND tax.insId IN (4,2,3) AND tax.Cancel = 1
	END
	--صورت حساب های خطا داده
	ELSE IF(@TypeSend = 9)
	BEGIN
		INSERT INTO #tblSended
		SELECT tax.Id FROM dbo.TblMiddelFactorTaxGov AS tax
		LEFT JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tax.FactorId AND fo.Type = tax.FactorType
		LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = tax.PersonId
		WHERE   
		tax.FactorId BETWEEN @factor1 AND @factor2 
		AND ISNULL(fo.DateFactor,tax.SavedDateFactor) BETWEEN @date1 AND @date2 
		AND (ISNULL(fo.CustumCod,0) IN (SELECT * FROM dbo.CSVToTable(@CusomerID)) OR @CusomerID='')
		AND (ISNULL(p.Type,0) = @TypeCustom OR @TypeCustom IS NULL)
		AND (ISNULL(fo.UserIDAdd,0) IN (SELECT * FROM dbo.CSVToTable(@UserIds)) OR @UserGroups = '')
        AND tax.FactorType = @TypeFactor AND tax.StatusId = 'FAILED' AND tax.insId IN (4,2,3) AND tax.Cancel = 1
	END

	IF(@TypeSend = 0)
	BEGIN
	SELECT  
		  CAST(0 AS bit) AS Selected,
		   '' AS EventName,
		   Res.ShFactor,
			Res.RefFactor,
		   Res.RefFactorYear,
		   Res.inno,
		   Res.StateFactor,
		   ISNULL(statename.Value,'') AS StateFactorName,
		   Res.insName,
		   Res.TaxId,
		   Res.IrTaxid,
		   Res.DateFactor,
		   Res.CustumCod,
		   Res.CustomName,
           Res.tins ,
           Res.sbc,
           Res.tob ,
		   ISNULL(tobname.Value,'') AS tobName,
           Res.bid ,
           Res.tinb ,
		   Res.bpc,
		   Res.bbc,
           Res.tprdis ,
           Res.tdis ,
           Res.tadis ,
           Res.tvam ,
		    Res.todam,
           Res.tbill ,
		   Res.Mande,
		   CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AS setm,
		   ISNULL(setmName.Value,'') AS setmName,
		   Res.cap ,
           Res.insp,
		   Res.Savedsetm,
		   Res.SavedsetmName,
		   Res.ReferenceNumber,
		   Res.SavedDateFactor,
		   Res.insId,
		   Res.UniqIdRow,
		   Res.JsonCode,
		 
		   Res.intyId,
		   Res.intyName,
		   Res.inpId,
		   Res.inpName,
		   Res.CreateTime,
		   Res.LastInquiryDate,
		   Res.SerialNumber,
		   Res.MergFactor
		    FROM (
        SELECT  fo.ShFactor ,
				'' AS inno ,
				fo.StateFactor AS StateFactor,
				'' AS insName,
				'' AS TaxId,
				fo.DateFactor,
				fo.CustumCod,
				ISNULL(p.Name +' '+p.Famil,'') AS CustomName,
                @codemeli AS tins ,
				@CodeShobe AS sbc,
                p.BuyerType AS tob ,
                p.codmeli AS bid ,
				CASE WHEN LEN(p.Cod_Egh) = 0 AND p.Type=0 AND LEN(p.codmeli)>0 THEN p.codmeli+'0001' WHEN  p.Type=1 AND LEN(p.codmeli)>0 THEN p.codmeli ELSE p.Cod_Egh END AS tinb,
				ISNULL(post.Tell,'') AS bpc,
				p.CodeShobe AS bbc,
				 CAST(0 AS BIGINT) AS tprdis,
				CAST(0 AS BIGINT) AS tdis,
				CAST(0 AS BIGINT) AS tadis,
				CAST(0 AS BIGINT) AS tvam,
				CAST(0 AS BIGINT) AS todam,
				CAST(0 AS BIGINT) AS tbill,
				CAST(0 AS BIGINT) AS Mande,
				CAST(0 AS BIGINT) AS cap,
				CAST(0 AS BIGINT) AS insp,
				CAST(0 AS BIGINT) AS setm,
				'' AS setmName,
				CAST(0 AS BIGINT) AS Savedsetm,
				'' AS SavedsetmName,
				'' AS ReferenceNumber,
				0 AS RandomSerial,
				fo.DateFactor AS SavedDateFactor,
				0 AS insId,
				0 AS UniqIdRow,
				'' AS JsonCode,
				ISNULL(fo.RefFactor,0) AS RefFactor,
				ISNULL(fo.RefFactorYear,0) AS RefFactorYear,
				ISNULL(fo.IrTaxId,'') AS IrTaxId,
				'' AS intyId,
				'' AS intyName,
				'' AS inpId,
				'' AS inpName,
				'' AS CreateTime,
				'' AS LastInquiryDate,
				'' AS SerialNumber,
				dbo.Func_Tax_ListDetailMergFactor(fo.ShFactor,0,ISNULL(fo.RefFactor,0)) AS MergFactor
        FROM    dbo.TblFactorOnvan AS fo
				INNER JOIN #FactorTasvie AS ft ON fo.ShFactor = ft.Factor AND fo.Type = ft.Type
				INNER JOIN #maintr AS mt ON fo.ShFactor = mt.Factor AND fo.Type = mt.Type
				INNER JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				LEFT JOIN dbo.Func_PersonTell(6) AS post ON post.ShOzviat = fo.CustumCod
				LEFT JOIN #tblFactorSended AS md ON md.Factor = fo.ShFactor
				

            WHERE   fo.ShFactor BETWEEN @factor1 AND @factor2 AND fo.DateFactor BETWEEN @date1 AND @date2
                AND fo.Type = @TypeFactor AND ISNULL(md.Factor,0) = 0) AS Res
				LEFT JOIN dbo.TblInfoTax AS tobname ON tobname.Id = Res.tob AND tobname.TpId = 5
				LEFT JOIN dbo.TblInfoTax AS setmName ON setmName.Id = CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AND setmName.TpId = 4
				LEFT JOIN dbo.TblInfoTax AS statename ON statename.Id = Res.StateFactor AND statename.TpId = 7
				ORDER BY Res.ShFactor
		
		
		END
	ELSE IF (@TypeSend = 10)
	BEGIN
	SELECT  
		  CAST(0 AS bit) AS Selected,
		   '' AS EventName,
		   Res.ShFactor,
			Res.RefFactor,
		   Res.RefFactorYear,
		   Res.inno,
		   Res.StateFactor,
		   ISNULL(statename.Value,'') AS StateFactorName,
		   Res.insName,
		   Res.TaxId,
		   Res.IrTaxid,
		   Res.DateFactor,
		   Res.CustumCod,
		   Res.CustomName,
           Res.tins ,
           Res.sbc,
           Res.tob ,
		   ISNULL(tobname.Value,'') AS tobName,
           Res.bid ,
           Res.tinb ,
		   Res.bpc,
		   Res.bbc,
           Res.tprdis ,
           Res.tdis ,
           Res.tadis ,
           Res.tvam ,
		    Res.todam,
           Res.tbill ,
		   Res.Mande,
		   CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AS setm,
		   ISNULL(setmName.Value,'') AS setmName,
		   Res.cap ,
           Res.insp,
		   Res.Savedsetm,
		   Res.SavedsetmName,
		   Res.ReferenceNumber,
		   Res.SavedDateFactor,
		   Res.insId,
		   Res.UniqIdRow,
		   Res.JsonCode,
		 
		   Res.intyId,
		   Res.intyName,
		   Res.inpId,
		   Res.inpName,
		   Res.CreateTime,
		   Res.LastInquiryDate,
		   Res.SerialNumber,
		   Res.MergFactor
		    FROM (
        SELECT  fo.ShFactor ,
				'' AS inno ,
				fo.StateFactor AS StateFactor,
				'' AS insName,
				'' AS TaxId,
				fo.DateFactor,
				fo.CustumCod,
				ISNULL(p.Name +' '+p.Famil,'') AS CustomName,
                @codemeli AS tins ,
				@CodeShobe AS sbc,
                p.BuyerType AS tob ,
                p.codmeli AS bid ,
				CASE WHEN LEN(p.Cod_Egh) = 0 AND p.Type=0 AND LEN(p.codmeli)>0 THEN p.codmeli+'0001' WHEN  p.Type=1 AND LEN(p.codmeli)>0 THEN p.codmeli ELSE p.Cod_Egh END AS tinb,
				ISNULL(post.Tell,'') AS bpc,
				p.CodeShobe AS bbc,
				 CAST(0 AS BIGINT) AS tprdis,
				CAST(0 AS BIGINT) AS tdis,
				CAST(0 AS BIGINT) AS tadis,
				CAST(0 AS BIGINT) AS tvam,
				CAST(0 AS BIGINT) AS todam,
				CAST(0 AS BIGINT) AS tbill,
				CAST(0 AS BIGINT) AS Mande,
				CAST(0 AS BIGINT) AS cap,
				CAST(0 AS BIGINT) AS insp,
				CAST(0 AS BIGINT) AS setm,
				'' AS setmName,
				CAST(0 AS BIGINT) AS Savedsetm,
				'' AS SavedsetmName,
				'' AS ReferenceNumber,
				0 AS RandomSerial,
				fo.DateFactor AS SavedDateFactor,
				0 AS insId,
				0 AS UniqIdRow,
				'' AS JsonCode,
				ISNULL(fo.RefFactor,0) AS RefFactor,
				ISNULL(fo.RefFactorYear,0) AS RefFactorYear,
				ISNULL(fo.IrTaxId,'') AS IrTaxId,
				'' AS intyId,
				'' AS intyName,
				'' AS inpId,
				'' AS inpName,
				'' AS CreateTime,
				'' AS LastInquiryDate,
				'' AS SerialNumber,
				dbo.Func_Tax_ListDetailMergFactor(fo.ShFactor,0,ISNULL(fo.RefFactor,0)) AS MergFactor
        FROM    dbo.TblFactorOnvan AS fo
				INNER JOIN #FactorTasvie AS ft ON fo.ShFactor = ft.Factor AND fo.Type = ft.Type
				INNER JOIN #maintr AS mt ON fo.ShFactor = mt.Factor AND fo.Type = mt.Type
				INNER JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				LEFT JOIN dbo.Func_PersonTell(6) AS post ON post.ShOzviat = fo.CustumCod
				INNER JOIN #tblFactorSended AS md ON md.Factor = fo.ShFactor
				LEFT JOIN #tblFactorSended2 AS md2 ON md2.Factor = fo.ShFactor
				

            WHERE   fo.ShFactor BETWEEN @factor1 AND @factor2 AND fo.DateFactor BETWEEN @date1 AND @date2
                AND fo.Type = @TypeFactor AND ISNULL(md2.Factor,0) = 0) AS Res
				LEFT JOIN dbo.TblInfoTax AS tobname ON tobname.Id = Res.tob AND tobname.TpId = 5
				LEFT JOIN dbo.TblInfoTax AS setmName ON setmName.Id = CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AND setmName.TpId = 4
				LEFT JOIN dbo.TblInfoTax AS statename ON statename.Id = Res.StateFactor AND statename.TpId = 7
				ORDER BY Res.ShFactor
		
		
		END
		ELSE
		BEGIN
		   SELECT 
		   CAST(0 AS bit) AS Selected,
		   '' AS EventName,
		   Res.ShFactor ,
		   Res.RefFactor,
		   Res.RefFactorYear,
		   Res.inno,
		   Res.StateFactor,
		   ISNULL(statename.Value,'') AS StateFactorName,
		   Res.insName,
		   Res.TaxId,
		   Res.DateFactor,
		   Res.CustumCod,
		   Res.CustomName,
           Res.tins ,
           Res.sbc,
           Res.tob ,
		   ISNULL(tobname.Value,'') AS tobName,
           Res.bid ,
           Res.tinb ,
		   Res.bpc,
		   Res.bbc,
           Res.tprdis ,
           Res.tdis ,
           Res.tadis ,
           Res.tvam ,
		   Res.todam,
           Res.tbill ,
		   Res.Mande,
		   CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AS setm,
		   ISNULL(setmName.Value,'') AS setmName,
		   Res.cap ,
           Res.insp,
		   Res.Savedsetm,
		   Res.SavedsetmName,
		   Res.ReferenceNumber,
		   Res.SavedDateFactor,
		   Res.insId,
		   Res.UniqIdRow,
		   Res.JsonCode,
		   Res.IrTaxid,
		   Res.intyId,
		   Res.intyName,
		   Res.inpId,
		   Res.inpName,
		   Res.CreateTime,
		   Res.LastInquiryDate,
		   Res.SerialNumber,
		   0 AS MergFactor
		   FROM (
        SELECT  tax.FactorId AS ShFactor  ,
				CAST(ISNULL(tax.inno, tax.RandomSerial) AS NVARCHAR(100)) AS inno ,
				ISNULL(fo.StateFactor,0) AS StateFactor,
				ISNULL(insName.Value,'') AS insName,
				tax.TaxId,
				tax.SavedDateFactor AS DateFactor,
				CASE WHEN ISNULL(tax.PersonId,0)>0 THEN ISNULL(tax.PersonId,0) ELSE fo.CustumCod END AS CustumCod,
				CASE WHEN  LEN(ISNULL(tax.PersonName,''))>0 THEN ISNULL(tax.PersonName,'') COLLATE DATABASE_DEFAULT ELSE ISNULL(p.Name +' '+p.Famil,'') COLLATE DATABASE_DEFAULT END AS CustomName,
                CASE WHEN LEN(ISNULL(tax.tins,''))>0 THEN ISNULL(tax.tins,'') ELSE @codemeli END  AS tins ,
				CASE WHEN LEN(ISNULL(tax.sbc,''))>0 THEN ISNULL(tax.sbc,'') ELSE @CodeShobe END AS sbc,
                CASE WHEN ISNULL(tax.tob,0)>0 THEN ISNULL(tax.tob,0) ELSE p.BuyerType END AS tob ,
                CASE WHEN  LEN(ISNULL(tax.bid,''))>0 THEN ISNULL(tax.bid,'') COLLATE DATABASE_DEFAULT ELSE p.codmeli COLLATE DATABASE_DEFAULT END  AS bid ,
                CASE WHEN  LEN(ISNULL(tax.tinb,''))>0 THEN ISNULL(tax.tinb,'') COLLATE DATABASE_DEFAULT ELSE p.Cod_Egh COLLATE DATABASE_DEFAULT END   AS tinb ,
				CASE WHEN  LEN(ISNULL(tax.bpc,''))>0 THEN ISNULL(tax.bpc,'') COLLATE DATABASE_DEFAULT ELSE ISNULL(post.Tell,'') COLLATE DATABASE_DEFAULT END  AS bpc,
				CASE WHEN  LEN(ISNULL(tax.bbc,''))>0 THEN ISNULL(tax.bbc,'') COLLATE DATABASE_DEFAULT ELSE p.CodeShobe COLLATE DATABASE_DEFAULT END  AS bbc,
               CAST(0 AS BIGINT) AS tprdis,
				CAST(0 AS BIGINT) AS tdis,
				CAST(0 AS BIGINT) AS tadis,
				CAST(0 AS BIGINT) AS tvam,
				CAST(0 AS BIGINT) AS todam,
				CAST(0 AS BIGINT) AS tbill,
				CAST(0 AS BIGINT) AS Mande,
				CAST(0 AS BIGINT) AS cap,
				CAST(0 AS BIGINT) AS insp,
				ISNULL(tax.setm,0) AS Savedsetm,
				ISNULL(SavedsetmName.Value,'') AS SavedsetmName,
				tax.ReferenceNumber AS ReferenceNumber,
				tax.SavedDateFactor,
				ISNULL(tax.insId,0) AS insId,
				tax.Id AS UniqIdRow,
				tax.JsonCode,
				tax.RefFactor,
				tax.RefFactorYear,
				tax.IrTaxId,
				ISNULL(tax.intyId,0) AS intyId,
				ISNULL(intyName.Value,'') AS intyName,
				ISNULL(tax.inpId,0) AS inpId,
				ISNULL(inpName.Value,'') AS inpName,
				ISNULL(tax.CreateTime,'') AS CreateTime,
				ISNULL(tax.LastInquiryDate,'') AS LastInquiryDate,
				ISNULL(tax.SerialNumber,'') AS SerialNumber
              
        FROM    dbo.TblMiddelFactorTaxGov AS tax
				INNER JOIN #tblSended AS ts ON ts.Id = tax.Id
				LEFT JOIN dbo.TblFactorOnvan AS fo ON tax.FactorId = fo.ShFactor AND tax.FactorType = fo.Type
				LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = fo.CustumCod
				LEFT JOIN dbo.TblInfoTax AS insName ON insName.Id = tax.insId AND insName.TpId = 1
				LEFT JOIN dbo.TblInfoTax AS intyName ON intyName.Id = tax.intyId AND intyName.TpId = 2
				LEFT JOIN dbo.TblInfoTax AS inpName ON inpName.Id = tax.inpId AND inpName.TpId = 3
				LEFT JOIN dbo.TblInfoTax AS SavedsetmName ON SavedsetmName.Id = tax.setm AND SavedsetmName.TpId = 4
				LEFT JOIN dbo.Func_PersonTell(6) AS post ON post.ShOzviat = fo.CustumCod
				) AS Res
				LEFT JOIN dbo.TblInfoTax AS tobname ON tobname.Id = Res.tob AND tobname.TpId = 5
				LEFT JOIN dbo.TblInfoTax AS setmName ON setmName.Id = CASE WHEN Res.cap>0 AND Res.insp>0 THEN 3 WHEN Res.insp>0 THEN 2 ELSE 1 END AND setmName.TpId = 4
				LEFT JOIN dbo.TblInfoTax AS statename ON statename.Id = Res.StateFactor AND statename.TpId = 7
				ORDER BY Res.ShFactor
		END
		
    END;















GO

-- Procedure: [dbo].[RptRizekala_Tafkik]
IF OBJECT_ID(N'[dbo].[RptRizekala_Tafkik]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptRizekala_Tafkik] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptRizekala_Tafkik]
    @idkalas NVARCHAR(MAX),
    @Code VARCHAR(500),
    @dtkala DtKala READONLY,
    @Supplier INT = 0
AS
BEGIN
    IF OBJECT_ID('tempdb.dbo.##tblIdkala', 'U') IS NOT NULL
		DROP TABLE ##tblIdkala;
	CREATE TABLE ##tblIdkala
	(
		IdKala INT
	);
	IF (@idkalas = '')
	BEGIN
		INSERT INTO ##tblIdkala
		SELECT k.IDKala
		FROM dbo.TblKala AS k
		WHERE (
				  k.Supplier = @Supplier
				  OR @Supplier = 0
			  )
		GROUP BY k.IDKala;
	END;
	ELSE
	BEGIN
		INSERT INTO ##tblIdkala
		SELECT k.IDKala
		FROM dbo.TblKala AS k
			INNER JOIN dbo.CSVToTable(@idkalas) AS tblkala
				ON k.IDKala = tblkala.id
		WHERE (
				  k.Supplier = @Supplier
				  OR @Supplier = 0
			  )
		GROUP BY k.IDKala;
	END;



	DECLARE @ck INT = 0;
	IF OBJECT_ID('tempdb.dbo.##dtkala', 'U') IS NOT NULL
		DROP TABLE ##dtkala;
	CREATE TABLE ##dtkala
	(
		IDAnbar INT NOT NULL,
		IDKala INT NOT NULL
	);
	SELECT @ck = COUNT(*)
	FROM @dtkala;
	IF (@ck > 0)
	BEGIN
		INSERT INTO ##dtkala
		SELECT IDAnbar,
			   dtkala.IDKala
		FROM @dtkala AS dtkala
			INNER JOIN ##tblIdkala AS t
				ON t.IdKala = dtkala.IDKala;
	END;
	ELSE
	BEGIN
		IF (LEN(@Code) > 0)
		BEGIN
			INSERT INTO ##dtkala
			SELECT IDAnbar,
				   k.IDKala
			FROM dbo.TblKala AS k
				INNER JOIN ##tblIdkala AS t
					ON t.IdKala = k.IDKala
			WHERE GroupCode LIKE @Code;
		END;
		ELSE
		BEGIN
			INSERT INTO ##dtkala
			SELECT IDAnbar,
				   k.IDKala
			FROM dbo.TblKala AS k
				INNER JOIN ##tblIdkala AS t
					ON t.IdKala = k.IDKala;
		END;
	END;



	IF OBJECT_ID('tempdb.dbo.#TRIn', 'U') IS NOT NULL
		DROP TABLE #TRIn;
	CREATE TABLE #TRIn
	(
		IdAnbar INT,
		Idkala INT,
		Td_in NUMERIC(30, 15),
		Td_Out NUMERIC(30, 15)
	);

	INSERT INTO #TRIn
	SELECT dbo.TR.IdAnbr,
		   TR.Idkala,
		   SUM(TED) AS Td_in,
		   CAST(0 AS NUMERIC(18, 3)) AS Td_Out
	FROM dbo.TR
	INNER JOIN ##dtkala AS dtkala
		ON dtkala.IDKala = TR.Idkala
			AND dtkala.IDAnbar = TR.IdAnbr
	WHERE TR.Type < 200
	GROUP BY dbo.TR.IdAnbr,
			 dbo.TR.Idkala
	UNION ALL
	SELECT dbo.TblTRAnbar.IDAnbar,
		   TblTRAnbar.IDKala,
		   SUM(Tedad) AS Td_in,
		   CAST(0 AS NUMERIC(18, 3)) AS Td_Out
	FROM dbo.TblTRAnbar
	INNER JOIN ##dtkala AS dtkala
		ON dtkala.IDKala = TblTRAnbar.IDKala
			AND dtkala.IDAnbar = TblTRAnbar.IDAnbar
	WHERE TblTRAnbar.Type < 200
	GROUP BY dbo.TblTRAnbar.IDAnbar,
			 dbo.TblTRAnbar.IDKala
	OPTION (RECOMPILE);



	IF OBJECT_ID('tempdb.dbo.#TROut', 'U') IS NOT NULL
		DROP TABLE #TROut;
	CREATE TABLE #TROut
	(
		IdAnbar INT,
		Idkala INT,
		Td_in NUMERIC(30, 15),
		Td_Out NUMERIC(30, 15)
	);

	INSERT INTO #TROut
	SELECT dbo.TR.IdAnbr,
		   TR.Idkala,
		   CAST(0 AS NUMERIC(18, 3)) AS Td_in,
		   SUM(TED) AS Td_Out
	FROM dbo.TR
	INNER JOIN ##dtkala AS dtkala
		ON dtkala.IDKala = TR.Idkala
			AND dtkala.IDAnbar = TR.IdAnbr
	WHERE TR.Type >= 200
	GROUP BY dbo.TR.IdAnbr,
			 dbo.TR.Idkala
	UNION ALL
	SELECT dbo.TblTRAnbar.IDAnbar,
		   TblTRAnbar.IDKala,
		   CAST(0 AS NUMERIC(18, 3)) AS Td_in,
		   SUM(Tedad) AS Td_Out
	FROM dbo.TblTRAnbar
	INNER JOIN ##dtkala AS dtkala
		ON dtkala.IDKala = TblTRAnbar.IDKala
			AND dtkala.IDAnbar = TblTRAnbar.IDAnbar
	WHERE TblTRAnbar.Type >= 200
	GROUP BY dbo.TblTRAnbar.IDAnbar,
			 dbo.TblTRAnbar.IDKala
	OPTION (RECOMPILE);

	IF OBJECT_ID('tempdb.dbo.#TR', 'U') IS NOT NULL
		DROP TABLE #TR;
	CREATE TABLE #TR
	(
		IdAnbar INT,
		Idkala INT,
		Name NVARCHAR(500),
		Mande NUMERIC(30, 15)
	);

	INSERT INTO #TR
	SELECT Res.IdAnbar,
		   Res.Idkala,
		   k.Name,
		   ISNULL(SUM(Res.Td_in) - SUM(Res.Td_Out), 0) AS Mande
	FROM
	(SELECT * FROM #TRIn 
	UNION ALL 
	SELECT * FROM #TROut) AS Res
	LEFT JOIN dbo.TblKala AS k
		ON k.IDAnbar = Res.IdAnbar
			AND k.IDKala = Res.Idkala
	GROUP BY Res.IdAnbar,
			 Res.Idkala,
			 k.Name;

	--SELECT k.IdKala,k.Name,k.IdAnbar,isnull(t.Mande,k.mande) as Mande FROM #TR as t
	--inner join TblKala as k on k.idanbar = t.idanbar and k.idkala = t.idkala

	DECLARE @Columns NVARCHAR(MAX),
			@Header NVARCHAR(MAX),
			@Query NVARCHAR(MAX);

	SELECT @Columns = ISNULL(@Columns + ',', '') + QUOTENAME(ID)
	FROM dbo.TblAnbar;

	SELECT @Header
		= ISNULL(@Header + ',', '') + N'ISNULL(' + QUOTENAME(ID) + N',0) as '
		  + QUOTENAME(CAST(REPLACE(Name, ' ', '_') AS VARCHAR(100)))
	FROM dbo.TblAnbar;

	SELECT @Query
		= N' 
	SELECT IdKala as [کد_کالا],Name as نام_کالا,' + @Header
		  + N' FROM ( 
	SELECT k.IdKala,k.Name,k.IdAnbar,isnull(t.Mande,k.mande) as Mande FROM #TR as t
	right join TblKala as k on k.idanbar = t.idanbar and k.idkala = t.idkala
	) AS T 
	PIVOT ( 
	SUM(Mande) FOR IdAnbar IN (' + @Columns + N') 
	) AS p 
	order by IdKala';
	EXEC sp_executesql @Query;

	
	DROP TABLE ##tblIdkala;
	DROP TABLE ##dtkala;
	DROP TABLE #TRIn;
	DROP TABLE #TROut;
	DROP TABLE #TR;

END





GO

-- Procedure: [dbo].[RptRizeKolMandePro]
IF OBJECT_ID(N'[dbo].[RptRizeKolMandePro]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptRizeKolMandePro] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptRizeKolMandePro]
@Srfsl1 INT,
@Srfsl2 INT,
@Moin1 INT ,
@Moin2 INT ,
@DateR NVARCHAR(500),
@Cshobe INT,
@City1 INT,
@City2 INT,
@PersonGroupid INT,
@PersonGroupid2 INT,
@PersonGroupid3 INT,
@PersonGroupid4 INT
AS
BEGIN
	
DECLARE @cshobe1 INT = @Cshobe,@cshobe2 INT = @Cshobe
IF(@Cshobe=0)
BEGIN
	SET @cshobe1 = 0
	SET @cshobe2 = 999999
END	


DECLARE @minPersonGroupid INT = @PersonGroupid,@maxPersonGroupid INT = @PersonGroupid
IF(@PersonGroupid=0)
BEGIN
	SET @minPersonGroupid = 0
	SET @maxPersonGroupid = 999999
END	

DECLARE @minPersonGroupid2 INT = @PersonGroupid2,@maxPersonGroupid2 INT = @PersonGroupid2
IF(@PersonGroupid2=0)
BEGIN
	SET @minPersonGroupid2 = 0
	SET @maxPersonGroupid2 = 999999
END	

DECLARE @minPersonGroupid3 INT = @PersonGroupid3,@maxPersonGroupid3 INT = @PersonGroupid3
IF(@PersonGroupid3=0)
BEGIN
	SET @minPersonGroupid3 = 0
	SET @maxPersonGroupid3 = 999999
END

DECLARE @minPersonGroupid4 INT = @PersonGroupid4,@maxPersonGroupid4 INT = @PersonGroupid4
IF(@PersonGroupid4=0)
BEGIN
	SET @minPersonGroupid4 = 0
	SET @maxPersonGroupid4 = 999999
END	

IF(@City1=0 AND @City2 = 0)
BEGIN
	SET @City1 = 0
	SET @City2 = 999999
END	

IF OBJECT_ID('tempdb.dbo.#TR', 'U') IS NOT NULL
    DROP TABLE #TR;
CREATE TABLE #TR
    (
      Sodor INT,Srfsl INT,Moin INT,HSB BIGINT,Factor INT,Type INT ,DateR VARCHAR(10),Bed BIGINT,Bes BIGINT,Sanad INT,TypeSanad INT
    );




	INSERT INTO #TR
		SELECT Sodor,Srfsl,Moin,HSB,Factor,
		tr.Type,
		DateR,
		Bed,
		Bes,
		Sanadm,
		ISNULL(ts.TypeSanad,1)
		FROM dbo.TR as tr left join dbo.TblSanad as ts on tr.Sanadm = ts.Sanad
		WHERE  Srfsl BETWEEN @Srfsl1 AND @Srfsl2 AND Moin BETWEEN @Moin1 AND @Moin2 AND (CShobe BETWEEN @cshobe1 AND @cshobe2 OR CShobe = 0)
		
	


IF OBJECT_ID('tempdb.dbo.#Aval', 'U') IS NOT NULL
    DROP TABLE #Aval;
CREATE TABLE #Aval
    (
      Srfsl INT,Moin INT,HSB BIGINT,Mande BIGINT,MMande VARCHAR(10)
    );
    
    INSERT INTO #Aval
    SELECT Srfsl,Moin,HSB,SUM(Bed-Bes) AS Mande,dbo.BedBes(SUM(Bed-Bes)) AS MMande FROM #TR WHERE TypeSanad = 2
    GROUP BY Srfsl,Moin,HSB
    
    
IF OBJECT_ID('tempdb.dbo.#MandeKol', 'U') IS NOT NULL
    DROP TABLE #MandeKol;
CREATE TABLE #MandeKol
    (
      Srfsl INT,Moin INT,HSB BIGINT,Mande BIGINT,MMande VARCHAR(10)
    );
    
    INSERT INTO #MandeKol
    SELECT Srfsl,Moin,HSB,SUM(Bed-Bes) AS Mande,dbo.BedBes(SUM(Bed-Bes)) AS MMande FROM #TR WHERE DateR<=@DateR
    GROUP BY Srfsl,Moin,HSB
    
    
IF OBJECT_ID('tempdb.dbo.#Bed', 'U') IS NOT NULL
    DROP TABLE #Bed;
CREATE TABLE #Bed
    (
      Srfsl INT,Moin INT,HSB BIGINT,Mab BIGINT
    );
    
    INSERT INTO #Bed
    SELECT Srfsl,Moin,HSB,SUM(Bed) AS DateR FROM #TR WHERE Bed>0 AND TypeSanad = 1
    GROUP BY Srfsl,Moin,HSB



	IF OBJECT_ID('tempdb.dbo.#Bes', 'U') IS NOT NULL
    DROP TABLE #Bes;
CREATE TABLE #Bes
    (
      Srfsl INT,Moin INT,HSB BIGINT,Mab BIGINT
    );
    
    INSERT INTO #Bes
    SELECT Srfsl,Moin,HSB,SUM(Bes) AS DateR FROM #TR WHERE Bes>0 AND TypeSanad = 1
    GROUP BY Srfsl,Moin,HSB


   IF OBJECT_ID('tempdb.dbo.#LastPardakht', 'U') IS NOT NULL
    DROP TABLE #LastPardakht;
CREATE TABLE #LastPardakht
    (
      Srfsl INT,Moin INT,HSB BIGINT,DateR VARCHAR(10)
    );
    
    INSERT INTO #LastPardakht
    SELECT Srfsl,Moin,HSB,MAX(DateR) AS DateR FROM #TR WHERE Bes>0 AND TypeSanad = 1
    GROUP BY Srfsl,Moin,HSB
    
    
    
        
   IF OBJECT_ID('tempdb.dbo.#LastFactor', 'U') IS NOT NULL
    DROP TABLE #LastFactor;
CREATE TABLE #LastFactor
    (
      Srfsl INT,Moin INT,HSB BIGINT,DateR VARCHAR(10)
    );
    


    INSERT INTO #LastFactor
    SELECT Srfsl,Moin,HSB,MAX(DateR) AS DateR FROM #TR WHERE Bed>0 AND Factor>0 AND TypeSanad = 1
    GROUP BY Srfsl,Moin,HSB


   IF OBJECT_ID('tempdb.dbo.#TblSharhMaster', 'U') IS NOT NULL
    DROP TABLE #TblSharhMaster;
CREATE TABLE #TblSharhMaster
    (
      Srfsl INT,Moin INT,HSB BIGINT,Sharh1 NVARCHAR(500),Sharh2 NVARCHAR(500),Sharh3 NVARCHAR(500),Sharh4 NVARCHAR(500),TimeP VARCHAR(50),UserId INT
    );


	INSERT #TblSharhMaster
	SELECT sm.Srfsl,sm.Moin,sm.HSB,sm.Sharh1,sm.Sharh2,sm.Sharh3,sm.Sharh4,sm.TimeP,sm.UserId FROM dbo.TblSharhMaster AS sm
	INNER JOIN (
	SELECT Srfsl,Moin,HSB,MAX(Id) AS Id FROM dbo.TblSharhMaster
	GROUP BY Srfsl,Moin,HSB) AS last ON last.Id = sm.Id
    
    
    SELECT 
	dbo.Master.Srfsl,
	dbo.Master.Moin,
	dbo.Master.HSB,
	dbo.Master.personcod,
	ISNULL(dbo.TblPerson.Name+ ' ' + dbo.TblPerson.Famil,'') AS Name,
    ISNULL(aval.Mande,0)  AS MandeAval,
	ISNULL(Bed.Mab,0)  AS Bed,
	ISNULL(Bes.Mab,0)  AS Bes,
    ISNULL(MandeKol.Mande,0)  AS MandeKol,
    ISNULL(LastPardakht.DateR,'')  AS LastPardakht,
    '' AS LastTasviye,
	CAST(0 AS int) AS ModatTasviye,
    ISNULL(LastFactor.DateR,'') AS LastFactor,
    ISNULL(sm.Sharh1,'') AS Sharh1,
    ISNULL(sm.Sharh2,'') AS Sharh2,
	ISNULL(sm.Sharh3,'') AS Sharh3,
	ISNULL(sm.Sharh4,'') AS Sharh4,
	ISNULL(u.FulName,'') AS UserNameSharh,
	ISNULL(sm.TimeP,'') AS TimeSharh,
	ISNULL(pm.Tell,'') AS Mobile,
	ISNULL(pt.Tell,'') AS Tell
     FROM dbo.Master
    LEFT JOIN #Aval AS aval ON dbo.Master.Srfsl = aval.Srfsl AND dbo.Master.Moin = aval.Moin AND dbo.Master.HSB = aval.HSB 
    LEFT JOIN #MandeKol AS MandeKol ON dbo.Master.Srfsl = MandeKol.Srfsl AND dbo.Master.Moin = MandeKol.Moin AND dbo.Master.HSB = MandeKol.HSB 
    LEFT JOIN #LastPardakht AS LastPardakht ON dbo.Master.Srfsl = LastPardakht.Srfsl AND dbo.Master.Moin = LastPardakht.Moin AND dbo.Master.HSB = LastPardakht.HSB 
    LEFT JOIN #LastFactor AS LastFactor ON dbo.Master.Srfsl = LastFactor.Srfsl AND dbo.Master.Moin = LastFactor.Moin AND dbo.Master.HSB = LastFactor.HSB 
	LEFT JOIN #Bed AS Bed ON dbo.Master.Srfsl = Bed.Srfsl AND dbo.Master.Moin = Bed.Moin AND dbo.Master.HSB = Bed.HSB 
	LEFT JOIN #Bes AS Bes ON dbo.Master.Srfsl = Bes.Srfsl AND dbo.Master.Moin = Bes.Moin AND dbo.Master.HSB = Bes.HSB 
    LEFT JOIN dbo.TblPerson ON dbo.TblPerson.Sh_ozviat = dbo.Master.personcod
	LEFT JOIN #TblSharhMaster AS sm ON sm.Srfsl = dbo.Master.Srfsl AND sm.Moin = dbo.Master.Moin AND sm.HSB = dbo.Master.HSB
	LEFT JOIN dbo.TblUser AS u ON u.Id = sm.UserId
	LEFT JOIN dbo.Func_PersonTell(2) AS pm ON pm.ShOzviat = dbo.Master.personcod
	LEFT JOIN dbo.Func_PersonTell(1) AS pt ON pt.ShOzviat = dbo.Master.personcod
    WHERE Master.Srfsl BETWEEN @Srfsl1 AND @Srfsl2 AND Master.Moin BETWEEN @Moin1 AND @Moin2 
	AND ISNULL(dbo.TblPerson.CityId,0) BETWEEN @City1 AND @City2
	AND	ISNULL(dbo.TblPerson.PersonGroupId,0) BETWEEN @minPersonGroupid AND @maxPersonGroupid
	AND	ISNULL(dbo.TblPerson.PersonGroupId2,0) BETWEEN @minPersonGroupid2 AND @maxPersonGroupid2
	AND	ISNULL(dbo.TblPerson.PersonGroupId3,0) BETWEEN @minPersonGroupid3 AND @maxPersonGroupid3
	AND	ISNULL(dbo.TblPerson.PersonGroupId4,0) BETWEEN @minPersonGroupid4 AND @maxPersonGroupid4
    AND ISNULL(MandeKol.Mande,0)<>0 --AND dbo.Master.HSB = 1469
	ORDER BY dbo.Master.HSB
    
END


GO

-- Procedure: [dbo].[RptRizeKolMandePro_Bes]
IF OBJECT_ID(N'[dbo].[RptRizeKolMandePro_Bes]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptRizeKolMandePro_Bes] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptRizeKolMandePro_Bes]
@Srfsl INT,
@Moin INT,
@HSB BIGINT,
@DateR NVARCHAR(500),
@Cshobe INT
AS
BEGIN

DECLARE @cshobe1 INT = @Cshobe,@cshobe2 INT = @Cshobe
IF(@Cshobe=0)
BEGIN
	SET @cshobe1 = 0
	SET @cshobe2 = 999999
END		

DECLARE @DataBaseName NVARCHAR(100) = ''
SET @DataBaseName = DB_NAME()

IF OBJECT_ID('tempdb.dbo.#TR', 'U') IS NOT NULL
    DROP TABLE #TR;
CREATE TABLE #TR
    (
      Sodor INT,DateR VARCHAR(10),DateRun VARCHAR(10),Modat INT,Sharh NVARCHAR(500),SanadM INT,Bes BIGINT,Factor INT,Type INT,DateCheck VARCHAR(10),TRDureTasviye INT,MabMande BIGINT,[Desc] NVARCHAR(500)
    );


Declare @Connection table (id int identity,databasename nvarchar(max))
INSERT INTO @Connection (databasename)
exec ('SELECT DatabaseName from '+@DataBaseName+'.dbo.TblDataBase ORDER BY StartDate')
DECLARE @t int,@c int = 0
SELECT @c = COUNT(*) FROM @Connection
IF(@c>=2)
	SET @t=1
ELSE
BEGIN

	IF(@c=1)
	BEGIN
		UPDATE @Connection SET databasename = @DataBaseName
	END
	ELSE
	BEGIN
		INSERT INTO @Connection
		        ( databasename )
		VALUES  ( @DataBaseName )
	END
	SET @t = 1
	SET @c = 1
end
WHILE (@t<= @c)
BEGIN
	select @DataBaseName = databasename from @Connection where id = @t

	DECLARE @tps NVARCHAR(100) = '1'
	IF(@t = 1)
		SET @tps = '1,2'

	INSERT INTO #TR
		EXEC('SELECT tt.Sodor,
		tt.DateR,
		'''' AS DateRun,
		0 AS Modat,
		tt.sharh,
		tt.SanadM,
		tt.Bes,
		tt.Factor,
		tt.Type,
		ISNULL(c.DateChek,'''') AS DateCheck,
		TRDureTasviye,
		tt.Bes as MabMande,
		'''' as [Desc]
		FROM '+@DataBaseName+'.dbo.TR as tt Left join
		'+@DataBaseName+'.dbo.TblSanad as ts on tt.SanadM = ts.Sanad Left join
		'+@DataBaseName+'.dbo.[Check] AS c ON c.Id = tt.IDCheck AND tt.TpCheck=0
		 WHERE tt.Srfsl = '+@Srfsl+' AND tt.Moin = '+@Moin +' AND tt.HSB = '+@HSB +' AND tt.Bes>0  AND (tt.CShobe BETWEEN '+@cshobe1+' AND '+@cshobe2+' OR tt.CShobe = 0) and IsNull(ts.TypeSanad,1)  in ('+@tps+') ')
		
		SET @t = @t + 1
END

SELECT * FROM #TR
ORDER BY DateR,Sodor
    

END

GO

-- Procedure: [dbo].[RptSoodZian_ST]
IF OBJECT_ID(N'[dbo].[RptSoodZian_ST]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[RptSoodZian_ST] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[RptSoodZian_ST]
 	@Cscod varchar(50),
 	@d1 varchar(10),
 	@d2 varchar(10),
 	@s1 int,
 	@s2 int,
 	@Cshobe int = 0,
	@cntCost1 INT = 0,
	@CntCost2 INT = 0,
	@cntProject1 INT = 0,
	@CntProject2 INT = 0
 AS
 BEGIN
 IF(@cntCost1=0 AND @CntCost2 =0)
	SET @CntCost2 = 9999999

IF(@cntProject1=0 AND @cntProject2 =0)
	SET @cntProject2 = 9999999
 if(@Cshobe = 0)
 BEGIN
	
 			Select TR.Srfsl,TR.Moin,dbo.GetSarfaslName(TR.Srfsl) as SrfslName,dbo.GetMoinName(TR.Srfsl,TR.Moin) as MoinName,
 		SUM(TR.Bed-TR.Bes) as Mande,
 		Abs(SUM(bed-bes)) as MandeAbs,
 		dbo.BedBes(SUM(bed-bes)) as MandeTP
 		from TR left join TblParam on TR.Srfsl=TblParam.Srfsl and TR.Moin=TblParam.Moin
 		where ISNULL(TblParam.Cscod,'') like @Cscod+'%' and TR.DateR between @d1 and @d2 and TR.SanadM between @s1 and @s2 AND TR.CntHaz BETWEEN @cntCost1 AND @CntCost2 AND TR.CntProject BETWEEN @cntProject1 AND @cntProject2
 		group by TR.Srfsl,TR.Moin
 		having SUM(TR.Bed-TR.Bes)<>0
 		order by TR.Srfsl,TR.Moin
 end
 else
 BEGIN
	 if(@Cscod = '600-101-101')
		begin
				Select TR.Srfsl,TR.Moin,dbo.GetSarfaslName(TR.Srfsl) as SrfslName,dbo.GetMoinName(TR.Srfsl,TR.Moin) as MoinName,
 				SUM(TR.Bed-TR.Bes) as Mande,
 				Abs(SUM(bed-bes)) as MandeAbs,
 				dbo.BedBes(SUM(bed-bes)) as MandeTP
 				from TR left join TblParam on TR.Srfsl=TblParam.Srfsl and TR.Moin=TblParam.Moin
 				where ISNULL(TblParam.Cscod,'') like @Cscod+'%' and TR.DateR between @d1 and @d2 and TR.SanadM between @s1 and @s2 and (TR.CShobe = @Cshobe OR TR.CShobe = 0) AND TR.CntHaz BETWEEN @cntCost1 AND @CntCost2 AND TR.CntProject BETWEEN @cntProject1 AND @cntProject2
 				group by TR.Srfsl,TR.Moin
 				having SUM(TR.Bed-TR.Bes)<>0


				union all

				select 0 as Srfsl,0 as Moin,N'خرید از مرکزی' as SrfslName,
				N'خرید از مرکزی' as MoinName,
				SUM(KardexKala.Ted*KardexKala.Fi) as Mande,
				SUM(KardexKala.Ted*KardexKala.Fi) as MandeAbs,
				N'بد' as MandeTP
				from KardexKala where type = 101 and IDAnbar in (select ID from TblAnbar where Cshobe = @Cshobe) and (KardexKala.DateR between @d1 and @d2)
				having SUM(KardexKala.Ted*KardexKala.Fi)>0
				order by TR.Srfsl,TR.Moin		
		end -- فروش
		else if(@Cscod = '400-101')
		begin
				Select TR.Srfsl,TR.Moin,dbo.GetSarfaslName(TR.Srfsl) as SrfslName,dbo.GetMoinName(TR.Srfsl,TR.Moin) as MoinName,
 				SUM(TR.Bed-TR.Bes) as Mande,
 				Abs(SUM(bed-bes)) as MandeAbs,
 				dbo.BedBes(SUM(bed-bes)) as MandeTP
 				from TR left join TblParam on TR.Srfsl=TblParam.Srfsl and TR.Moin=TblParam.Moin
 				where ISNULL(TblParam.Cscod,'') like @Cscod+'%' and TR.DateR between @d1 and @d2 and TR.SanadM between @s1 and @s2 and (TR.CShobe = @Cshobe OR TR.CShobe = 0) AND TR.CntHaz BETWEEN @cntCost1 AND @CntCost2 AND TR.CntProject BETWEEN @cntProject1 AND @cntProject2
 				group by TR.Srfsl,TR.Moin
 				having SUM(TR.Bed-TR.Bes)<>0


				union all

				select 0 as Srfsl,0 as Moin,N'فروش به شعبه' as SrfslName,
				N'فروش به شعبه' as MoinName,
				SUM(KardexKala.Ted*KardexKala.Fi) as Mande,
				SUM(KardexKala.Ted*-1*KardexKala.Fi) as MandeAbs,
				N'بس' as MandeTP
				from KardexKala where type = 201 and IDAnbar in (select ID from TblAnbar where Cshobe = @Cshobe) and (KardexKala.DateR between @d1 and @d2) 
				having SUM(KardexKala.Ted*-1*KardexKala.Fi)>0
				order by TR.Srfsl,TR.Moin		
		end
		else
		begin
 				Select TR.Srfsl,TR.Moin,dbo.GetSarfaslName(TR.Srfsl) as SrfslName,dbo.GetMoinName(TR.Srfsl,TR.Moin) as MoinName,
 				SUM(TR.Bed-TR.Bes) as Mande,
 				Abs(SUM(bed-bes)) as MandeAbs,
 				dbo.BedBes(SUM(bed-bes)) as MandeTP
 				from TR left join TblParam on TR.Srfsl=TblParam.Srfsl and TR.Moin=TblParam.Moin
 				where ISNULL(TblParam.Cscod,'') like @Cscod+'%' and TR.DateR between @d1 and @d2 and TR.SanadM between @s1 and @s2 and (TR.CShobe = @Cshobe OR TR.CShobe = 0) AND TR.CntHaz BETWEEN @cntCost1 AND @CntCost2 AND TR.CntProject BETWEEN @cntProject1 AND @cntProject2
 				group by TR.Srfsl,TR.Moin
 				having SUM(TR.Bed-TR.Bes)<>0
 				order by TR.Srfsl,TR.Moin
		END
 end
 
 END
 
 


GO

-- Procedure: [dbo].[Sp_Bime_SaveSMS_SetFactor]
IF OBJECT_ID(N'[dbo].[Sp_Bime_SaveSMS_SetFactor]', N'P') IS NULL
