GO
ALTER PROCEDURE [dbo].[Sp_Bime_SaveSMS_SetFactor]
	@FactorNumber INT,
	@FactorType INT,
	@TypeFormat INT
AS
	SELECT        COUNT(Id) AS Id
FROM            Bime_SaveSMS
WHERE       FactorNumber = @FactorNumber AND FactorType = @FactorType AND TypeFormat = @TypeFormat
	RETURN


GO

