-- Procedure: [dbo].[sp_Hotel_TblTr_SabtSanadFinal]
IF OBJECT_ID(N'[dbo].[sp_Hotel_TblTr_SabtSanadFinal]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_Hotel_TblTr_SabtSanadFinal] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_Hotel_TblTr_SabtSanadFinal] 
    @TitleId INT , 
    @Date1 VARCHAR(10) , 
    @Date2 VARCHAR(10) , 
    @CreatUser INT 
AS 
BEGIN      
    BEGIN TRANSACTION Sanad;      
      
    DECLARE @CreatTime NVARCHAR(20) , 
        @Number INT , 
        @CustomerName NVARCHAR(200) , 
        @Srfsl INT , 
        @Moin INT , 
        @Hsb BIGINT ,
		@Cshobe INT = 0; 
 
	DECLARE @DateSanad VARCHAR(10), @StartDate VARCHAR(10), @EndDate VARCHAR(10) 
	SELECT @StartDate = StartDate, @EndDate = EndDate FROM dbo.TblCompany WHERE Id = 1  
	SET @DateSanad = (SELECT CASE WHEN @EndDate < @Date2 THEN @EndDate ELSE @Date2 END) 
	DECLARE @Cnt INT; 
 
    SELECT  @CustomerName = Name + ' ' + Famil , 
            @Number = Number ,
			@Cshobe = Hotel_TRTitle.CShobe
    FROM    dbo.Hotel_TRTitle 
    LEFT JOIN dbo.TblPerson ON Customer_Id = Sh_ozviat 
    WHERE   Id = @TitleId;  
  
    SET @CreatTime = ( SELECT   dbo.GetToday() 
                        );  
    CREATE TABLE #HTR 
        ( 
            Customer INT , 
            Id INT , 
            Tag INT 
        );  
    INSERT  INTO #HTR 
    SELECT  Customer_Id , 
            Hotel_TR.Id , 
            0 
    FROM    dbo.Hotel_TR 
            LEFT JOIN dbo.Hotel_TRDetail ON dbo.Hotel_TR.Detail_Id = dbo.Hotel_TRDetail.Id 
    WHERE   Title_Id = @TitleId --AND Sodor = 0 AND [Date] BETWEEN @StartDate AND @EndDate 
    UNION ALL 
    SELECT  Customer_Id , 
            dbo.Hotel_TRAgent.Id , 
            [Type] 
    FROM    dbo.Hotel_TR 
            LEFT JOIN dbo.Hotel_TRAgent ON Hotel_TR.Id = Link 
            LEFT JOIN dbo.Hotel_TRDetail ON dbo.Hotel_TRAgent.Detail_Id = dbo.Hotel_TRDetail.Id 
    WHERE   Title_Id = @TitleId  
  
    CREATE TABLE #HTRMab 
        ( 
            Customer INT , 
            Bed BIGINT , 
            Bes BIGINT 
        );  
    INSERT  INTO #HTRMab 
    SELECT  tblHTR.Customer , 
            ISNULL(SUM(Bed), 0) , 
            ISNULL(SUM(Bes), 0) 
    FROM    #HTR AS tblHTR 
            LEFT JOIN dbo.TRDetail ON tblHTR.Id = Id2 
                                        AND tblHTR.Tag = Tag2 
            LEFT JOIN dbo.TR ON TR.Sodor = TRDetail.Sodor 
                                AND Type = 20 
    GROUP BY tblHTR.Customer;  
         
	SET @Cnt = (SELECT COUNT(*) FROM #HTRMab) 
	IF ( @Cnt = 0 )  
        BEGIN        
            ROLLBACK;      
            RAISERROR(N'اطلاعاتی برای ثبت وجود ندارد.',16,1);       
            RETURN;        
        END; 
					  
    IF ( @@ERROR <> 0 ) 
        BEGIN      
            ROLLBACK;      
            RETURN;      
        END;  
    DECLARE @Hesab TABLE 
        ( 
            Name NVARCHAR(100) , 
            Customer INT , 
            Srfsl INT , 
            Moin INT , 
            Hsb BIGINT , 
            Flag BIT 
        );  
    INSERT  INTO @Hesab 
    SELECT DISTINCT 
            TblPerson.Name + ' ' + Famil , 
            tblMab.Customer , 
            ISNULL(TblParam.Srfsl, 0) , 
            ISNULL(TblParam.Moin, 0) , 
            ISNULL(Hesab, 0) , 
            CASE ISNULL(Hesab, 0) 
                WHEN 0 THEN 0 
                ELSE 1 
            END 
    FROM    #HTRMab AS tblMab 
    LEFT JOIN dbo.TblPerson ON tblMab.Customer = dbo.TblPerson.Sh_ozviat 
    LEFT JOIN dbo.TblParam ON TblPerson.Srfsl = TblParam.Srfsl 
                                AND TblPerson.Moin = TblParam.Moin 
                                AND TblParam.BdBs <> 1;  
  
          
    DECLARE @TmpHsb TABLE 
        ( 
            [Row] INT , 
            Person INT , 
            S INT , 
            M INT , 
            H BIGINT 
        );  
    INSERT  INTO @TmpHsb 
    SELECT  ROW_NUMBER() OVER ( ORDER BY ISNULL(Master.HSB, 0) ) , 
            tblH.Customer , 
            ISNULL(Master.Srfsl, 0) , 
            ISNULL(Master.Moin, 0) , 
            ISNULL(Master.HSB, 0) 
    FROM    @Hesab AS tblH 
    LEFT JOIN dbo.Master ON tblH.Customer = personcod 
    LEFT JOIN dbo.TblParam ON Master.Srfsl = TblParam.Srfsl 
                                AND Master.Moin = TblParam.Moin 
    WHERE   tblH.Flag = 0 
            AND TblParam.BdBs <> 1;  
  
		  
  
    UPDATE  @Hesab 
    SET     Srfsl = tblHSB.S , 
            Moin = tblHSB.M , 
            Hsb = tblHSB.H , 
            Flag = CASE tblHSB.H 
                        WHEN 0 THEN 0 
                        ELSE 1 
                    END 
    FROM    @Hesab AS tblH 
    INNER JOIN @TmpHsb AS tblHSB ON tblH.Customer = tblHSB.Person 
    WHERE   tblH.Flag = 0 
            AND tblHSB.[Row] = 1;  
          
    IF ( @@ERROR <> 0 ) 
        BEGIN      
            ROLLBACK;      
            RETURN;      
        END;  
    SELECT  @Srfsl = Srfsl , 
            @Moin = Moin 
    FROM    dbo.Hotel_TblDefultHesab 
    WHERE   [Type] = 101;  
  
    SET @Hsb = ( SELECT ISNULL(MAX(Master.HSB), 0) 
                    FROM   dbo.Master WITH ( HOLDLOCK ) 
                    WHERE  Master.Srfsl = @Srfsl 
                        AND Master.Moin = @Moin 
                );  
    DECLARE @temp INT = 0;  
    UPDATE  @Hesab 
    SET     Srfsl = @Srfsl , 
            Moin = @Moin , 
            Hsb = @temp + @Hsb , 
            @temp = @temp + 1 
    WHERE   Flag = 0;  
		  
  
    INSERT  INTO [Master] 
	( Srfsl , 
		Moin , 
		HSB , 
		personcod  
	) 
	SELECT  Srfsl , 
			Moin , 
			Hsb , 
			Customer 
	FROM    @Hesab 
	WHERE   Flag = 0;  
    IF ( @@ERROR <> 0 ) 
        BEGIN      
            ROLLBACK;      
            RETURN;      
        END;  
  
    UPDATE  dbo.TblPerson 
    SET     Srfsl = tblH.Srfsl , 
            Moin = tblH.Moin , 
            Hesab = tblH.Hsb 
    FROM    dbo.TblPerson 
	INNER JOIN @Hesab AS tblH ON Sh_ozviat = tblH.Customer 
    WHERE   tblH.Flag = 0;   
    IF ( @@ERROR <> 0 ) 
        BEGIN      
            ROLLBACK;      
            RETURN;      
        END;	    
--*************************Sanad******************      
    DECLARE @TypSnd TINYINT = ( SELECT  DailySanad 
                                FROM    dbo.TblSetingSoft 
                                WHERE   Id = 1 
                                );      
    DECLARE @Sanad INT; 
        -- @Snd INT;       
          
    IF @TypSnd = 0 
    BEGIN       
 
        SET @Sanad = ( SELECT   ISNULL(MAX(SanadM), 0) + 1  -- @Snd 
                        FROM     TR 
                        );  
				   		         
        DELETE  TblSanad 
        WHERE   Sanad = @Sanad;    
		      
        IF ( @@ERROR <> 0 ) 
            BEGIN      
                ROLLBACK;      
                RETURN;      
            END;      
      
        INSERT  INTO TblSanad 
                ( Sanad , 
                    Date , 
                    Sharh , 
                    TypeSanad , 
                    User_Id  
                ) 
        VALUES  ( @Sanad , 
                    @DateSanad , 
                    N'سند پذیرش شماره ' + CAST(@Number AS NVARCHAR(200)) 
                    + ' ' + @CustomerName , 
                    1 , 
                    @CreatUser  
                );     
		      
        IF ( @@ERROR <> 0 ) 
            BEGIN      
                ROLLBACK;      
                RETURN;      
            END;      
	      
    END;        
    ELSE 
	BEGIN
	    IF @TypSnd = 1 OR @TypSnd = 4 
		BEGIN      
          
			SET @Sanad = ( SELECT   ISNULL(MAX(SanadM), 0) 
							FROM     TR 
							WHERE    DateR = @DateSanad AND Type<100 
							);       
		    
			IF @Sanad = 0 
				BEGIN    
                             
					SET @Sanad = ( SELECT   ISNULL(MAX(SanadM), 0) + 1 
									FROM     TR 
									);  
			    
					DELETE  TblSanad 
					WHERE   Sanad = @Sanad;    
    
					IF ( @@ERROR <> 0 ) 
						BEGIN    
							ROLLBACK;     
							RETURN;    
						END;    
    
					INSERT  INTO TblSanad 
							( Sanad , 
								Date , 
								Sharh , 
								TypeSanad , 
								User_Id  
							) 
					VALUES  ( @Sanad , 
								@DateSanad , 
								N'سند روز ' + @DateSanad , 
								1 , 
								@CreatUser  
							);    
					IF ( @@ERROR <> 0 ) 
						BEGIN    
							ROLLBACK;     
							RETURN;    
						END;     
				END;    
	      
		END;      
        ELSE 
		BEGIN
		    IF @TypSnd = 2 OR @TypSnd = 3 
            BEGIN      
          
                SET @Sanad = ( SELECT   ISNULL(MAX(SanadM), 0) 
                                FROM     TR 
                                WHERE    DateR = @DateSanad 
                                        AND ( [Type] = 20 
                                                OR [Type] = 30 
                                            ) 
                                );       
		    
                IF @Sanad = 0 
                    BEGIN    
                        SET @Sanad = ( SELECT   ISNULL(MAX(SanadM), 0) 
                                                + 1 
                                        FROM     TR 
                                        );     
			    
                        DELETE  TblSanad 
                        WHERE   Sanad = @Sanad;      
		      
                        IF ( @@ERROR <> 0 ) 
                            BEGIN    
                                ROLLBACK;     
                                RETURN;    
                            END;    
    
                        INSERT  INTO TblSanad 
                                ( Sanad , 
                                    Date , 
                                    Sharh , 
                                    TypeSanad , 
                                    User_Id  
                                ) 
                        VALUES  ( @Sanad , 
                                    @DateSanad , 
                                    N'سند پذیرش هتل روز ' + @DateSanad , 
                                    1 , 
                                    @CreatUser  
                                );    
                        IF ( @@ERROR <> 0 ) 
                            BEGIN    
                                ROLLBACK;     
                                RETURN;    
                            END;    
                    END;     
	      
            END;
		END
            
	END
              
	    
    DECLARE @MabSum BIGINT , 
        @Sodor INT , 
        @Row INT;  
    SET @MabSum = ( SELECT  SUM(Bes) - SUM(Bed) 
                    FROM    #HTRMab 
                    );  
    SET @Sodor = ( SELECT   ISNULL(MAX(Sodor), 0) 
                    FROM     dbo.TR 
                    );    
    SET @Row = ( SELECT ISNULL(MAX([Row]), 0) 
                    FROM   dbo.TR 
                    WHERE  SanadM = @Sanad 
                );    
    SELECT  @Srfsl = Srfsl , 
            @Moin = Moin , 
            @Hsb = HSB 
    FROM    dbo.Hotel_TblDefultHesab 
    WHERE   Type = 100;  --نوع بدهکاران موقت    
    
    INSERT  INTO dbo.TR 
    ( Sodor , 
        Srfsl , 
        Moin , 
        HSB , 
        GRP , 
        DateR , 
        Sharh , 
        Factor , 
        SanadM , 
        Takh , 
        Bed , 
        Bes , 
        Type , 
        Row  ,
		CShobe
    ) 
    SELECT  ROW_NUMBER() OVER ( ORDER BY tblH.Customer ) + @Sodor , 
            tblH.Srfsl , 
            tblH.Moin , 
            tblH.Hsb , 
            @CreatUser , 
            @DateSanad , 
            'اقامت هتل پذیرش شماره ' 
            + CAST(@Number AS VARCHAR(10)) + ' ' + tblH.Name 
            + ' از تاریخ ' + @Date1 + ' تا ' + @Date2 ,  
            @TitleId , 
            @Sanad , 
            0 , 
            tblMab.Bes - tblMab.Bed , 
            0 , 
            20 , 
            ROW_NUMBER() OVER ( ORDER BY tblH.Customer ) + @Row ,
			@Cshobe
    FROM    @Hesab AS tblH 
    LEFT JOIN #HTRMab AS tblMab ON tblMab.Customer = tblH.Customer;  
	  
    SET @Sodor = ( SELECT   ISNULL(MAX(Sodor), 0) + 1 
                    FROM     dbo.TR 
                    );    
    SET @Row = ( SELECT ISNULL(MAX([Row]), 0) + 1 
                    FROM   dbo.TR 
                    WHERE  SanadM = @Sanad 
                );  
	  
    INSERT  INTO dbo.TR 
			( Sodor , 
				Srfsl , 
				Moin , 
				HSB , 
				GRP , 
				DateR , 
				Sharh , 
				Factor , 
				SanadM , 
				Takh , 
				Bed , 
				Bes , 
				Type , 
				Row  
			) 
    VALUES  ( @Sodor , 
                @Srfsl , 
                @Moin , 
                @Hsb , 
                @CreatUser , 
                @DateSanad , 
                'اقامت هتل پذیرش شماره ' + CAST(@Number AS VARCHAR(10)) 
                + ' ' + @CustomerName + ' از تاریخ ' + @Date1 + ' تا ' 
                + @Date2 , 
                @TitleId , 
                @Sanad , 
                0 , 
                0 , 
                @MabSum , 
                20 , 
                @Row  
            );    
    
    IF ( @@ERROR <> 0 ) 
    BEGIN    
        ROLLBACK;     
        RETURN;    
    END;    
    
    INSERT  INTO TRDetail 
    ( Sodor , 
        Dep  
    ) 
    SELECT  dbo.TR.Sodor , 
            @Sodor 
    FROM    dbo.TR 
            LEFT JOIN dbo.TRDetail ON TRDetail.Sodor = TR.Sodor 
    WHERE   SanadM = @Sanad 
            AND Factor = @TitleId 
            AND Type = 20 
            AND ISNULL(Id1, 0) = 0; 
	      
    IF ( @@ERROR <> 0 ) 
	BEGIN    
		ROLLBACK;     
		RETURN;    
	END;      
    
    UPDATE  Tbl_Temp 
    SET     Sandmali = ( SELECT MAX(SanadM) 
                            FROM   dbo.TR 
                        );      
	      
    DECLARE @t1 TABLE 
        ( 
            srfsl INT , 
            moin INT , 
            hsb BIGINT , 
            bed BIGINT , 
            bes BIGINT 
        );      
    INSERT  INTO @t1 
	SELECT  Srfsl , 
			Moin , 
			HSB , 
			SUM(Bed) , 
			SUM(Bes) 
	FROM    TR 
	GROUP BY Srfsl , 
			Moin , 
			HSB;      
      
    UPDATE  [Master] 
    SET     Bed = 0 , 
            Bes = 0;      
    UPDATE  [Master] 
    SET     Bed = t1.bed , 
            Bes = t1.bes 
    FROM    Master 
    INNER JOIN @t1 AS t1 ON Master.Srfsl = t1.srfsl 
                            AND Master.Moin = t1.moin 
                            AND Master.HSB = t1.hsb;      
      
    IF ( @@ERROR <> 0 ) 
	BEGIN          
		ROLLBACK;      
		RETURN;      
	END;      
    DROP TABLE #HTR;  
    DROP TABLE #HTRMab;	      
    COMMIT TRANSACTION Sanad;      
	      
END;      
  

GO

-- Procedure: [dbo].[sp_Hotel_TblTr_ViewPersonMabalegh]
IF OBJECT_ID(N'[dbo].[sp_Hotel_TblTr_ViewPersonMabalegh]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_Hotel_TblTr_ViewPersonMabalegh] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_Hotel_TblTr_ViewPersonMabalegh] 
	@Reception INT  
AS  
BEGIN     
     
    DECLARE @CountAgent INT ,  
			@Loop INT = 1 ,  
			@PriceType BIT = 0 ,  
			@AutoCompute2 BIT = 0 ,  
			@ResNum INT ,  
			@Rom BIGINT;  
			  
    SELECT  @PriceType = ISNULL(PriceType, 0) ,  
            @AutoCompute2 = ISNULL(AutoCompute2, 0)  
    FROM    dbo.Hotel_TblSetting  
    WHERE   Id = 0;  
    SELECT  @PriceType = ISNULL(PriceType, @PriceType) ,  
            @AutoCompute2 = ISNULL(AutoCompute2, @AutoCompute2)  
    FROM    dbo.Hotel_TblSetting  
    WHERE   Id = @Reception;  
  
	IF (SELECT State_Id FROM dbo.Hotel_TRTitle WHERE Id = @Reception) = 2  
		SET @AutoCompute2 = 0  
  
    SET @ResNum = ( SELECT  CASE Link  
                                WHEN 0 THEN Id  
                                ELSE Link  
                            END  
                    FROM    Hotel_TRTitle  
                    WHERE   Id = @Reception  
                    );  
     
    DECLARE @Final TABLE  
    (  
        Person INT ,  
        Name NVARCHAR(200) ,  
        MabRoom BIGINT ,  
        MabSayer BIGINT ,  
        MabDaryaft BIGINT  
    );     
     
    INSERT  INTO @Final  
    SELECT DISTINCT  
            Customer_Id ,  
            '' ,  
            0 ,  
            0 ,  
            0  
    FROM    dbo.Hotel_TR  
    LEFT JOIN dbo.Hotel_TRDetail ON Detail_Id = Hotel_TRDetail.Id  
    WHERE   Title_Id = @Reception AND [Status] <> -1  
    UNION  
    SELECT DISTINCT  
            CustumCod ,  
            '' ,  
            0 ,  
            0 ,  
            0  
    FROM    dbo.TblFactorOnvan  
    WHERE   TblFactorOnvan.Id1 = 1  
            AND ( TblFactorOnvan.Id2 = @Reception  
                    OR TblFactorOnvan.Id2 = @ResNum  
                )  
    UNION  
    SELECT DISTINCT  
            personcod ,  
            '' ,  
            0 ,  
            0 ,  
            0  
    FROM    TR  
    LEFT JOIN dbo.Master ON TR.Srfsl = Master.Srfsl  
                            AND TR.Moin = Master.Moin  
                            AND TR.HSB = Master.HSB  
    LEFT JOIN dbo.TRDetail ON TR.Sodor = TRDetail.Sodor  
    WHERE   TR.Type = 0  
            AND Id1 = 1  
            AND ( Id2 = @Reception  
                    OR Id2 = @ResNum  
                );     
     
    DECLARE @Room TABLE  
    (  
        DetailId INT ,  
        Id INT ,  
        Customer INT ,  
        RoomId INT ,  
        Date VARCHAR(10) ,  
        TimeId INT ,  
        RoomPrice BIGINT ,  
        PersonPrice BIGINT ,  
        Kosorat BIGINT ,  
        Ezafat BIGINT ,  
        K DECIMAL(18, 3) ,  
        E DECIMAL(18, 3) ,  
        M DECIMAL(18, 3) ,  
        Maliat BIGINT ,  
        MabKol1 BIGINT ,  
        MabKol2 BIGINT ,  
        Msh INT  
    );     
    INSERT  INTO @Room  
    SELECT  Hotel_TRDetail.Id ,  
            Hotel_TR.Id ,  
            Customer_Id ,  
            dbo.Hotel_TRDetail.Room_id ,  
            Date ,  
            Time_Id ,  
            ROUND(Hotel_TR.RoomPrice, 0, 0) ,  
            ROUND(Hotel_TR.PersonPrice * Hotel_TR.AdditionalPerson,  
                    0, 0) ,  
            ROUND(Hotel_TR.MabTakh, 0, 0) ,  
            0 ,  
            0 ,  
            0 ,  
            0 ,  
            0 ,  
            ROUND(( Hotel_TR.RoomPrice + Hotel_TR.PersonPrice  
                    * Hotel_TR.AdditionalPerson - Hotel_TR.MabTakh ),  
                    0, 0) ,  
            0 ,  
            0  
    FROM    Hotel_TR  
    LEFT JOIN Hotel_TRDetail ON Hotel_TR.Detail_Id = Hotel_TRDetail.Id  
                                AND Hotel_TRDetail.Type = 0      
    WHERE   Title_Id = @Reception    
	  
    IF @AutoCompute2 = 1  
    BEGIN	  
					  
        DECLARE @CurrentDate CHAR(10) ,  
				@CurrentTime INT = 0 ,  
				@CurrentTimeId INT = 0 ,  
				@FullTime INT ,  
				@Cnt INT;  
  
        SET @CurrentDate = ( SELECT SUBSTRING(dbo.GetToday(), 1, 10)  
                            );  
        DELETE  @Room  
        WHERE   [Date] > ( SELECT   SUBSTRING(dbo.GetToday(), 1, 10)  
                            );  
			  
        SET @FullTime = ( SELECT    Id  
                            FROM      dbo.Hotel_TblTime  
                            WHERE     HalfPrice1 = 0  
                                    AND HalfPrice2 = 0  
                        );  
        SET @Cnt = ( SELECT COUNT(*)  
                        FROM   @Room  
                        WHERE  [Date] < @CurrentDate OR ([Date] = @CurrentDate AND TimeId < @FullTime)  
                    );			  
			  
        SET @CurrentTime = ( SELECT CAST(SUBSTRING(dbo.GetToday(), 11,  
                                                    2) AS INT) * 60  
                                    + CAST(SUBSTRING(dbo.GetToday(),  
                                                        14, 2) AS INT)  
                                    + CASE SUBSTRING(dbo.GetToday(),  
                                                        16, 1)  
                                        WHEN 'P' THEN 720  
                                        ELSE 0  
                                        END  
                            );  
        IF @CurrentTime < ( SELECT  MIN(Time1)  
                            FROM    dbo.Hotel_TblTime  
                            WHERE   HalfPrice2 = 1  
                            )  
        BEGIN  
            IF @Cnt > 0  
			BEGIN  
				DELETE  @Room  
				WHERE   [Date] = @CurrentDate AND TimeId >= @FullTime;  
			END;  
            ELSE  
            BEGIN  
                UPDATE  @Room  
                SET     TimeId = ( SELECT   MAX(Id)  
                                    FROM     dbo.Hotel_TblTime  
                                    WHERE    HalfPrice1 = 1  
                                    )  
                WHERE   TimeId = @FullTime;  
            END;  
        END;  
		ELSE  
        BEGIN  
  
            SET @CurrentTimeId = ISNULL(( SELECT  Id  
                                            FROM    dbo.Hotel_TblTime  
                                            WHERE   @CurrentTime BETWEEN Time1 AND Time2  
                                        ), 0);  
            UPDATE  @Room  
            SET     TimeId = CASE @CurrentTimeId  
                                WHEN 0 THEN @FullTime  
                                ELSE @CurrentTimeId  
                                END  
            WHERE   [Date] = @CurrentDate  
                    AND TimeId = @FullTime;					  
				  
        END;  
  
    END;  
  
    UPDATE  @Room  
    SET     RoomPrice = ROUND(tbl.RoomPrice * dbo.Hotel_TblTime.[Percent],  
                                0, 0) ,  
            PersonPrice = ROUND(tbl.PersonPrice  
                                * dbo.Hotel_TblTime.[Percent], 0, 0) ,  
            Kosorat = ROUND(tbl.Kosorat * dbo.Hotel_TblTime.[Percent], 0,  
                            0) ,  
            MabKol1 = ROUND(tbl.MabKol1 * dbo.Hotel_TblTime.[Percent], 0,  
                            0)  
    FROM    @Room AS tbl  
            LEFT JOIN dbo.Hotel_TblTime ON Hotel_TblTime.Id = tbl.TimeId;	  
	     
    DECLARE @Agent TABLE  
    (  
        Row INT ,  
        Id INT ,  
        AgentId INT ,  
        Type INT ,  
        Mashmol BIT ,  
        Maliat BIT ,  
        Person BIT  
    );  
	    
    INSERT  INTO @Agent  
    SELECT  ROW_NUMBER() OVER ( ORDER BY Hotel_TRDetail.Id ) ,  
            Hotel_TRDetail.Id ,  
            Hotel_TRDetail.Type ,  
            Hotel_TblAgent.Type ,  
            Mashmol ,  
            Maliat ,  
            Person  
    FROM    Hotel_TRDetail  
            LEFT JOIN Hotel_TblAgent ON Hotel_TRDetail.Type = Hotel_TblAgent.Id  
    WHERE   Hotel_TRDetail.Title_Id = @Reception  
            AND Hotel_TRDetail.Type > 0;     
	     
    IF @PriceType = 0     
--*********************     
    BEGIN     
        SET @CountAgent = ( SELECT  COUNT(*)  
                            FROM    @Agent  
                            );     
        WHILE @Loop <= @CountAgent  
        BEGIN     
            UPDATE  @Room  
            SET     K = ISNULL(CASE tblAgent.Maliat  
                                    WHEN 1 THEN 0  
                                    ELSE CASE tblAgent.Type  
                                        WHEN 0 THEN 0  
                                        ELSE CASE dbo.Hotel_TRAgent.PercentAgent  
                                                WHEN 0  
                                                THEN dbo.Hotel_TblTime.[Percent]  
                                                    * CASE Person  
                                                    WHEN 0  
                                                    THEN Hotel_TRAgent.MabAgent  
                                                    ELSE Hotel_TRAgent.MabAgent  
                                                    * ( Hotel_TR.TedPerson  
                                                    + Hotel_TR.AdditionalPerson )  
                                                    END  
                                                ELSE Hotel_TRAgent.PercentAgent  
                                                    * ( MabKol1  
                                                    + MabKol2 )  
                                                    / 100  
                                                END  
                                        END  
                                END, 0) ,  
                    E = ISNULL(CASE tblAgent.Maliat  
                                    WHEN 1 THEN 0  
                                    ELSE CASE tblAgent.Type  
                                        WHEN 1 THEN 0  
                                        ELSE CASE Hotel_TRAgent.PercentAgent  
                                                WHEN 0  
                                                THEN dbo.Hotel_TblTime.[Percent]  
                                                    * CASE Person  
                                                    WHEN 0  
                                                    THEN Hotel_TRAgent.MabAgent  
                                                    ELSE Hotel_TRAgent.MabAgent  
                                                    * ( Hotel_TR.TedPerson  
                                                    + Hotel_TR.AdditionalPerson )  
                                                    END  
                                                ELSE Hotel_TRAgent.PercentAgent  
                                                    * ( MabKol1  
                                                    + MabKol2 )  
                                                    / 100  
                                                END  
                                        END  
                                END, 0) ,  
                    M = ISNULL(CASE tblAgent.Maliat  
                                    WHEN 0 THEN 0  
                                    ELSE CASE Hotel_TRAgent.PercentAgent  
                                        WHEN 0  
                                        THEN dbo.Hotel_TblTime.[Percent]  
                                                * CASE Person  
                                                    WHEN 0  
                                                    THEN Hotel_TRAgent.MabAgent  
                                                    ELSE Hotel_TRAgent.MabAgent  
                                                    * ( Hotel_TR.TedPerson  
                                                    + Hotel_TR.AdditionalPerson )  
                                                END  
                                        ELSE Hotel_TRAgent.PercentAgent  
                                                * MabKol1 / 100  
                                        END  
                                END, 0) ,  
                    Msh = tblAgent.Mashmol  
            FROM    dbo.Hotel_TRAgent  
                    LEFT JOIN @Room AS tblRoom ON dbo.Hotel_TRAgent.Link = tblRoom.Id  
                    LEFT JOIN Hotel_TR ON dbo.Hotel_TRAgent.Link = dbo.Hotel_TR.Id  
                    LEFT JOIN Hotel_TRDetail ON dbo.Hotel_TRAgent.Detail_Id = Hotel_TRDetail.Id  
                    LEFT JOIN @Agent AS tblAgent ON Hotel_TRDetail.Type = tblAgent.AgentId  
                                                    AND tblAgent.Row = @Loop  
                    LEFT JOIN dbo.Hotel_TblTime ON dbo.Hotel_TR.Time_Id = dbo.Hotel_TblTime.Id  
            WHERE   tblAgent.Row = @Loop  
                    AND dbo.Hotel_TRAgent.Detail_Id IN (  
                    SELECT  Id  
                    FROM    dbo.Hotel_TRDetail  
                    WHERE   Title_Id = @Reception );      
		     
            UPDATE  @Room  
            SET     Kosorat = Kosorat + ROUND(K, 0, 0) ,  
                    Ezafat = Ezafat + ROUND(E, 0, 0) ,  
                    Maliat = Maliat + ROUND(M, 0, 0) ,  
                    MabKol1 = MabKol1 + CASE Msh  
                                            WHEN 0 THEN 0  
                                            ELSE ROUND(( E + M - K ),  
                                                    0, 0)  
                                        END ,  
                    MabKol2 = MabKol2 + CASE Msh  
                                            WHEN 1 THEN 0  
                                            ELSE ROUND(( E + M - K ),  
                                                    0, 0)  
                                        END ,  
                    K = 0 ,  
                    E = 0 ,  
                    M = 0;     
		         
            SET @Loop = @Loop + 1;			     
        END;     
             
        UPDATE  tblf  
        SET     MabRoom = ISNULL(tblRoom.Mab, 0)  
        FROM    @Final AS tblf  
        LEFT JOIN ( SELECT  t.Customer ,  
                            ISNULL(SUM(t.MabKol1), 0)  
                            + ISNULL(SUM(t.MabKol2), 0) AS Mab  
                    FROM    @Room AS t  
                    GROUP BY t.Customer  
                    ) tblRoom ON tblf.Person = tblRoom.Customer;     
		     
    END;     
--*********************	     
    ELSE     
--*********************     
    BEGIN     
        UPDATE  tblf  
        SET     MabRoom = ISNULL(tblRoom.Mab, 0)  
        FROM    @Final AS tblf  
        LEFT JOIN ( SELECT  t.Customer ,  
                            SUM(t.RoomPrice)  
                            + SUM(t.PersonPrice)  
                            - SUM(t.Kosorat) AS Mab  
                    FROM    @Room AS t  
                    GROUP BY t.Customer  
                    ) tblRoom ON tblf.Person = tblRoom.Customer;    		     
    END;     
--*********************     
    UPDATE  tblf  
    SET     tblf.MabSayer = ISNULL(TblFactor.Mab, 0)  
    FROM    @Final AS tblf  
    LEFT JOIN ( SELECT  CustumCod ,  
                        ISNULL(SUM(TR.Bed), 0) - ISNULL(SUM(TR.Bes),  
                                                    0) AS Mab  
                FROM    dbo.TblFactorOnvan  
                LEFT JOIN TR ON dbo.TblFactorOnvan.ShFactor = dbo.TR.Factor  
                                AND dbo.TblFactorOnvan.Type = dbo.TR.Type  
                LEFT JOIN TRDetail ON TR.Sodor = TRDetail.Sodor  
                WHERE   TblFactorOnvan.Id1 = 1  
                        AND ( TblFactorOnvan.Id2 = @Reception  
                                OR TblFactorOnvan.Id2 = @ResNum  
                            )  
                        AND TblFactorOnvan.Type = 203  
                        AND TRDetail.Id1 = 1  
                        AND ( dbo.TRDetail.Id2 = @Reception  
                                OR dbo.TRDetail.Id2 = @ResNum  
                            )  
                GROUP BY CustumCod  
				UNION ALL
                SELECT CustomerId AS CustumCod, SUM(dt.Bed) - SUM(dt.Bes) AS Mab 
				FROM dbo.Day_Factor AS df
				INNER JOIN dbo.Day_TR AS dt ON dt.Factor=df.FactorID
				WHERE df.Type=203 AND df.SubSystem =1 AND df.Cancel=0 AND
				( df.ReceptionId= @Reception OR df.ReceptionId = @ResNum) AND dt.IdAmel=99 AND dt.Tp1=0
				GROUP BY df.CustomerId
                ) tblFactor ON tblf.Person = tblFactor.CustumCod;     
     
    UPDATE  tblf  
    SET     tblf.MabDaryaft = ISNULL(tblDaryaft.Mab, 0)  
    FROM    @Final AS tblf  
    LEFT JOIN ( SELECT  personcod ,  
                        ISNULL(SUM(TR.Bes), 0) - ISNULL(SUM(TR.Bed),  
                                                    0) AS Mab  
                FROM    TR  
                LEFT JOIN dbo.Master ON TR.Srfsl = Master.Srfsl  
                                        AND TR.Moin = Master.Moin  
                                        AND TR.HSB = Master.HSB  
                LEFT JOIN TRDetail ON TR.Sodor = TRDetail.Sodor  
                WHERE   TR.Type = 0  
                        AND Id1 = 1  
                        AND ( Id2 = @Reception  
                                OR Id2 = @ResNum  
                            )  
                GROUP BY personcod  
                ) tblDaryaft ON tblf.Person = tblDaryaft.personcod; 

	DECLARE @MabBedBes BIGINT = 0, @PersonBedBes INT 
	SET @MabBedBes = (SELECT ISNULL(SUM(Bes-Bed), 0) FROM dbo.Hotel_tblBedBes WHERE Title_Id = @Reception OR Title_Id = @ResNum) 
	SET @PersonBedBes = (SELECT Customer_Id FROM dbo.Hotel_TRTitle WHERE Id = @Reception)

	UPDATE @Final 
    SET     MabDaryaft = MabDaryaft + @MabBedBes 
	WHERE Person = @PersonBedBes 
     
    UPDATE  @Final  
    SET     Name = dbo.TblPerson.Name + ' ' + Famil  
    FROM    @Final  
	LEFT JOIN dbo.TblPerson ON Person = Sh_ozviat;     
	     
    SELECT * FROM @Final;     
     
END;     
  

GO

