INSERT INTO [dbo].[Estehlak] ([Code], [Id], [radif], [Onvan], [sharh], [type], [nerkh]) VALUES (199, 2, 1, N'', N'انواع ماشین های پرس پرس بریک وسری سازی ویژه تولید انبوه وسری سازی وامثالهم-انواع ماشین های برش وقیچی(مکانبکی هیدرولیکی وبرقی)وسری سازی ویژهتولیدانبوهوسری-انواع ماشین های ساخت ابزاروسری سازی تولیدانبوه وسری', 2, 12.500000000000000000)
INSERT INTO [dbo].[Estehlak] ([Code], [Id], [radif], [Onvan], [sharh], [type], [nerkh]) VALUES (200, 2, 2, N'', N'انواع ماشین های تراش اتوماتیک ان سی وسی  ان  ،سی وفرزاتوماتیک وسری سازی و ویژه تولیدانبوه وسری به اضافه سایر ماشین های ان سی براده برداری-انواع ماشین های تراش وفرزوصحفه تراش ودنده تراش ودریل معمولی وکل ماشین های براده برداری کارهای سری-انواع ماشین های فلزکاری ازهرچاقوسازی ،تیغه سازی ،تیغه تیزکنی ،تیغ سازی، مته سازی، سوهان سازی ،گلدازفلزات، موج دادن فلزات وتیغ صورت تراشی(تولید انبوه)', 2, 10.000000000000000000)
