INSERT INTO [dbo].[Estehlak] ([Code], [Id], [radif], [Onvan], [sharh], [type], [nerkh]) VALUES (268, 24, 1, N'', N'ماشین آلات تولید:انواع اجاق گاز وبخاری،انواع شوفاژومشعل ورادیاتوروتجهیزات حرارت مرکزی،انواع آبگرمکن،انواع کولر،فن کویل،تهویه مطبوع،چیلروتجهیزات تبرید،انواع یخچال وفریزر وماشین لباسشویی،انواع پنکه،بخاری،جاروبرقی،پلوپز،کباب پز،آرام پز،انواع ساعت دیواری،سماور،لوستر،چراغ خوراک پزی،انواع آب میوه گیری،چرخ گوشت،مخلوط کن ها،قهوه ساز ها،انواع فلاسک ها،یخ سازی وسردخانه ها،سالنهای سردکننده ونگهداری مواد غذایی وسبزیجات وموادخوراکی وسایرلوازم خانگی', 2, 10.000000000000000000)
