INSERT INTO [dbo].[Estehlak] ([Code], [Id], [radif], [Onvan], [sharh], [type], [nerkh]) VALUES (271, 25, 2, N'', N'ماشین آلات تهیه وتولید:ریخته گری لاستیک برای مصارف صنعتی (لاستیک های ضد حرارت،ضد آب،ضد الکتریسته،ضدضربه ومواردمشابه)وقالب های آن', 2, 20.000000000000000000)
INSERT INTO [dbo].[Estehlak] ([Code], [Id], [radif], [Onvan], [sharh], [type], [nerkh]) VALUES (272, 26, 1, N'', N'ماشین آلات تهیه وتولید:چرم وپوست،آماده کردن روده وسالامبور،مصنوعات چرمی،بندکفش وپارچه آستری کفش انواع کفش چرمی ولاستیکی وسوپر فلکس،انواع پوتین وچکمه،انواع کفش ترلون وپارچه ای،ورزشی وکتانی وپلاستیکی،انواع دمپایی پلاستیکی،انواع زیره کفش وصندل سایر موارد مشابه،قطعات یدکی ماشین آلات کارخانجات کفش سازی', 2, 10.000000000000000000)
INSERT INTO [dbo].[Estehlak] ([Code], [Id], [radif], [Onvan], [sharh], [type], [nerkh]) VALUES (273, 27, 1, N'', N'ماشین آلات تولید:انواع تلفن ووسایل ارتباطی،رله ها وبردها وتجهیزات پستی،کلیه تجهیزات ووسایل مخابراتی،بی سیم،دکل های محمل،پایه هاوسایر مواردمرتبط باصنعت مخابرات،', 2, 12.500000000000000000)
INSERT INTO [dbo].[Estehlak] ([Code], [Id], [radif], [Onvan], [sharh], [type], [nerkh]) VALUES (274, 28, 1, N'', N'ماشین آلات تجهیزات تولید وریخته گری: چدن وصنایع جنبی وکوره های بلند،فولادریزی مداوم ومتناوب،مواد اولیه چدن وفولاد،نورد فولاد وآهن،تیرآهن وتسمه ونبشی،سپری آرماتوروسایر محصولات نوردوفولادی ساختمانی،ورق آهن وفولادوفولادهای صنعتی،فولادهای ضدرنگ ومخصوص وسایرمواردمشابه،', 1, 8.000000000000000000)
