-- Procedure: [dbo].[sp_PayRol_TblContract_SelectSearch]
IF OBJECT_ID(N'[dbo].[sp_PayRol_TblContract_SelectSearch]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_PayRol_TblContract_SelectSearch] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_PayRol_TblContract_SelectSearch] 
	@WorkPlaceId INT
AS
BEGIN
    SELECT PayRol_TblContract.ShContract,
           PayRol_TblContract.PersonalCode,
           TblPerson.Name + ' ' + TblPerson.Famil AS NameFamil,
           TblPerson.Sh_sh,
           TblPerson.codmeli,
           PayRol_TblContract.StartDateContract,
           PayRol_TblContract.EndDateContract,
           dbo.GetDefinitionsName(PayRol_TblContract.ContractType) AS ContractType,
           PayRol_TblContract.Sharh
    FROM TblPerson
    RIGHT JOIN PayRol_TblPersonal
        ON TblPerson.Sh_ozviat = PayRol_TblPersonal.Sh_ozviat
    RIGHT JOIN PayRol_TblContract
        ON PayRol_TblPersonal.PersonalCode = PayRol_TblContract.PersonalCode
    WHERE (PayRol_TblContract.ShHokm = 0)
          AND (PayRol_TblContract.WorkPlace_Id = @WorkPlaceId)
          AND dbo.PayRol_TblPersonal.SystemState_Id <> 6
	ORDER BY ShContract;
END;



GO

