-- ==========================================================================================
-- Entity Name:	sp_PayRol_TblMKParam_UseParam
-- Author:	Mehdi Keramati
-- Create date:	05/24/2014 03:19:38 ب.ظ
-- Description:	This stored procedure is intended for deleting a specific row from PayRol_TblMKParam table
-- ==========================================================================================
ALTER PROCEDURE [dbo].[sp_PayRol_TblMKParam_UseParam]
	@Name varchar(50)
As
Begin
select ISNULL((SELECT COUNT(*) FROM PayRol_TblFormula WHERE (Formula LIKE '%' + @Name + '%')),0) + ISNULL((SELECT COUNT(*) FROM PayRol_TblMKParam WHERE (Formula LIKE '%' + @Name + '%')),0) as CountNum
End




GO

-- Procedure: [dbo].[sp_PayRol_TblRest_ShowVarizMorakhasi]
IF OBJECT_ID(N'[dbo].[sp_PayRol_TblRest_ShowVarizMorakhasi]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_PayRol_TblRest_ShowVarizMorakhasi] AS SELECT 1;');
GO








-- ==========================================================================================
-- Entity Name:	sp_PayRol_TblRest_ShowVarizMorakhasi
-- Author:	Mehdi Keramati
-- Create date:	12/22/2013 12:30:50 ب.ظ
-- Description:	This stored procedure is intended for selecting all rows from PayRol_TblRest table
-- ==========================================================================================
ALTER PROCEDURE [dbo].[sp_PayRol_TblRest_ShowVarizMorakhasi]
	@Type tinyint
As
Begin
	if(@Type=1)/*تجمیعی*/
		SELECT PayRol_TblRest.PersonalCode, TblPerson.Name + ' ' + TblPerson.Famil AS NameFamil, PayRol_TblRest.DateSabt, PayRol_TblRest.DateStart, 
                      PayRol_TblRest.DateEnd,SUM(PayRol_TblRest.Variz) as intVariz, dbo.PayRol_RestTimeToString(SUM(PayRol_TblRest.Variz),dbo.PayRol_PersonalCodeTimeKari(PayRol_TblRest.PersonalCode)) AS Variz
		FROM TblPerson RIGHT OUTER JOIN
                      PayRol_TblPersonal ON TblPerson.Sh_ozviat = PayRol_TblPersonal.Sh_ozviat RIGHT OUTER JOIN
                      PayRol_TblRest ON PayRol_TblPersonal.PersonalCode = PayRol_TblRest.PersonalCode
		WHERE (PayRol_TblRest.RestType = 1)
		GROUP BY PayRol_TblRest.PersonalCode, TblPerson.Name + ' ' + TblPerson.Famil, PayRol_TblRest.DateSabt, PayRol_TblRest.DateStart, PayRol_TblRest.DateEnd,PayRol_TblRest.TimeKari
		ORDER BY Convert(bigint,PayRol_TblRest.PersonalCode),PayRol_TblRest.DateStart
	else if(@Type=2)/*ریز*/
		SELECT PayRol_TblRest.Id, PayRol_TblRest.PersonalCode, TblPerson.Name + ' ' + TblPerson.Famil AS NameFamil, PayRol_TblRest.DateSabt, PayRol_TblRest.DateStart, 
                      PayRol_TblRest.DateEnd,PayRol_TblRest.Variz as intVariz, dbo.PayRol_RestTimeToString(PayRol_TblRest.Variz,dbo.PayRol_PersonalCodeTimeKari(PayRol_TblRest.PersonalCode)) AS Variz
		FROM TblPerson RIGHT OUTER JOIN
                      PayRol_TblPersonal ON TblPerson.Sh_ozviat = PayRol_TblPersonal.Sh_ozviat RIGHT OUTER JOIN
                      PayRol_TblRest ON PayRol_TblPersonal.PersonalCode = PayRol_TblRest.PersonalCode
		WHERE (PayRol_TblRest.RestType = 1)
		ORDER BY Convert(bigint,PayRol_TblPersonal.PersonalCode), PayRol_TblRest.DateStart
End








GO

-- Procedure: [dbo].[sp_PayRollD_RptShowAghatVam]
IF OBJECT_ID(N'[dbo].[sp_PayRollD_RptShowAghatVam]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_PayRollD_RptShowAghatVam] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_PayRollD_RptShowAghatVam] 
    @s INT , 
    @m INT , 
    @date1 VARCHAR(20) , 
    @date2 VARCHAR(20) 
AS 
    BEGIN 
 
	   UPDATE  TblVamP 
        SET     SrVam = t.Srfsl , 
                MoVam = t.Moin , 
                Hsvam = t.HSB 
        FROM    TblVamP AS v 
                INNER JOIN TR AS t ON t.Sodor = v.Sodor 
        WHERE   v.Sodor > 0 
                AND NOT ( t.Srfsl = v.SrVam 
                          AND t.Moin = v.MoVam 
                          AND t.HSB = v.Hsvam 
                        ); 
 
	IF OBJECT_ID('tempdb.dbo.#tempMande', 'U') IS NOT NULL 
    DROP TABLE #tempMande; 
     
CREATE TABLE #tempMande 
    ( 
      Srfsl INT , 
      Moin INT , 
      HSB BIGINT , 
      Mab BIGINT 
    ); 
 
	INSERT INTO #tempMande 
	SELECT Srfsl,Moin,HSB,SUM(Bed-Bes) FROM dbo.TR 
	WHERE Srfsl = @s AND Moin = @m 
	AND DateR BETWEEN @date1 AND @date2 
	GROUP BY Srfsl,Moin,HSB 
 
	IF OBJECT_ID('tempdb.dbo.#tempGhest', 'U') IS NOT NULL 
    DROP TABLE #tempGhest; 
     
CREATE TABLE #tempGhest 
    ( 
      Srfsl INT , 
      Moin INT , 
      HSB BIGINT , 
      Mab BIGINT 
    ); 
 
	INSERT INTO #tempGhest 
	SELECT SrVam,MoVam,Hsvam,SUM(MabGh-MabPass) FROM dbo.View_VamDetail 
	WHERE SrVam = @s AND MoVam = @m 
	AND DateGhest BETWEEN @date1 AND @date2  
	GROUP BY SrVam,MoVam,Hsvam 
 
 
    SELECT  tmande.Srfsl , 
            tmande.Moin , 
            tmande.HSB , 
			p.PersonGroupId, 
			ISNULL(gp.Name,'') AS PersonGroupName, 
			p.Personal_Code, 
            p.Sh_ozviat , 
            ISNULL(p.Name + ' ' + p.Famil, '') AS PersonName , 
            tmande.Mab AS Mande , 
            ISNULL(tghest.Mab, 0) AS Ghest 
    FROM    #tempMande AS tmande 
	LEFT JOIN #tempGhest AS tghest ON tmande.Srfsl = tghest.Srfsl AND tmande.Moin = tghest.Moin AND tmande.HSB = tghest.HSB 
	LEFT JOIN dbo.Master AS m ON m.Srfsl = tmande.Srfsl AND m.Moin = tmande.Moin AND m.HSB = tmande.HSB 
	LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat = m.personcod 
	LEFT JOIN dbo.TblGroupPerson AS gp ON gp.ID = p.PersonGroupId 
	WHERE ISNULL(tghest.Mab, 0)>0
 
 
    END; 

GO

-- Procedure: [dbo].[sp_PayRollD_RptShowAghatVam_Merg]
IF OBJECT_ID(N'[dbo].[sp_PayRollD_RptShowAghatVam_Merg]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_PayRollD_RptShowAghatVam_Merg] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_PayRollD_RptShowAghatVam_Merg]
  @s1 INT,
	@s2 INT,
	@m1 INT,
	@m2 INT,
	@date1 VARCHAR(20),
	@date2 VARCHAR(20)
AS
    BEGIN

       IF OBJECT_ID('tempdb.dbo.#t1', 'U') IS NOT NULL 
                DROP TABLE #t1; 
            CREATE TABLE #t1 
                ( 
                 Srfsl INT,
				 Moin INT,
				 HSB BIGINT,
				 PersonGroupId INT,
				 PersonGroupName NVARCHAR(100),
				 Personal_Code NVARCHAR(100),
				 Sh_ozviat INT,
				 PersonName NVARCHAR(1000),
				 Mande BIGINT,
				 Ghest BIGINT

                ); 


  IF OBJECT_ID('tempdb.dbo.#t2', 'U') IS NOT NULL 
                DROP TABLE #t2; 
            CREATE TABLE #t2 
                ( 
                 Srfsl INT,
				 Moin INT,
				 HSB BIGINT,
				 PersonGroupId INT,
				 PersonGroupName NVARCHAR(100),
				 Personal_Code NVARCHAR(100),
				 Sh_ozviat INT,
				 PersonName NVARCHAR(1000),
				 Mande BIGINT,
				 Ghest BIGINT

                ); 


	

INSERT INTO #t1
EXEC dbo.sp_PayRollD_RptShowAghatVam @s = @s1, -- int
    @m = @m1, -- int
    @date1 = @date1, -- varchar(20)
    @date2 = @date2 -- varchar(20)


INSERT INTO #t2
EXEC dbo.sp_PayRollD_RptShowAghatVam @s = @s2, -- int
    @m = @m2, -- int
    @date1 = @date1, -- varchar(20)
    @date2 = @date2 -- varchar(20)



        SELECT  *
        FROM    #t1
        UNION
        SELECT  *
        FROM    #t2
		ORDER BY Sh_ozviat,Srfsl,Moin,HSB

    END;


GO

-- Procedure: [dbo].[sp_PayRollD_RptShowAghatVam_Sum]
IF OBJECT_ID(N'[dbo].[sp_PayRollD_RptShowAghatVam_Sum]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_PayRollD_RptShowAghatVam_Sum] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_PayRollD_RptShowAghatVam_Sum]
	@s1 INT,
	@s2 INT,
	@m1 INT,
	@m2 INT,
	@date1 VARCHAR(20),
	@date2 VARCHAR(20)
AS
BEGIN

  IF OBJECT_ID('tempdb.dbo.#t1', 'U') IS NOT NULL 
                DROP TABLE #t1; 
            CREATE TABLE #t1 
                ( 
                 Srfsl INT,
				 Moin INT,
				 HSB BIGINT,
				 PersonGroupId INT,
				 PersonGroupName NVARCHAR(100),
				 Personal_Code NVARCHAR(100),
				 Sh_ozviat INT,
				 PersonName NVARCHAR(1000),
				 Mande BIGINT,
				 Ghest BIGINT

                ); 


  IF OBJECT_ID('tempdb.dbo.#t2', 'U') IS NOT NULL 
                DROP TABLE #t2; 
            CREATE TABLE #t2 
                ( 
                 Srfsl INT,
				 Moin INT,
				 HSB BIGINT,
				 PersonGroupId INT,
				 PersonGroupName NVARCHAR(100),
				 Personal_Code NVARCHAR(100),
				 Sh_ozviat INT,
				 PersonName NVARCHAR(1000),
				 Mande BIGINT,
				 Ghest BIGINT

                ); 


	

INSERT INTO #t1
EXEC dbo.sp_PayRollD_RptShowAghatVam @s = @s1, -- int
    @m = @m1, -- int
    @date1 = @date1, -- varchar(20)
    @date2 = @date2 -- varchar(20)


INSERT INTO #t2
EXEC dbo.sp_PayRollD_RptShowAghatVam @s = @s2, -- int
    @m = @m2, -- int
    @date1 = @date1, -- varchar(20)
    @date2 = @date2 -- varchar(20)





SELECT 
p.PersonGroupId,
ISNULL(gp.Name, '') AS PersonGroupName ,
p.Personal_Code, 
p.Sh_ozviat,
p.Name + ' ' +p.Famil AS PersonName,
SUM(ISNULL(t1.Mande,0)+ISNULL(t2.Mande,0)) AS Mande,
SUM(ISNULL(t1.Ghest,0)+ISNULL(t2.Ghest,0)) AS Ghest
FROM dbo.TblPerson AS p
LEFT JOIN #t1 AS t1 ON t1.Sh_ozviat = p.Sh_ozviat
LEFT JOIN #t2 AS t2 ON t2.Sh_ozviat = p.Sh_ozviat
LEFT JOIN dbo.TblGroupPerson AS gp ON gp.ID=  p.PersonGroupId
WHERE ISNULL(t1.Ghest,0)>0 OR ISNULL(t2.Ghest,0)>0
GROUP BY p.Personal_Code,p.Sh_ozviat,p.Name,p.Famil,gp.Name,p.PersonGroupId,gp.Name

END


GO

-- Procedure: [dbo].[sp_PayRollD_RptShowSupplierPayments]
IF OBJECT_ID(N'[dbo].[sp_PayRollD_RptShowSupplierPayments]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_PayRollD_RptShowSupplierPayments] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_PayRollD_RptShowSupplierPayments]
    @srfsl INT ,
    @moin INT ,
    @date1 VARCHAR(210) ,
    @date2 VARCHAR(100)
AS
    BEGIN


        SELECT  t.Srfsl,t.Moin,t.HSB ,
                dbo.Func_ArabicToPersian(dbo.GetSahebHesab(t.Srfsl, t.Moin, t.HSB)) AS HSBName ,
                SUM(t.Bes) MabVam ,
                SUM(vp.MabGh) AS MabGh ,
                SUM(t.Bes / v.TedAghsat) AS MabGhSublier
        FROM    dbo.TR AS t
                INNER JOIN dbo.TblVampDetail AS vp ON t.IdVam = vp.IDVam
                                                      AND t.TypepVam = vp.TypeP
                INNER JOIN dbo.TblVamP AS v ON v.IDVam = t.IdVam
                                               AND v.TypeP = t.TypepVam
        WHERE   Srfsl = @srfsl
                AND Moin = @moin
                AND t.IdVam > 0
                AND vp.DateGhest BETWEEN @date1 AND @date2
				GROUP BY t.Srfsl,t.Moin,t.HSB




    END;

GO

-- Procedure: [dbo].[Sp_RptDaryaftBN]
IF OBJECT_ID(N'[dbo].[Sp_RptDaryaftBN]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[Sp_RptDaryaftBN] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[Sp_RptDaryaftBN]
	@Taraf int
AS
BEGIN
	SELECT
	tr.sodor,
	tr.Taraf,
	tr.Srfsl,
	tr.Moin,
	tr.Hsb,
	dbo.GetSarfaslName(tr.Srfsl) AS SrfslName,
	dbo.GetMoinName(tr.Srfsl,tr.Moin) AS MoinName,
	dbo.GetHSBName(tr.Srfsl,tr.Moin,tr.HSB) AS HSBName,
	dbo.HesabToString(tr.Srfsl,tr.Moin,tr.HSB) AS Code,
	dbo.GetSahebHesab(tr.Srfsl,tr.Moin,tr.HSB) AS Saheb,
	dbo.TR.Serial,
	tr.Sharh,
	tr.Bed,
	tr.Bes,
	tr.SanadM,
	tr.DateR,
	ISNULL(dbo.TRDetail.Text,'') AS SharhSanad,
	tr.IDCheck,
	tr.TpCheck,
	ISNULL(ts.RndCode,'') AS RndCode,
	ISNULL(dbo.TblPerson.Name + ' ' + dbo.TblPerson.Famil,'') + ' ' + ISNULL(taraf.PersonName,'') AS TarafHesab,
	ISNULL(BedArz,0) AS BedArz,
	ISNULL(BesArz,0) AS BesArz,
	ISNULL(TRDetail.Nerkh,0) AS NerkhArz,
	ISNULL(arz.Name,'') AS ArzName,
	ISNULL(u.FulName,'') AS FulName,
	CASE WHEN  LEN(ISNULL(taraf.Mobile,''))>0 THEN ISNULL(taraf.Mobile,'') ELSE ISNULL(mobile.Tell,'') END AS Mobile
	FROM dbo.TR
	LEFT JOIN dbo.TRDetail ON dbo.TR.Sodor = dbo.TRDetail.Sodor
	LEFT OUTER JOIN dbo.TblSanad AS ts ON tr.SanadM = ts.Sanad
	LEFT JOIN dbo.TblPerson ON dbo.TblPerson.Sh_ozviat = tr.IDForushande
	LEFT JOIN dbo.TblArz AS arz ON arz.Id = ISNULL(dbo.TRDetail.ArzId,0)
	LEFT JOIN dbo.TblUser AS u ON u.Id = dbo.TR.GRP
	LEFT JOIN dbo.TblTaraf AS taraf ON taraf.Id = tr.Taraf AND taraf.TP = tr.TpTaraf
	LEFT JOIN dbo.Func_PersonTell_TouchFactor(2) AS mobile ON mobile.ShOzviat = dbo.TblPerson.Sh_ozviat
	WHERE Taraf=@Taraf AND TpTaraf=10 AND Tp1<100
	ORDER BY tr.Sodor
END

GO

