-- Procedure: [dbo].[sp_SearchAnbar]
IF OBJECT_ID(N'[dbo].[sp_SearchAnbar]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_SearchAnbar] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_SearchAnbar] @UserId INT
AS
    BEGIN
        DECLARE @TblGroupAnbar TABLE
            (
              IdAnbar INT ,
              Name NVARCHAR(100)
            );
        INSERT  INTO @TblGroupAnbar
                EXEC sp_TblGroupAnbar_GetAnbar @UserId;
		
        SELECT DISTINCT
                dbo.TblAnbar.ID ,
                TblAnbar.Name ,
                Officer ,
                Adress ,
                TypeAnbar ,
				ISNULL(ta.Name,'') AS TypeAnbarName,
                Sarfasl ,
                Moin ,
                Hsb ,
                Cshobe ,
				ISNULL(cs.Name,'همه شعب') AS CshobeName,
				dbo.TblAnbar.Online,
                CAST(0 AS BIT) AS Selected
        FROM    dbo.TblAnbar
                INNER JOIN @TblGroupAnbar AS GA ON dbo.TblAnbar.ID = GA.IdAnbar
				LEFT JOIN dbo.TblCompanyShobe AS cs ON cs.Id = dbo.TblAnbar.Cshobe
				LEFT JOIN dbo.TblTypeAnbar AS ta ON ta.Id = dbo.TblAnbar.TypeAnbar

    END;



GO

-- Procedure: [dbo].[sp_SearchKala]
IF OBJECT_ID(N'[dbo].[sp_SearchKala]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_SearchKala] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_SearchKala]
    @IdAnbar INT ,
    @Lable INT ,
    @ShowPriceMasraf INT = 0 ,
    @UserId INT = 0 ,
    @ShowPriceKharid INT = 0 ,
    @ShowSerial BIT = 0 ,
    @Supplier INT = 0 ,
    @ShowList INT = 0
AS
    BEGIN

		DECLARE @Permisioncount INT = 0,@Groupcount INT = 0;
		SELECT @Groupcount = COUNT(*) FROM TblGroupKala WHERE LenNextLevel=0

		IF OBJECT_ID('tempdb.dbo.#TblGroupKala', 'U') IS NOT NULL
            DROP TABLE #TblGroupKala;
        CREATE TABLE #TblGroupKala
            (
              IdAnbar INT ,
              idkala INT
            );

		SELECT @Permisioncount = COUNT(*) FROM dbo.TblGroupKalaPermision
		INNER JOIN dbo.tblGroupUsers AS tgu ON tgu.GroupId = TblGroupKalaPermision.GroupId
        WHERE tgu.UserId = @UserId
		
		IF @Permisioncount>0 AND @Permisioncount<>@Groupcount
		BEGIN
		INSERT INTO #TblGroupKala
		SELECT IDAnbar,IDKala FROM dbo.TblKala WHERE GroupCode NOT IN( 
		    SELECT Code FROM TblGroupKala WHERE LenNextLevel=0 AND Id NOT IN (
			SELECT TblGroupKala_Id FROM dbo.TblGroupKalaPermision
			INNER JOIN dbo.tblGroupUsers AS tgu ON tgu.GroupId = TblGroupKalaPermision.GroupId
			WHERE tgu.UserId = @UserId))
		END
		ELSE	
		BEGIN
			INSERT INTO #TblGroupKala
		    SELECT IDAnbar,IDKala FROM dbo.TblKala
		END
		
        EXEC dbo.UpdateTblKala;
        DECLARE @Supplier1 INT= 0 ,
            @Supplier2 INT= 99999999;

        IF ( @Supplier > 0 )
            BEGIN 
                SET @Supplier1 = @Supplier;
                SET @Supplier2 = @Supplier;
            END;

        DECLARE @ia1 INT;
        DECLARE @ia2 INT; 
        SET @ia1 = 1;
        SET @ia2 = 99999;
        IF ( @IdAnbar > 0 )
            BEGIN
                SET @ia1 = @IdAnbar;
                SET @ia2 = @IdAnbar;
            END;
	
        IF OBJECT_ID('tempdb.dbo.#TblGroupAnbar', 'U') IS NOT NULL
            DROP TABLE #TblGroupAnbar;
        CREATE TABLE #TblGroupAnbar
            (
              IdAnbar INT ,
              Name NVARCHAR(100)
            );
                
        INSERT  INTO #TblGroupAnbar
                EXEC sp_TblGroupAnbar_GetAnbar @UserId;
		
        DECLARE @count INT = 0;
        SELECT  @count = COUNT(*)
        FROM    dbo.TblGroupLabel AS gl
        INNER JOIN dbo.TblGroupUsers AS tgu ON tgu.GroupId = gl.GroupId
		WHERE tgu.UserId = @UserId

        DECLARE @labels TABLE
            (
              GroupId INT ,
              IdLabel INT
            );
        IF ( @count > 0 )
            BEGIN
                INSERT  INTO @labels
                        EXEC sp_TblGroupLabel_GetLabel @UserId;
            END;
        ELSE
            BEGIN
                INSERT  INTO @labels
                        SELECT 0 ,ID FROM dbo.TblLable;
            END;
		--بررسی آخرین خرید تجمعی
		DECLARE @lpkt BIT=1
		SELECT @lpkt = CAST(ISNULL(Value,'0') as bit) FROM dbo.TblParameters WHERE Name ='LastPriceKharid'

		--عدم نمایش مانده کالا
		-- اگر 1 باشه یعنی نمایش ندهد
		DECLARE @MandeKala BIT,@MabKh BIT
		SELECT @MandeKala=ISNULL(ug.HideMandeKala,0),@MabKh = ISNULL(ug.MabKh,0) FROM dbo.TblUser AS u
		LEFT JOIN TblUserGroup AS ug ON u.GroupId=ug.Id
		WHERE u.Id=@UserId

		--عدم نمایش سریال
        IF ( @ShowSerial = 0 )
            BEGIN
                IF ( @ShowPriceKharid = -1 )
                    BEGIN
                        EXEC dbo.SP_TblLastMabFactorKharid_Refresh;
                        SELECT  TblKala.IDAnbar ,
                                ISNULL(dbo.TblAnbar.Name, '') AS AnbarName ,
                                TblKala.IDKala ,
                                CASE WHEN LEN(TblKala.Name2)>0 THEN  TblKala.Name + ' ' + TblKala.Name2 ELSE TblKala.Name END AS Name ,
                                TblKala.Model ,
                                TblKala.IDF ,
                                TblKala.moshakhasatFani1 ,
                                TblKala.moshakhasatFani2 ,
                                ISNULL(MIN(TblBarCode.Barcod), N'') AS Barcod ,
                                '' AS Serial ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.Mande AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeKol ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeRezerv AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeRezerv ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeServer ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeT AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeErsal ,
                                CASE WHEN @MandeKala=0 THEN CAST(( ( TblKala.Mande - TblKala.MandeRezerv )
                                       - ( TblKala.MandeT ) ) + TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS Mande ,
                                CAST(ISNULL(TblPrice.Price, 0) AS BIGINT) AS Price ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN CAST(ROUND(ISNULL(TblPrice.Price, 0)
                                                     * ( ( 100.0
                                                           + ISNULL(TblKala.DarsadMaliat,0) )
                                                         / 100.0 ), 0) AS BIGINT)
                                     ELSE CAST(ISNULL(TblPrice.Price, 0) AS BIGINT)
                                END AS PriceMaliat ,
                                CAST(ISNULL(TblPriceMasraf.Price, 0) AS BIGINT) AS PriceMasraf ,
                                CAST(ISNULL(TblPriceList.Price, 0) AS BIGINT) AS PriceList ,
                                CASE @MabKh WHEN 1 THEN CASE @lpkt WHEN 0 THEN ISNULL(ISNULL(TblPriceKharid.MabKH,TblPriceKharid2.Fi), 0) 
								ELSE ISNULL(ISNULL(TblPriceKharidTagmi.MabKH,TblPriceKharidTagmi2.Fi),0) END ELSE 0 END AS PriceKharid ,
								CASE @MabKh WHEN 1 THEN CAST(TblKala.Bprice AS BIGINT) ELSE 0 END AS Bprice,
                                CAST(TblKala.U1toU2 AS FLOAT) AS U1toU2 ,
                                CAST(TblKala.U1toU3 AS FLOAT) AS U1toU3 ,
                                CAST(CAST(ROUND(TblKala.Mande
                                                / CASE WHEN TblKala.U1toU2 = 0
                                                       THEN 1
                                                       ELSE TblKala.U1toU2
                                                  END, 3) AS FLOAT) AS NVARCHAR(100))
                                + ' ' + ISNULL(u2.Name, '') AS MandeUnit2 ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN ISNULL(TblKala.DarsadMaliat,0)
                                     ELSE 0
                                END AS DarsadMaliat ,
                                CASE WHEN TblKala.maliyat = 1 THEN 'مشمول'
                                     ELSE 'غیر مشمول'
                                END AS maliyat ,
                                Lock ,
								ISNULL(u1.Name,'') AS UnitName,
                                CAST(0 AS BIT) AS Selected
                        FROM    TblKala TblKala
                                LEFT JOIN TblPrice ON TblKala.IDAnbar = TblPrice.IDAnbar
                                                            AND TblKala.IDKala = TblPrice.IDKala
                                                            AND TblPrice.IDLable = @Lable
                                                            AND TblPrice.IDLable IN (
                                                            SELECT
                                                              IdLabel
                                                            FROM
                                                              @labels )
                                LEFT JOIN TblPrice AS TblPriceMasraf ON TblKala.IDAnbar = TblPriceMasraf.IDAnbar
                                                              AND TblKala.IDKala = TblPriceMasraf.IDKala
                                                              AND TblPriceMasraf.IDLable = @ShowPriceMasraf
                                                              AND TblPriceMasraf.IDLable IN (
                                                              SELECT
                                                              IdLabel
                                                              FROM
                                                              @labels )
                                LEFT JOIN TblPrice AS TblPriceList ON TblKala.IDAnbar = TblPriceList.IDAnbar
                                                              AND TblKala.IDKala = TblPriceList.IDKala
                                                              AND TblPriceList.IDLable = @ShowList
                                                              AND TblPriceList.IDLable IN (
                                                              SELECT
                                                              IdLabel
                                                              FROM
                                                              @labels )
                                LEFT JOIN dbo.LastMabFactorKharid AS TblPriceKharid ON TblKala.IDAnbar = TblPriceKharid.IdAnbr
                                                              AND TblKala.IDKala = TblPriceKharid.IDKala
								LEFT JOIN TblLastMabFactorKharid AS TblPriceKharid2 ON TblKala.IDAnbar=TblPriceKharid2.IDAnbar 
															  AND TblKala.IDKala=TblPriceKharid2.IDKala 
								LEFT JOIN dbo.LastMabFactorKharidTagmi AS TblPriceKharidTagmi ON TblKala.IDKala = TblPriceKharidTagmi.IDKala
								LEFT JOIN dbo.TblLastMabFactorKharidTagmi AS TblPriceKharidTagmi2 ON TblKala.IDKala=TblPriceKharidTagmi2.IDKala
                                LEFT JOIN TblBarCode ON TblKala.IDAnbar = TblBarCode.IdAnbar
                                                              AND TblKala.IDKala = TblBarCode.IdKala
                                LEFT JOIN TblSerialKala ON TblSerialKala.IdAnbar = TblKala.IDAnbar
                                                              AND TblSerialKala.IdKala = TblKala.IDKala
                                LEFT JOIN dbo.TblAnbar ON TblKala.IDAnbar = dbo.TblAnbar.ID
                                INNER JOIN #TblGroupAnbar AS ga ON TblKala.IDAnbar = ga.IdAnbar
								INNER JOIN #TblGroupKala AS ka ON TblKala.IDAnbar = ka.IdAnbar AND TblKala.IDKala=ka.idkala
                                LEFT JOIN dbo.TblUnit AS u2 ON u2.ID = TblKala.Unit2
								LEFT JOIN dbo.TblUnit AS u1 ON u1.ID = TblKala.Unit1
                        WHERE   ( TblKala.IDAnbar BETWEEN @ia1 AND @ia2 )
                                AND ( ISNULL(TblKala.Supplier, 0) BETWEEN @Supplier1
                                                              AND
                                                              @Supplier2
                                      OR ISNULL(TblKala.Supplier, 0) = 0
                                    )
                        GROUP BY TblKala.IDAnbar ,
                                dbo.TblAnbar.Name ,
                                TblKala.IDKala ,
                                TblKala.Name ,
                                TblKala.Name2 ,
                                TblKala.IDF ,
                                TblKala.Model ,
                                TblKala.moshakhasatFani1 ,
                                TblKala.moshakhasatFani2 ,
                                TblKala.Mande ,
                                TblKala.MandeRezerv ,
                                TblKala.MandeS ,
                                TblKala.MandeT ,
                                TblPrice.Price ,
                                TblPriceMasraf.Price ,
                                TblPriceList.Price ,
                                TblPriceKharid.MabKH ,
								TblPriceKharid2.Fi,
								TblPriceKharidTagmi.MabKH ,
								TblPriceKharidTagmi2.Fi,
                                Lock ,
                                TblKala.U1toU2 ,
                                TblKala.U1toU3 ,
                                TblKala.maliyat ,
                                u2.Name ,
                                TblKala.maliyat ,
                                TblKala.DarsadMaliat,
								TblKala.Bprice,
								u1.Name
                        ORDER BY TblKala.IDAnbar ,
                                TblKala.IDKala
								OPTION  ( RECOMPILE );
                    END;
                ELSE
                    BEGIN
                        SELECT  TblKala.IDAnbar ,
                                ISNULL(dbo.TblAnbar.Name, '') AS AnbarName ,
                                TblKala.IDKala ,
                                CASE WHEN LEN(TblKala.Name2)>0 THEN TblKala.Name + ' - ' + TblKala.Name2 ELSE TblKala.Name END AS Name ,
                                TblKala.Model ,
                                TblKala.IDF ,
                                TblKala.moshakhasatFani1 ,
                                TblKala.moshakhasatFani2 ,
                                ISNULL(MIN(TblBarCode.Barcod), N'') AS Barcod ,
                                '' AS Serial ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.Mande AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeKol ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeRezerv AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeRezerv ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeServer ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeT AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeErsal ,
                                CASE WHEN @MandeKala=0 THEN CAST(( ( TblKala.Mande - TblKala.MandeRezerv )
                                       - ( TblKala.MandeT ) ) + TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS Mande ,
                                CAST(ISNULL(TblPrice.Price, 0) AS BIGINT) AS Price ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN CAST(ROUND(ISNULL(TblPrice.Price, 0)
                                                     * ( ( 100.0
                                                           + ISNULL(TblKala.DarsadMaliat,0) )
                                                         / 100.0 ), 0) AS BIGINT)
                                     ELSE CAST(ISNULL(TblPrice.Price, 0) AS BIGINT)
                                END AS PriceMaliat ,
                                CAST(ISNULL(TblPriceMasraf.Price, 0) AS BIGINT) AS PriceMasraf ,
                                CAST(ISNULL(TblPriceList.Price, 0) AS BIGINT) AS PriceList ,
								CASE @MabKh WHEN 1 THEN ISNULL(TblPriceKharid.Price, 0) ELSE 0 END AS PriceKharid ,
								CASE @MabKh WHEN 1 THEN CAST(TblKala.Bprice AS BIGINT) ELSE 0 END AS Bprice, 
								CAST(TblKala.Bprice AS BIGINT) AS Bprice,
                                CAST(TblKala.U1toU2 AS FLOAT) AS U1toU2 ,
                                CAST(TblKala.U1toU3 AS FLOAT) AS U1toU3 ,
                                CAST(CAST(ROUND(TblKala.Mande
                                                / CASE WHEN TblKala.U1toU2 = 0
                                                       THEN 1
                                                       ELSE TblKala.U1toU2
                                                  END, 3) AS FLOAT) AS NVARCHAR(100))
                                + ' ' + ISNULL(u2.Name, '') AS MandeUnit2 ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN ISNULL(TblKala.DarsadMaliat,0)
                                     ELSE 0
                                END AS DarsadMaliat ,
                                CASE WHEN TblKala.maliyat = 1 THEN 'مشمول'
                                     ELSE 'غیر مشمول'
                                END AS maliyat ,
                                Lock ,
								ISNULL(u1.Name,'') AS UnitName,
                                CAST(0 AS BIT) AS Selected
                        FROM    TblKala TblKala
                                LEFT JOIN TblPrice ON TblKala.IDAnbar = TblPrice.IDAnbar
                                                            AND TblKala.IDKala = TblPrice.IDKala
                                                            AND TblPrice.IDLable = @Lable
                                                            AND TblPrice.IDLable IN (
                                                            SELECT
                                                              IdLabel
                                                            FROM
                                                              @labels )
                                LEFT JOIN TblPrice AS TblPriceMasraf ON TblKala.IDAnbar = TblPriceMasraf.IDAnbar
                                                              AND TblKala.IDKala = TblPriceMasraf.IDKala
                                                              AND TblPriceMasraf.IDLable = @ShowPriceMasraf
                                                              AND TblPriceMasraf.IDLable IN (
                                                              SELECT
                                                              IdLabel
                                                              FROM
                                                              @labels )
                                LEFT JOIN TblPrice AS TblPriceList ON TblKala.IDAnbar = TblPriceList.IDAnbar
                                                              AND TblKala.IDKala = TblPriceList.IDKala
                                                              AND TblPriceList.IDLable = @ShowList
                                                              AND TblPriceList.IDLable IN (
                                                              SELECT
                                                              IdLabel
                                                              FROM
                                                              @labels )
                                LEFT JOIN dbo.TblPrice AS TblPriceKharid ON TblKala.IDAnbar = TblPriceKharid.IDAnbar
                                                              AND TblKala.IDKala = TblPriceKharid.IDKala
                                                              AND TblPriceKharid.IDLable = @ShowPriceKharid
                                LEFT JOIN TblBarCode ON TblKala.IDAnbar = TblBarCode.IdAnbar
                                                              AND TblKala.IDKala = TblBarCode.IdKala
                                LEFT JOIN TblSerialKala ON TblSerialKala.IdAnbar = TblKala.IDAnbar
                                                              AND TblSerialKala.IdKala = TblKala.IDKala
                                LEFT JOIN dbo.TblAnbar ON TblKala.IDAnbar = dbo.TblAnbar.ID
                                INNER JOIN #TblGroupAnbar AS ga ON TblKala.IDAnbar = ga.IdAnbar
								INNER JOIN #TblGroupKala AS ka ON TblKala.IDAnbar = ka.IdAnbar AND TblKala.IDKala=ka.idkala
                                LEFT JOIN dbo.TblUnit AS u2 ON u2.ID = TblKala.Unit2
								LEFT JOIN dbo.TblUnit AS u1 ON u1.ID = TblKala.Unit1
                        WHERE   ( TblKala.IDAnbar BETWEEN @ia1 AND @ia2 )
                                AND ( ISNULL(TblKala.Supplier, 0) BETWEEN @Supplier1
                                                              AND
                                                              @Supplier2
                                      OR ISNULL(TblKala.Supplier, 0) = 0
                                    )
                        GROUP BY TblKala.IDAnbar ,
                                dbo.TblAnbar.Name ,
                                TblKala.IDKala ,
                                TblKala.Name ,
                                TblKala.Name2 ,
                                TblKala.IDF ,
                                TblKala.Model ,
                                TblKala.moshakhasatFani1 ,
                                TblKala.moshakhasatFani2 ,
                                TblKala.Mande ,
                                TblKala.MandeRezerv ,
                                TblKala.MandeS ,
                                TblKala.MandeT ,
                                TblPrice.Price ,
                                TblPriceMasraf.Price ,
                                TblPriceList.Price ,
                                TblPriceKharid.Price ,
                                Lock ,
                                TblKala.U1toU2 ,
                                TblKala.U1toU3 ,
                                TblKala.maliyat ,
                                u2.Name ,
                                TblKala.maliyat ,
                                TblKala.DarsadMaliat,
								TblKala.Bprice,
								u1.Name
                        ORDER BY TblKala.IDAnbar ,
                                TblKala.IDKala
								 OPTION  ( RECOMPILE );
                    END;
            END;
		-- نمایش سریال
        ELSE
            BEGIN
                IF ( @ShowPriceKharid = -1 )
                    BEGIN
                        EXEC dbo.SP_TblLastMabFactorKharid_Refresh;
                        SELECT  TblKala.IDAnbar ,
                                ISNULL(dbo.TblAnbar.Name, '') AS AnbarName ,
                                TblKala.IDKala ,
                                CASE WHEN LEN(TblKala.Name2)>0 THEN  TblKala.Name + ' - ' + TblKala.Name2 ELSE TblKala.Name END AS Name ,
                                TblKala.Model ,
                                TblKala.IDF ,
                                TblKala.moshakhasatFani1 ,
                                TblKala.moshakhasatFani2 ,
                                ISNULL(MIN(TblBarCode.Barcod), N'') AS Barcod ,
                                ISNULL(TblSerialKala.Serial,'') AS Serial ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.Mande AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeKol ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeRezerv AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeRezerv ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeServer ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeT AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeErsal ,
                                CASE WHEN @MandeKala=0 THEN CAST(( ( TblKala.Mande - TblKala.MandeRezerv )
                                       - ( TblKala.MandeT ) ) + TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS Mande ,
                                CAST(ISNULL(TblPrice.Price, 0) AS BIGINT) AS Price ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN CAST(ROUND(ISNULL(TblPrice.Price, 0)
                                                     * ( ( 100.0
                                                           + ISNULL(TblKala.DarsadMaliat,0) )
                                                         / 100.0 ), 0) AS BIGINT)
                                     ELSE CAST(ISNULL(TblPrice.Price, 0) AS BIGINT)
                                END AS PriceMaliat ,
                                CAST(ISNULL(TblPriceMasraf.Price, 0) AS BIGINT) AS PriceMasraf ,
                                CAST(ISNULL(TblPriceList.Price, 0) AS BIGINT) AS PriceList ,
                               CASE @MabKh WHEN 1 THEN CASE @lpkt WHEN 0 THEN ISNULL(ISNULL(TblPriceKharid.MabKH,TblPriceKharid2.Fi), 0) 
								ELSE ISNULL(ISNULL(TblPriceKharidTagmi.MabKH,TblPriceKharidTagmi2.Fi),0) END ELSE 0 END AS PriceKharid ,
								CASE @MabKh WHEN 1 THEN CAST(TblKala.Bprice AS BIGINT) ELSE 0 END AS Bprice,
                                CAST(TblKala.U1toU2 AS FLOAT) AS U1toU2 ,
                                CAST(TblKala.U1toU3 AS FLOAT) AS U1toU3 ,
                                CAST(CAST(ROUND(TblKala.Mande
                                                / CASE WHEN TblKala.U1toU2 = 0
                                                       THEN 1
                                                       ELSE TblKala.U1toU2
                                                  END, 3) AS FLOAT) AS NVARCHAR(100))
                                + ' ' + ISNULL(u2.Name, '') AS MandeUnit2 ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN ISNULL(TblKala.DarsadMaliat,0)
