								LEFT JOIN dbo.LastMabFactorKharidTagmi AS TblPriceKharidTagmi ON TblKala.IDKala = TblPriceKharidTagmi.IDKala
								LEFT JOIN dbo.TblLastMabFactorKharidTagmi AS TblPriceKharidTagmi2 ON TblKala.IDKala=TblPriceKharidTagmi2.IDKala
                                LEFT JOIN TblBarCode ON TblKala.IDAnbar = TblBarCode.IdAnbar
