                                LEFT JOIN TblSerialKala ON TblSerialKala.IdAnbar = TblKala.IDAnbar
                                                              AND TblSerialKala.IdKala = TblKala.IDKala
                                LEFT JOIN dbo.TblAnbar ON TblKala.IDAnbar = dbo.TblAnbar.ID
                                INNER JOIN #TblGroupAnbar AS ga ON TblKala.IDAnbar = ga.IdAnbar
								INNER JOIN #TblGroupKala AS ka ON TblKala.IDAnbar = ka.IdAnbar AND TblKala.IDKala=ka.idkala
