                                TblKala.Model ,
                                TblKala.IDF ,
                                TblKala.moshakhasatFani1 ,
                                TblKala.moshakhasatFani2 ,
                                ISNULL(MIN(TblBarCode.Barcod), N'') AS Barcod ,
                               ISNULL(TblSerialKala.Serial,'') AS Serial ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.Mande AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeKol ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeRezerv AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeRezerv ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeServer ,
                                CASE WHEN @MandeKala=0 THEN CAST(TblKala.MandeT AS FLOAT) ELSE CAST(0 AS FLOAT) END AS MandeErsal ,
                                CASE WHEN @MandeKala=0 THEN CAST(( ( TblKala.Mande - TblKala.MandeRezerv )
                                       - ( TblKala.MandeT ) ) + TblKala.MandeS AS FLOAT) ELSE CAST(0 AS FLOAT) END AS Mande ,
                                CAST(ISNULL(TblPrice.Price, 0) AS BIGINT) AS Price ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN CAST(ROUND(ISNULL(TblPrice.Price, 0)
                                                     * ( ( 100.0
                                                           + ISNULL(TblKala.DarsadMaliat,0) )
                                                         / 100.0 ), 0) AS BIGINT)
                                     ELSE CAST(ISNULL(TblPrice.Price, 0) AS BIGINT)
