                                CAST(ISNULL(TblPriceMasraf.Price, 0) AS BIGINT) AS PriceMasraf ,
                                CAST(ISNULL(TblPriceList.Price, 0) AS BIGINT) AS PriceList ,
                                CASE @MabKh WHEN 1 THEN ISNULL(TblPriceKharid.Price, 0) ELSE 0 END AS PriceKharid ,
								CASE @MabKh WHEN 1 THEN CAST(TblKala.Bprice AS BIGINT) ELSE 0 END AS Bprice,
								CAST(TblKala.Bprice AS BIGINT) AS Bprice,
                                CAST(TblKala.U1toU2 AS FLOAT) AS U1toU2 ,
                                CAST(TblKala.U1toU3 AS FLOAT) AS U1toU3 ,
                                CAST(CAST(ROUND(TblKala.Mande
                                                / CASE WHEN TblKala.U1toU2 = 0
                                                       THEN 1
                                                       ELSE TblKala.U1toU2
                                                  END, 3) AS FLOAT) AS NVARCHAR(100))
                                + ' ' + ISNULL(u2.Name, '') AS MandeUnit2 ,
                                CASE WHEN TblKala.maliyat = 1
                                     THEN ISNULL(TblKala.DarsadMaliat,0)
                                     ELSE 0
                                END AS DarsadMaliat ,
                                CASE WHEN TblKala.maliyat = 1 THEN 'مشمول'
                                     ELSE 'غیر مشمول'
                                END AS maliyat ,
                                Lock ,
								ISNULL(u1.Name,'') AS UnitName,
                                CAST(0 AS BIT) AS Selected
                        FROM    TblKala TblKala
                                LEFT JOIN TblPrice ON TblKala.IDAnbar = TblPrice.IDAnbar
                                                            AND TblKala.IDKala = TblPrice.IDKala
                                                            AND TblPrice.IDLable = @Lable
                                                            AND TblPrice.IDLable IN (
                                                            SELECT
                                                              IdLabel
                                                            FROM
                                                              @labels )
                                LEFT JOIN TblPrice AS TblPriceMasraf ON TblKala.IDAnbar = TblPriceMasraf.IDAnbar
                                                              AND TblKala.IDKala = TblPriceMasraf.IDKala
                                                              AND TblPriceMasraf.IDLable = @ShowPriceMasraf
                                                              AND TblPriceMasraf.IDLable IN (
                                                              SELECT
                                                              IdLabel
                                                              FROM
                                                              @labels )
                                LEFT JOIN TblPrice AS TblPriceList ON TblKala.IDAnbar = TblPriceList.IDAnbar
                                                              AND TblKala.IDKala = TblPriceList.IDKala
                                                              AND TblPriceList.IDLable = @ShowList
                                                              AND TblPriceList.IDLable IN (
                                                              SELECT
                                                              IdLabel
                                                              FROM
                                                              @labels )
                                LEFT JOIN dbo.TblPrice AS TblPriceKharid ON TblKala.IDAnbar = TblPriceKharid.IDAnbar
                                                              AND TblKala.IDKala = TblPriceKharid.IDKala
                                                              AND TblPriceKharid.IDLable = @ShowPriceKharid
                                LEFT JOIN TblBarCode ON TblKala.IDAnbar = TblBarCode.IdAnbar
                                                              AND TblKala.IDKala = TblBarCode.IdKala
                                LEFT JOIN TblSerialKala ON TblSerialKala.IdAnbar = TblKala.IDAnbar
                                                              AND TblSerialKala.IdKala = TblKala.IDKala
                                LEFT JOIN dbo.TblAnbar ON TblKala.IDAnbar = dbo.TblAnbar.ID
                                INNER JOIN #TblGroupAnbar AS ga ON TblKala.IDAnbar = ga.IdAnbar
								INNER JOIN #TblGroupKala AS ka ON TblKala.IDAnbar = ka.IdAnbar AND TblKala.IDKala=ka.idkala
                                LEFT JOIN dbo.TblUnit AS u2 ON u2.ID = TblKala.Unit2
								LEFT JOIN dbo.TblUnit AS u1 ON u1.ID = TblKala.Unit1
                        WHERE   ( TblKala.IDAnbar BETWEEN @ia1 AND @ia2 )
                                AND ( ISNULL(TblKala.Supplier, 0) BETWEEN @Supplier1
                                                              AND
                                                              @Supplier2
                                      OR ISNULL(TblKala.Supplier, 0) = 0
                                    )
                        GROUP BY TblKala.IDAnbar ,
                                dbo.TblAnbar.Name ,
                                TblKala.IDKala ,
                                TblKala.Name ,
                                TblKala.Name2 ,
                                TblKala.IDF ,
                                TblKala.Model ,
                                TblKala.moshakhasatFani1 ,
                                TblKala.moshakhasatFani2 ,
                                TblKala.Mande ,
                                TblKala.MandeRezerv ,
                                TblKala.MandeS ,
                                TblKala.MandeT ,
                                TblPrice.Price ,
                                TblPriceMasraf.Price ,
                                TblPriceList.Price ,
                                TblPriceKharid.Price ,
                                TblSerialKala.Serial ,
                                Lock ,
                                TblKala.U1toU2 ,
                                TblKala.U1toU3 ,
                                TblKala.maliyat ,
                                u2.Name ,
                                TblKala.maliyat ,
                                TblKala.DarsadMaliat,
								TblKala.Bprice,
								u1.Name
                        ORDER BY TblKala.IDAnbar ,
                                TblKala.IDKala
								    OPTION  ( RECOMPILE );
                    END;
            END;
			DROP TABLE #TblGroupAnbar
			DROP TABLE #TblGroupKala
    END;

GO

-- Procedure: [dbo].[sp_TblFactor_Update]
IF OBJECT_ID(N'[dbo].[sp_TblFactor_Update]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblFactor_Update] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_TblFactor_Update]
    @shfactor INT ,
    @type INT ,
    @date VARCHAR(10) ,
    @idforoshande INT ,
    @sharh NVARCHAR(500) ,
    @nameforosh NVARCHAR(100) ,
    @CShobe INT = 0 ,
    @shift NVARCHAR(500) = '' ,
    @UserIdEdit INT = 0 ,
    @statefactor TINYINT = 0,
	@Description NVARCHAR(500) = '',
	@Serial NVARCHAR(100) = '',
	@Mobile VARCHAR(11),
	@Address NVARCHAR(200),
	@Supplier INT,
	@Driver INT,
	@Driver2 INT ,
	@Clearance INT ,
	@Clearance2 INT,
	@Visitor INT,
	@LoadDate VARCHAR(10),
	@BargeKhorouj INT,
	@Border INT,
	@Gomrok INT ,
	@WeightFactor DECIMAL(18,3),
	@Region INT,
	@PostalCode NVARCHAR(50) = NULL,
	@FactorCust NVARCHAR(50) = NULL ,
	@id1 INT = 0,
	@id2 INT = 0,
	@id3 INT = 0,
	@CodeMeli NVARCHAR(10) = NULL
AS

    UPDATE  TblFactor
    SET     ShFactor = @shfactor ,
            Type = @type ,
            Date = @date ,
            IDForoshande = @idforoshande ,
            sharh = @sharh ,
            NameForosh = @nameforosh ,
            CShobe = @CShobe ,
            [shift] = @shift ,
            UserIdEdit = @UserIdEdit ,
            StateFactor = @statefactor,
			[Description] = @Description,
			Mobile =@Mobile,
			Address = @Address,
			Supplier=@Supplier,
			Driver=@Driver,
			Driver2=@Driver2,
			Clearance=@Clearance,
			Clearance2=@Clearance2,
			Visitor = @Visitor,
			LoadDate = @LoadDate,
			BargeKhorouj = @BargeKhorouj,
			Border=@Border,
			Gomrok=@Gomrok,
			WeightFactor=@WeightFactor,
			Region=@Region,
			PostalCode = @PostalCode,
			FactorCust = @FactorCust,
			id1 = @id1 ,
			id2 = @id2 ,
			id3 = @id3,
			CodeMeli = @CodeMeli
    WHERE   ( ShFactor = @shfactor )
            AND ( Type = @type );

	IF(LEN(@Serial)>0)
	BEGIN
		IF(@type IN (202,102))
		BEGIN
			ALTER TABLE dbo.TblTRAnbar DISABLE TRIGGER ALL
			UPDATE dbo.TblTRAnbar SET Seriyal = @Serial WHERE ShFactor = @shfactor AND Type IN (102,202)
			ALTER TABLE dbo.TblTRAnbar ENABLE TRIGGER ALL
		END
		ELSE IF(@type IN (206,106))
		BEGIN
			ALTER TABLE dbo.TblTRAnbar DISABLE TRIGGER ALL
			UPDATE dbo.TblTRAnbar SET Seriyal = @Serial WHERE ShFactor = @shfactor AND Type IN (206,106)
			ALTER TABLE dbo.TblTRAnbar ENABLE TRIGGER ALL
		END
	END
    RETURN;


GO

-- Procedure: [dbo].[sp_TblFactorOnvan_CustomerVizitor]
IF OBJECT_ID(N'[dbo].[sp_TblFactorOnvan_CustomerVizitor]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblFactorOnvan_CustomerVizitor] AS SELECT 1;');
GO
--Creator: Aref Salem
--Description: 
--Date: 1405/02/31 1:13PM
ALTER PROCEDURE [dbo].[sp_TblFactorOnvan_CustomerVizitor]
    @VizitorId INT,
	@date1 VARCHAR(10),
	@date2 VARCHAR(10),
	@CntCost INT,
	@CntProject INT

AS
BEGIN

	SELECT f.CustumCod,MAX(ISNULL(p.Name + ' ' + p.Famil , N'تعریف نشده')) AS CustomerName,SUM(t.Bes-t.Bed) AS mab 
	FROM dbo.TblFactorOnvan AS f
	INNER JOIN dbo.TR AS t ON t.Factor=f.ShFactor AND t.Type=f.Type
	LEFT JOIN dbo.TblPerson AS p ON p.Sh_ozviat=f.CustumCod
	WHERE (f.VizitorID=@VizitorId OR @VizitorId=0 ) AND f.DateFactor BETWEEN @date1 AND @date2 
	AND f.Type=203 AND (t.Idkala>0 OR t.Tp1>0)
	AND (@CntCost = 0 
         OR EXISTS (
                SELECT 1 FROM dbo.TR 
                WHERE Factor = f.ShFactor 
                    AND Type = 203 
                    AND CntHaz = @CntCost)
        )
    AND (@CntProject = 0 
         OR EXISTS (
                SELECT 1 FROM dbo.TR 
                WHERE Factor = f.ShFactor 
                    AND Type = 203 
                    AND CntProject = @CntProject)
        )
	GROUP BY f.CustumCod

END

GO

-- Procedure: [dbo].[sp_TblFactorOnvan_GroupKalaVizitor]
IF OBJECT_ID(N'[dbo].[sp_TblFactorOnvan_GroupKalaVizitor]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblFactorOnvan_GroupKalaVizitor] AS SELECT 1;');
GO
--Creator: Aref Salem
--Description: 
--Date: 1405/03/2610:01AM
ALTER PROCEDURE [dbo].[sp_TblFactorOnvan_GroupKalaVizitor]
    @VizitorId INT,
	@date1 VARCHAR(10),
	@date2 VARCHAR(10),
	@CntCost INT,
	@CntProject INT,
	@CustumCod INT

AS
BEGIN
	SELECT k.GroupCode,MAX(ISNULL(gk.Name,'بدون گروه کالا')) AS GroupName,SUM(t.TED) AS ted,SUM(t.Bes-t.Bed) AS mab 
	FROM dbo.TblFactorOnvan AS f
	INNER JOIN dbo.TR AS t ON t.Factor=f.ShFactor AND t.Type=f.Type
	INNER JOIN dbo.TblKala AS k ON k.IDAnbar=t.IdAnbr AND k.IDKala=t.Idkala
	LEFT JOIN TblGroupKala AS gk ON gk.Code=k.GroupCode
	WHERE (f.VizitorID=@VizitorId OR @VizitorId=0) AND f.DateFactor BETWEEN @date1 AND @date2 
	AND f.Type=203 AND t.Idkala>0 AND (f.CustumCod=@CustumCod OR @CustumCod=0)
	AND (@CntCost = 0 
			OR EXISTS (
				SELECT 1 FROM dbo.TR 
				WHERE Factor = f.ShFactor 
					AND Type = 203 
					AND CntHaz = @CntCost)
		)
	AND (@CntProject = 0 
			OR EXISTS (
				SELECT 1 FROM dbo.TR 
				WHERE Factor = f.ShFactor 
					AND Type = 203 
					AND CntProject = @CntProject)
		)
	GROUP BY k.GroupCode
END

GO

-- Procedure: [dbo].[sp_TblFactorOnvan_InsertUpdate_Android]
IF OBJECT_ID(N'[dbo].[sp_TblFactorOnvan_InsertUpdate_Android]', N'P') IS NULL
