ALTER PROCEDURE [dbo].[sp_TblFactorOnvan_InsertUpdate_Android]
	@Factor	INT,
	@Takht INT,
	@TypeForosh INT,
	@UserID INT,
	@CShobe INT
AS
BEGIN
IF(@Factor = -1)
BEGIN
		DECLARE @dailySanad INT = 0,@Srfsl INT,@Moin INT,@HSB BIGINT,@sanadM INT = 0,@Dater NVARCHAR(10) = '',@Sharh NVARCHAR(100) = ''
		SET @Dater = dbo.GetCurrentDate();
		SELECT @dailySanad = isnull(DailySanad,0) from TblSetingSoft where Id=1
		if(@dailySanad=2)
		begin
			SELECT @sanadM = isnull(MIN(SanadM),0) FROM TR WHERE (Type in (203,104)) AND (Type Not in (103,204)) AND (DateR = @dater) AND (CShobe = @CShobe)
		end
		else if(@dailySanad=1)
		begin
			SELECT @sanadM = isnull(MIN(SanadM),0) FROM TR WHERE (DateR = @dater) and (CShobe = @CShobe)
		end
		else	
		begin
			select @sanadM = ISNULL(MAX(SanadM),0)+1 from TR 
		end
		if(@sanadM=0)
			SELECT @sanadM = ISNULL(MAX(SanadM),0)+1 from TR 
			
		
		SELECT @Srfsl=sarfasl,@Moin = moin,@HSB = hesab FROM dbo.TblDefultHesab WHERE id = 5
		
		DECLARE @Rest INT,@Salon INT,@TakhtName NVARCHAR(100) = ''
		SELECT @Rest =  Restaurant,@Salon = Salon,@TakhtName = Name FROM dbo.TblRestaurant WHERE Id = @Takht
		
		SELECT @Sharh = Name + ' ' + @TakhtName FROM dbo.TblRestaurant WHERE Restaurant = @Rest AND Salon = @Salon AND Takht = 0
		
			DECLARE @FishNumber INT = 0
				SELECT @FishNumber = ISNULL(MAX(FishNumber),0) + 1 FROM dbo.TblFactorOnvan WHERE Type = 203 AND DateFactor = @Dater

			SELECT @Factor = ISNULL(MAX(ShFactor),0) + 1 FROM dbo.TblFactorOnvan WHERE Type = 203
			INSERT INTO	 dbo.TblFactorOnvan (ShFactor,Type,CustumCod,DateFactor,TypeForush,Sharh,BargeKhoruj,Sanad,sarfasl,moin,hsb,UserIDAdd,FishNumber)
			VALUES(@Factor,203,1,@Dater,@TypeForosh,@Sharh,@Takht,@sanadM,@Srfsl,@Moin,@HSB,@UserID,@FishNumber)
			IF(@@ERROR=0)
				SELECT @Factor,@sanadM,@Srfsl,@Moin,@HSB,@Dater
END
ELSE
	INSERT INTO dbo.TblFactorOnvan_Updated
	SELECT @UserID,dbo.GetTodayNew(), TblFactorOnvan.ShFactor,
                                     TblFactorOnvan.Type,
                                     TblFactorOnvan.CustumCod,
                                     TblFactorOnvan.CustumName,
                                     TblFactorOnvan.DateFactor,
                                     TblFactorOnvan.TypeForush,
                                     TblFactorOnvan.Sharh,
                                     TblFactorOnvan.BargeKhoruj,
                                     TblFactorOnvan.Sanad,
                                     TblFactorOnvan.sarfasl,
                                     TblFactorOnvan.moin,
                                     TblFactorOnvan.hsb,
                                     TblFactorOnvan.Tashkhis,
                                     TblFactorOnvan.TasviyeSharh,
                                     TblFactorOnvan.TypePardakht,
                                     TblFactorOnvan.FactorCust,
                                     TblFactorOnvan.UserIDAdd,
                                     TblFactorOnvan.UserIDEdit,
                                     TblFactorOnvan.DatePrint,
                                     TblFactorOnvan.Driver,
                                     TblFactorOnvan.PazirandeId,
                                     TblFactorOnvan.CShobe,
                                     TblFactorOnvan.StateFactor,
                                     TblFactorOnvan.EmzaUser,
                                     TblFactorOnvan.EmzaDate,
                                     TblFactorOnvan.Mobile,
                                     TblFactorOnvan.TedPerson,
                                     TblFactorOnvan.Description,
                                     TblFactorOnvan.TypeTasviye,
                                     TblFactorOnvan.Id1,
                                     TblFactorOnvan.Id2,
                                     TblFactorOnvan.Id3,
                                     TblFactorOnvan.FactorTypeId,
                                     TblFactorOnvan.CustomerClub_Factor_Id,
                                     TblFactorOnvan.VizitorID,
                                     TblFactorOnvan.Address,
                                     TblFactorOnvan.TypeSefaresh,
                                     TblFactorOnvan.GUID,
                                     TblFactorOnvan.ClearanceId,
                                     TblFactorOnvan.ClearanceId2,
                                     TblFactorOnvan.CustumCod2,
                                     TblFactorOnvan.Driver2,
                                     TblFactorOnvan.BorderId,
                                     TblFactorOnvan.Date2,
                                     TblFactorOnvan.GomrokId,
                                     TblFactorOnvan.Moved,
                                     TblFactorOnvan.FactorOff,
                                     TblFactorOnvan.RefId,
                                     TblFactorOnvan.RegionId,
                                     TblFactorOnvan.WeightFactor,
                                     TblFactorOnvan.ChangeStateTime,
                                     TblFactorOnvan.DriverTime,
                                     TblFactorOnvan.DriveUser,
                                     TblFactorOnvan.FishNumber,
                                     TblFactorOnvan.Tell,
                                     TblFactorOnvan.CreateTime,
                                     TblFactorOnvan.FactorSite,
                                     TblFactorOnvan.PostalCode,
                                     TblFactorOnvan.DiscountState,
                                     TblFactorOnvan.CodeMeli,
                                     TblFactorOnvan.ShiftId,
                                     TblFactorOnvan.BPMS_InvTitleId,
                                     TblFactorOnvan.Longitude,
                                     TblFactorOnvan.Latitude,
                                     TblFactorOnvan.GharardadNumber,
                                     TblFactorOnvan.IrTaxId,
                                     TblFactorOnvan.RefFactor,
                                     TblFactorOnvan.RefFactorYear,
                                     TblFactorOnvan.HamlStatus,
                                     TblFactorOnvan.ShBar,
                                     TblFactorOnvan.SerialBar,
                                     TblFactorOnvan.DateBar, TblFactorOnvan.ModatTasviye, TblFactorOnvan.CarNumber FROM dbo.TblFactorOnvan WHERE ShFactor = @Factor AND Type = 203
	UPDATE dbo.TblFactorOnvan SET UserIDEdit = @UserID WHERE ShFactor = @Factor AND Type = 203
	IF(@@ERROR=0)
		SELECT ShFactor,Sanad,sarfasl,moin,hsb,DateFactor FROM TblFactorOnvan WHERE ShFactor = @Factor AND Type = 203
		
	
		
	
	
	
END

GO

-- Procedure: [dbo].[sp_TblFactorOnvan_KalaVizitor]
IF OBJECT_ID(N'[dbo].[sp_TblFactorOnvan_KalaVizitor]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblFactorOnvan_KalaVizitor] AS SELECT 1;');
GO
--Creator: Aref Salem
--Description: 
--Date: 1405/02/31 1:13PM
ALTER PROCEDURE [dbo].[sp_TblFactorOnvan_KalaVizitor]
    @VizitorId INT,
	@date1 VARCHAR(10),
	@date2 VARCHAR(10),
	@CntCost INT,
	@CntProject INT,
	@CustumCod INT

AS
BEGIN

	SELECT t.IdAnbr AS idanbar,MAX(a.Name) AS anbarname,t.Idkala,MAX(k.Name) AS KalaName,SUM(t.TED) AS ted,MAX(ISNULL(u.Name , 'مشخص نشده')) AS UnitName,SUM(t.Bes-t.Bed) AS mab 
	FROM dbo.TblFactorOnvan AS f
	INNER JOIN dbo.TR AS t ON t.Factor=f.ShFactor AND t.Type=f.Type
	INNER JOIN dbo.TblKala AS k ON k.IDAnbar=t.IdAnbr AND k.IDKala=t.Idkala
	INNER JOIN dbo.TblAnbar AS a ON a.ID=t.IdAnbr
	left JOIN dbo.TblUnit AS u ON u.ID=k.Unit1
	WHERE (f.VizitorID=@VizitorId OR @VizitorId=0) AND f.DateFactor BETWEEN @date1 AND @date2 
	AND f.Type=203 AND t.Idkala>0 AND (f.CustumCod=@CustumCod OR @CustumCod=0)
	AND (@CntCost = 0 
			OR EXISTS (
				SELECT 1 FROM dbo.TR 
				WHERE Factor = f.ShFactor 
					AND Type = 203 
					AND CntHaz = @CntCost)
		)
	AND (@CntProject = 0 
			OR EXISTS (
				SELECT 1 FROM dbo.TR 
				WHERE Factor = f.ShFactor 
					AND Type = 203 
					AND CntProject = @CntProject)
		)
	GROUP BY t.IdAnbr,t.Idkala

END

GO

-- Procedure: [dbo].[sp_TblGroupAgent_SelectGroupAgent]
IF OBJECT_ID(N'[dbo].[sp_TblGroupAgent_SelectGroupAgent]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblGroupAgent_SelectGroupAgent] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_TblGroupAgent_SelectGroupAgent]
	@GroupIds NVARCHAR(100),
	@AgentId INT,
	@Factor INT,
	@Type INT

AS
BEGIN
	DECLARE @Mab BIGINT  = 0
	SELECT @Mab = ABS(ISNULL(SUM(Bed-Bes),0)) FROM dbo.TR
	LEFT JOIN dbo.TRDetail ON dbo.TR.Sodor = dbo.TRDetail.Sodor
	WHERE dbo.TR.Factor = @Factor AND dbo.TR.Type = @Type AND ISNULL(dbo.TRDetail.Tag2,0) = @AgentId
	
	DECLARE @c INT = 0
	SELECT @c = COUNT(*) FROM TblGroupAgent WHERE Agent_Id = @AgentId AND Group_Id IN (SELECT * FROM dbo.CSVToTable(@GroupIds))
	IF(@c>0)
		SELECT ISNULL(MAX(MaxMab),0) AS MaxMab,ISNULL(MIN(MinMab),0) AS MinMab,@Mab AS Mab FROM dbo.TblGroupAgent WHERE Agent_Id = @AgentId AND Group_Id IN (SELECT * FROM dbo.CSVToTable(@GroupIds))
	ELSE
		SELECT MaxMab,MinMab,0 AS Mab FROM dbo.TblGroupAgent WHERE Agent_Id = @AgentId AND Group_Id IN (SELECT * FROM dbo.CSVToTable(@GroupIds))
END



GO

