	(N'FactorBack',N'مرجوعی'),
	(N'ReceivePayment',N'دریافت وجه'),
	(N'Payment',N'پرداخت وجه'),
	(N'ReciveDeposite',N'دریافت بیعانه'),
	(N'DepositePayment',N'پرداخت بیعانه'),
	(N'DepositeStatement',N'صورت حساب بیعانه'),
	(N'Statement',N'صورت حساب'),
	(N'SearchKala',N'جستجوی کالا')
	SELECT m.Name,m.FarsiName,CAST(CASE WHEN ISNULL(g.GroupId,0)>0 THEN 1 ELSE 0 END AS BIT) AS Selected FROM dbo.TblClient_Menu AS m 
LEFT JOIN dbo.TblGroupMenu_Client AS g ON m.Name = g.Client_MenuName AND g.GroupId = @GroupId 
END    

GO

-- Procedure: [dbo].[sp_TblMiddelFactorTaxGov_Insert]
IF OBJECT_ID(N'[dbo].[sp_TblMiddelFactorTaxGov_Insert]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblMiddelFactorTaxGov_Insert] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_TblMiddelFactorTaxGov_Insert]
    @FactorId INT ,
    @FactorType TINYINT ,
    @ReferenceNumber NVARCHAR(1000) ,
    @MSGERROR NVARCHAR(MAX) ,
    @StatusId NVARCHAR(100) ,
    @CreateUser INT ,
	@Id int	OUT,
    @TaxId NVARCHAR(100) ,
    @TokenTaxGov NVARCHAR(50) ,
    @RandomSerial BIGINT ,
    @SavedDateFactor NVARCHAR(50) ,
    @insId TINYINT ,
    @bid VARCHAR(20) = NULL ,
    @tinb VARCHAR(20) = NULL ,
    @bpc VARCHAR(20) = NULL ,
    @JsonCode NVARCHAR(MAX) = NULL ,
    @IrTaxid NVARCHAR(100) = NULL ,
    @PersonId INT = 0 ,
    @PersonName NVARCHAR(50) ,
    @bbc VARCHAR(50) = NULL ,
    @intyId TINYINT ,
    @inpId TINYINT ,
    @inno VARCHAR(10) ,
    @tob INT ,
    @tins VARCHAR(20) ,
    @sbc VARCHAR(20) ,
    @setm INT ,
	@SerialNumber BIGINT,
	@Cancel BIT,
	@tprdis BIGINT,
	@tdis BIGINT,
	@tadis BIGINT,
	@tvam BIGINT,
	@tbill BIGINT,
	@RefFactor INT,
	@RefFactorYear INT,
	@cap BIGINT,
	@insp BIGINT,
	@Flag TINYINT ,
    @Checked TINYINT ,
	@detailtax DetailTax READONLY

AS
    BEGIN
		BEGIN TRAN t1
		DECLARE @c INT = 0
		DECLARE @msg NVARCHAR(500) = ''
		SELECT @c = COUNT(*) FROM dbo.TblMiddelFactorTaxGov WHERE TaxId = @TaxId
		IF(@c>0)
		BEGIN
			ROLLBACK
			SET @msg = 'شماره منحصر به فرد مالیاتی '+@TaxId+'قبلا ثبت شده است'
			RAISERROR(@msg,16,1)
			RETURN
		END
        INSERT  INTO dbo.TblMiddelFactorTaxGov
                ( FactorId ,
                  FactorType ,
                  ReferenceNumber ,
                  MSGERROR ,
                  StatusId ,
                  CreateTime ,
                  CreateUser ,
                  TaxId ,
                  TokenTaxGov ,
                  RandomSerial ,
                  SavedDateFactor ,
                  insId ,
                  bid ,
                  tinb ,
                  bpc ,
                  JsonCode ,
                  IrTaxid ,
                  PersonId ,
                  PersonName ,
                  bbc ,
                  intyId ,
                  inpId ,
                  inno ,
                  tob ,
                  tins ,
                  sbc ,
                  setm,
				  SerialNumber,
				  Cancel,
				  tprdis,
				  tdis,
				  tadis,
				  tvam,
				  tbill,
				  RefFactor,
				  RefFactorYear,
				  cap,
				  insp,
				  Flag,
				  Checked

	            )
        VALUES  ( @FactorId ,
                  @FactorType ,
                  @ReferenceNumber ,
                  @MSGERROR ,
                  @StatusId ,
                  dbo.GetTodayNewTax() ,
                  @CreateUser ,
                  @TaxId ,
                  @TokenTaxGov ,
                  @RandomSerial ,
                  @SavedDateFactor ,
                  @insId ,
                  @bid ,
                  @tinb ,
                  @bpc ,
                  @JsonCode ,
                  @IrTaxid ,
                  @PersonId ,
                  @PersonName ,
                  @bbc ,
				  @intyId ,
                  @inpId ,
                  @inno ,
                  @tob ,
                  @tins ,
                  @sbc ,
                  @setm ,
				  @SerialNumber,
				  @Cancel,
				  @tprdis,
				  @tdis,
				  @tadis,
				  @tvam,
				  @tbill,
				  @RefFactor,
				  @RefFactorYear,
				  @cap,
				  @insp,
				  @Flag,
				  @Checked
	            );
				IF(@@ERROR<>0)
				BEGIN
					ROLLBACK
					RETURN
				END

				DECLARE @TblMiddelFactorTaxGov_Id INT = 0
				SELECT @TblMiddelFactorTaxGov_Id = @@IDENTITY

				SELECT @Id = @TblMiddelFactorTaxGov_Id


				INSERT INTO dbo.TblMiddelFactorDetailTaxGov
					SELECT @TblMiddelFactorTaxGov_Id,* FROM @detailtax
					IF(@@ERROR<>0)
					BEGIN
						ROLLBACK
						RETURN
					END


			COMMIT TRAN t1
    END;









GO

