ALTER PROCEDURE [dbo].[sp_TblMiddelFactorTaxGov_Update]
	@FactorId int,
	@FactorType TINYINT,
	@ReferenceNumber nvarchar(1000),
	@MSGERROR nvarchar(MAX),
	@StatusId nvarchar(50),
	@ModifyUser int,
	@Id int,
	@TaxId nvarchar(100),
	@TokenTaxGov nvarchar(50),
	@RandomSerial bigint,
	@SavedDateFactor nvarchar(50),
	@insId tinyint,
	@bid varchar(20),
	@tinb varchar(20),
	@bpc varchar(20),
	@JsonCode nvarchar(MAX),
	@IrTaxid nvarchar(100),
	@PersonId int,
	@PersonName nvarchar(100),
	@bbc varchar(50),
	@intyId tinyint,
	@inpId tinyint,
	@inno varchar(10),
	@tob tinyint,
	@tins varchar(20),
	@sbc varchar(20),
	@setm tinyint,
	@SerialNumber bigint,
	@Cancel bit,
	@LastInquiry bit,
	@tprdis bigint,
	@tdis bigint,
	@tadis bigint,
	@tvam bigint,
	@tbill bigint,
	@RefFactor int,
	@RefFactorYear int,
	@cap bigint,
	@insp bigint,
	@Flag tinyint,
	@Checked tinyint
As
Begin
	Update TblMiddelFactorTaxGov
	Set
		[FactorId] = @FactorId,
		[FactorType] = @FactorType,
		[ReferenceNumber] = @ReferenceNumber,
		[MSGERROR] = @MSGERROR,
		[StatusId] = @StatusId,
		[ModifyTime] = dbo.GetTodayNewTax(),
		[ModifyUser] = @ModifyUser,
		[TaxId] = @TaxId,
		[TokenTaxGov] = @TokenTaxGov,
		[RandomSerial] = @RandomSerial,
		[SavedDateFactor] = @SavedDateFactor,
		[insId] = @insId,
		[bid] = @bid,
		[tinb] = @tinb,
		[bpc] = @bpc,
		[JsonCode] = @JsonCode,
		[IrTaxid] = @IrTaxid,
		[PersonId] = @PersonId,
		[PersonName] = @PersonName,
		[bbc] = @bbc,
		[intyId] = @intyId,
		[inpId] = @inpId,
		[inno] = @inno,
		[tob] = @tob,
		[tins] = @tins,
		[sbc] = @sbc,
		[setm] = @setm,
		[SerialNumber] = @SerialNumber,
		[Cancel] = @Cancel,
		[LastInquiryDate] = CASE WHEN @LastInquiry = 1 THEN dbo.GetTodayNewTax() ELSE [LastInquiryDate] END,
		[tprdis] = @tprdis,
		[tdis] = @tdis,
		[tadis] = @tadis,
		[tvam] = @tvam,
		[tbill] = @tbill,
		[RefFactor] = @RefFactor,
		[RefFactorYear] = @RefFactorYear,
		[cap] = @cap,
		[insp] = @insp,
		[Flag] = @Flag,
		[Checked] = @Checked
	Where		
		[Id] = @Id

End

