-- Procedure: [dbo].[sp_TblPerson_SelectRow]
IF OBJECT_ID(N'[dbo].[sp_TblPerson_SelectRow]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblPerson_SelectRow] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_TblPerson_SelectRow] @Sh_ozviat INT
AS
    BEGIN
        DECLARE @cshobecom INT = 0;
        SELECT  @cshobecom = CShobe
        FROM    dbo.TblCompany
        WHERE   Id = 1;
        DECLARE @Tell NVARCHAR(100) = '' ,
            @Mobile NVARCHAR(100) = '' ,
            @Pelak NVARCHAR(100) = '' ,
            @CardId NVARCHAR(100) = '' ,
            @Address NVARCHAR(1000) = '' ,
            @HsbNumber NVARCHAR(100) = '' ,
            @ShabaNumber NVARCHAR(100) = '' ,
            @post NVARCHAR(100) = '' ,
            @DarsadKarmozd NVARCHAR(100) = '';
        SELECT TOP ( 1 )
                @Tell = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 1
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @Mobile = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 2
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @Pelak = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 3
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @CardId = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 4
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @Address = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 5
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @post = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 6
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @HsbNumber = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 7
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @ShabaNumber = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 8
        ORDER BY Id DESC;
        SELECT TOP ( 1 )
                @DarsadKarmozd = Tell
        FROM    dbo.TblPersonTell
        WHERE   ShOzviat = @Sh_ozviat
                AND Type = 9
        ORDER BY Id DESC;
        SELECT  Sh_ozviat ,
                Name AS Name ,
                Famil ,
                Sh_sh ,
                FatherName ,
                TblPerson.Srfsl ,
                TblPerson.Moin ,
                Hesab ,
                mahaleSodur ,
                Dt_Tavalod ,
                @Tell AS Tell ,
                @Address AS Addres_mk ,
                @Address AS Addres_home ,
                job ,
                @post AS post ,
                Cod_Egh ,
                codmeli ,
                Type ,
                @Mobile AS Mobile ,
                AliasName ,
                group_Id ,
                Etebar AS Etebar ,
                CityId ,
                InsurerId ,
                PersonGroupId ,
                Status ,
                MarketerPercent ,
                BlackList ,
                BlackListDesc ,
                SystemCode ,
                Email ,
                Website ,
                MarriageDate ,
                AutomaticSMS ,
                EtebarM ,
                HoghoghM ,
                ISNULL(pn.Value, '') AS PreNameValue ,
                PreName AS PreNameId ,
                DarsadEtebar ,
                CASE WHEN @cshobecom > 0 THEN @cshobecom
                     ELSE CShobe
                END AS Cshobe ,
                IDLable ,
                DureTasviye ,
                RegionId ,
                @Pelak AS Pelak ,
                @CardId AS CardId ,
                Kala_Score ,
                CreateUser ,
                CreateTime ,
                ModifyUser ,
                ModifyTime ,
                PersonGroupId2 ,
                PersonGroupId3 ,
                PersonGroupId3 ,
                PersonGroupId4 ,
                Note ,
                BuyerType ,
                CntCost ,
                CntProject ,
                Personal_Code ,
                @HsbNumber AS HsbNumber ,
                @ShabaNumber AS ShabaNumber ,
                EtebarGM ,
                CodeShobe ,
                @DarsadKarmozd AS DarsadKarmozd ,
                SrfslTaraf ,
                MoinTaraf ,
                SrfslP ,
                MoinP ,
                HesabP
        FROM    TblPerson
                LEFT OUTER JOIN dbo.TblPreName AS pn ON pn.Id = TblPerson.PreName
        WHERE   [Sh_ozviat] = @Sh_ozviat;
    END;

GO

-- Procedure: [dbo].[Sp_TblPishFactorConvartOrderBuy]
IF OBJECT_ID(N'[dbo].[Sp_TblPishFactorConvartOrderBuy]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[Sp_TblPishFactorConvartOrderBuy] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[Sp_TblPishFactorConvartOrderBuy]
@ShFactor INT ,
@CShobe INT 
AS
BEGIN
	Declare @MinCShobe int=0,@MinIdAnbar int=0,@MaxCShobe int=2147483647,@MaxIdAnbar int=2147483647 
	IF(@CShobe>0) 
	BEGIN 
		Set @MinCShobe=@CShobe 
		set @MaxCShobe=@CShobe 
	END 
	
	IF OBJECT_ID('tempdb.dbo.#temp', 'U') IS NOT NULL
            DROP TABLE #temp;
        CREATE TABLE #temp
            (
                TblPishFactor_Id INT,
				TED NUMERIC(18,3),
				TED2 NUMERIC(18,3)
            );


	INSERT INTO #temp
	SELECT t.TblPishFactor_Id,SUM(t.TED),SUM(t.Tedad2) FROM (
	SELECT TblPishFactor_Id,Ted,Tedad2 FROM dbo.TblOrderBuy
	WHERE TblPishFactor_Id>0)
	AS t
	GROUP BY t.TblPishFactor_Id

	SELECT 
	tp.Id,
	tp.IdAnbar,
	ISNULL(ta.Name,'') as AnbarName, 
	ISNULL(tk.IDKala,'') as IDKala, 
	ISNULL(tk.Name,'') as KalaName, 
	tp.Serial,
	dbo.RoundDecimalPishFactor(tp.Ted,0) as TedKol, 
	dbo.RoundDecimalPishFactor(tp.Ted - ISNULL(temp.Ted,0),0) as TedMandeMain, 
	dbo.RoundDecimalPishFactor(tp.Ted - ISNULL(temp.Ted,0),tp.nerkh) as TedOut, 
	CAST (0 AS DECIMAL(18,3)) AS Mande, 
	tp.Ted - ISNULL(temp.Ted,0) AS Ted, 
	tp.Ted2-ISNULL(temp.TED2,0) AS Ted2,
	dbo.GetUnit(tp.IdAnbar,tp.IdKala, tp.Unit) as UnitName, 
	tp.Nerkh,
	tp.CntHaz, 
	tp.CntProject,
	0 AS Fi,
	tp.Text AS Text,
	cast(1 as bit) as Tik, 
	'' as Event 
	from TblPishFactor as tp
	LEFT JOIN TblFactorOnvan AS TFO ON tp.Type = TFO.Type AND tp.Factor=TFO.ShFactor 
	LEFT JOIN TblAnbar as ta on tp.IdAnbar=ta.ID 
	LEFT JOIN TblKala as tk on tp.IdKala=tk.IDKala and tp.IdAnbar=tk.IDAnbar
	LEFT JOIN #temp AS temp ON tp.Id=temp.TblPishFactor_Id

	where Factor=@ShFactor  and not exists (select * from tr where tp.Id=TR.TblPishFactor_Id) AND ((tp.CShobe = 0) OR (tp.CShobe between @MinCShobe and @MaxCShobe)) AND (tp.IdAnbar between @MinIdAnbar AND @MaxIdAnbar) and tp.IdAnbar>0 and tp.IdKala> 0
	GROUP BY tp.id,ta.Name,tk.IDKala,tk.Name,tp.Nerkh,tp.Ted,tp.IdAnbar,tp.IdKala,tp.Unit,tp.Serial,temp.TED,temp.TED2,tp.Text,
	tp.CntHaz,tp.CntProject,tp.Bes,tp.Ted2
	HAVING 	tp.Ted - ISNULL(temp.Ted,0)>0 
END


GO

-- Procedure: [dbo].[sp_TblReport_ShowElectronicledger]
IF OBJECT_ID(N'[dbo].[sp_TblReport_ShowElectronicledger]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TblReport_ShowElectronicledger] AS SELECT 1;');
GO
	

ALTER PROCEDURE [dbo].[sp_TblReport_ShowElectronicledger]
	@DateElectronicledger1 NVARCHAR(100),
	@DateElectronicledger2 NVARCHAR(100)
AS
BEGIN
	DECLARE @n BIGINT = 0
	SELECT @n = ISNULL(SUM(Bed-Bes),0) FROM dbo.TR
	WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2
	IF(@n=0)
	BEGIN

		DECLARE @ts TABLE(DateR NVARCHAR(100),TP INT,Id INT IDENTITY)
		INSERT INTO @ts
		SELECT * FROM (
		SELECT t.DateR AS DateR,1 AS TP FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND ISNULL(s.TypeSanad,0) = 2
		GROUP BY t.DateR
		UNION ALL
		SELECT t.DateR AS DateR,2 AS TP FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND ISNULL(s.TypeSanad,0) NOT IN (2,3)
		GROUP BY t.DateR
		UNION ALL
		SELECT t.DateR AS DateR,3 AS TP FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND ISNULL(s.TypeSanad,0) = 3
		GROUP BY t.DateR) AS res
		ORDER BY res.TP,res.DateR

		SELECT 
		ts.Id AS 'ردیف',
		Res.DateR N'تاریخ',
		Res.Srfsl N'کد_حساب_کل',
		ISNULL(psrfsl.Name,'')  N'عنوان_حساب_کل',
		0 N'کد_حساب_معین',
		'' AS N'عنوان_حساب_معین',
		'' N'شرح',
		Res.Bed AS N'مبلغ_بدهکار_(ریال)',
		Res.Bes AS N'مبلغ_بستانکار_(ریال)'
		 FROM (
		SELECT t.DateR,Srfsl,1 AS TP,SUM(Bed) AS Bed,0 AS Bes FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND Bed>0 AND ISNULL(s.TypeSanad,0) = 2
		GROUP BY t.DateR,Srfsl
		UNION ALL
		SELECT t.DateR,Srfsl,1 AS TP,0 AS Bed,SUM(Bes) AS Bes FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND Bes>0 AND ISNULL(s.TypeSanad,0) = 2
		GROUP BY t.DateR,Srfsl
		UNION ALL
		SELECT t.DateR AS DateR,Srfsl,2 AS TP,SUM(Bed) AS Bed,0 AS Bes FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND Bed>0 AND ISNULL(s.TypeSanad,0) NOT IN (2,3)
		GROUP BY t.DateR,Srfsl
		UNION ALL
		SELECT t.DateR AS DateR,Srfsl,2 AS TP,0 AS Bed,SUM(Bes) AS Bes FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND Bes>0 AND ISNULL(s.TypeSanad,0) NOT IN (2,3)
		GROUP BY t.DateR,Srfsl
		UNION ALL
		SELECT t.DateR,Srfsl,3 AS TP,SUM(Bed) AS Bed,0 AS Bes FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND Bed>0 AND ISNULL(s.TypeSanad,0) = 3
		GROUP BY t.DateR,Srfsl
		UNION ALL
		SELECT t.DateR,Srfsl,3 AS TP,0 AS Bed,SUM(Bes) AS Bes FROM dbo.TR AS t
		LEFT JOIN dbo.TblSanad AS s ON s.Sanad = t.SanadM
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2 AND Bes>0 AND ISNULL(s.TypeSanad,0) = 3
		GROUP BY t.DateR,Srfsl) AS Res
		LEFT JOIN dbo.TblParam AS psrfsl ON psrfsl.Srfsl = Res.Srfsl AND psrfsl.Moin = 0
		LEFT JOIN @ts AS ts ON ts.DateR = res.DateR AND ts.TP = res.TP
		ORDER BY Res.TP,Res.DateR,Res.Bes,Res.Bed,Res.Srfsl
	END
	ELSE
	BEGIN
		SELECT SanadM سند,DateR تاریخ_سند,ABS(SUM(Bed-Bes)) AS مبلغ_ناتراز,'سند تراز نیست' AS خطا FROM dbo.TR
		WHERE DateR BETWEEN @DateElectronicledger1 AND @DateElectronicledger2
		GROUP BY SanadM,DateR
		HAVING SUM(Bed-Bes)<>0
	END
END


GO

-- Procedure: [dbo].[sp_tblreport_ShowFactorsMoved]
IF OBJECT_ID(N'[dbo].[sp_tblreport_ShowFactorsMoved]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_tblreport_ShowFactorsMoved] AS SELECT 1;');
GO

ALTER PROCEDURE [dbo].[sp_tblreport_ShowFactorsMoved]
    @DFrom NVARCHAR(10) = NULL,   -- فیلتر اختیاری: از تاریخ
    @DTo NVARCHAR(10) = NULL,     -- فیلتر اختیاری: تا تاریخ
    @CShobe INT = 0,              -- فیلتر اختیاری: کد شعبه (0 یعنی تمام شعب)
    @IdKala INT = 0               -- فیلتر اختیاری: کد کالا (0 یعنی تمام کالاها)
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    -- ۱. تجمیع و انطباق سطور خروج (مبدأ) و ورود (مقصد) فاکتورهای جابجایی شعب
    WITH TransferData AS (
        SELECT 
            tr.CShobe,
            tr.DateR,
            tr.Factor,
            tr.Idkala,
            -- تشخیص انبار مبدأ (سمت خروج جابجایی - Type=201 یا بستانکار انبار)
            MAX(CASE WHEN tr.Type IN (201, 202) OR tr.Bes > 0 THEN tr.IdAnbr END) AS IdAnbarMabda,
            -- تشخیص انبار مقصد (سمت ورود جابجایی - Type=101 یا بدهکار انبار)
            MAX(CASE WHEN tr.Type IN (101, 102) OR tr.Bed > 0 THEN tr.IdAnbr END) AS IdAnbarMaghsad,
            -- محاسبه دقیق تعداد جابجایی
            CASE 
                WHEN SUM(CASE WHEN tr.Type IN (201, 202) OR tr.Bes > 0 THEN tr.TED ELSE 0 END) > 0 
                THEN SUM(CASE WHEN tr.Type IN (201, 202) OR tr.Bes > 0 THEN tr.TED ELSE 0 END)
                ELSE MAX(tr.TED)
            END AS Tedad
        FROM dbo.TR AS tr WITH (NOLOCK)
        WHERE LEN(tr.Factor) = 8 
          AND tr.TRMiddle_ID > 0
          AND (@DFrom IS NULL OR @DFrom = '' OR tr.DateR >= @DFrom)
          AND (@DTo IS NULL OR @DTo = '' OR tr.DateR <= @DTo)
          AND (@CShobe = 0 OR tr.CShobe = @CShobe)
          AND (@IdKala = 0 OR tr.Idkala = @IdKala)
        GROUP BY tr.CShobe, tr.DateR, tr.Factor, tr.Idkala
    ),
    -- ۲. استخراج نام یکتای کالا جهت جلوگیری از دوگانگی بر اساس انبار
    DistinctKala AS (
        SELECT 
            IDKala, 
            MAX(Name) AS KalaName
        FROM dbo.TblKala WITH (NOLOCK)
        GROUP BY IDKala
    )
    -- ۳. خروجی نهایی گزارش جابجایی کالا بین انبارها
    SELECT 
        c.Name AS [شعبه],
        t.DateR AS [تاریخ],
        t.Factor AS [شماره فاکتور جابجایی],
        t.Idkala AS [کد کالا],
        ISNULL(k.KalaName, N'کالای نامشخص') AS [اسم کالا],
        ISNULL(aMabda.Name, N'نامشخص') AS [انبار مبدا],
        ISNULL(aMaghsad.Name, N'نامشخص') AS [انبار مقصد],
        t.Tedad AS [تعداد]
    FROM TransferData AS t
    LEFT JOIN dbo.TblCompanyShobe AS c WITH (NOLOCK) ON t.CShobe = c.Id
    LEFT JOIN DistinctKala AS k ON t.Idkala = k.IDKala
    LEFT JOIN dbo.TblAnbar AS aMabda WITH (NOLOCK) ON t.IdAnbarMabda = aMabda.ID
    LEFT JOIN dbo.TblAnbar AS aMaghsad WITH (NOLOCK) ON t.IdAnbarMaghsad = aMaghsad.ID
    ORDER BY t.DateR DESC, c.Name, t.Factor, k.KalaName;
END;

GO

