	DECLARE @V BIT = 0
	DECLARE @ip INT = 0
	SELECT @V = ISNULL(CAST(Value AS BIT),0) FROM dbo.TblParameters WHERE Name = 'TblPersonTell'
	IF(@V = 0)
	BEGIN

		INSERT INTO dbo.TblPersonTell
				( ShOzviat, Tell, Type )
		SELECT Sh_ozviat,LTRIM(RTRIM(Addres_home))  AS Tell,5 AS Type FROM dbo.TblPerson WHERE LEN(LTRIM(RTRIM(Addres_home)))>0
		AND NOT EXISTS (SELECT * FROM dbo.TblPersonTell WHERE Type = 5 AND LTRIM(RTRIM(Tell)) = LTRIM(RTRIM(Addres_home)))

		INSERT INTO dbo.TblPersonTell
				( ShOzviat, Tell, Type )
		SELECT Sh_ozviat,LTRIM(RTRIM(Addres_mk))  AS Tell,5 AS Type FROM dbo.TblPerson WHERE LEN(LTRIM(RTRIM(Addres_mk)))>0
		AND NOT EXISTS (SELECT * FROM dbo.TblPersonTell WHERE Type = 5 AND LTRIM(RTRIM(Tell)) = LTRIM(RTRIM(Addres_mk)))

		INSERT INTO dbo.TblPersonTell
				( ShOzviat, Tell, Type )
		SELECT Sh_ozviat,LTRIM(RTRIM(Mobile))  AS Tell,2 AS Type FROM dbo.TblPerson WHERE LEN(LTRIM(RTRIM(Mobile)))>0
		AND NOT EXISTS (SELECT * FROM dbo.TblPersonTell WHERE Type = 2 AND LTRIM(RTRIM(Tell)) = LTRIM(RTRIM(Mobile)))

		INSERT INTO dbo.TblPersonTell
				( ShOzviat, Tell, Type )
		SELECT Sh_ozviat,LTRIM(RTRIM(Tell)) AS Tell,1 AS Type FROM dbo.TblPerson WHERE LEN(LTRIM(RTRIM(Tell)))>0
		AND NOT EXISTS (SELECT * FROM dbo.TblPersonTell WHERE Type = 1 AND LTRIM(RTRIM(Tell)) = LTRIM(RTRIM(Tell)))

		DELETE FROM dbo.TblParameters   WHERE Name = 'TblPersonTell'
		SET @ip = 0
		SELECT @ip = ISNULL(MAX(Id),0) + 1 FROM dbo.TblParameters
		INSERT INTO dbo.TblParameters
				( Id, Name, Type, Value )
		VALUES  (@ip,'TblPersonTell',2,'True' )
	END

