-- Procedure: [dbo].[sp_TR_Anbargardani_ListMoghayerat]
IF OBJECT_ID(N'[dbo].[sp_TR_Anbargardani_ListMoghayerat]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TR_Anbargardani_ListMoghayerat] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_TR_Anbargardani_ListMoghayerat] 
	@Num varchar(100), 
@Label INT, 
@date1 varchar(100), 
@Idanbars VARCHAR(max), 
@ChkSabtshode bit 
As 
 
 
Begin 
 
declare @Anbargardani table 
(idanbar int, 
idkala int, 
Count NUMERIC(30,15)) 
insert into @Anbargardani 
	SELECT 
t.IdAnbar, 
t.IdKala,      
ISNULL((SELECT  top(1)   sum(Count)FROM         TR_Anbargardani WHERE     (IdAnbar =  t.IDAnbar) AND (IdKala =  t.IDKala) AND (Numeration in (select * from CSVToTable(@Num))) GROUP BY  Numeration ORDER BY Numeration DESC), 0) AS Count 
FROM      
		  TR_Anbargardani AS t 
where t.Numeration in (select * from CSVToTable(@Num)) 
GROUP BY  t.IDAnbar, t.IDKala 
 
 
 
 
DECLARE @Price TABLE(IdAnbar INT,IdKala INT,Price BIGINT) 
--EXEC dbo.SP_TblLastMabFactor_Refresh 
--EXEC dbo.SP_TblLastMabFactorTagmi_Refresh 
 
 
declare @Mande table 
( 
	idanbar int, 
	idkala int, 
	Tedad NUMERIC(25,7), 
	MabeKh BIGINT
) 
insert into @Mande 
select idanbar,idkala,sum(Td_in-Td_out) as ted,ROUND(SUM(Arzesh_In) / CASE WHEN SUM(Td_in)>0 THEN SUM(Td_in) ELSE 1 END,3)  AS Fi from ViewKadexKol WHERE IDAnbar IN (SELECT * FROM dbo.CSVToTable(@Idanbars)) AND dbo.ViewKadexKol.DateR<=@date1 
group by idanbar,idkala 
 
 
IF(@Label=-1) 
BEGIN 
	INSERT INTO @Price  
	SELECT IdAnbAr,IDKala,Fi FROM dbo.LastMabFactorIn WHERE Fi>0 AND IDAnbAr IN (SELECT * FROM dbo.CSVToTable(@Idanbars)) 
END 
ELSE IF (@Label = 0) 
BEGIN 
	 
	 
	INSERT INTO @Price  
	SELECT IDAnbar,IDKala,Bprice FROM dbo.TblKala WHERE Bprice>0 
END 
ELSE 
BEGIN 
	INSERT INTO @Price  
	SELECT IDAnbar,IDKala,Price FROM dbo.TblPrice WHERE IDLable = @Label AND Price>0 AND IDAnbar IN (SELECT * FROM dbo.CSVToTable(@Idanbars)) 
END 
 
IF(@ChkSabtshode=1) 
BEGIN 
SELECT res.IDAnbar ,
       res.IDKala ,
       res.AnbarName ,
       res.Name ,
       res.Unit ,
       res.moshakhasatFani2 ,
       res.Bprice ,
       res.Count ,
	   dbo.RoundDecimal(res.Count,res.U1toU2) AS Count2,
       res.Mande ,
	   dbo.RoundDecimal(res.Mande,res.U1toU2) AS Mande2,
       res.moghayerat ,
	   dbo.RoundDecimal(res.moghayerat,res.U1toU2) AS moghayerat2,
	   CASE WHEN res.moghayerat>0 THEN res.moghayerat ELSE 0 END AS Ezafat,
	   dbo.RoundDecimal(CASE WHEN res.moghayerat>0 THEN res.moghayerat ELSE 0 END,res.U1toU2) AS Ezafat2,
	   CASE WHEN res.moghayerat<0 THEN ABS(res.moghayerat) ELSE 0 END AS Kosorat,
	   dbo.RoundDecimal(CASE WHEN res.moghayerat<0 THEN ABS(res.moghayerat) ELSE 0 END,res.U1toU2) AS Kosorat2,
	   CAST(CASE WHEN res.moghayerat>0 THEN res.moghayerat ELSE 0 END * res.Bprice AS BIGINT) AS EzafatR,
	   CAST(CASE WHEN res.moghayerat<0 THEN ABS(res.moghayerat) ELSE 0 END * res.Bprice AS BIGINT) AS KosoratR,
       res.c1 FROM (
	select TblKala.IDAnbar,TblKala.IDKala,ISNULL(TblAnbar.Name,'') AS AnbarName,TblKala.Name,ISNULL(TblUnit.Name,'') AS Unit,TblKala.moshakhasatFani2,ISNULL(price.Price,ISNULL(lastkha.Fi,1)) as Bprice,ISNULL(Anbargardani.Count,0) as Count,ISNULL(mande.Tedad,0) as Mande,ISNULL(Anbargardani.Count,0)-ISNULL(mande.Tedad,0) as moghayerat,CASE WHEN dbo.TblKala.U1toU2 = 0 THEN 1 ELSE dbo.TblKala.U1toU2 END AS U1toU2,CAST(1 AS bit) AS c1 
	FROM dbo.TblKala 
	LEFT JOIN @Mande AS mande ON mande.idanbar = TblKala.IDAnbar AND mande.idkala = TblKala.IDKala 
	LEFT JOIN @Price AS price ON price.IdAnbar = TblKala.idanbar AND price.IdKala = TblKala.IDKala 
	LEFT join @Anbargardani as Anbargardani on Anbargardani.idanbar=TblKala.IDAnbar and Anbargardani.idkala = TblKala.IDKala 
	left join TblAnbar on TblAnbar.ID=TblKala.IDAnbar 
	left join TblUnit on TblUnit.ID=TblKala.Unit1 
	LEFT JOIN dbo.TblLastMabFactorKharid AS lastkha ON lastkha.IDAnbar = TblKala.idanbar AND lastkha.IDKala = TblKala.IDKala
	WHERE TblKala.IDAnbar IN (SELECT * FROM dbo.CSVToTable(@Idanbars)) 
	AND ISNULL(Anbargardani.Count,0)-ISNULL(mande.Tedad,0)<>0 AND dbo.TblKala.KalaKhadamati = 0 AND ISNULL(Anbargardani.Count,-1)>-1 
	) AS res
END 
ELSE 
BEGIN 
SELECT res.IDAnbar ,
       res.IDKala ,
       res.AnbarName ,
       res.Name ,
       res.Unit ,
       res.moshakhasatFani2 ,
       res.Bprice ,
       res.Count ,
	   dbo.RoundDecimal(res.Count,res.U1toU2) AS Count2,
       res.Mande ,
	   dbo.RoundDecimal(res.Mande,res.U1toU2) AS Mande2,
       res.moghayerat ,
	   dbo.RoundDecimal(res.moghayerat,res.U1toU2) AS moghayerat2,
	   CASE WHEN res.moghayerat>0 THEN res.moghayerat ELSE 0 END AS Ezafat,
	   dbo.RoundDecimal(CASE WHEN res.moghayerat>0 THEN res.moghayerat ELSE 0 END,res.U1toU2) AS Ezafat2,
	   CASE WHEN res.moghayerat<0 THEN ABS(res.moghayerat) ELSE 0 END AS Kosorat,
	   dbo.RoundDecimal(CASE WHEN res.moghayerat<0 THEN ABS(res.moghayerat) ELSE 0 END,res.U1toU2) AS Kosorat2,
	   CAST(CASE WHEN res.moghayerat>0 THEN res.moghayerat ELSE 0 END * res.Bprice AS BIGINT) AS EzafatR,
	   CAST(CASE WHEN res.moghayerat<0 THEN ABS(res.moghayerat) ELSE 0 END * res.Bprice AS BIGINT) AS KosoratR,
       res.c1 FROM (
	select TblKala.IDAnbar,TblKala.IDKala,ISNULL(TblAnbar.Name,'') AS AnbarName,TblKala.Name,ISNULL(TblUnit.Name,'') AS Unit,TblKala.moshakhasatFani2,ISNULL(price.Price,ISNULL(lastkha.Fi,1)) as Bprice,ISNULL(Anbargardani.Count,0) as Count,ISNULL(mande.Tedad,0) as Mande,ISNULL(Anbargardani.Count,0)-ISNULL(mande.Tedad,0) as moghayerat,CASE WHEN dbo.TblKala.U1toU2 = 0 THEN 1 ELSE dbo.TblKala.U1toU2 END AS U1toU2,CAST(1 AS bit) AS c1  
	FROM dbo.TblKala 
	LEFT JOIN @Mande AS mande ON mande.idanbar = TblKala.IDAnbar AND mande.idkala = TblKala.IDKala 
	LEFT JOIN @Price AS price ON price.IdAnbar = TblKala.idanbar AND price.IdKala = TblKala.IDKala 
	LEFT join @Anbargardani as Anbargardani on Anbargardani.idanbar=TblKala.IDAnbar and Anbargardani.idkala = TblKala.IDKala 
	left join TblAnbar on TblAnbar.ID=TblKala.IDAnbar 
	left join TblUnit on TblUnit.ID=TblKala.Unit1 
	LEFT JOIN dbo.TblLastMabFactorKharid AS lastkha ON lastkha.IDAnbar = TblKala.idanbar AND lastkha.IDKala = TblKala.IDKala
	WHERE TblKala.IDAnbar IN (SELECT * FROM dbo.CSVToTable(@Idanbars)) 
	AND ISNULL(Anbargardani.Count,0)-ISNULL(mande.Tedad,0)<>0 AND dbo.TblKala.KalaKhadamati = 0 
	) AS res
END 
 
 
 
 
End 
 
 

GO

