	[UserIDAdd] [INT] NOT NULL, 
	[UserIDEdit] [INT] NOT NULL, 
	[TR_ID] [INT] NOT NULL, 
	[TypeForush] [INT] NOT NULL, 
	[BargeKhoruj] [INT] NOT NULL, 
	[TasviyeSharh] [NVARCHAR](500) NOT NULL, 
	[TypePardakht] [BIT] NOT NULL, 
	[FactorCust] [VARCHAR](500) NOT NULL, 
	[DatePrint] [NVARCHAR](500) NOT NULL, 
	[Driver] [INT] NOT NULL, 
	[PazirandeId] [INT] NOT NULL, 
	[StateFactor] [INT] NOT NULL, 
	[EmzaUser] [INT] NOT NULL, 
	[EmzaDate] [VARCHAR](500) NOT NULL, 
	[Mobile] [NVARCHAR](500) NOT NULL, 
	[TedPerson] [INT] NOT NULL, 
	[Description] [NVARCHAR](500) NOT NULL, 
	[TypeTasviye] [INT] NOT NULL, 
	[Id1] [INT] NOT NULL, 
	[Id2] [INT] NOT NULL, 
	[Id3] [INT] NOT NULL, 
	[FactorTypeId] [INT] NOT NULL, 
	[CustomerClub_Factor_Id] [INT] NOT NULL, 
	[VizitorID] [INT] NOT NULL, 
	[Address] [NVARCHAR](500) NOT NULL, 
	[TypeSefaresh] [INT] NOT NULL, 
	[Tag1] [INT] NOT NULL, 
	[Tag2] [INT] NOT NULL, 
	[Unit] [TINYINT] NOT NULL, 
	[Text] [NVARCHAR](500) NOT NULL, 
	[IdTaraf] [INT] NOT NULL, 
	[TpTaraf] [INT] NOT NULL, 
	[IdCheck] [INT] NOT NULL, 
	[TpCheck] [INT] NOT NULL, 
	[Bank] [TINYINT] NOT NULL, 
	[Shob] [NVARCHAR](500) NOT NULL, 
	[SharhCheck] [NVARCHAR](500) NOT NULL, 
	[State] [INT] NOT NULL, 
	[DateChek] [NVARCHAR](500) NOT NULL, 
	[numhesab] [NVARCHAR](500) NOT NULL, 
	[CodShobe] [NVARCHAR](500) NOT NULL, 
	[SayadNum] [NVARCHAR](500) NOT NULL,
	[Ted2] NUMERIC(30,15) NOT NULL,
	[DescriptionTR] [NVARCHAR](500) NOT NULL,
	[Mashmol] [TINYINT] NOT NULL,
	[Maliat] [BIGINT] NOT NULL,
	[ShiftId] [INT] NOT NULL,
	[TedTahvily] NUMERIC(30,15) NOT NULL,
	[TRDureTasviye] [INT] NOT NULL,
	[ExpireDate] [VARCHAR](50) NOT NULL,
	[Kala_Score] [FLOAT] NOT NULL,
	[IdAmel] [INT] NOT NULL,
	[BedArz] NUMERIC(30,15) NOT NULL,
	[BesArz] NUMERIC(30,15) NOT NULL,
	[NerkhArz] [BIGINT] NOT NULL,
