	[RefId] [INT] NULL,
	[RegionId] [INT] NOT NULL,
	[WeightFactor] [NUMERIC](18, 3) NOT NULL,
	[ChangeStateTime] [NVARCHAR](50) NULL,
	[DriverTime] [NVARCHAR](50) NULL,
	[DriveUser] [INT] NOT NULL,
	[FishNumber] [INT] NOT NULL,
	[Tell] [NVARCHAR](50) NOT NULL,
	[CreateTime] [NVARCHAR](50) NOT NULL,
	[FactorSite_Onvan] [NVARCHAR](100) NOT NULL,
	[PostalCode] [NVARCHAR](20) NULL,
	[DiscountState] [TINYINT] NOT NULL,
	[CodeMeli] [NVARCHAR](10) NULL,
	[ShiftId_Onvan] [INT] NULL,
	[BPMS_InvTitleId] [INT] NULL,
	[Longitude] [VARCHAR](50) NULL,
	[Latitude] [VARCHAR](50) NULL,
	[GharardadNumber] [INT] NULL,
	[IrTaxId] [NVARCHAR](50) NULL,
	[RefFactor] [INT] NULL,
	[RefFactorYear] [INT] NULL,
	[HamlStatus] [INT] NULL,
	[ShBar] [NVARCHAR](50) NULL,
	[SerialBar] [NVARCHAR](50) NULL,
	[DateBar] [NVARCHAR](50) NULL,
	[Price1] [BIGINT] NULL,
	[Price2] [BIGINT] NULL,
	[Price3] [BIGINT] NULL,
	[Sayadi] [TINYINT] NOT NULL
) 
 
INSERT INTO #TR 
	SELECT * FROM @dtTR 
 
declare @cs int = 0,@StartDate NVARCHAR(10),@EndDate NVARCHAR(10),@MSG NVARCHAR(1000) 
DECLARE @DateR1 VARCHAR(10)='',@DateR2 VARCHAR(10)='',@CShobe1 INT = 0,@CShobe2 INT = 0 
 
SELECT @cs = COUNT(*) FROM #TR WHERE DateR COLLATE DATABASE_DEFAULT NOT BETWEEN @StartDate AND @EndDate 
if(@cs>0) 
begin 
	ROLLBACK 
	SET @MSG = 'اسناد در محدوه سال مالی '+DB_NAME() + ' نمی باشد' 
	RAISERROR(@MSG,16,1) 
	RETURN 
END 
 
DECLARE @dailySanad INT = 0
SELECT  @dailySanad = ISNULL(DailySanad, 0)
FROM    TblSetingSoft
WHERE   Id = 1;

IF ( @dailySanad = 2 )
BEGIN
	 IF OBJECT_ID('tempdb.dbo.#DateRSanad2', 'U') IS NOT NULL 
                DROP TABLE #DateRSanad2; 
	CREATE TABLE #DateRSanad2 (DateR NVARCHAR(100),Cshobe INT,Type INT,NewSanad INT) 
	INSERT INTO #DateRSanad2 
	SELECT DateR,Cshobe,Type,ROW_NUMBER() OVER (ORDER BY DateR,Cshobe,Type) FROM #TR 
	GROUP BY DateR,Cshobe,Type 

	UPDATE #TR SET SanadM = temp.NewSanad FROM #TR AS tr 
	INNER JOIN #DateRSanad2 AS temp ON temp.DateR = tr.DateR AND temp.Cshobe = tr.Cshobe AND temp.Type = tr.Type

	DROP TABLE #DateRSanad2
END
ELSE IF ( @dailySanad = 1)
BEGIN
	  IF OBJECT_ID('tempdb.dbo#DateRSanad1', 'U') IS NOT NULL 
                DROP TABLE #DateRSanad1; 
	CREATE TABLE #DateRSanad1 (DateR NVARCHAR(100),Cshobe INT,NewSanad INT) 
	INSERT INTO #DateRSanad1 
	SELECT DateR,Cshobe,ROW_NUMBER() OVER (ORDER BY DateR,Cshobe) FROM #TR 
	GROUP BY DateR,Cshobe 

	UPDATE #TR SET SanadM = temp.NewSanad FROM #TR AS tr 
	INNER JOIN #DateRSanad1 AS temp ON temp.DateR = tr.DateR AND temp.Cshobe = tr.Cshobe

	DROP TABLE #DateRSanad1
END
ELSE
BEGIN
  IF OBJECT_ID('tempdb.dbo.#FactorSanad', 'U') IS NOT NULL 
                DROP TABLE #FactorSanad; 
	CREATE TABLE #FactorSanad (Factor INT,Type INT,NewSanad INT) 
	INSERT INTO #FactorSanad 
	SELECT Factor,Type,ROW_NUMBER() OVER (ORDER BY Factor,Type ) + 10000 FROM #TR 
	WHERE Factor>0 AND IdTaraf = 0 
	GROUP BY Factor,Type 
 
	UPDATE #TR SET SanadM = temp.NewSanad FROM #TR AS tr 
	INNER JOIN #FactorSanad AS temp ON temp.Factor = tr.Factor AND temp.Type = tr.Type 
 
 
   IF OBJECT_ID('tempdb.dbo.#TarafSanad', 'U') IS NOT NULL 
                DROP TABLE #TarafSanad; 
	CREATE TABLE #TarafSanad(IdTaraf INT,TpTaraf INT,NewSanad INT) 
	INSERT INTO #TarafSanad 
	SELECT IdTaraf,TpTaraf,ROW_NUMBER() OVER (ORDER BY IdTaraf,TpTaraf)+20000 FROM #TR 
	WHERE IdTaraf>0 AND Factor = 0 
	GROUP BY IdTaraf,TpTaraf 
 
	UPDATE #TR SET SanadM = temp.NewSanad FROM #TR AS tr 
	INNER JOIN #TarafSanad AS temp ON temp.IdTaraf = tr.IdTaraf AND temp.TpTaraf = tr.TpTaraf 
 

   IF OBJECT_ID('tempdb.dbo.#DateRSanad', 'U') IS NOT NULL 
                DROP TABLE #DateRSanad; 
	CREATE TABLE #DateRSanad (DateR NVARCHAR(100),Cshobe INT,NewSanad INT) 
	INSERT INTO #DateRSanad 
	SELECT DateR,Cshobe,ROW_NUMBER() OVER (ORDER BY DateR,Cshobe)+30000 FROM #TR 
	WHERE IdTaraf = 0 AND Factor = 0 
	GROUP BY DateR,Cshobe 
 
 
	UPDATE #TR SET SanadM = temp.NewSanad FROM #TR AS tr 
	INNER JOIN #DateRSanad AS temp ON temp.DateR = tr.DateR AND temp.Cshobe = tr.Cshobe 

 END
   IF OBJECT_ID('tempdb.dbo.#Sanad', 'U') IS NOT NULL 
    DROP TABLE #Sanad; 
	CREATE TABLE #Sanad(SanadM INT,NewSanad INT) 

	INSERT INTO	#Sanad 
	SELECT SanadM,ROW_NUMBER() OVER (ORDER BY SanadM) FROM #TR 
	GROUP BY SanadM 
 
	DECLARE @MaxSanad INT = 0 
	SELECT @MaxSanad=ISNULL(MAX(SanadM),0) FROM dbo.TR 
 
	UPDATE #TR SET SanadM = temp.NewSanad + @MaxSanad FROM #TR AS tr 
	INNER JOIN #Sanad AS temp ON temp.SanadM = tr.SanadM 
 
	IF OBJECT_ID('tempdb.dbo.#Factros', 'U') IS NOT NULL 
		DROP TABLE #Factros; 
	CREATE TABLE #Factros(Factor INT,Type INT,Srfsl INT,Moin INT,HSB BIGINT) 

	INSERT INTO #Factros 
	SELECT dttr.Factor,dttr.Type,MAX(dttr.Srfsl) AS Srfsl,MAX(dttr.Moin) AS Moin,MAX(dttr.HSB) AS HSB FROM #TR AS dttr 
	WHERE dttr.Type>0 AND dttr.IDAnbar>0 AND dttr.IDKala>0 
	GROUP BY dttr.Factor,dttr.Type 
 
	BEGIN TRANSACTION
 
	INSERT INTO dbo.TblFactorOnvan 
		(ShFactor , 
		 Type  
		) 
 
	SELECT dttr.Factor,dttr.Type FROM #TR AS dttr 
	LEFT JOIN dbo.TR AS tr ON tr.TRMiddle_ID = dttr.Sodor AND tr.Cshobe = dttr.Cshobe 
	LEFT JOIN dbo.TblFactorOnvan AS fo ON  fo.ShFactor = dttr.Factor AND fo.Type = dttr.Type 
	WHERE ISNULL(tr.Sodor,0)=0 AND ISNULL(fo.ShFactor,0)=0 
	AND dttr.Factor>0 AND dttr.Type>0 
	GROUP BY dttr.Factor,dttr.Type 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error INSERT TblFactorOnvan', 16, 1)
		RETURN
	END
        
	UPDATE dbo.TblFactorOnvan SET 
	CShobe = dttr.Cshobe, 
	CustumCod = dttr.CustumCod, 
	CustumName = dttr.CustumName, 
	Sharh = dttr.SharhFactor, 
	UserIDAdd = dttr.UserIDAdd, 
	UserIDEdit = dttr.UserIDEdit, 
	DateFactor = dttr.DateR, 
	Sanad = dttr.SanadM, 
	sarfasl = FActors.Srfsl, 
	moin = FActors.Moin, 
	hsb = FActors.HSB, 
	TypeForush = dttr.TypeForush, 
	BargeKhoruj = dttr.BargeKhoruj, 
	TasviyeSharh = dttr.TasviyeSharh, 
	TypePardakht = dttr.TypePardakht, 
	FactorCust = dttr.FactorCust, 
	DatePrint = dttr.DatePrint, 
	Driver = dttr.Driver, 
	PazirandeId = dttr.PazirandeId, 
	StateFactor = dttr.StateFactor, 
	EmzaUser = dttr.EmzaUser, 
	EmzaDate = dttr.EmzaDate, 
	Mobile = dttr.Mobile, 
	TedPerson = dttr.TedPerson, 
	[Description] = dttr.[Description], 
	TypeTasviye = dttr.TypeTasviye, 
	Id1 = dttr.Id1, 
	Id2 = dttr.Id2, 
	Id3 = dttr.Id3, 
	FactorTypeId = dttr.FactorTypeId, 
	CustomerClub_Factor_Id = dttr.CustomerClub_Factor_Id, 
	VizitorID = dttr.VizitorID, 
	[Address] = dttr.[Address], 
	TypeSefaresh = dttr.TypeSefaresh,
	ClearanceId = dttr.ClearanceId,
	ClearanceId2 = dttr.ClearanceId2,
	CustumCod2 = dttr.CustumCod2,
	Driver2 = dttr.Driver2,
	BorderId = dttr.BorderId,
	Date2 = dttr.Date2,
	GomrokId = dttr.GomrokId,
	Moved = dttr.Moved,
	FactorOff = dttr.FactorOff,
	RefId = dttr.RefId,
	RegionId = dttr.RegionId,
	WeightFactor = dttr.WeightFactor,
	ChangeStateTime = dttr.ChangeStateTime,
	DriverTime = dttr.DriverTime,
	DriveUser = dttr.DriveUser,
	FishNumber = dttr.FishNumber,
	Tell = dttr.Tell,
	CreateTime = dttr.CreateTime,
	FactorSite = dttr.FactorSite_Onvan,
	PostalCode = dttr.PostalCode,
	DiscountState = dttr.DiscountState,
	CodeMeli = dttr.CodeMeli,
	ShiftId = dttr.ShiftId_Onvan,
	BPMS_InvTitleId = dttr.BPMS_InvTitleId,
	Longitude = dttr.Longitude,
	Latitude = dttr.Latitude,
	GharardadNumber = dttr.GharardadNumber,
	IrTaxId = dttr.IrTaxId,
	RefFactor = dttr.RefFactor,
	RefFactorYear = dttr.RefFactorYear,
	HamlStatus = dttr.HamlStatus,
	ShBar = dttr.ShBar,
	SerialBar = dttr.SerialBar,
	DateBar = dttr.DateBar
	FROM dbo.TblFactorOnvan 
	INNER JOIN #TR AS dttr	 ON dbo.TblFactorOnvan.ShFactor = dttr.Factor AND dbo.TblFactorOnvan.Type = dttr.Type 
	INNER JOIN #Factros AS FActors ON FActors.Factor = dbo.TblFactorOnvan.ShFactor AND FActors.Type = dbo.TblFactorOnvan.Type 
	LEFT JOIN dbo.TR AS tr ON tr.TRMiddle_ID = dttr.Sodor AND tr.Cshobe = dttr.Cshobe 
	WHERE ISNULL(tr.Sodor,0)=0 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error UPDATE TblFactorOnvan', 16, 1)
		RETURN
	end
 
	DECLARE @MaxIDCheckD INT = 0 
	SELECT @MaxIDCheckD = ISNULL(MAX(Id),0) FROM [dbo].[Check] 

	IF OBJECT_ID('tempdb.dbo.#dtCheckD', 'U') IS NOT NULL 
			DROP TABLE #dtCheckD; 
	CREATE TABLE #dtCheckD(IdCheckD INT,Sodor INT,Cshobe INT) 

	INSERT INTO #dtCheckD 
	SELECT  ROW_NUMBER() OVER (ORDER BY dttr.Cshobe,dttr.Sodor ) + @MaxIDCheckD as IdCheckD,Sodor,Cshobe 
	FROM #TR AS dttr WHERE IdCheck>0 AND TpCheck = 0 
 
	DECLARE @MaxIDCheckP INT = 0 
	SELECT @MaxIDCheckP = ISNULL(MAX(Id),0) FROM [dbo].CheckPardakht 

	IF OBJECT_ID('tempdb.dbo.#dtCheckP', 'U') IS NOT NULL 
			DROP TABLE #dtCheckP; 
	CREATE TABLE #dtCheckP (IdCheckP INT,Sodor INT,Cshobe INT) 

	INSERT INTO #dtCheckP 
	SELECT  ROW_NUMBER() OVER (ORDER BY dttr.Cshobe,dttr.Sodor ) + @MaxIDCheckP as IdCheckP,Sodor,Cshobe 
	FROM #TR AS dttr WHERE IdCheck>0 AND TpCheck = 1 
 
	DECLARE @MaxIdTaraf INT = 0 
	SELECT @MaxIdTaraf = ISNULL(MAX(Taraf),0) FROM [dbo].TR 

	IF OBJECT_ID('tempdb.dbo.#dtTaraf', 'U') IS NOT NULL 
			DROP TABLE #dtTaraf; 
	CREATE TABLE #dtTaraf(IdTarafNew INT,IdTaraf INT,Cshobe INT) 

	INSERT INTO #dtTaraf 
	SELECT  ROW_NUMBER() OVER (ORDER BY dttr.IdTaraf,dttr.Cshobe ) + @MaxIdTaraf as IdTarafNew,dttr.IdTaraf,dttr.Cshobe 
	FROM #TR AS dttr WHERE IdTaraf>0 
	GROUP BY IdTaraf,dttr.Cshobe 
 
	DECLARE @MaxSodor INT = 0 
	SELECT @MaxSodor=ISNULL(MAX(Sodor),0)+100 FROM dbo.TR 

	IF OBJECT_ID('tempdb.dbo.#dtSodor', 'U') IS NOT NULL 
		DROP TABLE #dtSodor; 
	CREATE TABLE #dtSodor(IdSodor INT,Sodor INT,Cshobe INT) 

	INSERT INTO #dtSodor 
	SELECT  ROW_NUMBER() OVER (ORDER BY dttr.Cshobe,dttr.Sodor ) + @MaxSodor as IdSodor,dttr.Sodor,dttr.Cshobe 
	FROM #TR AS dttr 
	LEFT JOIN dbo.TR AS tr ON tr.TRMiddle_ID = dttr.Sodor AND tr.Cshobe = dttr.Cshobe 
	WHERE ISNULL(tr.Sodor,0)=0 
 
	INSERT INTO dbo.TR 
		( Sodor , 
			Cshobe , 
			Srfsl , 
			Moin , 
			HSB , 
			Grp , 
			Serial , 
			Sharh , 
			Factor , 
			Type , 
			DateR , 
			SanadM , 
			IdAnbr , 
			IDKala , 
			Ted , 
			Nerkh , 
			Takh , 
			Bed , 
			Bes , 
			Tp1 , 
			CntHaz , 
			CntProject, 
			TRMiddle_ID, 
			Taraf, 
			TpTaraf, 
			IDCheck, 
			TpCheck, 
			IDForushande, 
			Ted2,
			Description,
			Mashmol,
			Maliat,
			ShiftId,
			TedTahvily,
			TRDureTasviye,
			ExpireDate,
			Kala_Score,
			IdAmel,
			DarsadMashmol,
			Price1,
			Price2,
			Price3
		) 
         
	SELECT  
		dtsodor.IdSodor AS Sodor, 
		dttr.Cshobe, 
		dttr.Srfsl, 
		dttr.Moin, 
		dttr.HSB, 
		dttr.Grp, 
		dttr.Serial, 
		dttr.Sharh, 
		dttr.Factor, 
		dttr.Type, 
		dttr.DateR, 
		dttr.SanadM, 
		dttr.IDAnbar, 
		dttr.IDKala, 
		dttr.Ted, 
		dttr.Nerkh, 
		dttr.Takh, 
		dttr.Bed, 
		dttr.Bes, 
		dttr.Tp1, 
		dttr.CntHaz, 
		dttr.CntProject, 
		dttr.Sodor, 
		ISNULL(dtTaraf.IdTarafNew,0) AS IdTaraf, 
		dttr.TpTaraf, 
		ISNULL(dtCheckD.IdCheckD,ISNULL(dtCheckP.IdCheckP,0)) AS IdCheck, 
		dttr.TpCheck, 
		dttr.CustumCod, 
		dttr.Ted2,
		dttr.Description,
		dttr.Mashmol,
		dttr.Maliat,
		dttr.ShiftId,
		dttr.TedTahvily,
		dttr.TRDureTasviye,
		dttr.ExpireDate,
		dttr.Kala_Score,
		dttr.IdAmel,
		k.DarsadMaliat,
		dttr.Price1,
		dttr.Price2,
		dttr.Price3
	FROM #TR AS dttr 
	INNER JOIN #dtSodor AS dtsodor ON dtsodor.Sodor = dttr.Sodor AND dtsodor.Cshobe = dttr.Cshobe 
	LEFT JOIN #dtCheckD AS dtCheckD ON dtCheckD.Sodor = dttr.Sodor AND dtCheckD.Cshobe = dttr.Cshobe 
	LEFT JOIN #dtCheckP AS dtCheckP ON dtCheckP.Sodor = dttr.Sodor AND dtCheckP.Cshobe = dttr.Cshobe 
	LEFT JOIN #dtTaraf AS dtTaraf ON dtTaraf.IdTaraf = dttr.IdTaraf AND dtTaraf.Cshobe = dttr.Cshobe 
	LEFT JOIN dbo.TblKala AS k ON dttr.IDAnbar = k.IDAnbar AND dttr.IDKala = k.IDKala 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error Insert TR', 16, 1)
		RETURN
	end
		  
	DELETE dbo.TRDetail FROM dbo.TRDetail 
	INNER JOIN #dtSodor AS dtsodor ON dbo.TRDetail.Sodor = dtsodor.IdSodor 
 
	INSERT INTO dbo.TRDetail 
		( Sodor , 
		Tag1 , 
		Tag2 , 
		Unit , 
		Text ,
		BedArz,
		BesArz,
		Nerkh,
		ArzId,
		FactorSite
		) 
	SELECT  
		dtsodor.IdSodor, 
		dttr.Tag1, 
		dttr.Tag2, 
		dttr.Unit, 
		dttr.Text,
		dttr.BedArz,
		dttr.BesArz,
		dttr.NerkhArz,
		dttr.ArzId,
		dttr.FactorSite
		FROM #TR AS dttr 
	INNER JOIN #dtSodor AS dtsodor ON dtsodor.Sodor = dttr.Sodor AND dtsodor.Cshobe = dttr.Cshobe 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error Insert TRDetail', 16, 1)
		RETURN
	end
 
	INSERT INTO [dbo].[Check] 
		( [Id] , 
		[Bank] , 
		[shob] , 
		[serial] , 
		[mab] , 
		[sharh] , 
		[sarfasl2] , 
		[moin2] , 
		[hsb2] , 
		[sodur] , 
		[State] , 
		[DateR] , 
		[DateChek] , 
		[numhesab] , 
		[CodShobe] , 
		[PersonId] , 
		[CShobe] , 
		[SayadNum] ,
		[Sayadi]
		) 
	SELECT  
		dtCheckD.IdCheckD, 
		dttr.Bank, 
		dttr.Shob, 
		dttr.Serial, 
		dttr.Bed, 
		dttr.SharhCheck, 
		dttr.Srfsl, 
		dttr.Moin, 
		dttr.HSB, 
		dtsodor.IdSodor, 
		dttr.State, 
		dttr.DateR, 
		dttr.DateChek, 
		dttr.numhesab, 
		dttr.CodShobe, 
		dttr.CustumCod, 
		dttr.Cshobe, 
		dttr.SayadNum ,
		dttr.Sayadi
	FROM #TR AS dttr 
	INNER JOIN #dtSodor AS dtsodor ON dtsodor.Sodor = dttr.Sodor AND dtsodor.Cshobe = dttr.Cshobe 
	INNER JOIN #dtCheckD AS dtCheckD ON dtCheckD.Sodor = dttr.Sodor AND dtCheckD.Cshobe = dttr.Cshobe 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error Insert Check', 16, 1)
		RETURN
	end
 
	INSERT INTO dbo.TRCheck 
		( CheckId, Type, Sodor, State, Sharh,TCO ) 
	SELECT  
		dtCheckD.IdCheckD, 
		0 AS Type, 
		dtsodor.IdSodor, 
		dttr.State, 
		'ورود چک دریافتی' AS Sharh,1
	FROM #TR AS dttr 
	INNER JOIN #dtSodor AS dtsodor ON dtsodor.Sodor = dttr.Sodor AND dtsodor.Cshobe = dttr.Cshobe 
	INNER JOIN #dtCheckD AS dtCheckD ON dtCheckD.Sodor = dttr.Sodor AND dtCheckD.Cshobe = dttr.Cshobe 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error Insert TRCheck', 16, 1)
		RETURN
	end
 
	INSERT INTO [dbo].CheckPardakht 
		( [Id] , 
		[Bank] , 
		[serial] , 
		[mab] , 
		[sharh] , 
		[sarfasl2] , 
		[moin2] , 
		[hsb2] , 
		[sodur] , 
		[State] , 
		[DateR] , 
		[DateChek] , 
		[numhesab] , 
		[PersonId] , 
		[CShobe] , 
		[SayadNum] 
		) 
	SELECT  
		dtCheckP.IdCheckP, 
		dttr.Bank, 
		dttr.Serial, 
		dttr.Bes, 
		dttr.SharhCheck, 
		dttr.Srfsl, 
		dttr.Moin, 
		dttr.HSB, 
		dtsodor.IdSodor, 
		dttr.State, 
		dttr.DateR, 
		dttr.DateChek, 
		dttr.numhesab, 
		dttr.CustumCod, 
		dttr.Cshobe, 
		dttr.SayadNum 
	FROM #TR AS dttr 
	INNER JOIN #dtSodor AS dtsodor ON dtsodor.Sodor = dttr.Sodor AND dtsodor.Cshobe = dttr.Cshobe 
	INNER JOIN #dtCheckP AS dtCheckP ON dtCheckP.Sodor = dttr.Sodor AND dtCheckP.Cshobe = dttr.Cshobe 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error Insert CheckPardakht', 16, 1)
		RETURN
	END
        
	INSERT INTO dbo.TRCheck 
		( CheckId, Type, Sodor, State, Sharh,TCO ) 
	SELECT  
		dtCheckP.IdCheckP, 
		1 AS Type, 
		dtsodor.IdSodor, 
		dttr.State, 
		'ورود چک پرداختی' AS Sharh,1
	FROM #TR AS dttr 
	INNER JOIN #dtSodor AS dtsodor ON dtsodor.Sodor = dttr.Sodor AND dtsodor.Cshobe = dttr.Cshobe 
	INNER JOIN #dtCheckP AS dtCheckP ON dtCheckP.Sodor = dttr.Sodor AND dtCheckP.Cshobe = dttr.Cshobe 
	IF @@ERROR <> 0
	BEGIN
		ROLLBACK
		RAISERROR ('Error Insert TRCheck', 16, 1)
		RETURN
	END  

	COMMIT TRANSACTION;
 
	UPDATE dbo.TR_Middle SET TR_ID = dbo.TR.Sodor 
	FROM dbo.TR_Middle INNER JOIN dbo.TR ON dbo.TR_Middle.Sodor = dbo.TR.TRMiddle_ID AND dbo.TR_Middle.Cshobe = dbo.TR.CShobe 
	WHERE dbo.TR.DateR BETWEEN @DateR1 AND @DateR2 

	EXEC dbo.UpdateTblKala 

	EXEC dbo.UpdateTblMaster
	
	EXEC dbo.UpdateTblTemp 
 
	EXEC SP_TblSerialKalaServer_Refresh
	
END 
 

GO

-- Procedure: [dbo].[sp_TRMiddle_SelectAll_MoveSodor]
IF OBJECT_ID(N'[dbo].[sp_TRMiddle_SelectAll_MoveSodor]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TRMiddle_SelectAll_MoveSodor] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_TRMiddle_SelectAll_MoveSodor]
@dater1 varchar(10),
@dater2 varchar(10),
@state INT = 0,
@Taraz INT = 2

AS
BEGIN
	
		IF OBJECT_ID('tempdb.dbo.#tempSodor', 'U') IS NOT NULL
                DROP TABLE #tempSodor;
            CREATE TABLE #tempSodor
                (
					 SodorId INT
                );


		IF(@Taraz = 0)
		BEGIN
			INSERT INTO #tempSodor
			SELECT Sodor FROM dbo.TR
					INNER JOIN (
					SELECT Factor,Type FROM dbo.TR WHERE Type>0 AND Factor>0 AND DateR BETWEEN @dater1 AND @dater2
					GROUP BY Factor,Type
					HAVING SUM(Bed-Bes)=0) AS r ON tr.Factor = r.Factor AND dbo.TR.Type = r.Type

					UNION

					SELECT Sodor FROM dbo.TR
					INNER JOIN (
					SELECT Taraf,TpTaraf FROM dbo.TR WHERE TpTaraf>0 AND Taraf>0 AND DateR BETWEEN @dater1 AND @dater2
					GROUP BY Taraf,TpTaraf
					HAVING SUM(Bed-Bes)=0) r2 ON tr.Taraf = r2.Taraf AND dbo.TR.TpTaraf = r2.TpTaraf
		
					UNION 

					SELECT Sodor FROM dbo.TR
					INNER JOIN (
					SELECT SanadM FROM dbo.TR WHERE SanadM>0 AND DateR BETWEEN @dater1 AND @dater2
					GROUP BY SanadM
					HAVING SUM(Bed-Bes)=0) r3 ON tr.SanadM = r3.SanadM
		END	
		ELSE IF(@Taraz = 1)
		BEGIN
			INSERT INTO #tempSodor
			SELECT Sodor FROM dbo.TR
					INNER JOIN (
					SELECT Factor,Type FROM dbo.TR WHERE Type>0 AND Factor>0 AND DateR BETWEEN @dater1 AND @dater2
					GROUP BY Factor,Type
					HAVING SUM(Bed-Bes)<>0) AS r ON tr.Factor = r.Factor AND dbo.TR.Type = r.Type

					UNION

					SELECT Sodor FROM dbo.TR
					INNER JOIN (
					SELECT Taraf,TpTaraf FROM dbo.TR WHERE TpTaraf>0 AND Taraf>0 AND DateR BETWEEN @dater1 AND @dater2
					GROUP BY Taraf,TpTaraf
					HAVING SUM(Bed-Bes)<>0) r2 ON tr.Taraf = r2.Taraf AND dbo.TR.TpTaraf = r2.TpTaraf
		
					UNION 

					SELECT Sodor FROM dbo.TR
					INNER JOIN (
					SELECT SanadM FROM dbo.TR WHERE SanadM>0 AND DateR BETWEEN @dater1 AND @dater2
					GROUP BY SanadM
					HAVING SUM(Bed-Bes)<>0) r3 ON tr.SanadM = r3.SanadM
		END
		ELSE 
		BEGIN
			INSERT INTO #tempSodor
			SELECT Sodor FROM dbo.TR WHERE DateR BETWEEN @dater1 AND @dater2
		END
		
		declare @Cshobe int = 0
		select @Cshobe = CShobe from TblCompany where Id=1
		if(@state = 0)
		begin	
			Select
			N'بدون اقدام' as Event,
			TR.Sodor,
			@Cshobe as Cshobe,
			TR.Srfsl,
			TR.Moin,
			TR.HSB,
			'' as SahebHesab,
			TR.Sharh,
			TR.Factor,
			TbltypeTR.Name as TypeName,
			TR.DateR,
			TR.SanadM,
			TR.IdAnbr as IdAnbar,
			TR.Idkala,
			Isnull(TblKala.Name,'') as KalaName,
			Isnull(TblUnit.Name,'') as UnitName,
			TR.TED ,
			TR.Bed,
			TR.Bes,
			ISNULL(TblUser.FulName,'') as UserName,
			TR.GRP,
			TR.serial,
			TR.[Type],
			TR.Nerkh,
			TR.Takh,
			TR.Tp1,
			TR.CntHaz,
			TR.CntProject,
			ISNULL(TblFactorOnvan.CustumCod,dbo.TR.IDForushande) AS CustumCod,
			ISNULL(TblFactorOnvan.CustumName,0) AS CustumName,
			ISNULL(TblFactorOnvan.Sharh,0) AS SharhFactor,
			ISNULL(TblFactorOnvan.UserIDAdd,0) AS UserIDAdd,
			ISNULL(TblFactorOnvan.UserIDEdit,0) AS UserIDEdit,
			0 AS TR_ID,
			ISNULL(TblFactorOnvan.TypeForush,0) AS TypeForush,
			ISNULL(TblFactorOnvan.BargeKhoruj,0) AS BargeKhoruj,
			ISNULL(TblFactorOnvan.TasviyeSharh,'') AS TasviyeSharh,
			ISNULL(TblFactorOnvan.TypePardakht,0) AS TypePardakht,
			ISNULL(TblFactorOnvan.FactorCust,'') AS FactorCust,
			ISNULL(TblFactorOnvan.DatePrint,'') AS DatePrint,
			ISNULL(TblFactorOnvan.Driver,0) AS Driver,
			ISNULL(TblFactorOnvan.PazirandeId,0) AS PazirandeId,
			ISNULL(TblFactorOnvan.StateFactor,0) AS StateFactor,
			ISNULL(TblFactorOnvan.EmzaUser,0) AS EmzaUser,
			ISNULL(TblFactorOnvan.EmzaDate,'') AS EmzaDate,
			ISNULL(TblFactorOnvan.Mobile,'') AS Mobile,
			ISNULL(TblFactorOnvan.TedPerson,0) AS TedPerson,
