-- Procedure: [dbo].[sp_TrTemp_Insert_New]
IF OBJECT_ID(N'[dbo].[sp_TrTemp_Insert_New]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_TrTemp_Insert_New] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_TrTemp_Insert_New]
	@UserId INT,
	@SanadM INT,
	@Factor INT,
	@Type INT,
	@DateR NVARCHAR(100),
	@Cshobe INT,
	@Sodor INT,
	@IdAnbar INT ,
	@IdKala INT,
	@Ted NUMERIC(18,3),
	@Ted2 NUMERIC(18,3),
	@Nerkh NUMERIC(18,3),
	@Unit INT,
	@TakhTR BIGINT,
	@Mashmol INT,
	@Bed BIGINT,
	@Bes BIGINT,
	@Text  NVARCHAR(100),
	@Srfsl INT,
	@Moin INT,
	@HSB BIGINT,
	@IdAmel INT,
	@tp1 INT,
	@SharhTR NVARCHAR(100),
	@Sh_Order INT = 0,
	@QabNumber int	= 0,
	@OrderType INT = 0,
	@PriceForosh BIGINT = 0,
	@PriceMasraf BIGINT = 0,
	@PriceKharid BIGINT = 0,
	@DarsadMashmol NUMERIC(18,3) = 0,
	@RowFactor INT = 0,
	@RowFactor_Id INT = 0,
	@Description NVARCHAR(500) = '',
	@refid INT=0,
	@IDForushande INT =0
AS
    BEGIN TRY
		

       DECLARE @msg NVARCHAR(100) =''
	DECLARE @C INT = 0
	SELECT @C = COUNT(*) FROM dbo.Master WHERE Srfsl = @Srfsl AND Moin = @Moin AND HSB = @HSB
	IF(@C = 0)
	BEGIN
		SET @msg = 'حساب یافت نشد '+CAST(@Srfsl AS NVARCHAR(100))+'-'+CAST(@Moin AS NVARCHAR(100))+'-'+CAST(@HSB AS NVARCHAR(100))
		RAISERROR(@msg,16,1)
		RETURN
	END

	DECLARE @MabKh BIGINT = 0

	IF(@IdAnbar>0)
	BEGIN
		SET @C = 0
		SELECT @C = COUNT(*) FROM dbo.TblKala WHERE IDAnbar = @IdAnbar AND IDKala = @IdKala
		IF(@C = 0)
		BEGIN
			SET @msg = 'کالا یافت نشد '+CAST(@IdAnbar AS NVARCHAR(100))+'-'+CAST(@IdKala AS NVARCHAR(100))
			RAISERROR(@msg,16,1)
			RETURN
		END

		SELECT @MabKh = Bprice FROM dbo.TblKala WHERE IDAnbar = @IdAnbar AND IDKala = @IdKala
	END
	SET @C = 0
	SELECT  @C = COUNT(*) FROM dbo.TR WHERE Sodor = @Sodor AND Factor = @Factor AND Type = @Type

	IF(@C>0)
	BEGIN
		SET @C = 0
		SELECT  @C = COUNT(*) FROM dbo.TR WHERE Sodor = @Sodor AND Factor = @Factor AND Type = @Type
		AND  NOT(TED = @Ted * @Nerkh AND Ted2 = @Ted2 AND Bed = @Bed AND Bes = @Bes AND IdAnbr = @IDAnbar AND Idkala = @IDKala AND IdAmel = @IdAmel AND Nerkh = @Nerkh AND Mashmol = @Mashmol AND DarsadMashmol = @DarsadMashmol AND IDForushande=@IDForushande)

		IF(@C>0)
		BEGIN
			
			UPDATE dbo.TR SET TED = @Ted * @Nerkh,Ted2 = @Ted2,Bed = @Bed,Bes = @Bes,IdAnbr = @IDAnbar,Idkala = @IDKala,IdAmel = @IdAmel,
			Nerkh = @Nerkh,DarsadMashmol  = @DarsadMashmol,Mashmol = @Mashmol,Price1 = @PriceForosh,Price2 = @PriceMasraf,Price3 = @PriceKharid,
			IDForushande=@IDForushande
			WHERE Sodor = @Sodor

			UPDATE dbo.TRDetail SET Unit = @Unit WHERE Sodor = @Sodor

			UPDATE  TR_Deleted SET Userid = @UserId
			WHERE   ( Id = ( SELECT MAX(Id)
						FROM   TR_Deleted
						WHERE  ( Sodor = @Sodor )
					) )
			AND ( Sodor = @Sodor );
		END
	END
	ELSE
	BEGIN
		SET @Sodor = 0
		SELECT @Sodor = ISNULL(MAX(Sodor),0) + 1 FROM dbo.TR
		IF @Type=104
		BEGIN
		    INSERT INTO tr(Sodor,IdAnbr,Idkala,TED,Ted2,Nerkh,Takh,Mashmol,Bed,Bes,Srfsl,Moin,HSB,IdAmel,SanadM,Factor,Type,GRP,DateR,Tp1,Sharh,CShobe,Price1,Price2,Price3,DarsadMashmol,Mabkh,Description,Tolid_Id,IDForushande)
			VALUES(@Sodor,@IdAnbar,@IdKala,@Ted * @Nerkh,@Ted2,@Nerkh,@TakhTR,@Mashmol,@Bed,@Bes,@Srfsl,@Moin,@HSB,@IdAmel,@SanadM,@Factor,@Type,@UserId,@DateR,@tp1,@SharhTR,@Cshobe,@PriceForosh,@PriceMasraf,@PriceKharid,@DarsadMashmol,@MabKh,@Description,@refid,@IDForushande)
		END
		ELSE
		BEGIN
		    INSERT INTO tr(Sodor,IdAnbr,Idkala,TED,Ted2,Nerkh,Takh,Mashmol,Bed,Bes,Srfsl,Moin,HSB,IdAmel,SanadM,Factor,Type,GRP,DateR,Tp1,Sharh,CShobe,Price1,Price2,Price3,DarsadMashmol,Mabkh,Description,TblPishFactor_ID,IDForushande)
			VALUES(@Sodor,@IdAnbar,@IdKala,@Ted * @Nerkh,@Ted2,@Nerkh,@TakhTR,@Mashmol,@Bed,@Bes,@Srfsl,@Moin,@HSB,@IdAmel,@SanadM,@Factor,@Type,@UserId,@DateR,@tp1,@SharhTR,@Cshobe,@PriceForosh,@PriceMasraf,@PriceKharid,@DarsadMashmol,@MabKh,@Description,@refid,@IDForushande)
		END
		

		DELETE FROM dbo.TRDetail WHERE Sodor = @Sodor
		INSERT INTO dbo.TRDetail
		       (Sodor,Tag2,Unit,Text,RowFactor,RowFactor_Id)
		VALUES(@Sodor,@IdAmel,@Unit,@Text,@RowFactor,@RowFactor_Id)
	END


	IF(@QabNumber>0)
	BEGIN
				

						DECLARE @now VARCHAR(30) =dbo.GetToday()
						IF(@orderType=1)
						BEGIN
							EXEC dbo.sp_Qab_TblOrderDetails_Insert @Order_Id = @Sh_Order,
																   @Order_Type_Id = @orderType,
																   @Qab_Id = @QabNumber,
																   @Order_State_Id = 5,
																   @CreateUser = @userId,
																   @CreateTime = @now,
																   @PrintTime =@now,
																   @PrintUser = @userId,
																   @ShelfNumber = 0,
																   @RowNumber = 0
						END
						IF(@orderType=2)
						BEGIN
							EXEC dbo.sp_Qab_TblOrderDetails_Insert @Order_Id = @Sh_Order,
																   @Order_Type_Id = @orderType,
																   @Qab_Id = 0,
																   @Order_State_Id = 5,
																   @CreateUser = @UserId,
																   @CreateTime = @now,
																   @PrintTime =@now,
																   @PrintUser = @UserId,
																   @ShelfNumber = 0,
																   @RowNumber = 0
						END
	END
		
	
    END TRY
    BEGIN CATCH
        SELECT  @msg = ERROR_MESSAGE();
        RAISERROR(@msg, 16, 1);
        RETURN -1;
    END CATCH;




GO

-- Procedure: [dbo].[sp_UpdateMabKhTR]
IF OBJECT_ID(N'[dbo].[sp_UpdateMabKhTR]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[sp_UpdateMabKhTR] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[sp_UpdateMabKhTR]
	
	as

SET NOCOUNT ON;
BEGIN

	EXEC sp_CalcFloatingAverage

	UPDATE dbo.TR SET Mabkh = td.Fi FROM dbo.TR AS t
	INNER JOIN ##tempDate AS td ON t.IdAnbr = td.IdAnbar AND t.Idkala = td.IdKala AND t.DateR COLLATE DATABASE_DEFAULT = td.DateR AND t.type  = td.tp
	WHERE t.Type = 203 AND t.IdAnbr>0 AND t.Idkala>0 AND t.Mabkh<>td.FI
END





GO

-- Procedure: [dbo].[sp_WorkbookTax_InsertTotal]
