       tob ,
       setm ,
       period,
	   IrTaxId FROM @Data
END





GO

-- Procedure: [dbo].[TblFactorOnvan_Insert]
IF OBJECT_ID(N'[dbo].[TblFactorOnvan_Insert]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[TblFactorOnvan_Insert] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[TblFactorOnvan_Insert]
    @ShFactor INT ,
    @CustumCod INT ,
    @CustumName NVARCHAR(50) ,
    @DateFactor NCHAR(10) ,
    @TypeForush INT ,
    @Sharh NVARCHAR(500) ,
    @BargeKhoruj INT ,
    @sanad INT ,
    @sarfasl INT ,
    @moin INT ,
    @hsb BIGINT ,
    @tashkhis INT ,
    @type TINYINT ,
    @tasviyeshrh NVARCHAR(500) ,
    @FactorCust VARCHAR(100) ,
    @UserIDAdd INT ,
    @UserIDEdit INT ,
    @DatePrint VARCHAR(50) ,
    @driver INT ,
    @PazirandeId INT ,
    @Flag VARCHAR(10) ,
    @ret_ShFactor INT OUT ,
    @ret_sanad INT OUT ,
    @CShobe INT = 0 ,
    @StateFactor TINYINT = 0 ,
    @ISMove BIT = 0 ,
    @EmzaUser INT = 0 ,
    @EmzaDate VARCHAR(100) = '' ,
    @Mobile VARCHAR(100) = '' ,
    @TedPerson INT = 0 ,
    @Description NVARCHAR(500) = '' ,
    @TypeTasviye INT = 0 ,
    @Id1 INT = 0 ,
    @Id2 INT = 0 ,
    @Id3 INT = 0 ,
    @FactorTypeId INT = 0 ,
    @CustomerClub_Factor_Id INT = 0 ,
    @VizitorId INT = 0 ,
    @Address NVARCHAR(100) = '' ,
    @TypeSefaresh INT = 0 ,
    @ClearanceId INT = 0 ,
    @ClearanceId2 INT = 0 ,
    @CustumCod2 INT = 0 ,
    @Driver2 INT = 0 ,
    @BorderId INT = 0 ,
    @Date2 VARCHAR(10) = '' ,
    @GomrokId INT = 0 ,
    @Moved TINYINT = 0 ,
    @TypePardakht INT = 0,
	@RegionId INT = 0,
	@WeightFactor NUMERIC(18,3) = 0,
	@PostalCode NVARCHAR(10) = NULL,
	@DiscountState TINYINT  = 0,
	@CodeMeli NVARCHAR(10) = NULL ,
	@HamlStatus INT = 0 ,
	@ShBar NVARCHAR(50) = NULL ,
	@ShSerialBar NVARCHAR(50) = NULL ,
	@DateBar NVARCHAR(50) = null
AS
    BEGIN
		
        DECLARE @i INT ,@c INT , @TafkikPishFactor BIT = 0;

        SELECT  @TafkikPishFactor = CAST(ISNULL(Value, 0) AS BIT)
        FROM    dbo.TblParameters
        WHERE   Name = 'TafkikPishFactor';

		IF(@CustumCod=0)
		BEGIN
			SELECT @CustumCod=MAX(IDForushande) FROM dbo.TR WHERE Factor=@ShFactor AND Type=@type
			IF (@CustumCod IS NULL OR @CustumCod=0)
				SELECT @CustumCod=MAX(IDForushande) FROM dbo.TR_Deleted WHERE Factor=@ShFactor AND Type=@type
		END
		DECLARE @c1 INT
		SELECT @c1=COUNT(Sh_ozviat) FROM dbo.TblPerson WHERE Sh_ozviat = @CustumCod
		IF(@c1=0 OR @c1 IS NULL)
		BEGIN
			RAISERROR( N'کد شخص مشخص نیست',16,1)
			RETURN
		END
     --درصورتی که شعبه به صورت افلاین  باشد
        DECLARE @ShobeCompany INT = 0;
        SELECT  @ShobeCompany = CShobe
        FROM    TblCompany
        WHERE   Id = 1;
        IF ( @ShobeCompany > 0 AND @ISMove = 0)
            SET @CShobe = @ShobeCompany;


		IF(@CShobe = 0)
			SELECT @CShobe=ISNULL(MAX(CShobe),0) FROM tr WHERE Factor=@ShFactor AND Type=@type
	
		DECLARE @DefaultCshobe INT = 0
		SELECT @DefaultCshobe = Id FROM dbo.TblCompanyShobe WHERE IsDefault = 1
		IF(@CShobe = 0)
			SET @CShobe = @DefaultCshobe

        IF ( @type = 1 AND @TafkikPishFactor = 1 AND @CShobe = 0 )
            BEGIN
                RAISERROR(N'شعبه مشخص نیست',16,1);
                RETURN;
            END;


        IF ( @type = 1 AND @TafkikPishFactor = 1)
            BEGIN
                DELETE  FROM dbo.TblFactorOnvan
                WHERE   UserIDAdd = @UserIDAdd
                        AND DateFactor = @DateFactor
                        AND NOT EXISTS ( SELECT *
                                         FROM   dbo.TblPishFactor
                                         WHERE  Factor = dbo.TblFactorOnvan.ShFactor
                                                AND Type = dbo.TblFactorOnvan.Type )
						AND  NOT EXISTS ( SELECT *
                                         FROM   dbo.TR
                                         WHERE  Factor = dbo.TblFactorOnvan.ShFactor
                                                AND Type = dbo.TblFactorOnvan.Type )
						AND TYPE = 1
            END;

        DECLARE @MinFactor INT = @CShobe * 10000 ,@MaxFactor INT = ( ( @CShobe + 1 ) * 10000 ) - 1;

        IF ( @ShFactor = -1 )
        BEGIN
            SET @ShFactor = ( SELECT    ISNULL(MAX(ShFactor), 0) + 1
                                FROM      TblFactorOnvan
                                WHERE     Type = @type
                            );
            SET @Flag = 'True';
        END;
	
		

		DECLARE @FactorSori INT
		IF ( @type = 203 )
		BEGIN
			SELECT  @FactorSori = ISNULL(MAX(CAST(FactorCust AS INT)), 0)
			FROM    ( SELECT    FactorCust
						FROM      dbo.TblFactorOnvan
						WHERE     Type = @type
								AND DateFactor = @DateFactor
						UNION ALL
						SELECT    FactorCust
						FROM      dbo.TRPrinted
						WHERE     Type = @type
								AND DateR = @DateFactor 
								AND Ted > 0
					) AS t;

			IF ( @FactorSori = 0 )
			BEGIN
				SET @FactorSori = 1;
			END;
			ELSE
			BEGIN
				SET @FactorSori = @FactorSori + 1;
			END;

			SET @FactorCust = CAST(@FactorSori AS NVARCHAR(100));
		END;


        IF ( @type = 1 AND @TafkikPishFactor = 1)
        BEGIN
            SELECT  @ShFactor = ISNULL(MAX(ShFactor) + 1, @MinFactor)
            FROM    dbo.TblFactorOnvan
            WHERE   Type = 1 AND ShFactor BETWEEN @MinFactor AND @MaxFactor;
        END;

		DECLARE @FishNumber INT = 0
		SELECT @FishNumber = ISNULL(MAX(FishNumber),0) + 1 FROM dbo.TblFactorOnvan WHERE Type = @type AND DateFactor = @DateFactor
        INSERT  INTO TblFactorOnvan
                ( ShFactor ,
                  CustumCod ,
                  CustumName ,
                  DateFactor ,
                  TypeForush ,
                  Sharh ,
                  BargeKhoruj ,
                  Sanad ,
                  sarfasl ,
                  moin ,
                  hsb ,
                  Tashkhis ,
                  Type ,
                  TasviyeSharh ,
                  FactorCust ,
                  UserIDAdd ,
                  UserIDEdit ,
                  DatePrint ,
                  Driver ,
                  PazirandeId ,
                  CShobe ,
                  StateFactor ,
                  EmzaUser ,
                  EmzaDate ,
                  Mobile ,
                  TedPerson ,
                  Description ,
                  TypeTasviye ,
                  Id1 ,
                  Id2 ,
                  Id3 ,
                  FactorTypeId ,
                  VizitorID ,
                  Address ,
                  TypeSefaresh ,
                  ClearanceId ,
                  ClearanceId2 ,
                  CustumCod2 ,
                  Driver2 ,
                  BorderId ,
                  Date2 ,
                  GomrokId ,
                  Moved ,
                  TypePardakht,
				  RegionId,
				  WeightFactor,
				  PostalCode,
				  DiscountState,
				  CodeMeli,
				  FishNumber ,
				  HamlStatus ,
				  ShBar ,
				  SerialBar,
				  DateBar
                )
        VALUES  ( @ShFactor ,
                  @CustumCod ,
                  @CustumName ,
                  @DateFactor ,
                  @TypeForush ,
                  @Sharh ,
                  @BargeKhoruj ,
                  @sanad ,
                  @sarfasl ,
                  @moin ,
                  @hsb ,
                  @tashkhis ,
                  @type ,
                  @tasviyeshrh ,
                  @FactorCust ,
                  @UserIDAdd ,
                  @UserIDEdit ,
                  @DatePrint ,
                  @driver ,
                  @PazirandeId ,
                  @CShobe ,
                  @StateFactor ,
                  @EmzaUser ,
                  @EmzaDate ,
                  @Mobile ,
                  @TedPerson ,
                  @Description ,
                  @TypeTasviye ,
                  @Id1 ,
                  @Id2 ,
                  @Id3 ,
                  @FactorTypeId ,
                  @VizitorId ,
                  @Address ,
                  @TypeSefaresh ,
                  @ClearanceId ,
                  @ClearanceId2 ,
                  @CustumCod2 ,
                  @Driver2 ,
                  @BorderId ,
                  @Date2 ,
                  @GomrokId ,
                  @Moved ,
                  @TypePardakht,
				  @RegionId,
				  @WeightFactor,
				  @PostalCode,
				  @DiscountState,
				  @CodeMeli,
				  @FishNumber ,
				  @HamlStatus ,
				  @ShBar,
				  @ShSerialBar,
				  @DateBar
                );

	

      
	                
        SET @ret_ShFactor = @ShFactor;
        SET @ret_sanad = @sanad;
        SELECT  @c = COUNT(Factor)
        FROM    TblShFactor
        WHERE   Type = @type; 
	   
        SELECT  @i = Factor
        FROM    TblShFactor
        WHERE   Type = @type;
        IF ( @ShFactor > ISNULL(@i, 0) )
            BEGIN
                IF ( @c > 0 )
                    UPDATE  TblShFactor
                    SET     Factor = @ShFactor
                    WHERE   Type = @type;
                ELSE
                    INSERT  TblShFactor
                            ( Factor, Type )
                    VALUES  ( @ShFactor, @type );
	   
            END;
	   
        ALTER TABLE TR DISABLE TRIGGER Tr_Update;
        UPDATE  TR
        SET     Tashkhis = @tashkhis
        WHERE   Factor = @ShFactor
                AND Type = @type;
        ALTER TABLE TR ENABLE TRIGGER Tr_Update;
	   
        SELECT  @ret_ShFactor;
	

   
    END;



/****** Object:  StoredProcedure [dbo].[TblFactorOnvan_Update]    Script Date: 01/05/2013 10:55:54 ******/


GO

-- Procedure: [dbo].[TblFactorOnvan_SelectRow]
IF OBJECT_ID(N'[dbo].[TblFactorOnvan_SelectRow]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[TblFactorOnvan_SelectRow] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[TblFactorOnvan_SelectRow]
    @ShFactor INT ,
    @type TINYINT
AS
    BEGIN
	iF(@ShFactor<=0)
			RETURN
		update TblFactorOnvan set TypeForush = p.IDLable from TblFactorOnvan inner join TblPerson as p on p.Sh_ozviat = TblFactorOnvan.CustumCod where TypeForush = 0 and ShFactor = @ShFactor and TblFactorOnvan.Type =  @type and p.IDLable>0

        UPDATE  dbo.TblFactorOnvan
        SET     Sanad = 0
        WHERE   ShFactor = @ShFactor
                AND Type = @type;
        IF ( @type > 1 )
            UPDATE  dbo.TblFactorOnvan
            SET     DateFactor = TR.DateR ,
                    Sanad = TR.SanadM
            FROM    dbo.TblFactorOnvan
                    INNER JOIN dbo.TR ON dbo.TblFactorOnvan.ShFactor = TR.Factor
                                         AND dbo.TblFactorOnvan.Type = TR.Type
            WHERE   TR.Factor = @ShFactor
                    AND TR.Type = @type;
        IF ( @type = 1 )
            BEGIN
                UPDATE  dbo.TblFactorOnvan
                SET     Sanad = dbo.TR.SanadM ,
                        Id3 = dbo.TR.Sodor ,
                        FactorCust = CAST(dbo.TR.Factor AS VARCHAR(500))
                FROM    dbo.TblFactorOnvan
                        INNER JOIN dbo.TblPishFactor ON dbo.TblFactorOnvan.ShFactor = dbo.TblPishFactor.Factor
                                                        AND dbo.TblFactorOnvan.Type = dbo.TblPishFactor.Type
                        INNER JOIN dbo.TR ON dbo.TR.TblPishFactor_ID = dbo.TblPishFactor.Id
                WHERE   TblPishFactor.Factor = @ShFactor
                        AND TblPishFactor.Type = @type
                        AND dbo.TR.IdAnbr = 0
                        AND TR.Idkala = 0;
            END;

        IF ( @ShFactor > 0
             AND @type = 203
           )
            BEGIN
                DECLARE @Mab BIGINT ,
                    @C INT ,
                    @Moved TINYINT = 0;
                SELECT  @Mab = SUM(ISNULL(Bes - Bed, 0)) ,
                        @C = COUNT(*)
                FROM    dbo.TR
                WHERE   Factor = @ShFactor
                        AND Type = @type AND (Bed>0 OR Bes>0)
                IF ( @Mab = 0
                     AND @C > 0
                   )
                    BEGIN
                        UPDATE  dbo.TblFactorOnvan
                        SET     TypeTasviye = 1
                        WHERE   ShFactor = @ShFactor
                                AND Type = @type;
                    END;
            END;	

        DECLARE @SumTRDureTasviye INT = 0 ,
            @CountTRDureTasviye INT = 1;
        SELECT  @SumTRDureTasviye = ISNULL(SUM(TRDureTasviye), 0)
        FROM    TR
        WHERE   Factor = @ShFactor
                AND Type = @type
                AND TRDureTasviye > 0;
        SELECT  @CountTRDureTasviye = ISNULL(COUNT(TRDureTasviye), 1)
        FROM    TR
        WHERE   Factor = @ShFactor
                AND Type = @type
                AND TRDureTasviye > 0;
        IF ( @SumTRDureTasviye = 0 )
            BEGIN
                SET @SumTRDureTasviye = 1;
                SET @CountTRDureTasviye = -1;
            END;

        DECLARE @FactorSite NVARCHAR(100) = ''; 
        SELECT  @FactorSite = ISNULL(MAX(tp.FactorSite), '')
        FROM    dbo.TR AS t
                INNER JOIN dbo.TRDetail AS tp ON t.Sodor = tp.Sodor
        WHERE   t.Factor = @ShFactor
                AND t.Type = @type;


        UPDATE  dbo.TRPrinted
        SET     FactorCust = fo.FactorCust ,
                DateR = fo.DateFactor
        FROM    dbo.TRPrinted AS tp
                INNER JOIN dbo.TblFactorOnvan AS fo ON fo.ShFactor = tp.Factor
                                                       AND fo.Type = tp.Type
        WHERE   fo.ShFactor = @ShFactor
                AND fo.Type = 203;

        DECLARE @CreateTime NVARCHAR(100) = '';
        IF ( @type = 1 )
            SELECT  @CreateTime = MIN(CreateTime)
            FROM    dbo.TblPishFactor
            WHERE   Factor = @ShFactor
                    AND Type = @type;
        ELSE
            SELECT  @CreateTime = MIN(Time)
            FROM    dbo.TR
            WHERE   Factor = @ShFactor
                    AND Type = @type;


        SELECT  TblFactorOnvan.ShFactor ,
                TblFactorOnvan.CustumCod ,
                TblFactorOnvan.CustumName ,
                TblFactorOnvan.DateFactor ,
                TblFactorOnvan.TypeForush ,
                TblFactorOnvan.Sharh ,
                TblFactorOnvan.BargeKhoruj ,
                TblFactorOnvan.Sanad ,
                TblFactorOnvan.sarfasl ,
                TblFactorOnvan.moin ,
                TblFactorOnvan.hsb ,
                TblFactorOnvan.Tashkhis ,
                TblFactorOnvan.Type ,
                TblFactorOnvan.TasviyeSharh ,
                TblFactorOnvan.TypePardakht ,
                TblFactorOnvan.FactorCust ,
                TblFactorOnvan.UserIDAdd ,
                TblFactorOnvan.UserIDEdit ,
                TblFactorOnvan.DatePrint ,
                TblFactorOnvan.Driver ,
                TblFactorOnvan.PazirandeId ,
                dbo.TblUser.FulName AS UserAddName ,
                TblUser_1.FulName AS UserEditName ,
                TblFactorOnvan.CShobe ,
                TblFactorOnvan.StateFactor ,
                TblFactorOnvan.EmzaUser ,
                TblFactorOnvan.EmzaDate ,
                CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.Mobile))) > 0
                     THEN dbo.TblFactorOnvan.Mobile
                     ELSE ISNULL(pmobile.Tell, '')
                END COLLATE DATABASE_DEFAULT AS Mobile ,
                CASE WHEN LEN(LTRIM(RTRIM(dbo.TblFactorOnvan.Mobile))) > 0
                     THEN dbo.TblFactorOnvan.Mobile
                     ELSE ISNULL(pmobile.Tell, '')
                END COLLATE DATABASE_DEFAULT AS MobilePerson ,
                TedPerson ,
                Description ,
                dbo.TblFactorOnvan.TypeTasviye ,
                dbo.TblFactorOnvan.Id1 ,
                dbo.TblFactorOnvan.Id2 ,
                dbo.TblFactorOnvan.Id3 ,
                dbo.TblFactorOnvan.FactorTypeId ,
				dbo.TblFactorOnvan.HamlStatus ,
				dbo.TblFactorOnvan.ShBar ,
				dbo.TblFactorOnvan.SerialBar ,
				dbo.TblFactorOnvan.DateBar ,
                CAST(ROUND(@SumTRDureTasviye / @CountTRDureTasviye, 0) AS INT) AS TRDureTasviye ,
                CustomerClub_Factor_Id ,
                VizitorID ,
                dbo.TblFactorOnvan.Address ,
                TypeSefaresh ,
                ClearanceId ,
                ClearanceId2 ,
                CustumCod2 ,
                Driver2 ,
                BorderId ,
                Date2 ,
                GomrokId ,
                Moved ,
                @CreateTime AS TimeSabt ,
                ISNULL(pv.Name + ' ' + pv.Famil, '') AS VizitorName ,
                ISNULL(TblFactorOnvan.RefId, 0) AS RefId ,
                dbo.TblFactorOnvan.RegionId ,
                FactorOff ,
                WeightFactor ,
                CASE WHEN @FactorSite = ''
                          OR @FactorSite = '' THEN FactorSite
                     ELSE @FactorSite
                END AS FactorSite ,
                dbo.GetTypeSefareshName(TypeSefaresh) AS TypeSefareshName ,
                PostalCode ,
                DiscountState ,
                CodeMeli ,
                FishNumber,
				GharardadNumber,
				ModatTasviye,
				CarNumber
        FROM    TblFactorOnvan
                LEFT OUTER JOIN dbo.TblUser ON TblFactorOnvan.UserIDEdit = TblUser.Id
                LEFT OUTER JOIN TblUser AS TblUser_1 ON TblFactorOnvan.UserIDAdd = TblUser_1.Id
                LEFT JOIN dbo.TblPerson ON dbo.TblPerson.Sh_ozviat = dbo.TblFactorOnvan.CustumCod
                LEFT JOIN dbo.TblPerson AS pv ON pv.Sh_ozviat = dbo.TblFactorOnvan.VizitorID
                LEFT JOIN dbo.Func_PersonTell (2) AS pmobile ON pmobile.ShOzviat = TblFactorOnvan.CustumCod
        WHERE   ( TblFactorOnvan.ShFactor = @ShFactor )
                AND ( TblFactorOnvan.Type = @type );
    END;


/****** Object:  StoredProcedure [dbo].[RptSuratHesab]    Script Date: 01/09/2018 15:13:00 ******/
    SET ANSI_NULLS ON;


GO

-- Procedure: [dbo].[TblFactorOnvan_Update]
IF OBJECT_ID(N'[dbo].[TblFactorOnvan_Update]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[TblFactorOnvan_Update] AS SELECT 1;');
GO
ALTER PROCEDURE [dbo].[TblFactorOnvan_Update]
    @ShFactor INT,
    @CustumCod INT,
    @CustumName NVARCHAR(50),
    @DateFactor NCHAR(10),
    @TypeForush INT,
    @Sharh NVARCHAR(500),
    @BargeKhoruj INT,
    @sanad INT,
    @sarfasl INT,
    @moin INT,
    @hsb BIGINT,
    @tashkhis INT,
    @type TINYINT,
    @tasviyesharh NVARCHAR(500),
    @FuctorCust VARCHAR(100),
    @UserIDAdd INT,
    @UserIDEdit INT,
    @DatePrint VARCHAR(50),
    @driver INT,
    @PazirandeId INT,
    @CShobe INT = 0,
    @StateFactor TINYINT = 0,
    @ISMove BIT = 0,
    @EmzaUser INT = 0,
    @EmzaDate VARCHAR(100) = '',
    @Mobile VARCHAR(100) = '',
    @TedPerson INT = 0,
    @Description NVARCHAR(500) = '',
    @TypeTasviye INT = 0,
    @Id1 INT = 0,
    @Id2 INT = 0,
    @Id3 INT = 0,
    @FactorTypeId INT = 0,
    @CustomerClub_Factor_Id INT = 0,
    @VizitorID INT = 0,
    @Address NVARCHAR(100) = '',
    @TypeSefaresh INT = 0,
    @ClearanceId INT = 0,
    @ClearanceId2 INT = 0,
    @CustumCod2 INT = 0,
    @Driver2 INT = 0,
    @BorderId INT = 0,
    @Date2 VARCHAR(10) = '',
    @GomrokId INT = 0,
    @Moved TINYINT = 0,
    @TypePardakht INT = 0,
    @RegionId INT = 0,
    @WeightFactor NUMERIC(18, 3) = 0,
    @PostalCode NVARCHAR(10) = NULL,
    @DiscountState TINYINT = 0,
    @CodeMeli NVARCHAR(10) = NULL,
    @GharardadNumber INT = 0,
    @HamlStatus INT = 0,
    @ShBarName NVARCHAR(50) = NULL,
    @SerialBarName NVARCHAR(50) = NULL,
    @DateBarName NVARCHAR(50) = NULL,
	@ModatTasviye INT = 0,
	@CarNumber NVARCHAR(100) = ''
AS
BEGIN
    DECLARE @s INT;
    SELECT @s = ISNULL(SanadM, 0)
    FROM TR
    WHERE Factor = @ShFactor
          AND Type = @type;
    IF (@s > 0)
        SET @sanad = @s;

    DECLARE @ShobeCompany INT = 0;
    SELECT @ShobeCompany = CShobe
    FROM TblCompany
    WHERE Id = 1;
    IF (@ShobeCompany > 0 AND @ISMove = 0)
        SET @CShobe = @ShobeCompany;

    DECLARE @CurrentEmzauser INT = 0,
            @CurrentCustom INT = 0;
    SELECT @CurrentEmzauser = ISNULL(CustumCod, 0),
           @CurrentEmzauser = ISNULL(EmzaUser, 0),
           @CurrentCustom = CustumCod
    FROM TblFactorOnvan
    WHERE TblFactorOnvan.ShFactor = @ShFactor
          AND Type = @type;
    IF (@CurrentEmzauser > 0)
    BEGIN

        RAISERROR(N'این فاکتور امضا شده است و قایل تغییر نمی باشد', 16, 1);
        RETURN;
    END;

    IF (@CustumCod = 0)
    BEGIN
        SELECT @CustumCod = MAX(IDForushande)
        FROM dbo.TR
        WHERE Factor = @ShFactor
              AND Type = @type;
        IF (@CustumCod IS NULL OR @CustumCod = 0)
            SELECT @CustumCod = MAX(IDForushande)
            FROM dbo.TR_Deleted
            WHERE Factor = @ShFactor
                  AND Type = @type;
    END;

    SELECT *
    FROM dbo.TblPerson
    WHERE Sh_ozviat = @CustumCod;
    IF (@@ROWCOUNT = 0)
    BEGIN
        RAISERROR(N'کد شخص مشخص نیست', 16, 1);
        RETURN;
    END;

	INSERT INTO dbo.TblFactorOnvan_Updated
	SELECT @UserIDEdit,dbo.GetTodayNew(), TblFactorOnvan.ShFactor,
                                         TblFactorOnvan.Type,
                                         TblFactorOnvan.CustumCod,
                                         TblFactorOnvan.CustumName,
                                         TblFactorOnvan.DateFactor,
                                         TblFactorOnvan.TypeForush,
                                         TblFactorOnvan.Sharh,
                                         TblFactorOnvan.BargeKhoruj,
                                         TblFactorOnvan.Sanad,
                                         TblFactorOnvan.sarfasl,
                                         TblFactorOnvan.moin,
                                         TblFactorOnvan.hsb,
                                         TblFactorOnvan.Tashkhis,
                                         TblFactorOnvan.TasviyeSharh,
                                         TblFactorOnvan.TypePardakht,
                                         TblFactorOnvan.FactorCust,
                                         TblFactorOnvan.UserIDAdd,
                                         TblFactorOnvan.UserIDEdit,
                                         TblFactorOnvan.DatePrint,
                                         TblFactorOnvan.Driver,
                                         TblFactorOnvan.PazirandeId,
                                         TblFactorOnvan.CShobe,
                                         TblFactorOnvan.StateFactor,
                                         TblFactorOnvan.EmzaUser,
                                         TblFactorOnvan.EmzaDate,
                                         TblFactorOnvan.Mobile,
                                         TblFactorOnvan.TedPerson,
                                         TblFactorOnvan.Description,
                                         TblFactorOnvan.TypeTasviye,
                                         TblFactorOnvan.Id1,
                                         TblFactorOnvan.Id2,
                                         TblFactorOnvan.Id3,
                                         TblFactorOnvan.FactorTypeId,
                                         TblFactorOnvan.CustomerClub_Factor_Id,
                                         TblFactorOnvan.VizitorID,
                                         TblFactorOnvan.Address,
                                         TblFactorOnvan.TypeSefaresh,
                                         TblFactorOnvan.GUID,
                                         TblFactorOnvan.ClearanceId,
                                         TblFactorOnvan.ClearanceId2,
                                         TblFactorOnvan.CustumCod2,
                                         TblFactorOnvan.Driver2,
                                         TblFactorOnvan.BorderId,
                                         TblFactorOnvan.Date2,
                                         TblFactorOnvan.GomrokId,
                                         TblFactorOnvan.Moved,
                                         TblFactorOnvan.FactorOff,
                                         TblFactorOnvan.RefId,
                                         TblFactorOnvan.RegionId,
                                         TblFactorOnvan.WeightFactor,
                                         TblFactorOnvan.ChangeStateTime,
                                         TblFactorOnvan.DriverTime,
                                         TblFactorOnvan.DriveUser,
                                         TblFactorOnvan.FishNumber,
                                         TblFactorOnvan.Tell,
                                         TblFactorOnvan.CreateTime,
                                         TblFactorOnvan.FactorSite,
                                         TblFactorOnvan.PostalCode,
                                         TblFactorOnvan.DiscountState,
                                         TblFactorOnvan.CodeMeli,
                                         TblFactorOnvan.ShiftId,
                                         TblFactorOnvan.BPMS_InvTitleId,
                                         TblFactorOnvan.Longitude,
                                         TblFactorOnvan.Latitude,
                                         TblFactorOnvan.GharardadNumber,
                                         TblFactorOnvan.IrTaxId,
                                         TblFactorOnvan.RefFactor,
                                         TblFactorOnvan.RefFactorYear,
                                         TblFactorOnvan.HamlStatus,
                                         TblFactorOnvan.ShBar,
                                         TblFactorOnvan.SerialBar,
                                         TblFactorOnvan.DateBar,
										 TblFactorOnvan.ModatTasviye,
										 TblFactorOnvan.CarNumber
										 FROM dbo.TblFactorOnvan 
    WHERE ShFactor = @ShFactor
          AND Type = @type;
    UPDATE TblFactorOnvan
    SET CustumCod = @CustumCod,
        CustumName = @CustumName,
        DateFactor = @DateFactor,
        TypeForush = @TypeForush,
        Sharh = @Sharh,
        BargeKhoruj = @BargeKhoruj,
        Sanad = @sanad,
        sarfasl = @sarfasl,
        moin = @moin,
        hsb = @hsb,
        Tashkhis = @tashkhis,
        TasviyeSharh = @tasviyesharh,
        FactorCust = @FuctorCust,
        UserIDAdd = @UserIDAdd,
        UserIDEdit = @UserIDEdit,
        DatePrint = @DatePrint,
        Driver = @driver,
        PazirandeId = @PazirandeId,
        CShobe = @CShobe,
        StateFactor = @StateFactor,
        EmzaUser = @EmzaUser,
        EmzaDate = @EmzaDate,
        Mobile = @Mobile,
        TedPerson = @TedPerson,
        Description = @Description,
        Id1 = @Id1,
        Id2 = @Id2,
        Id3 = @Id3,
        FactorTypeId = @FactorTypeId,
        CustomerClub_Factor_Id = @CustomerClub_Factor_Id,
        VizitorID = @VizitorID,
        Address = @Address,
        TypeSefaresh = @TypeSefaresh,
        ClearanceId = @ClearanceId,
        ClearanceId2 = @ClearanceId2,
        CustumCod2 = @CustumCod2,
        Driver2 = @Driver2,
        BorderId = @BorderId,
        Date2 = @Date2,
        GomrokId = @GomrokId,
        Moved = @Moved,
        TypePardakht = @TypePardakht,
        RegionId = @RegionId,
        WeightFactor = @WeightFactor,
        PostalCode = @PostalCode,
        DiscountState = @DiscountState,
        CodeMeli = @CodeMeli,
        GharardadNumber = @GharardadNumber,
        HamlStatus = @HamlStatus,
        ShBar = @ShBarName,
        SerialBar = @SerialBarName,
        DateBar = @DateBarName,
		ModatTasviye = @ModatTasviye,
		CarNumber = @CarNumber
    WHERE ShFactor = @ShFactor
          AND Type = @type;


    IF (@tashkhis > 0)
    BEGIN
        ALTER TABLE TR DISABLE TRIGGER Tr_Update;
        UPDATE TR
        SET Tashkhis = @tashkhis
        WHERE Factor = @ShFactor
              AND Type = @type;
        ALTER TABLE TR ENABLE TRIGGER Tr_Update;
    END;
END;

GO

